static NSString *arg_value(int argc, const char **argv, const char *name) {
    for (int i = 1; i + 1 < argc; i++) {
        if (strcmp(argv[i], name) == 0) {
            return [NSString stringWithUTF8String:argv[i + 1]];
        }
    }
    return nil;
}

static int has_flag(int argc, const char **argv, const char *name) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], name) == 0) return 1;
    }
    return 0;
}

static float half_to_float(uint16_t h) {
    uint32_t sign = (uint32_t)(h & 0x8000u) << 16;
    uint32_t exp = (h >> 10) & 0x1fu;
    uint32_t mant = h & 0x03ffu;
    uint32_t bits = 0;
    if (exp == 0) {
        if (mant == 0) {
            bits = sign;
        } else {
            exp = 1;
            while ((mant & 0x0400u) == 0) {
                mant <<= 1;
                exp--;
            }
            mant &= 0x03ffu;
            bits = sign | ((exp + 112u) << 23) | (mant << 13);
        }
    } else if (exp == 31) {
        bits = sign | 0x7f800000u | (mant << 13);
    } else {
        bits = sign | ((exp + 112u) << 23) | (mant << 13);
    }
    float value;
    memcpy(&value, &bits, sizeof(value));
    return value;
}

static int checked_mul_u64(uint64_t a, uint64_t b, uint64_t *out);

static int parse_u64_strict_value(NSString *s, const char *label, uint64_t *out) {
    if (!s || !out) {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    NSString *trimmed = [s stringByTrimmingCharactersInSet:
                         [NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (trimmed.length == 0) {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    const char *raw = trimmed.UTF8String;
    if (!raw || raw[0] == '\0') {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    for (const char *p = raw; *p; p++) {
        if (*p < '0' || *p > '9') {
            fprintf(stderr, "%s must be an integer\n", label);
            return 0;
        }
    }
    errno = 0;
    char *end = NULL;
    unsigned long long value = strtoull(raw, &end, 10);
    if (errno == ERANGE || !end || *end != '\0') {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    *out = (uint64_t)value;
    return 1;
}

static int parse_optional_u64_arg(int argc,
                                  const char **argv,
                                  const char *name,
                                  uint64_t fallback,
                                  uint64_t *out) {
    NSString *value = arg_value(argc, argv, name);
    if (!value) {
        *out = fallback;
        return 1;
    }
    return parse_u64_strict_value(value, name, out);
}

static int parse_optional_kib_bytes_arg_checked(int argc,
                                                const char **argv,
                                                const char *name,
                                                uint64_t fallback_kib,
                                                uint64_t *out) {
    uint64_t kib = 0;
    if (!parse_optional_u64_arg(argc, argv, name, fallback_kib, &kib)) {
        return 0;
    }
    if (!checked_mul_u64(kib, 1024ull, out)) {
        fprintf(stderr, "%s is too large\n", name);
        return 0;
    }
    return 1;
}

static int parse_f64_strict_value(NSString *s, const char *label, double *out) {
    if (!s || !out) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    NSString *trimmed = [s stringByTrimmingCharactersInSet:
                         [NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (trimmed.length == 0) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    const char *raw = trimmed.UTF8String;
    errno = 0;
    char *end = NULL;
    double value = strtod(raw, &end);
    if (errno == ERANGE || end == raw || !end || *end != '\0' ||
        !isfinite(value)) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    *out = value;
    return 1;
}

static int parse_f32_strict_value(NSString *s, const char *label, float *out) {
    if (!s || !out) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    NSString *trimmed = [s stringByTrimmingCharactersInSet:
                         [NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (trimmed.length == 0) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    const char *raw = trimmed.UTF8String;
    errno = 0;
    char *end = NULL;
    double value = strtod(raw, &end);
    if (errno == ERANGE || end == raw || !end || *end != '\0' ||
        !isfinite(value) ||
        value > (double)FLT_MAX ||
        value < -(double)FLT_MAX) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    *out = (float)value;
    return 1;
}

static int parse_optional_f64_arg(int argc,
                                  const char **argv,
                                  const char *name,
                                  double fallback,
                                  double *out) {
    NSString *value = arg_value(argc, argv, name);
    if (!value) {
        *out = fallback;
        return 1;
    }
    return parse_f64_strict_value(value, name, out);
}

static int parse_optional_f32_arg(int argc,
                                  const char **argv,
                                  const char *name,
                                  float fallback,
                                  float *out) {
    NSString *value = arg_value(argc, argv, name);
    if (!value) {
        *out = fallback;
        return 1;
    }
    return parse_f32_strict_value(value, name, out);
}

static int parse_u64_list_labeled(NSString *s,
                                  const char *label,
                                  uint64_t *out,
                                  int max_count) {
    if (!s || max_count <= 0) return -1;
    NSArray *parts = [s componentsSeparatedByString:@","];
    if (parts.count == 0 || parts.count > (NSUInteger)max_count) return -1;
    int count = 0;
    for (NSString *part in parts) {
        NSString *trimmed = [part stringByTrimmingCharactersInSet:
                             [NSCharacterSet whitespaceAndNewlineCharacterSet]];
        if (trimmed.length == 0) return -1;
        uint64_t value = 0;
        if (!parse_u64_strict_value(trimmed, label, &value)) return -1;
        out[count++] = value;
    }
    return count;
}

static int parse_u64_list(NSString *s, uint64_t *out, int max_count) {
    return parse_u64_list_labeled(s, "MoE expert", out, max_count);
}

static int parse_float_list(NSString *s, float *out, int max_count) {
    if (!s || max_count <= 0) return -1;
    NSArray *parts = [s componentsSeparatedByString:@","];
    if (parts.count == 0 || parts.count > (NSUInteger)max_count) return -1;
    int count = 0;
    for (NSString *part in parts) {
        NSString *trimmed = [part stringByTrimmingCharactersInSet:
                             [NSCharacterSet whitespaceAndNewlineCharacterSet]];
        if (trimmed.length == 0) return -1;
        float value = 0.0f;
        if (!parse_f32_strict_value(trimmed, "MoE weight", &value)) return -1;
        out[count++] = value;
    }
    return count;
}

static NSDictionary *load_json(NSString *path) {
    static NSMutableDictionary *json_cache = nil;
    if (!path) {
        fprintf(stderr, "missing layout json path\n");
        return nil;
    }
    if (!json_cache) json_cache = [NSMutableDictionary dictionary];
    NSString *cache_key = [path stringByStandardizingPath];
    NSDictionary *cached = json_cache[cache_key];
    if (cached) return cached;

    NSData *data = [NSData dataWithContentsOfFile:path];
    if (!data) {
        fprintf(stderr, "failed to read %s\n", path.UTF8String);
        return nil;
    }
    NSError *error = nil;
    id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
    if (error || ![obj isKindOfClass:[NSDictionary class]]) {
        fprintf(stderr, "failed to parse layout json: %s\n",
                error.localizedDescription.UTF8String);
        return nil;
    }
    NSDictionary *dict = (NSDictionary *)obj;
    json_cache[cache_key] = dict;
    return dict;
}

static int read_json_u64_number(id value,
                                const char *label,
                                int require_positive,
                                uint64_t *out);

static NSDictionary *find_layer(NSArray *layers, uint64_t layer_id) {
    for (id item in layers) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *layer = (NSDictionary *)item;
        id n = layer[@"layer"];
        uint64_t parsed_layer = 0;
        if (!read_json_u64_number(n, "expert layout layer id", 0, &parsed_layer)) {
            return nil;
        }
        if (parsed_layer == layer_id) return layer;
    }
    return nil;
}

static int checked_mul_u64(uint64_t a, uint64_t b, uint64_t *out) {
    if (a != 0 && b > UINT64_MAX / a) return 0;
    *out = a * b;
    return 1;
}

static int checked_add_u64(uint64_t a, uint64_t b, uint64_t *out) {
    if (b > UINT64_MAX - a) return 0;
    *out = a + b;
    return 1;
}

static int mib_to_bytes_arg(uint64_t mib, const char *label, uint64_t *out) {
    if (mib == 0 || mib > UINT64_MAX / (1024ull * 1024ull)) {
        fprintf(stderr, "%s must be positive and within range\n", label);
        return 0;
    }
    *out = mib * 1024ull * 1024ull;
    return 1;
}

static int mib_double_to_bytes_arg(double mib, const char *label, uint64_t *out) {
    const double scale = 1024.0 * 1024.0;
    const double max_mib = (double)(UINT64_MAX / (1024ull * 1024ull));
    if (!isfinite(mib) || mib <= 0.0 || mib > max_mib) {
        fprintf(stderr, "%s must be positive and within range\n", label);
        return 0;
    }
    double bytes = mib * scale;
    if (!isfinite(bytes) || bytes < 1.0) {
        fprintf(stderr, "%s must be positive and within range\n", label);
        return 0;
    }
    *out = (uint64_t)bytes;
    if (*out == 0) {
        fprintf(stderr, "%s must be positive and within range\n", label);
        return 0;
    }
    return 1;
}

static int parse_optional_mib_bytes_arg(int argc,
                                        const char **argv,
                                        const char *name,
                                        double fallback_mib,
                                        uint64_t *out) {
    double mib = 0.0;
    if (!parse_optional_f64_arg(argc, argv, name, fallback_mib, &mib)) {
        return 0;
    }
    return mib_double_to_bytes_arg(mib, name, out);
}

static int read_positive_json_u64(NSDictionary *dict,
                                  NSString *key,
                                  const char *label,
                                  uint64_t *out) {
    id value = dict[key];
    if (![value isKindOfClass:[NSNumber class]]) {
        fprintf(stderr, "%s must be a positive integer\n", label);
        return 0;
    }
    NSNumber *number = (NSNumber *)value;
    const char *type = number.objCType;
    if (strcmp(type, @encode(float)) == 0 ||
        strcmp(type, @encode(double)) == 0 ||
        strcmp(type, "c") == 0 ||
        strcmp(type, "B") == 0) {
        fprintf(stderr, "%s must be a positive integer\n", label);
        return 0;
    }
    long long signed_value = number.longLongValue;
    if (signed_value <= 0) {
        fprintf(stderr, "%s must be a positive integer\n", label);
        return 0;
    }
    *out = (uint64_t)signed_value;
    return 1;
}

static int validate_resident_tensor_spans(NSDictionary *resident_layout);

static int read_nonnegative_json_u64(NSDictionary *dict,
                                     NSString *key,
                                     const char *label,
                                     uint64_t *out) {
    id value = dict[key];
    if (![value isKindOfClass:[NSNumber class]]) {
        fprintf(stderr, "%s must be a non-negative integer\n", label);
        return 0;
    }
    NSNumber *number = (NSNumber *)value;
    const char *type = number.objCType;
    if (strcmp(type, @encode(float)) == 0 ||
        strcmp(type, @encode(double)) == 0 ||
        strcmp(type, "c") == 0 ||
        strcmp(type, "B") == 0) {
        fprintf(stderr, "%s must be a non-negative integer\n", label);
        return 0;
    }
    long long signed_value = number.longLongValue;
    if (signed_value < 0) {
        fprintf(stderr, "%s must be a non-negative integer\n", label);
        return 0;
    }
    *out = (uint64_t)signed_value;
    return 1;
}

static int parse_expert_layer_fields(NSDictionary *layer,
                                     uint64_t max_slot_bytes,
                                     NSString **out_layer_file,
                                     uint64_t *out_num_experts,
                                     uint64_t *out_slot_bytes,
                                     uint64_t *out_layer_file_bytes) {
    NSString *layer_file = layer[@"layer_file"];
    if (![layer_file isKindOfClass:[NSString class]] || layer_file.length == 0 ||
        layer_file.isAbsolutePath || [layer_file containsString:@"/"]) {
        fprintf(stderr, "expert layout layer_file must be a relative file name\n");
        return 0;
    }
    uint64_t num_experts = 0;
    uint64_t slot_bytes = 0;
    if (!read_positive_json_u64(layer, @"num_experts",
                                "expert layout layer num_experts", &num_experts) ||
        !read_positive_json_u64(layer, @"expert_slot_bytes",
                                "expert layout layer expert_slot_bytes", &slot_bytes)) {
        return 0;
    }
    if (slot_bytes > max_slot_bytes) {
        fprintf(stderr,
                "expert slot %llu bytes exceeds configured limit %llu bytes; refusing\n",
                (unsigned long long)slot_bytes,
                (unsigned long long)max_slot_bytes);
        return 0;
    }
    uint64_t layer_file_bytes = 0;
    if (!checked_mul_u64(num_experts, slot_bytes, &layer_file_bytes)) {
        fprintf(stderr, "expert layout layer file byte size overflows uint64\n");
        return 0;
    }
    *out_layer_file = layer_file;
    *out_num_experts = num_experts;
    *out_slot_bytes = slot_bytes;
    *out_layer_file_bytes = layer_file_bytes;
    return 1;
}

static int validate_expert_layer_file_size(NSString *expert_path,
                                           uint64_t expected_bytes) {
    struct stat st;
    if (stat(expert_path.UTF8String, &st) != 0) {
        fprintf(stderr, "stat failed for expert layer file %s: %s\n",
                expert_path.UTF8String,
                strerror(errno));
        return 0;
    }
    if (st.st_size < 0) {
        fprintf(stderr, "expert layer file %s has invalid size\n",
                expert_path.UTF8String);
        return 0;
    }
    uint64_t actual = (uint64_t)st.st_size;
    if (actual != expected_bytes) {
        fprintf(stderr,
                "expert layer file size %llu does not match layout bytes %llu\n",
                (unsigned long long)actual,
                (unsigned long long)expected_bytes);
        return 0;
    }
    return 1;
}

static NSString *validate_resident_weight_path(NSString *resident_layout_path,
                                               NSDictionary *resident_layout) {
    static NSMutableDictionary *weight_path_cache = nil;
    if (!weight_path_cache) weight_path_cache = [NSMutableDictionary dictionary];
    NSString *layout_key = [resident_layout_path stringByStandardizingPath];
    NSString *cache_key = [NSString stringWithFormat:@"%p:%@",
                           (void *)resident_layout,
                           layout_key];
    NSString *cached = weight_path_cache[cache_key];
    if (cached) return cached;

    NSString *weight_file = resident_layout[@"weight_file"];
    if (![weight_file isKindOfClass:[NSString class]] ||
        weight_file.length == 0 ||
        weight_file.isAbsolutePath ||
        [weight_file containsString:@"/"]) {
        fprintf(stderr, "resident layout weight_file must be a relative file name\n");
        return nil;
    }
    uint64_t expected_bytes = 0;
    if (!read_positive_json_u64(resident_layout,
                                @"total_bytes",
                                "resident layout total_bytes",
                                &expected_bytes)) {
        return nil;
    }
    NSString *layout_dir = [resident_layout_path stringByDeletingLastPathComponent];
    NSString *weight_path = [layout_dir stringByAppendingPathComponent:weight_file];
    struct stat st;
    if (stat(weight_path.UTF8String, &st) != 0) {
        fprintf(stderr, "stat failed for resident weight file %s: %s\n",
                weight_path.UTF8String,
                strerror(errno));
        return nil;
    }
    if (st.st_size < 0) {
        fprintf(stderr, "resident weight file %s has invalid size\n",
                weight_path.UTF8String);
        return nil;
    }
    uint64_t actual = (uint64_t)st.st_size;
    if (actual != expected_bytes) {
        fprintf(stderr,
                "resident weight file size %llu does not match layout total_bytes %llu\n",
                (unsigned long long)actual,
                (unsigned long long)expected_bytes);
        return nil;
    }
    if (!validate_resident_tensor_spans(resident_layout)) {
        return nil;
    }
    weight_path_cache[cache_key] = weight_path;
    return weight_path;
}

static int validate_resident_layout_backing(NSString *resident_layout_path) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 0;
    return validate_resident_weight_path(resident_layout_path, resident_layout) != nil;
}

static int read_exact_fd(int fd, const char *label, void *dst, size_t size, off_t offset) {
    size_t copied = 0;
    while (copied < size) {
        size_t to_read = size - copied;
        if (to_read > 8 * 1024 * 1024) to_read = 8 * 1024 * 1024;
        ssize_t n = pread(fd, (char *)dst + copied, to_read, offset + (off_t)copied);
        if (n <= 0) {
            fprintf(stderr, "pread failed for %s at %zu/%zu: %s\n",
                    label, copied, size, n == 0 ? "short read" : strerror(errno));
            return 0;
        }
        copied += (size_t)n;
    }
    return 1;
}

static int read_exact_slot(const char *path, void *dst, size_t size, off_t offset) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", path, strerror(errno));
        return 0;
    }
    int ok = read_exact_fd(fd, path, dst, size, offset);
    close(fd);
    return ok;
}

static int write_exact_fd(int fd, const char *label, const void *src, size_t size, off_t offset) {
    size_t copied = 0;
    while (copied < size) {
        size_t to_write = size - copied;
        if (to_write > 8 * 1024 * 1024) to_write = 8 * 1024 * 1024;
        ssize_t n = pwrite(fd, (const char *)src + copied, to_write,
                           offset + (off_t)copied);
        if (n <= 0) {
            fprintf(stderr, "pwrite failed for %s at %zu/%zu: %s\n",
                    label, copied, size, n == 0 ? "short write" : strerror(errno));
            return 0;
        }
        copied += (size_t)n;
    }
    return 1;
}

static int write_exact_at(NSString *path, const void *src, size_t size, off_t offset) {
    int fd = open(path.UTF8String, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", path.UTF8String, strerror(errno));
        return 0;
    }
    size_t copied = 0;
    while (copied < size) {
        size_t to_write = size - copied;
        if (to_write > 8 * 1024 * 1024) to_write = 8 * 1024 * 1024;
        ssize_t n = pwrite(fd, (const char *)src + copied, to_write,
                           offset + (off_t)copied);
        if (n <= 0) {
            fprintf(stderr, "pwrite failed at %zu/%zu: %s\n",
                    copied, size, n == 0 ? "short write" : strerror(errno));
            close(fd);
            return 0;
        }
        copied += (size_t)n;
    }
    close(fd);
    return 1;
}

static uint64_t align_up_u64(uint64_t value, uint64_t alignment) {
    return (value + alignment - 1) & ~(alignment - 1);
}

static uint64_t align_down_any(uint64_t value, uint64_t alignment) {
    return alignment <= 1 ? value : (value / alignment) * alignment;
}

static uint64_t align_up_any(uint64_t value, uint64_t alignment) {
    if (alignment <= 1) return value;
    return ((value + alignment - 1) / alignment) * alignment;
}

static int compare_u64_values(const void *a, const void *b) {
    uint64_t av = *(const uint64_t *)a;
    uint64_t bv = *(const uint64_t *)b;
    return (av > bv) - (av < bv);
}

static void advise_read_range(int fd, uint64_t offset, uint64_t length) {
#ifdef F_RDADVISE
    while (length > 0) {
        int chunk = length > (uint64_t)INT_MAX ? INT_MAX : (int)length;
        struct radvisory ra;
        ra.ra_offset = (off_t)offset;
        ra.ra_count = chunk;
        if (fcntl(fd, F_RDADVISE, &ra) != 0) {
            return;
        }
        offset += (uint64_t)chunk;
        length -= (uint64_t)chunk;
    }
#else
    (void)fd;
    (void)offset;
    (void)length;
#endif
}

static void advise_expert_read_ranges(int fd,
                                      uint64_t slot_bytes,
                                      uint64_t layer_file_bytes,
                                      const uint64_t *expert_ids,
                                      int expert_count,
                                      uint64_t merge_gap_bytes,
                                      uint64_t align_bytes) {
#ifdef F_RDADVISE
    if (expert_count <= 0 || slot_bytes == 0) return;
    if (align_bytes == 0) align_bytes = 1;
    uint64_t *sorted = calloc((size_t)expert_count, sizeof(uint64_t));
    if (!sorted) return;
    for (int i = 0; i < expert_count; i++) {
        sorted[i] = expert_ids[i];
    }
    qsort(sorted, (size_t)expert_count, sizeof(uint64_t), compare_u64_values);

    int unique_count = 0;
    for (int i = 0; i < expert_count; i++) {
        if (unique_count == 0 || sorted[i] != sorted[unique_count - 1]) {
            sorted[unique_count++] = sorted[i];
        }
    }

    uint64_t group_start = sorted[0] * slot_bytes;
    uint64_t group_end = group_start + slot_bytes;
    for (int i = 1; i < unique_count; i++) {
        uint64_t offset = sorted[i] * slot_bytes;
        uint64_t end = offset + slot_bytes;
        uint64_t gap = offset > group_end ? offset - group_end : 0;
        if (gap <= merge_gap_bytes) {
            group_end = end;
            continue;
        }
        uint64_t aligned_start = align_down_any(group_start, align_bytes);
        uint64_t aligned_end = align_up_any(group_end, align_bytes);
        if (layer_file_bytes > 0 && aligned_end > layer_file_bytes) {
            aligned_end = layer_file_bytes;
        }
        if (aligned_end > aligned_start) {
            advise_read_range(fd, aligned_start, aligned_end - aligned_start);
        }
        group_start = offset;
        group_end = end;
    }
    uint64_t aligned_start = align_down_any(group_start, align_bytes);
    uint64_t aligned_end = align_up_any(group_end, align_bytes);
    if (layer_file_bytes > 0 && aligned_end > layer_file_bytes) {
        aligned_end = layer_file_bytes;
    }
    if (aligned_end > aligned_start) {
        advise_read_range(fd, aligned_start, aligned_end - aligned_start);
    }
    free(sorted);
#else
    (void)fd;
    (void)slot_bytes;
    (void)layer_file_bytes;
    (void)expert_ids;
    (void)expert_count;
    (void)merge_gap_bytes;
    (void)align_bytes;
#endif
}

static int enforce_scratch_limit(const char *stage,
                                 uint64_t estimated_bytes,
                                 uint64_t limit_bytes) {
    if (estimated_bytes <= limit_bytes) return 1;
    fprintf(stderr,
            "%s scratch estimate %llu bytes exceeds configured limit %llu bytes; "
            "raise --max-runner-scratch-mib only after checking memory headroom\n",
            stage,
            (unsigned long long)estimated_bytes,
            (unsigned long long)limit_bytes);
    return 0;
}

static uint64_t estimate_expert_forward_peak(uint64_t slot_alloc_bytes,
                                             uint32_t hidden_dim,
                                             uint32_t intermediate_dim) {
    uint64_t hidden_bytes = (uint64_t)hidden_dim * sizeof(float);
    uint64_t intermediate_bytes = (uint64_t)intermediate_dim * sizeof(float);
    return slot_alloc_bytes + 4 * hidden_bytes + 3 * intermediate_bytes;
}

static uint64_t estimate_moe_forward_peak(uint64_t slot_alloc_bytes,
                                          uint32_t hidden_dim,
                                          uint32_t intermediate_dim,
                                          uint64_t extra_live_bytes) {
    uint64_t hidden_bytes = (uint64_t)hidden_dim * sizeof(float);
    uint64_t intermediate_bytes = (uint64_t)intermediate_dim * sizeof(float);
    return slot_alloc_bytes + extra_live_bytes + 5 * hidden_bytes + 3 * intermediate_bytes;
}

static int moe_batch_buffer_bytes_for_block(uint32_t hidden_dim,
                                            uint32_t intermediate_dim,
                                            uint32_t token_block,
                                            uint64_t *out_batch_buffer_bytes) {
    if (!out_batch_buffer_bytes || token_block == 0) return 0;
    uint64_t hidden_bytes = (uint64_t)hidden_dim * sizeof(float);
    uint64_t intermediate_bytes = (uint64_t)intermediate_dim * sizeof(float);
    if (hidden_bytes > UINT64_MAX / 3 || intermediate_bytes > UINT64_MAX / 3) {
        return 0;
    }
    uint64_t per_row = 3 * hidden_bytes + 3 * intermediate_bytes + sizeof(float);
    if (per_row == 0 || (uint64_t)token_block > UINT64_MAX / per_row) {
        return 0;
    }
    *out_batch_buffer_bytes = (uint64_t)token_block * per_row;
    return 1;
}

static int estimate_moe_batch_forward_peak(uint64_t slot_alloc_bytes,
                                           uint32_t hidden_dim,
                                           uint32_t intermediate_dim,
                                           uint32_t token_block,
                                           uint64_t route_live_bytes,
                                           uint64_t *out_batch_buffer_bytes,
                                           uint64_t *out_peak) {
    if (!out_batch_buffer_bytes || !out_peak || token_block == 0) return 0;
    uint64_t batch_buffer_bytes = 0;
    if (!moe_batch_buffer_bytes_for_block(hidden_dim,
                                          intermediate_dim,
                                          token_block,
                                          &batch_buffer_bytes)) {
        return 0;
    }
    if (route_live_bytes > UINT64_MAX - batch_buffer_bytes) return 0;
    uint64_t live = route_live_bytes + batch_buffer_bytes;
    if (slot_alloc_bytes > UINT64_MAX - live) return 0;
    *out_batch_buffer_bytes = batch_buffer_bytes;
    *out_peak = slot_alloc_bytes + live;
    return 1;
}

static int choose_moe_batch_token_block(uint64_t slot_alloc_bytes,
                                        uint32_t hidden_dim,
                                        uint32_t intermediate_dim,
                                        uint32_t requested_token_block,
                                        uint64_t max_expert_assignments,
                                        uint64_t route_live_bytes,
                                        uint64_t max_runner_scratch_bytes,
                                        uint32_t *out_effective_token_block,
                                        uint64_t *out_batch_buffer_bytes,
                                        uint64_t *out_peak) {
    if (!out_effective_token_block || !out_batch_buffer_bytes || !out_peak ||
        max_expert_assignments == 0) {
        return 0;
    }
    uint32_t max_block = max_expert_assignments > UINT32_MAX
        ? UINT32_MAX
        : (uint32_t)max_expert_assignments;
    uint32_t token_block = requested_token_block;
    if (token_block == 0) {
        uint64_t block_one_bytes = 0;
        if (!moe_batch_buffer_bytes_for_block(hidden_dim,
                                              intermediate_dim,
                                              1,
                                              &block_one_bytes)) {
            return 0;
        }
        if (slot_alloc_bytes > max_runner_scratch_bytes ||
            route_live_bytes > max_runner_scratch_bytes - slot_alloc_bytes ||
            block_one_bytes > max_runner_scratch_bytes - slot_alloc_bytes - route_live_bytes) {
            return 0;
        }
        uint64_t available =
            max_runner_scratch_bytes - slot_alloc_bytes - route_live_bytes;
        uint64_t auto_block = available / block_one_bytes;
        if (auto_block == 0) return 0;
        if (auto_block > (uint64_t)max_block) auto_block = max_block;
        if (auto_block > UINT32_MAX) auto_block = UINT32_MAX;
        token_block = (uint32_t)auto_block;
    } else if (token_block > max_block) {
        token_block = max_block;
    }
    if (token_block == 0) return 0;
    if (!estimate_moe_batch_forward_peak(slot_alloc_bytes,
                                         hidden_dim,
                                         intermediate_dim,
                                         token_block,
                                         route_live_bytes,
                                         out_batch_buffer_bytes,
                                         out_peak)) {
        return 0;
    }
    *out_effective_token_block = token_block;
    return 1;
}

static int moe_batch_memory_accumulator_from_env(int *enabled) {
    if (!enabled) return 0;
    *enabled = 0;
    const char *value = getenv("LARGERLM_MOE_BATCH_ACCUMULATOR");
    if (!value || value[0] == '\0') {
        return 1;
    }
    if (strcmp(value, "0") == 0 ||
        strcasecmp(value, "file") == 0 ||
        strcasecmp(value, "disk") == 0 ||
        strcasecmp(value, "false") == 0 ||
        strcasecmp(value, "no") == 0 ||
        strcasecmp(value, "off") == 0) {
        return 1;
    }
    if (strcmp(value, "1") == 0 ||
        strcasecmp(value, "memory") == 0 ||
        strcasecmp(value, "mem") == 0 ||
        strcasecmp(value, "in-memory") == 0 ||
        strcasecmp(value, "ram") == 0 ||
        strcasecmp(value, "true") == 0 ||
        strcasecmp(value, "yes") == 0 ||
        strcasecmp(value, "on") == 0) {
        *enabled = 1;
        return 1;
    }
    fprintf(stderr,
            "unsupported LARGERLM_MOE_BATCH_ACCUMULATOR=%s; expected file or memory\n",
            value);
    return 0;
}

static uint64_t estimate_moe_forward_peak_with_shared(uint64_t slot_alloc_bytes,
                                                      uint32_t hidden_dim,
                                                      uint32_t intermediate_dim,
                                                      uint64_t extra_live_bytes,
                                                      uint64_t shared_matrix_alloc_bytes) {
    return estimate_moe_forward_peak(slot_alloc_bytes,
                                     hidden_dim,
                                     intermediate_dim,
                                     extra_live_bytes + shared_matrix_alloc_bytes);
}

static uint64_t estimate_router_peak(uint64_t router_bytes,
                                     uint32_t hidden_dim,
                                     uint32_t num_experts) {
    uint64_t input_bytes = (uint64_t)hidden_dim * sizeof(float);
    uint64_t logits_bytes = (uint64_t)num_experts * sizeof(float);
    return 2 * router_bytes + 2 * input_bytes + 2 * logits_bytes;
}

static uint32_t pack8(const uint8_t vals[8]) {
    uint32_t out = 0;
    for (int i = 0; i < 8; i++) {
        out |= ((uint32_t)(vals[i] & 0xF)) << (i * 4);
    }
    return out;
}

typedef struct {
    NSUInteger offset;
    NSUInteger size;
    uint32_t dim0;
    uint32_t dim1;
    char dtype[16];
} ComponentInfo;

static int find_component_info(NSDictionary *layer,
                               NSString *name,
                               ComponentInfo *out) {
    NSArray *components = layer[@"components"];
    if (![components isKindOfClass:[NSArray class]]) return 0;
    for (id item in components) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *component = (NSDictionary *)item;
        NSString *cname = component[@"name"];
        if (![cname isKindOfClass:[NSString class]] || ![cname isEqualToString:name]) {
            continue;
        }
        NSArray *shape = component[@"shape"];
        if (![shape isKindOfClass:[NSArray class]] || shape.count != 2) {
            fprintf(stderr, "expert layout component %s shape must be rank 2\n",
                    name.UTF8String);
            return 0;
        }
        uint64_t offset = 0;
        uint64_t size = 0;
        uint64_t d0 = 0;
        uint64_t d1 = 0;
        if (!read_json_u64_number(component[@"offset"],
                                  "expert layout component offset",
                                  0,
                                  &offset) ||
            !read_json_u64_number(component[@"size"],
                                  "expert layout component size",
                                  1,
                                  &size) ||
            !read_json_u64_number(shape[0],
                                  "expert layout component shape dimension",
                                  1,
                                  &d0) ||
            !read_json_u64_number(shape[1],
                                  "expert layout component shape dimension",
                                  1,
                                  &d1)) {
            return 0;
        }
        if (d0 > UINT32_MAX || d1 > UINT32_MAX) {
            fprintf(stderr, "expert layout component %s shape dimension is out of range\n",
                    name.UTF8String);
            return 0;
        }
        out->offset = (NSUInteger)offset;
        out->size = (NSUInteger)size;
        out->dim0 = (uint32_t)d0;
        out->dim1 = (uint32_t)d1;
        NSString *dtype = component[@"dtype"];
        if (![dtype isKindOfClass:[NSString class]] || dtype.length == 0) {
            fprintf(stderr, "expert layout component %s dtype must be a string\n",
                    name.UTF8String);
            return 0;
        }
        snprintf(out->dtype, sizeof(out->dtype), "%s", dtype.UTF8String);
        return 1;
    }
    return 0;
}

