    float weight;
} MoEBatchAssignment;

static int compare_moe_batch_assignments(const void *lhs, const void *rhs) {
    const MoEBatchAssignment *a = (const MoEBatchAssignment *)lhs;
    const MoEBatchAssignment *b = (const MoEBatchAssignment *)rhs;
    if (a->expert < b->expert) return -1;
    if (a->expert > b->expert) return 1;
    if (a->token < b->token) return -1;
    if (a->token > b->token) return 1;
    return 0;
}

static void advise_sorted_moe_assignment_ranges(int fd,
                                                uint64_t slot_bytes,
                                                uint64_t layer_file_bytes,
                                                const MoEBatchAssignment *assignments,
                                                uint64_t assignment_count,
                                                uint64_t merge_gap_bytes,
                                                uint64_t align_bytes) {
#ifdef F_RDADVISE
    if (!assignments || assignment_count == 0 || slot_bytes == 0) return;
    if (align_bytes == 0) align_bytes = 1;
    int have_group = 0;
    uint64_t current_expert = UINT64_MAX;
    uint64_t group_start = 0;
    uint64_t group_end = 0;
    for (uint64_t i = 0; i < assignment_count; i++) {
        uint64_t expert = assignments[i].expert;
        if (expert == current_expert) {
            continue;
        }
        current_expert = expert;
        uint64_t offset = expert * slot_bytes;
        uint64_t end = offset + slot_bytes;
        if (!have_group) {
            group_start = offset;
            group_end = end;
            have_group = 1;
            continue;
        }
        uint64_t gap = offset > group_end ? offset - group_end : 0;
        if (gap <= merge_gap_bytes) {
            group_end = end;
            continue;
        }
        uint64_t aligned_start = align_down_any(group_start, align_bytes);
        uint64_t aligned_end = align_up_any(group_end, align_bytes);
        if (layer_file_bytes > 0 && aligned_end > layer_file_bytes) {
            aligned_end = layer_file_bytes;
        }
        if (aligned_end > aligned_start) {
            advise_read_range(fd, aligned_start, aligned_end - aligned_start);
        }
        group_start = offset;
        group_end = end;
    }
    if (have_group) {
        uint64_t aligned_start = align_down_any(group_start, align_bytes);
        uint64_t aligned_end = align_up_any(group_end, align_bytes);
        if (layer_file_bytes > 0 && aligned_end > layer_file_bytes) {
            aligned_end = layer_file_bytes;
        }
        if (aligned_end > aligned_start) {
            advise_read_range(fd, aligned_start, aligned_end - aligned_start);
        }
    }
#else
    (void)fd;
    (void)slot_bytes;
    (void)layer_file_bytes;
    (void)assignments;
    (void)assignment_count;
    (void)merge_gap_bytes;
    (void)align_bytes;
#endif
}

