static int require_component_order(NSDictionary *layout) {
    NSArray *order = layout[@"component_order"];
    NSArray *expected = @[
        @"gate_proj.weight",
        @"gate_proj.scales",
        @"gate_proj.biases",
        @"up_proj.weight",
        @"up_proj.scales",
        @"up_proj.biases",
        @"down_proj.weight",
        @"down_proj.scales",
        @"down_proj.biases",
    ];
    if (![order isKindOfClass:[NSArray class]] || order.count != expected.count) {
        fprintf(stderr, "expert layout component_order does not match affine-int4 slot order\n");
        return 0;
    }
    for (NSUInteger i = 0; i < expected.count; i++) {
        id item = order[i];
        if (![item isKindOfClass:[NSString class]] ||
            ![(NSString *)item isEqualToString:expected[i]]) {
            fprintf(stderr, "expert layout component_order does not match affine-int4 slot order\n");
            return 0;
        }
    }
    return 1;
}

static int require_mxfp4_component_order(NSDictionary *layout) {
    NSArray *order = layout[@"component_order"];
    NSArray *expected = @[
        @"gate_proj.weight",
        @"gate_proj.scales",
        @"up_proj.weight",
        @"up_proj.scales",
        @"down_proj.weight",
        @"down_proj.scales",
    ];
    if (![order isKindOfClass:[NSArray class]] || order.count != expected.count) {
        fprintf(stderr, "expert layout component_order does not match mlx-mxfp4 slot order\n");
        return 0;
    }
    for (NSUInteger i = 0; i < expected.count; i++) {
        id item = order[i];
        if (![item isKindOfClass:[NSString class]] ||
            ![(NSString *)item isEqualToString:expected[i]]) {
            fprintf(stderr, "expert layout component_order does not match mlx-mxfp4 slot order\n");
            return 0;
        }
    }
    return 1;
}

static int component_has_dtype_for(NSDictionary *layer,
                                   NSString *name,
                                   NSArray<NSString *> *expected_dtypes,
                                   const char *quantization_label) {
    NSArray *components = layer[@"components"];
    if (![components isKindOfClass:[NSArray class]]) return 0;
    for (id item in components) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *component = (NSDictionary *)item;
        NSString *cname = component[@"name"];
        if (![cname isKindOfClass:[NSString class]] || ![cname isEqualToString:name]) {
            continue;
        }
        NSString *dtype = component[@"dtype"];
        if (![dtype isKindOfClass:[NSString class]]) {
            fprintf(stderr,
                    "expert layout component %s dtype does not match %s expectation\n",
                    name.UTF8String,
                    quantization_label);
            return 0;
        }
        int ok = 0;
        for (NSString *expected_dtype in expected_dtypes) {
            if ([dtype caseInsensitiveCompare:expected_dtype] == NSOrderedSame) {
                ok = 1;
                break;
            }
        }
        if (!ok) {
            fprintf(stderr,
                    "expert layout component %s dtype does not match %s expectation\n",
                    name.UTF8String,
                    quantization_label);
            return 0;
        }
        return 1;
    }
    return 0;
}

static int component_has_dtype(NSDictionary *layer,
                               NSString *name,
                               NSArray<NSString *> *expected_dtypes) {
    return component_has_dtype_for(layer, name, expected_dtypes, "affine-int4");
}

static int component_expected_span(ComponentInfo component,
                                   NSString *name,
                                   uint64_t expected_offset,
                                   uint64_t expected_size,
                                   uint64_t slot_bytes) {
    if (component.offset != expected_offset || component.size != expected_size) {
        fprintf(stderr,
                "expert layout component %s span does not match affine-int4 slot order\n",
                name.UTF8String);
        return 0;
    }
    uint64_t end = 0;
    if (!checked_add_u64((uint64_t)component.offset,
                         (uint64_t)component.size,
                         &end)) {
        fprintf(stderr,
                "expert layout component %s span overflows uint64\n",
                name.UTF8String);
        return 0;
    }
    if (slot_bytes && end > slot_bytes) {
        fprintf(stderr,
                "expert layout component %s exceeds expert slot\n",
                name.UTF8String);
        return 0;
    }
    return 1;
}

static int affine_meta_dtype_mode(const char *scale_dtype,
                                  const char *bias_dtype,
                                  uint32_t *out) {
    int scale_bf16 = strcmp(scale_dtype, "BF16") == 0 ||
                     strcmp(scale_dtype, "bfloat16") == 0 ||
                     strcmp(scale_dtype, "BFLOAT16") == 0;
    int bias_bf16 = strcmp(bias_dtype, "BF16") == 0 ||
                    strcmp(bias_dtype, "bfloat16") == 0 ||
                    strcmp(bias_dtype, "BFLOAT16") == 0;
    int scale_f16 = strcmp(scale_dtype, "F16") == 0 ||
                    strcmp(scale_dtype, "float16") == 0 ||
                    strcmp(scale_dtype, "FLOAT16") == 0;
    int bias_f16 = strcmp(bias_dtype, "F16") == 0 ||
                   strcmp(bias_dtype, "float16") == 0 ||
                   strcmp(bias_dtype, "FLOAT16") == 0;
    if (scale_bf16 && bias_bf16) {
        *out = 0;
        return 1;
    }
    if (scale_f16 && bias_f16) {
        *out = 1;
        return 1;
    }
    fprintf(stderr, "affine-int4 scale/bias metadata dtypes must match\n");
    return 0;
}

static int parse_mxfp4_expert_layout(NSDictionary *layout,
                                     NSDictionary *layer,
                                     ExpertLayoutInfo *info) {
    if (!require_mxfp4_component_order(layout)) {
        return 0;
    }
    if (!find_component_info(layer, @"gate_proj.weight", &info->gate_w) ||
        !find_component_info(layer, @"gate_proj.scales", &info->gate_s) ||
        !find_component_info(layer, @"up_proj.weight", &info->up_w) ||
        !find_component_info(layer, @"up_proj.scales", &info->up_s) ||
        !find_component_info(layer, @"down_proj.weight", &info->down_w) ||
        !find_component_info(layer, @"down_proj.scales", &info->down_s)) {
        fprintf(stderr, "layout is missing one or more mlx-mxfp4 expert components\n");
        return 0;
    }
    NSArray<NSString *> *weight_dtypes = @[@"U32", @"uint32"];
    NSArray<NSString *> *scale_dtypes = @[@"U8", @"uint8", @"UINT8"];
    if (!component_has_dtype_for(layer, @"gate_proj.weight", weight_dtypes, "mlx-mxfp4") ||
        !component_has_dtype_for(layer, @"gate_proj.scales", scale_dtypes, "mlx-mxfp4") ||
        !component_has_dtype_for(layer, @"up_proj.weight", weight_dtypes, "mlx-mxfp4") ||
        !component_has_dtype_for(layer, @"up_proj.scales", scale_dtypes, "mlx-mxfp4") ||
        !component_has_dtype_for(layer, @"down_proj.weight", weight_dtypes, "mlx-mxfp4") ||
        !component_has_dtype_for(layer, @"down_proj.scales", scale_dtypes, "mlx-mxfp4")) {
        return 0;
    }

    info->is_mxfp4 = 1;
    info->intermediate_dim = info->gate_w.dim0;
    info->hidden_dim = info->down_w.dim0;
    uint64_t gate_in_u64 = (uint64_t)info->gate_w.dim1 * 8ull;
    uint64_t up_in_u64 = (uint64_t)info->up_w.dim1 * 8ull;
    uint64_t down_in_u64 = (uint64_t)info->down_w.dim1 * 8ull;
    if (gate_in_u64 > UINT32_MAX ||
        up_in_u64 > UINT32_MAX ||
        down_in_u64 > UINT32_MAX) {
        fprintf(stderr, "mlx-mxfp4 expert layout dimensions are out of range\n");
        return 0;
    }
    uint32_t gate_in = (uint32_t)gate_in_u64;
    uint32_t up_in = (uint32_t)up_in_u64;
    uint32_t down_in = (uint32_t)down_in_u64;
    if (info->up_w.dim0 != info->intermediate_dim ||
        gate_in != up_in ||
        gate_in != info->hidden_dim ||
        down_in != info->intermediate_dim) {
        fprintf(stderr,
                "unsupported mlx-mxfp4 expert dimensions: gate_in=%u up_in=%u "
                "down_in=%u hidden=%u intermediate=%u\n",
                gate_in, up_in, down_in, info->hidden_dim, info->intermediate_dim);
        return 0;
    }

    id gs = layout[@"group_size"];
    info->group_size = 0;
    if (gs) {
        uint64_t group_size = 0;
        if (!read_json_u64_number(gs,
                                  "expert layout group_size",
                                  1,
                                  &group_size)) {
            return 0;
        }
        if (group_size > UINT32_MAX) {
            fprintf(stderr, "expert layout group_size is out of range\n");
            return 0;
        }
        info->group_size = (uint32_t)group_size;
    }
    if (info->group_size == 0) {
        if (info->gate_s.dim1 == 0) return 0;
        info->group_size = gate_in / info->gate_s.dim1;
    }
    if (info->group_size != 32 ||
        gate_in % info->group_size != 0 ||
        down_in % info->group_size != 0) {
        fprintf(stderr, "unsupported mlx-mxfp4 group size %u\n", info->group_size);
        return 0;
    }
    uint32_t gate_groups = gate_in / info->group_size;
    uint32_t down_groups = down_in / info->group_size;
    if (info->gate_s.dim0 != info->intermediate_dim ||
        info->up_s.dim0 != info->intermediate_dim ||
        info->down_s.dim0 != info->hidden_dim ||
        info->gate_s.dim1 != gate_groups ||
        info->up_s.dim1 != gate_groups ||
        info->down_s.dim1 != down_groups) {
        fprintf(stderr, "mlx-mxfp4 expert scale shapes do not match group layout\n");
        return 0;
    }

    uint64_t slot_bytes = 0;
    if (!read_positive_json_u64(layer,
                                @"expert_slot_bytes",
                                "expert layout layer expert_slot_bytes",
                                &slot_bytes)) {
        return 0;
    }
    uint64_t gate_weight_values = 0;
    uint64_t gate_weight_bytes = 0;
    uint64_t gate_scale_values = 0;
    uint64_t gate_scale_bytes = 0;
    uint64_t down_weight_values = 0;
    uint64_t down_weight_bytes = 0;
    uint64_t down_scale_values = 0;
    uint64_t down_scale_bytes = 0;
    if (!checked_mul_u64((uint64_t)info->intermediate_dim,
                         (uint64_t)info->gate_w.dim1,
                         &gate_weight_values) ||
        !checked_mul_u64(gate_weight_values, sizeof(uint32_t), &gate_weight_bytes) ||
        !checked_mul_u64((uint64_t)info->intermediate_dim,
                         (uint64_t)gate_groups,
                         &gate_scale_values) ||
        !checked_mul_u64(gate_scale_values, sizeof(uint8_t), &gate_scale_bytes) ||
        !checked_mul_u64((uint64_t)info->hidden_dim,
                         (uint64_t)info->down_w.dim1,
                         &down_weight_values) ||
        !checked_mul_u64(down_weight_values, sizeof(uint32_t), &down_weight_bytes) ||
        !checked_mul_u64((uint64_t)info->hidden_dim,
                         (uint64_t)down_groups,
                         &down_scale_values) ||
        !checked_mul_u64(down_scale_values, sizeof(uint8_t), &down_scale_bytes)) {
        fprintf(stderr, "mlx-mxfp4 expert layout component byte size overflows uint64\n");
        return 0;
    }
    if (gate_scale_bytes % sizeof(uint32_t) != 0 ||
        down_scale_bytes % sizeof(uint32_t) != 0) {
        fprintf(stderr, "mlx-mxfp4 expert scale spans must be 4-byte aligned\n");
        return 0;
    }
    uint64_t expected_offset = 0;
    if (!component_expected_span(info->gate_w, @"gate_proj.weight",
                                 expected_offset, gate_weight_bytes, slot_bytes)) return 0;
    expected_offset += gate_weight_bytes;
    if (!component_expected_span(info->gate_s, @"gate_proj.scales",
                                 expected_offset, gate_scale_bytes, slot_bytes)) return 0;
    expected_offset += gate_scale_bytes;
    if (!component_expected_span(info->up_w, @"up_proj.weight",
                                 expected_offset, gate_weight_bytes, slot_bytes)) return 0;
    expected_offset += gate_weight_bytes;
    if (!component_expected_span(info->up_s, @"up_proj.scales",
                                 expected_offset, gate_scale_bytes, slot_bytes)) return 0;
    expected_offset += gate_scale_bytes;
    if (!component_expected_span(info->down_w, @"down_proj.weight",
                                 expected_offset, down_weight_bytes, slot_bytes)) return 0;
    expected_offset += down_weight_bytes;
    if (!component_expected_span(info->down_s, @"down_proj.scales",
                                 expected_offset, down_scale_bytes, slot_bytes)) return 0;
    expected_offset += down_scale_bytes;
    if (slot_bytes && expected_offset != slot_bytes) {
        fprintf(stderr,
                "expert layout mlx-mxfp4 component span total does not match expert slot bytes\n");
        return 0;
    }
    return 1;
}

static int router_options_from_args(int argc, const char **argv, RouterOptions *out) {
    if (!out) return 0;
    RouterOptions options = {0};
    options.use_correction_bias = has_flag(argc, argv, "--ignore-router-bias") ? 0 : 1;
    NSString *scale_s = arg_value(argc, argv, "--routed-scaling-factor");
    if (scale_s) {
        float scale = 0.0f;
        if (!parse_f32_strict_value(scale_s, "--routed-scaling-factor", &scale)) {
            return 0;
        }
        if (scale <= 0.0f) {
            fprintf(stderr, "--routed-scaling-factor must be positive\n");
            return 0;
        }
        options.routed_scaling_factor = scale;
        options.routed_scaling_factor_set = 1;
    }
    if (has_flag(argc, argv, "--norm-topk-prob")) {
        options.norm_topk_prob = 1;
        options.norm_topk_prob_set = 1;
    }
    if (has_flag(argc, argv, "--no-norm-topk-prob")) {
        options.norm_topk_prob = 0;
        options.norm_topk_prob_set = 1;
    }
    NSString *n_group_s = arg_value(argc, argv, "--router-n-group");
    if (n_group_s) {
        uint64_t n_group = 0;
        if (!parse_u64_strict_value(n_group_s, "--router-n-group", &n_group)) {
            return 0;
        }
        if (n_group == 0 || n_group > UINT32_MAX) {
            fprintf(stderr, "--router-n-group must be in 1..%u\n", UINT32_MAX);
            return 0;
        }
        options.n_group = (uint32_t)n_group;
        options.n_group_set = 1;
    }
    NSString *topk_group_s = arg_value(argc, argv, "--router-topk-group");
    if (topk_group_s) {
        uint64_t topk_group = 0;
        if (!parse_u64_strict_value(topk_group_s, "--router-topk-group", &topk_group)) {
            return 0;
        }
        if (topk_group == 0 || topk_group > UINT32_MAX) {
            fprintf(stderr, "--router-topk-group must be in 1..%u\n", UINT32_MAX);
            return 0;
        }
        options.topk_group = (uint32_t)topk_group;
        options.topk_group_set = 1;
    }
    *out = options;
    return 1;
}

static int parse_expert_layout(NSDictionary *layout,
                               NSDictionary *layer,
                               ExpertLayoutInfo *info) {
    NSString *quantization = layout[@"quantization"];
    if ([quantization isKindOfClass:[NSString class]] &&
        [quantization caseInsensitiveCompare:@"mlx-mxfp4"] == NSOrderedSame) {
        return parse_mxfp4_expert_layout(layout, layer, info);
    }
    info->is_mxfp4 = 0;
    if (!require_component_order(layout)) {
        return 0;
    }
    if (!find_component_info(layer, @"gate_proj.weight", &info->gate_w) ||
        !find_component_info(layer, @"gate_proj.scales", &info->gate_s) ||
        !find_component_info(layer, @"gate_proj.biases", &info->gate_b) ||
        !find_component_info(layer, @"up_proj.weight", &info->up_w) ||
        !find_component_info(layer, @"up_proj.scales", &info->up_s) ||
        !find_component_info(layer, @"up_proj.biases", &info->up_b) ||
        !find_component_info(layer, @"down_proj.weight", &info->down_w) ||
        !find_component_info(layer, @"down_proj.scales", &info->down_s) ||
        !find_component_info(layer, @"down_proj.biases", &info->down_b)) {
        fprintf(stderr, "layout is missing one or more expert components\n");
        return 0;
    }
    NSArray<NSString *> *weight_dtypes = @[@"U32", @"uint32"];
    NSArray<NSString *> *meta_dtypes = @[@"BF16", @"bfloat16", @"F16", @"float16"];
    if (!component_has_dtype(layer, @"gate_proj.weight", weight_dtypes) ||
        !component_has_dtype(layer, @"gate_proj.scales", meta_dtypes) ||
        !component_has_dtype(layer, @"gate_proj.biases", meta_dtypes) ||
        !component_has_dtype(layer, @"up_proj.weight", weight_dtypes) ||
        !component_has_dtype(layer, @"up_proj.scales", meta_dtypes) ||
        !component_has_dtype(layer, @"up_proj.biases", meta_dtypes) ||
        !component_has_dtype(layer, @"down_proj.weight", weight_dtypes) ||
        !component_has_dtype(layer, @"down_proj.scales", meta_dtypes) ||
        !component_has_dtype(layer, @"down_proj.biases", meta_dtypes)) {
        return 0;
    }

    info->intermediate_dim = info->gate_w.dim0;
    info->hidden_dim = info->down_w.dim0;
    uint64_t gate_in_u64 = (uint64_t)info->gate_w.dim1 * 8ull;
    uint64_t up_in_u64 = (uint64_t)info->up_w.dim1 * 8ull;
    uint64_t down_in_u64 = (uint64_t)info->down_w.dim1 * 8ull;
    if (gate_in_u64 > UINT32_MAX ||
        up_in_u64 > UINT32_MAX ||
        down_in_u64 > UINT32_MAX) {
        fprintf(stderr, "expert layout dimensions are out of range\n");
        return 0;
    }
    uint32_t gate_in = (uint32_t)gate_in_u64;
    uint32_t up_in = (uint32_t)up_in_u64;
    uint32_t down_in = (uint32_t)down_in_u64;
    if (gate_in != up_in || gate_in != info->hidden_dim ||
        down_in != info->intermediate_dim) {
        fprintf(stderr,
                "unsupported expert dimensions: gate_in=%u up_in=%u "
                "down_in=%u hidden=%u intermediate=%u\n",
                gate_in, up_in, down_in, info->hidden_dim, info->intermediate_dim);
        return 0;
    }

    id gs = layout[@"group_size"];
    info->group_size = 0;
    if (gs) {
        uint64_t group_size = 0;
        if (!read_json_u64_number(gs,
                                  "expert layout group_size",
                                  1,
                                  &group_size)) {
            return 0;
        }
        if (group_size > UINT32_MAX) {
            fprintf(stderr, "expert layout group_size is out of range\n");
            return 0;
        }
        info->group_size = (uint32_t)group_size;
    }
    if (info->group_size == 0) {
        if (info->gate_s.dim1 == 0) return 0;
        info->group_size = gate_in / info->gate_s.dim1;
    }
    if (info->group_size == 0 || gate_in % info->group_size != 0 ||
        info->intermediate_dim % info->group_size != 0) {
        fprintf(stderr, "unsupported group size %u\n", info->group_size);
        return 0;
    }
    uint64_t slot_bytes = 0;
    if (!read_positive_json_u64(layer,
                                @"expert_slot_bytes",
                                "expert layout layer expert_slot_bytes",
                                &slot_bytes)) {
        return 0;
    }
    uint64_t gate_groups = (uint64_t)gate_in / info->group_size;
    uint64_t down_groups = (uint64_t)down_in / info->group_size;
    uint64_t gate_weight_values = 0;
    uint64_t gate_weight_bytes = 0;
    uint64_t gate_meta_values = 0;
    uint64_t gate_meta_bytes = 0;
    uint64_t down_weight_values = 0;
    uint64_t down_weight_bytes = 0;
    uint64_t down_meta_values = 0;
    uint64_t down_meta_bytes = 0;
    if (!checked_mul_u64((uint64_t)info->intermediate_dim,
                         (uint64_t)info->gate_w.dim1,
                         &gate_weight_values) ||
        !checked_mul_u64(gate_weight_values, sizeof(uint32_t), &gate_weight_bytes) ||
        !checked_mul_u64((uint64_t)info->intermediate_dim,
                         gate_groups,
                         &gate_meta_values) ||
        !checked_mul_u64(gate_meta_values, sizeof(uint16_t), &gate_meta_bytes) ||
        !checked_mul_u64((uint64_t)info->hidden_dim,
                         (uint64_t)info->down_w.dim1,
                         &down_weight_values) ||
        !checked_mul_u64(down_weight_values, sizeof(uint32_t), &down_weight_bytes) ||
        !checked_mul_u64((uint64_t)info->hidden_dim,
                         down_groups,
                         &down_meta_values) ||
        !checked_mul_u64(down_meta_values, sizeof(uint16_t), &down_meta_bytes)) {
        fprintf(stderr, "expert layout component byte size overflows uint64\n");
        return 0;
    }
    uint64_t expected_offset = 0;
    if (!component_expected_span(info->gate_w, @"gate_proj.weight",
                                 expected_offset, gate_weight_bytes, slot_bytes)) return 0;
    expected_offset += gate_weight_bytes;
    if (!component_expected_span(info->gate_s, @"gate_proj.scales",
                                 expected_offset, gate_meta_bytes, slot_bytes)) return 0;
    expected_offset += gate_meta_bytes;
    if (!component_expected_span(info->gate_b, @"gate_proj.biases",
                                 expected_offset, gate_meta_bytes, slot_bytes)) return 0;
    expected_offset += gate_meta_bytes;
    if (!component_expected_span(info->up_w, @"up_proj.weight",
                                 expected_offset, gate_weight_bytes, slot_bytes)) return 0;
    expected_offset += gate_weight_bytes;
    if (!component_expected_span(info->up_s, @"up_proj.scales",
                                 expected_offset, gate_meta_bytes, slot_bytes)) return 0;
    expected_offset += gate_meta_bytes;
    if (!component_expected_span(info->up_b, @"up_proj.biases",
                                 expected_offset, gate_meta_bytes, slot_bytes)) return 0;
    expected_offset += gate_meta_bytes;
    if (!component_expected_span(info->down_w, @"down_proj.weight",
                                 expected_offset, down_weight_bytes, slot_bytes)) return 0;
    expected_offset += down_weight_bytes;
    if (!component_expected_span(info->down_s, @"down_proj.scales",
                                 expected_offset, down_meta_bytes, slot_bytes)) return 0;
    expected_offset += down_meta_bytes;
    if (!component_expected_span(info->down_b, @"down_proj.biases",
                                 expected_offset, down_meta_bytes, slot_bytes)) return 0;
    expected_offset += down_meta_bytes;
    if (slot_bytes && expected_offset != slot_bytes) {
        fprintf(stderr,
                "expert layout affine-int4 component span total does not match expert slot bytes\n");
        return 0;
    }
    return 1;
}

static NSArray *resident_layout_tensors(NSDictionary *resident_layout) {
    NSArray *tensors = resident_layout[@"tensors"];
    if (![tensors isKindOfClass:[NSArray class]]) {
        fprintf(stderr, "resident layout missing tensors array\n");
        return nil;
    }
    return tensors;
}

static NSArray *resident_tensors_for_layer(NSDictionary *resident_layout,
                                           uint64_t layer_id) {
    static NSMutableDictionary *layer_tensor_cache = nil;
    if (!layer_tensor_cache) layer_tensor_cache = [NSMutableDictionary dictionary];
    NSString *cache_key = [NSString stringWithFormat:@"%p:%llu",
                           (void *)resident_layout,
                           (unsigned long long)layer_id];
    NSArray *cached = layer_tensor_cache[cache_key];
    if (cached) return cached;

    NSArray *tensors = resident_layout_tensors(resident_layout);
    if (!tensors) return nil;
    NSMutableArray *filtered = [NSMutableArray array];
    NSString *needle = [NSString stringWithFormat:@".layers.%llu.",
                        (unsigned long long)layer_id];
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) continue;
        if ([name containsString:needle]) [filtered addObject:tensor];
    }
    NSArray *result = [filtered copy];
    layer_tensor_cache[cache_key] = result;
    return result;
}

static NSDictionary *resident_tensor_name_index(NSDictionary *resident_layout) {
    static NSMutableDictionary *name_index_cache = nil;
    if (!name_index_cache) name_index_cache = [NSMutableDictionary dictionary];
    NSString *cache_key = [NSString stringWithFormat:@"%p", (void *)resident_layout];
    NSDictionary *cached = name_index_cache[cache_key];
    if (cached) return cached;

    NSArray *tensors = resident_layout_tensors(resident_layout);
    if (!tensors) return nil;
    NSMutableDictionary *index = [NSMutableDictionary dictionary];
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) continue;
        if (!index[name]) index[name] = tensor;
    }
    NSDictionary *result = [index copy];
    name_index_cache[cache_key] = result;
    return result;
}

static int read_json_u64_number(id value,
                                const char *label,
                                int require_positive,
                                uint64_t *out) {
    if (![value isKindOfClass:[NSNumber class]]) {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    NSNumber *number = (NSNumber *)value;
    const char *type = number.objCType;
    if (strcmp(type, @encode(float)) == 0 ||
        strcmp(type, @encode(double)) == 0 ||
        strcmp(type, "c") == 0 ||
        strcmp(type, "B") == 0) {
        fprintf(stderr, "%s must be an integer\n", label);
        return 0;
    }
    long long signed_value = number.longLongValue;
    if (require_positive ? (signed_value <= 0) : (signed_value < 0)) {
        fprintf(stderr, "%s must be %s\n",
                label,
                require_positive ? "positive" : "non-negative");
        return 0;
    }
    *out = (uint64_t)signed_value;
    return 1;
}

static int read_json_f32_number(id value,
                                const char *label,
                                float *out) {
    if (![value isKindOfClass:[NSNumber class]]) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    NSNumber *number = (NSNumber *)value;
    const char *type = number.objCType;
    if (strcmp(type, "c") == 0 || strcmp(type, "B") == 0) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    double value64 = number.doubleValue;
    if (!isfinite(value64) ||
        value64 > (double)FLT_MAX ||
        value64 < -(double)FLT_MAX) {
        fprintf(stderr, "%s must be a finite number\n", label);
        return 0;
    }
    *out = (float)value64;
    return 1;
}

static int parse_resident_tensor_metadata(NSDictionary *resident_layout,
                                          NSDictionary *tensor,
                                          ResidentTensorMetadata *out) {
    NSString *name = tensor[@"name"];
    NSString *dtype = tensor[@"dtype"];
    NSArray *shape = tensor[@"shape"];
    if (![name isKindOfClass:[NSString class]] ||
        name.length == 0 ||
        ![dtype isKindOfClass:[NSString class]] ||
        ![shape isKindOfClass:[NSArray class]] ||
        shape.count == 0 ||
        shape.count > 4) {
        fprintf(stderr, "resident tensor has invalid name/dtype/shape metadata\n");
        return 0;
    }
    int dtype_bytes = matrix_dtype_bytes(dtype.UTF8String);
    if (dtype_bytes == 0 &&
        (strcmp(dtype.UTF8String, "U32") == 0 ||
         strcmp(dtype.UTF8String, "uint32") == 0 ||
         strcmp(dtype.UTF8String, "UINT32") == 0)) {
        dtype_bytes = 4;
    }
    if (dtype_bytes == 0) {
        fprintf(stderr, "unsupported resident tensor dtype %s for %s\n",
                dtype.UTF8String,
                name.UTF8String);
        return 0;
    }

    uint64_t offset = 0;
    uint64_t size = 0;
    if (!read_json_u64_number(tensor[@"offset"],
                              "resident tensor offset",
                              0,
                              &offset) ||
        !read_json_u64_number(tensor[@"size"],
                              "resident tensor size",
                              1,
                              &size)) {
        return 0;
    }
    uint64_t layout_total = 0;
    if (!read_positive_json_u64(resident_layout,
                                @"total_bytes",
                                "resident layout total_bytes",
                                &layout_total)) {
        return 0;
    }
    uint64_t end = 0;
    if (!checked_add_u64(offset, size, &end) || end > layout_total) {
        fprintf(stderr, "resident tensor %s exceeds layout total_bytes\n",
                name.UTF8String);
        return 0;
    }

    uint64_t expected_size = (uint64_t)dtype_bytes;
    memset(out, 0, sizeof(*out));
    out->rank = shape.count;
    for (NSUInteger i = 0; i < shape.count; i++) {
        uint64_t dim = 0;
        if (!read_json_u64_number(shape[i],
                                  "resident tensor shape dimension",
                                  1,
                                  &dim)) {
            return 0;
        }
        if (dim > UINT32_MAX) {
            fprintf(stderr, "resident tensor %s shape dimension is out of range\n",
                    name.UTF8String);
            return 0;
        }
        if (!checked_mul_u64(expected_size, dim, &expected_size)) {
            fprintf(stderr, "resident tensor %s byte size overflows uint64\n",
                    name.UTF8String);
            return 0;
        }
        out->dims[i] = (uint32_t)dim;
    }
    if (size != expected_size) {
        fprintf(stderr,
                "resident tensor %s size mismatch: layout=%llu expected=%llu\n",
                name.UTF8String,
                (unsigned long long)size,
                (unsigned long long)expected_size);
        return 0;
    }

    out->offset = offset;
    out->size = size;
    snprintf(out->dtype, sizeof(out->dtype), "%s", dtype.UTF8String);
    snprintf(out->name, sizeof(out->name), "%s", name.UTF8String);
    return 1;
}

static int compare_resident_tensor_span(const void *a, const void *b) {
    const ResidentTensorSpan *lhs = (const ResidentTensorSpan *)a;
    const ResidentTensorSpan *rhs = (const ResidentTensorSpan *)b;
    if (lhs->start < rhs->start) return -1;
    if (lhs->start > rhs->start) return 1;
    if (lhs->end < rhs->end) return -1;
    if (lhs->end > rhs->end) return 1;
    return 0;
}

static int validate_resident_tensor_spans(NSDictionary *resident_layout) {
    NSArray *tensors = resident_layout[@"tensors"];
    if (![tensors isKindOfClass:[NSArray class]]) {
        fprintf(stderr, "resident layout missing tensors array\n");
        return 0;
    }
    NSUInteger count = tensors.count;
    if (count == 0) {
        fprintf(stderr, "resident layout tensors array is empty\n");
        return 0;
    }
    ResidentTensorSpan *spans = calloc(count, sizeof(ResidentTensorSpan));
    if (!spans) {
        fprintf(stderr, "failed to allocate resident tensor span table\n");
        return 0;
    }
    NSUInteger span_count = 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) {
            fprintf(stderr, "resident tensor must be a JSON object\n");
            free(spans);
            return 0;
        }
        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout,
                                            (NSDictionary *)item,
                                            &meta)) {
            free(spans);
            return 0;
        }
        spans[span_count].start = meta.offset;
        spans[span_count].end = meta.offset + meta.size;
        span_count++;
    }
    qsort(spans, span_count, sizeof(ResidentTensorSpan), compare_resident_tensor_span);
    for (NSUInteger i = 1; i < span_count; i++) {
        if (spans[i].start < spans[i - 1].end) {
            fprintf(stderr, "resident tensor byte spans overlap\n");
            free(spans);
            return 0;
        }
    }
    free(spans);
    return 1;
}

static int resident_tensor_to_router(ResidentTensorMetadata meta,
                                     RouterTensorInfo *out) {
    if (meta.rank != 2) {
        fprintf(stderr, "router tensor %s must be rank 2\n", meta.name);
        return 0;
    }
    out->offset = (NSUInteger)meta.offset;
    out->size = (NSUInteger)meta.size;
    out->num_experts = meta.dims[0];
    out->hidden_dim = meta.dims[1];
    snprintf(out->dtype, sizeof(out->dtype), "%s", meta.dtype);
    snprintf(out->name, sizeof(out->name), "%s", meta.name);
    return 1;
}

static int resident_tensor_to_vector(ResidentTensorMetadata meta,
                                     VectorTensorInfo *out) {
    if (meta.rank != 1) {
        fprintf(stderr, "resident vector tensor %s must be rank 1\n", meta.name);
        return 0;
    }
    out->offset = (NSUInteger)meta.offset;
    out->size = (NSUInteger)meta.size;
    out->dim0 = meta.dims[0];
    snprintf(out->dtype, sizeof(out->dtype), "%s", meta.dtype);
    snprintf(out->name, sizeof(out->name), "%s", meta.name);
    return 1;
}

static int resident_tensor_to_matrix(ResidentTensorMetadata meta,
                                     ResidentMatrixInfo *out) {
    if (meta.rank != 2) {
        fprintf(stderr, "resident matrix tensor %s must be rank 2\n", meta.name);
        return 0;
    }
    out->offset = (NSUInteger)meta.offset;
    out->size = (NSUInteger)meta.size;
    out->out_dim = meta.dims[0];
    out->in_dim = meta.dims[1];
    snprintf(out->dtype, sizeof(out->dtype), "%s", meta.dtype);
    snprintf(out->name, sizeof(out->name), "%s", meta.name);
    return 1;
}

static int find_router_tensor(NSDictionary *resident_layout,
                              uint64_t layer_id,
                              RouterTensorInfo *out) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) {
            continue;
        }
        int name_ok = ([name hasSuffix:@".gate.weight"] ||
                       [name containsString:@".mlp.gate.weight"]);
        if (!name_ok) continue;

        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout, tensor, &meta)) return 0;
        return resident_tensor_to_router(meta, out);
    }
    fprintf(stderr, "router tensor for layer %llu not found in resident layout\n",
            (unsigned long long)layer_id);
    return 0;
}

static ResidentMatrixInfo router_to_resident_matrix(RouterTensorInfo router) {
    ResidentMatrixInfo matrix = {0};
    matrix.offset = router.offset;
    matrix.size = router.size;
    matrix.out_dim = router.num_experts;
    matrix.in_dim = router.hidden_dim;
    snprintf(matrix.dtype, sizeof(matrix.dtype), "%s", router.dtype);
    snprintf(matrix.name, sizeof(matrix.name), "%s", router.name);
    return matrix;
}

static int find_router_bias_tensor(NSDictionary *resident_layout,
                                   uint64_t layer_id,
                                   VectorTensorInfo *out) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) {
            continue;
        }
        if (![name containsString:@".gate.e_score_correction_bias"]) continue;

        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout, tensor, &meta)) return 0;
        return resident_tensor_to_vector(meta, out);
    }
    return 0;
}

static int find_vector_tensor_by_suffix(NSDictionary *resident_layout,
                                        uint64_t layer_id,
                                        NSString *suffix,
                                        VectorTensorInfo *out) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) {
            continue;
        }
        if (![name hasSuffix:suffix]) continue;

        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout, tensor, &meta)) return 0;
        return resident_tensor_to_vector(meta, out);
    }
    return 0;
}

static int find_resident_matrix_tensor(NSDictionary *resident_layout,
                                       uint64_t layer_id,
                                       NSString *contains,
                                       NSString *suffix,
                                       ResidentMatrixInfo *out) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) {
            continue;
        }
        if (![name containsString:contains]) continue;
        if (![name hasSuffix:suffix]) continue;

        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout, tensor, &meta)) return 0;
        return resident_tensor_to_matrix(meta, out);
    }
    return 0;
}

static int find_resident_matrix_by_suffix_impl(NSDictionary *resident_layout,
                                               uint64_t layer_id,
                                               NSString *suffix,
                                               ResidentMatrixInfo *out,
                                               int report_missing) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) {
            continue;
        }
        if (![name hasSuffix:suffix]) continue;

        ResidentTensorMetadata meta = {0};
        if (!parse_resident_tensor_metadata(resident_layout, tensor, &meta)) return 0;
        return resident_tensor_to_matrix(meta, out);
    }
    if (report_missing) {
        fprintf(stderr, "resident matrix with suffix %s for layer %llu not found\n",
                suffix.UTF8String, (unsigned long long)layer_id);
    }
    return 0;
}

static int find_resident_matrix_by_suffix(NSDictionary *resident_layout,
                                          uint64_t layer_id,
                                          NSString *suffix,
                                          ResidentMatrixInfo *out) {
    return find_resident_matrix_by_suffix_impl(resident_layout, layer_id, suffix, out, 1);
}

static int find_resident_matrix_by_name(NSDictionary *resident_layout,
                                        NSString *target_name,
                                        ResidentMatrixInfo *out) {
    NSDictionary *index = resident_tensor_name_index(resident_layout);
    if (!index) return 0;
    id item = index[target_name];
    if (![item isKindOfClass:[NSDictionary class]]) return 0;
    ResidentTensorMetadata meta = {0};
    if (!parse_resident_tensor_metadata(resident_layout, (NSDictionary *)item, &meta)) return 0;
    return resident_tensor_to_matrix(meta, out);
}

static int find_resident_tensor_by_name(NSDictionary *resident_layout,
                                        NSString *target_name,
                                        ResidentTensorMetadata *out) {
    NSDictionary *index = resident_tensor_name_index(resident_layout);
    if (!index) return 0;
    id item = index[target_name];
    if (![item isKindOfClass:[NSDictionary class]]) return 0;
    return parse_resident_tensor_metadata(resident_layout, (NSDictionary *)item, out);
}

static int find_resident_tensor_by_suffix(NSDictionary *resident_layout,
                                          uint64_t layer_id,
                                          NSString *suffix,
                                          ResidentTensorMetadata *out,
                                          int report_missing) {
    NSArray *tensors = resident_tensors_for_layer(resident_layout, layer_id);
    if (!tensors) return 0;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]]) continue;
        if (![name hasSuffix:suffix]) continue;
        return parse_resident_tensor_metadata(resident_layout, tensor, out);
    }
    if (report_missing) {
        fprintf(stderr, "resident tensor with suffix %s for layer %llu not found\n",
                suffix.UTF8String, (unsigned long long)layer_id);
    }
    return 0;
}

static int resident_matrix_is_affine_int4_weight(ResidentMatrixInfo matrix) {
    return strcmp(matrix.dtype, "U32") == 0 ||
           strcmp(matrix.dtype, "uint32") == 0 ||
           strcmp(matrix.dtype, "UINT32") == 0;
}

static int resident_matrix_is_mxfp4_scale(ResidentMatrixInfo matrix) {
    return strcmp(matrix.dtype, "U8") == 0 ||
           strcmp(matrix.dtype, "uint8") == 0 ||
           strcmp(matrix.dtype, "UINT8") == 0;
}

static int resident_tensor_is_u32(ResidentTensorMetadata tensor) {
    return strcmp(tensor.dtype, "U32") == 0 ||
           strcmp(tensor.dtype, "uint32") == 0 ||
           strcmp(tensor.dtype, "UINT32") == 0;
}

static int resident_tensor_is_u8(ResidentTensorMetadata tensor) {
    return strcmp(tensor.dtype, "U8") == 0 ||
           strcmp(tensor.dtype, "uint8") == 0 ||
           strcmp(tensor.dtype, "UINT8") == 0;
}

static int resident_tensor_f32_convertible(ResidentTensorMetadata tensor) {
    return strcmp(tensor.dtype, "F32") == 0 ||
           strcmp(tensor.dtype, "float32") == 0 ||
           strcmp(tensor.dtype, "FLOAT32") == 0 ||
           strcmp(tensor.dtype, "BF16") == 0 ||
           strcmp(tensor.dtype, "bfloat16") == 0 ||
           strcmp(tensor.dtype, "BFLOAT16") == 0 ||
           strcmp(tensor.dtype, "F16") == 0 ||
           strcmp(tensor.dtype, "float16") == 0 ||
           strcmp(tensor.dtype, "FLOAT16") == 0;
}

static int resident_tensor_value_count(ResidentTensorMetadata tensor,
                                       uint64_t *out_count) {
    uint64_t count = 1;
    for (NSUInteger i = 0; i < tensor.rank; i++) {
        if (!checked_mul_u64(count, tensor.dims[i], &count)) {
            fprintf(stderr, "resident tensor %s value count overflows uint64\n",
                    tensor.name);
            return 0;
        }
    }
    *out_count = count;
    return 1;
}

static int resident_tensor3d_f32_bytes(ResidentTensor3DInfo info,
                                       uint64_t *out_bytes) {
    uint64_t d01 = 0;
    uint64_t count = 0;
    if (!checked_mul_u64((uint64_t)info.dim0, (uint64_t)info.dim1, &d01) ||
        !checked_mul_u64(d01, (uint64_t)info.dim2, &count) ||
        !checked_mul_u64(count, sizeof(float), out_bytes)) {
        fprintf(stderr, "resident tensor %s f32 byte size overflows uint64\n",
                info.name);
        return 0;
    }
    return 1;
}

static int validate_resident_affine_int4_matrix(ResidentAffineInt4MatrixInfo *info) {
    if (!resident_matrix_is_affine_int4_weight(info->weight)) {
        fprintf(stderr, "resident affine-int4 weight %s must have U32 dtype\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.out_dim == 0 || info->weight.in_dim == 0) {
        fprintf(stderr, "resident affine-int4 weight %s has zero dimension [%u,%u]\n",
                info->weight.name,
                info->weight.out_dim,
                info->weight.in_dim);
        return 0;
    }
    uint64_t weight_values = 0;
    uint64_t expected_weight_bytes = 0;
    if (!checked_mul_u64((uint64_t)info->weight.out_dim,
                         (uint64_t)info->weight.in_dim,
                         &weight_values) ||
        !checked_mul_u64(weight_values, sizeof(uint32_t), &expected_weight_bytes)) {
        fprintf(stderr, "resident affine-int4 weight %s byte size overflows uint64\n",
                info->weight.name);
        return 0;
    }
    if (expected_weight_bytes != (uint64_t)info->weight.size) {
        fprintf(stderr,
                "resident affine-int4 weight %s size mismatch: layout=%llu expected=%llu\n",
                info->weight.name,
                (unsigned long long)info->weight.size,
                (unsigned long long)expected_weight_bytes);
        return 0;
    }
    if (!validate_resident_matrix(info->scales) ||
        !validate_resident_matrix(info->biases)) {
        return 0;
    }
    if (!affine_meta_dtype_mode(info->scales.dtype,
                                info->biases.dtype,
                                &info->meta_dtype)) {
        return 0;
    }
    if (info->scales.out_dim != info->weight.out_dim ||
        info->biases.out_dim != info->weight.out_dim ||
        info->scales.in_dim == 0 ||
        info->biases.in_dim != info->scales.in_dim) {
        fprintf(stderr,
                "resident affine-int4 metadata shapes for %s must be [out_dim, groups]\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.in_dim > UINT32_MAX / 8u) {
        fprintf(stderr, "resident affine-int4 logical input dim overflows uint32 for %s\n",
                info->weight.name);
        return 0;
    }
    uint32_t in_dim = info->weight.in_dim * 8u;
    uint32_t groups = info->scales.in_dim;
    if (groups == 0 || in_dim % groups != 0) {
        fprintf(stderr,
                "resident affine-int4 metadata groups for %s do not divide logical input dim %u\n",
                info->weight.name,
                in_dim);
        return 0;
    }
    uint32_t group_size = in_dim / groups;
    if (group_size == 0 || group_size % 8u != 0) {
        fprintf(stderr,
                "resident affine-int4 group size for %s must be a positive multiple of 8, got %u\n",
                info->weight.name,
                group_size);
        return 0;
    }
    uint64_t ws = 0;
    uint64_t total = 0;
    if (!checked_add_u64((uint64_t)info->weight.size,
                         (uint64_t)info->scales.size,
                         &ws) ||
        !checked_add_u64(ws,
                         (uint64_t)info->biases.size,
                         &total)) {
        fprintf(stderr, "resident affine-int4 total bytes overflow for %s\n",
                info->weight.name);
        return 0;
    }
    info->out_dim = info->weight.out_dim;
    info->in_dim = in_dim;
    info->group_size = group_size;
    info->total_bytes = total;
    snprintf(info->name, sizeof(info->name), "%s", info->weight.name);
    return 1;
}

static int find_resident_affine_int4_matrix(NSDictionary *resident_layout,
                                            ResidentMatrixInfo weight,
                                            ResidentAffineInt4MatrixInfo *out) {
    if (!resident_matrix_is_affine_int4_weight(weight)) return 0;
    NSString *weight_name = [NSString stringWithUTF8String:weight.name];
    if (![weight_name hasSuffix:@".weight"]) {
        fprintf(stderr, "resident affine-int4 tensor %s must end with .weight\n",
                weight.name);
        return 0;
    }
    NSString *base = [weight_name substringToIndex:(weight_name.length - 7)];
    NSString *scale_name = [base stringByAppendingString:@".scales"];
    NSString *bias_name = [base stringByAppendingString:@".biases"];
    ResidentAffineInt4MatrixInfo info = {0};
    info.weight = weight;
    if (!find_resident_matrix_by_name(resident_layout, scale_name, &info.scales)) {
        fprintf(stderr, "resident affine-int4 matrix %s missing companion %s\n",
                weight.name,
                scale_name.UTF8String);
        return 0;
    }
    if (!find_resident_matrix_by_name(resident_layout, bias_name, &info.biases)) {
        fprintf(stderr, "resident affine-int4 matrix %s missing companion %s\n",
                weight.name,
                bias_name.UTF8String);
        return 0;
    }
    if (!validate_resident_affine_int4_matrix(&info)) return 0;
    *out = info;
    return 1;
}

static int validate_resident_mxfp4_matrix(ResidentMxfp4MatrixInfo *info) {
    if (!resident_matrix_is_affine_int4_weight(info->weight)) {
        fprintf(stderr, "resident MXFP4 weight %s must have U32 dtype\n",
                info->weight.name);
        return 0;
    }
    if (!resident_matrix_is_mxfp4_scale(info->scales)) {
        fprintf(stderr, "resident MXFP4 scales for %s must have U8 dtype\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.out_dim == 0 || info->weight.in_dim == 0) {
        fprintf(stderr, "resident MXFP4 weight %s has zero dimension [%u,%u]\n",
                info->weight.name,
                info->weight.out_dim,
                info->weight.in_dim);
        return 0;
    }
    uint64_t weight_values = 0;
    uint64_t expected_weight_bytes = 0;
    if (!checked_mul_u64((uint64_t)info->weight.out_dim,
                         (uint64_t)info->weight.in_dim,
                         &weight_values) ||
        !checked_mul_u64(weight_values, sizeof(uint32_t), &expected_weight_bytes)) {
        fprintf(stderr, "resident MXFP4 weight %s byte size overflows uint64\n",
                info->weight.name);
        return 0;
    }
    if (expected_weight_bytes != (uint64_t)info->weight.size) {
        fprintf(stderr,
                "resident MXFP4 weight %s size mismatch: layout=%llu expected=%llu\n",
                info->weight.name,
                (unsigned long long)info->weight.size,
                (unsigned long long)expected_weight_bytes);
        return 0;
    }
    if (!validate_resident_matrix(info->scales)) {
        return 0;
    }
    if (info->scales.out_dim != info->weight.out_dim ||
        info->scales.in_dim == 0) {
        fprintf(stderr,
                "resident MXFP4 scale shape for %s must be [out_dim, groups]\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.in_dim > UINT32_MAX / 8u) {
        fprintf(stderr, "resident MXFP4 logical input dim overflows uint32 for %s\n",
                info->weight.name);
        return 0;
    }
    uint32_t in_dim = info->weight.in_dim * 8u;
    uint32_t groups = info->scales.in_dim;
    if (groups == 0 || in_dim % groups != 0) {
        fprintf(stderr,
                "resident MXFP4 groups for %s do not divide logical input dim %u\n",
                info->weight.name,
                in_dim);
        return 0;
    }
    uint32_t group_size = in_dim / groups;
    if (group_size == 0 || group_size % 8u != 0) {
        fprintf(stderr,
                "resident MXFP4 group size for %s must be a positive multiple of 8, got %u\n",
                info->weight.name,
                group_size);
        return 0;
    }
    uint64_t total = 0;
    if (!checked_add_u64((uint64_t)info->weight.size,
                         (uint64_t)info->scales.size,
                         &total)) {
        fprintf(stderr, "resident MXFP4 total bytes overflow for %s\n",
                info->weight.name);
        return 0;
    }
    info->out_dim = info->weight.out_dim;
    info->in_dim = in_dim;
    info->group_size = group_size;
    info->total_bytes = total;
    snprintf(info->name, sizeof(info->name), "%s", info->weight.name);
    return 1;
}

static int find_resident_mxfp4_matrix(NSDictionary *resident_layout,
                                      ResidentMatrixInfo weight,
                                      ResidentMxfp4MatrixInfo *out) {
    if (!resident_matrix_is_affine_int4_weight(weight)) return 0;
    NSString *weight_name = [NSString stringWithUTF8String:weight.name];
    if (![weight_name hasSuffix:@".weight"]) {
        fprintf(stderr, "resident MXFP4 tensor %s must end with .weight\n",
                weight.name);
        return 0;
    }
    NSString *base = [weight_name substringToIndex:(weight_name.length - 7)];
    NSString *scale_name = [base stringByAppendingString:@".scales"];
    NSString *bias_name = [base stringByAppendingString:@".biases"];
    ResidentMxfp4MatrixInfo info = {0};
    info.weight = weight;
    if (!find_resident_matrix_by_name(resident_layout, scale_name, &info.scales)) {
        return 0;
    }
    if (!resident_matrix_is_mxfp4_scale(info.scales)) {
        return 0;
    }
    ResidentMatrixInfo ignored_bias = {0};
    if (find_resident_matrix_by_name(resident_layout, bias_name, &ignored_bias)) {
        fprintf(stderr, "resident MXFP4 matrix %s must not have companion %s\n",
                weight.name,
                bias_name.UTF8String);
        return 0;
    }
    if (!validate_resident_mxfp4_matrix(&info)) return 0;
    *out = info;
    return 1;
}

static int validate_resident_tensor3d_dense(ResidentTensor3DInfo *info) {
    if (info->weight.rank != 3) {
        fprintf(stderr, "resident tensor %s must be rank 3\n", info->weight.name);
        return 0;
    }
    if (!resident_tensor_f32_convertible(info->weight)) {
        fprintf(stderr, "unsupported resident 3D tensor dtype %s for %s\n",
                info->weight.dtype,
                info->weight.name);
        return 0;
    }
    info->dim0 = info->weight.dims[0];
    info->dim1 = info->weight.dims[1];
    info->dim2 = info->weight.dims[2];
    info->group_size = 0;
    info->total_bytes = info->weight.size;
    info->is_mxfp4 = 0;
    snprintf(info->name, sizeof(info->name), "%s", info->weight.name);
    return 1;
}

static int validate_resident_tensor3d_mxfp4(ResidentTensor3DInfo *info) {
    if (!resident_tensor_is_u32(info->weight)) {
        fprintf(stderr, "resident MXFP4 tensor %s must have U32 dtype\n",
                info->weight.name);
        return 0;
    }
    if (!resident_tensor_is_u8(info->scales)) {
        fprintf(stderr, "resident MXFP4 scales for %s must have U8 dtype\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.rank != 3 || info->scales.rank != 3) {
        fprintf(stderr, "resident MXFP4 tensor %s and scales must be rank 3\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.dims[0] != info->scales.dims[0] ||
        info->weight.dims[1] != info->scales.dims[1] ||
        info->scales.dims[2] == 0) {
        fprintf(stderr,
                "resident MXFP4 scale shape for %s must match first two dims and have groups\n",
                info->weight.name);
        return 0;
    }
    if (info->weight.dims[2] > UINT32_MAX / 8u) {
        fprintf(stderr, "resident MXFP4 logical last dim overflows uint32 for %s\n",
                info->weight.name);
        return 0;
    }
    uint32_t logical_last = info->weight.dims[2] * 8u;
    uint32_t groups = info->scales.dims[2];
    if (groups == 0 || logical_last % groups != 0) {
        fprintf(stderr,
                "resident MXFP4 groups for %s do not divide logical dim %u\n",
                info->weight.name,
                logical_last);
        return 0;
    }
    uint32_t group_size = logical_last / groups;
    if (group_size == 0 || group_size % 8u != 0) {
        fprintf(stderr,
                "resident MXFP4 group size for %s must be a positive multiple of 8, got %u\n",
                info->weight.name,
                group_size);
        return 0;
    }
    uint64_t total = 0;
    if (!checked_add_u64(info->weight.size, info->scales.size, &total)) {
        fprintf(stderr, "resident MXFP4 total bytes overflow for %s\n",
                info->weight.name);
        return 0;
    }
    info->dim0 = info->weight.dims[0];
    info->dim1 = info->weight.dims[1];
    info->dim2 = logical_last;
    info->group_size = group_size;
    info->total_bytes = total;
    info->is_mxfp4 = 1;
    snprintf(info->name, sizeof(info->name), "%s", info->weight.name);
    return 1;
}

static int find_resident_tensor3d_by_suffix(NSDictionary *resident_layout,
                                            uint64_t layer_id,
                                            NSString *suffix,
                                            ResidentTensor3DInfo *out,
                                            int report_missing) {
    ResidentTensorMetadata weight = {0};
    if (!find_resident_tensor_by_suffix(resident_layout,
                                        layer_id,
                                        suffix,
                                        &weight,
                                        report_missing)) {
        return 0;
    }
    ResidentTensor3DInfo info = {0};
    info.weight = weight;
    if (resident_tensor_is_u32(weight)) {
        NSString *weight_name = [NSString stringWithUTF8String:weight.name];
        if (![weight_name hasSuffix:@".weight"]) {
            fprintf(stderr, "resident MXFP4 tensor %s must end with .weight\n",
                    weight.name);
            return 0;
        }
        NSString *base = [weight_name substringToIndex:(weight_name.length - 7)];
        NSString *scale_name = [base stringByAppendingString:@".scales"];
        NSString *bias_name = [base stringByAppendingString:@".biases"];
        if (!find_resident_tensor_by_name(resident_layout, scale_name, &info.scales)) {
            fprintf(stderr, "resident MXFP4 tensor %s missing companion %s\n",
                    weight.name,
                    scale_name.UTF8String);
            return 0;
        }
        ResidentTensorMetadata ignored_bias = {0};
        if (find_resident_tensor_by_name(resident_layout, bias_name, &ignored_bias)) {
            fprintf(stderr, "resident MXFP4 tensor %s must not have companion %s\n",
                    weight.name,
                    bias_name.UTF8String);
            return 0;
        }
        if (!validate_resident_tensor3d_mxfp4(&info)) return 0;
    } else {
        if (!validate_resident_tensor3d_dense(&info)) return 0;
    }
    *out = info;
    return 1;
}

static int find_global_matrix_by_suffixes(NSDictionary *resident_layout,
                                          NSArray<NSString *> *suffixes,
                                          ResidentMatrixInfo *out,
                                          int required,
                                          const char *label) {
    NSArray *tensors = resident_layout[@"tensors"];
    if (![tensors isKindOfClass:[NSArray class]]) {
        fprintf(stderr, "resident layout missing tensors array\n");
        return 0;
    }
    NSDictionary *best = nil;
    NSString *best_name = nil;
    for (id item in tensors) {
        if (![item isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *tensor = (NSDictionary *)item;
        NSString *name = tensor[@"name"];
        if (![name isKindOfClass:[NSString class]] ||
            [name containsString:@".layers."]) {
            continue;
        }
        int suffix_ok = 0;
        for (NSString *suffix in suffixes) {
            if ([name hasSuffix:suffix]) {
                suffix_ok = 1;
                break;
            }
        }
        if (!suffix_ok) continue;
        if (!best_name || name.length < best_name.length) {
            best = tensor;
            best_name = name;
        }
    }
    if (!best) {
        if (required) fprintf(stderr, "%s tensor not found\n", label);
        return 0;
    }
    NSString *dtype = best[@"dtype"];
    if (![dtype isKindOfClass:[NSString class]]) {
        fprintf(stderr, "%s tensor has invalid metadata\n", label);
        return 0;
    }
    ResidentTensorMetadata meta = {0};
    if (!parse_resident_tensor_metadata(resident_layout, best, &meta)) return 0;
    return resident_tensor_to_matrix(meta, out);
}

