    }
    ResidentTensorMetadata meta = {0};
    if (!parse_resident_tensor_metadata(resident_layout, best, &meta)) return 0;
    return resident_tensor_to_vector(meta, out);
}

static int matrix_dtype_bytes(const char *dtype) {
    if (strcmp(dtype, "F32") == 0 || strcmp(dtype, "float32") == 0 ||
        strcmp(dtype, "FLOAT32") == 0) return 4;
    if (strcmp(dtype, "BF16") == 0 || strcmp(dtype, "bfloat16") == 0 ||
        strcmp(dtype, "BFLOAT16") == 0) return 2;
    if (strcmp(dtype, "F16") == 0 || strcmp(dtype, "float16") == 0 ||
        strcmp(dtype, "FLOAT16") == 0) return 2;
    if (strcmp(dtype, "U8") == 0 || strcmp(dtype, "uint8") == 0 ||
        strcmp(dtype, "UINT8") == 0) return 1;
    return 0;
}

static int validate_decode_cache_file_size(NSString *cache_file_path,
                                           uint64_t expected_bytes) {
    static NSMutableSet *validated_file_size_cache = nil;
    if (!validated_file_size_cache) validated_file_size_cache = [NSMutableSet set];
    NSString *path_key = [cache_file_path stringByStandardizingPath];
    NSString *cache_key = [NSString stringWithFormat:@"%@:%llu",
                           path_key,
                           (unsigned long long)expected_bytes];
    if ([validated_file_size_cache containsObject:cache_key]) return 1;

    struct stat st;
    if (stat(cache_file_path.UTF8String, &st) != 0) {
        fprintf(stderr, "stat failed for decode cache file %s: %s\n",
                cache_file_path.UTF8String,
                strerror(errno));
        return 0;
    }
    if (st.st_size < 0) {
        fprintf(stderr, "decode cache file %s has invalid size\n",
                cache_file_path.UTF8String);
        return 0;
    }
    uint64_t actual = (uint64_t)st.st_size;
    if (actual != expected_bytes) {
        fprintf(stderr,
                "decode cache file size %llu does not match layout total_bytes %llu\n",
                (unsigned long long)actual,
                (unsigned long long)expected_bytes);
        return 0;
    }
    [validated_file_size_cache addObject:cache_key];
    return 1;
}

static int parse_decode_cache_segment(NSDictionary *segment,
                                      uint64_t layout_total_bytes,
                                      NSString *layout_dtype,
                                      uint64_t layout_dtype_bytes,
                                      CacheSegmentInfo *out) {
    NSString *kind = segment[@"kind"];
    NSString *dtype = segment[@"dtype"];
    if (![kind isKindOfClass:[NSString class]] ||
        ![dtype isKindOfClass:[NSString class]]) {
        fprintf(stderr, "cache segment missing kind or dtype\n");
        return 0;
    }
    if (!([kind isEqualToString:@"mla_kv"] ||
          [kind isEqualToString:@"dsa_index"])) {
        fprintf(stderr, "unsupported cache segment kind %s\n", kind.UTF8String);
        return 0;
    }
    if (![dtype isEqualToString:layout_dtype]) {
        fprintf(stderr, "cache segment dtype does not match layout dtype\n");
        return 0;
    }

    uint64_t layer = 0;
    uint64_t offset = 0;
    uint64_t width = 0;
    uint64_t dtype_bytes = 0;
    uint64_t token_stride_bytes = 0;
    uint64_t max_context_tokens = 0;
    uint64_t total_bytes = 0;
    if (!read_nonnegative_json_u64(segment, @"layer", "cache segment layer", &layer) ||
        !read_nonnegative_json_u64(segment, @"offset", "cache segment offset", &offset) ||
        !read_positive_json_u64(segment, @"width", "cache segment width", &width) ||
        !read_positive_json_u64(segment, @"dtype_bytes",
                                "cache segment dtype_bytes", &dtype_bytes) ||
        !read_positive_json_u64(segment, @"token_stride_bytes",
                                "cache segment token_stride_bytes",
                                &token_stride_bytes) ||
        !read_positive_json_u64(segment, @"max_context_tokens",
                                "cache segment max_context_tokens",
                                &max_context_tokens) ||
        !read_positive_json_u64(segment, @"total_bytes",
                                "cache segment total_bytes", &total_bytes)) {
        return 0;
    }
    if (width > UINT32_MAX || dtype_bytes > UINT32_MAX) {
        fprintf(stderr, "cache segment width or dtype_bytes is out of range\n");
        return 0;
    }
    int expected_dtype_bytes = matrix_dtype_bytes(dtype.UTF8String);
    if (expected_dtype_bytes == 0 ||
        dtype_bytes != (uint64_t)expected_dtype_bytes ||
        dtype_bytes != layout_dtype_bytes) {
        fprintf(stderr, "cache segment dtype_bytes does not match dtype\n");
        return 0;
    }
    uint64_t expected_stride = 0;
    if (!checked_mul_u64(width, dtype_bytes, &expected_stride)) {
        fprintf(stderr, "cache segment token stride overflows uint64\n");
        return 0;
    }
    if (token_stride_bytes != expected_stride) {
        fprintf(stderr, "cache segment token_stride_bytes does not match width*dtype_bytes\n");
        return 0;
    }
    uint64_t expected_total = 0;
    if (!checked_mul_u64(token_stride_bytes, max_context_tokens, &expected_total)) {
        fprintf(stderr, "cache segment total byte size overflows uint64\n");
        return 0;
    }
    if (total_bytes != expected_total) {
        fprintf(stderr, "cache segment total_bytes does not match stride*max_context_tokens\n");
        return 0;
    }
    uint64_t segment_end = 0;
    if (!checked_add_u64(offset, total_bytes, &segment_end) ||
        segment_end > layout_total_bytes) {
        fprintf(stderr, "cache segment exceeds layout total_bytes\n");
        return 0;
    }

    memset(out, 0, sizeof(*out));
    out->layer = layer;
    out->offset = offset;
    out->total_bytes = total_bytes;
    out->max_context_tokens = max_context_tokens;
    out->width = (uint32_t)width;
    out->dtype_bytes = (uint32_t)dtype_bytes;
    snprintf(out->dtype, sizeof(out->dtype), "%s", dtype.UTF8String);
    snprintf(out->kind, sizeof(out->kind), "%s", kind.UTF8String);
    return 1;
}

static NSMutableDictionary *decode_cache_segment_index_cache(void) {
    static NSMutableDictionary *cache = nil;
    if (!cache) cache = [NSMutableDictionary dictionary];
    return cache;
}

static NSString *decode_cache_layout_key(NSDictionary *cache_layout) {
    return [NSString stringWithFormat:@"%p", (void *)cache_layout];
}

static int validate_decode_cache_layout(NSDictionary *cache_layout,
                                        uint64_t max_cache_file_bytes,
                                        uint64_t *out_total_bytes) {
    static NSMutableDictionary *validated_layout_cache = nil;
    if (!validated_layout_cache) validated_layout_cache = [NSMutableDictionary dictionary];
    NSString *layout_key = decode_cache_layout_key(cache_layout);
    NSString *validation_key = [NSString stringWithFormat:@"%@:%llu",
                                layout_key,
                                (unsigned long long)max_cache_file_bytes];
    NSNumber *cached_total = validated_layout_cache[validation_key];
    if (cached_total) {
        if (out_total_bytes) *out_total_bytes = cached_total.unsignedLongLongValue;
        return 1;
    }

    uint64_t total_bytes = 0;
    uint64_t version = 0;
    uint64_t dtype_bytes = 0;
    uint64_t max_context_tokens = 0;
    uint64_t alignment = 0;
    if (!read_positive_json_u64(cache_layout, @"version",
                                "cache layout version", &version) ||
        !read_positive_json_u64(cache_layout, @"total_bytes",
                                "cache layout total_bytes", &total_bytes) ||
        !read_positive_json_u64(cache_layout, @"dtype_bytes",
                                "cache layout dtype_bytes", &dtype_bytes) ||
        !read_positive_json_u64(cache_layout, @"max_context_tokens",
                                "cache layout max_context_tokens",
                                &max_context_tokens) ||
        !read_positive_json_u64(cache_layout, @"alignment",
                                "cache layout alignment", &alignment)) {
        return 0;
    }
    if (version != 1) {
        fprintf(stderr, "unsupported cache layout version %llu\n",
                (unsigned long long)version);
        return 0;
    }
    NSString *model_type = cache_layout[@"model_type"];
    if (![model_type isKindOfClass:[NSString class]] || model_type.length == 0) {
        fprintf(stderr, "cache layout missing model_type\n");
        return 0;
    }
    NSString *layout_dtype = cache_layout[@"dtype"];
    if (![layout_dtype isKindOfClass:[NSString class]]) {
        fprintf(stderr, "cache layout missing dtype\n");
        return 0;
    }
    int expected_dtype_bytes = matrix_dtype_bytes(layout_dtype.UTF8String);
    if (expected_dtype_bytes == 0 ||
        dtype_bytes != (uint64_t)expected_dtype_bytes) {
        fprintf(stderr, "cache layout dtype_bytes does not match dtype\n");
        return 0;
    }
    if (total_bytes > max_cache_file_bytes) {
        fprintf(stderr, "cache layout total %llu bytes exceeds limit %llu\n",
                (unsigned long long)total_bytes,
                (unsigned long long)max_cache_file_bytes);
        return 0;
    }
    NSArray *segments = cache_layout[@"segments"];
    if (![segments isKindOfClass:[NSArray class]] || segments.count == 0) {
        fprintf(stderr, "cache layout missing segments array\n");
        return 0;
    }
    NSMutableSet *seen = [NSMutableSet setWithCapacity:segments.count];
    NSMutableDictionary *segment_index =
        [NSMutableDictionary dictionaryWithCapacity:segments.count];
    for (id item in segments) {
        if (![item isKindOfClass:[NSDictionary class]]) {
            fprintf(stderr, "cache segment must be a JSON object\n");
            return 0;
        }
        CacheSegmentInfo segment = {0};
        if (!parse_decode_cache_segment((NSDictionary *)item,
                                        total_bytes,
                                        layout_dtype,
                                        dtype_bytes,
                                        &segment)) {
            return 0;
        }
        NSString *key = [NSString stringWithFormat:@"%s:%llu",
                         segment.kind,
                         (unsigned long long)segment.layer];
        if ([seen containsObject:key]) {
            fprintf(stderr, "duplicate cache segment %s\n", key.UTF8String);
            return 0;
        }
        [seen addObject:key];
        segment_index[key] =
            [NSValue valueWithBytes:&segment objCType:@encode(CacheSegmentInfo)];
    }
    decode_cache_segment_index_cache()[layout_key] = [segment_index copy];
    validated_layout_cache[validation_key] =
        [NSNumber numberWithUnsignedLongLong:total_bytes];
    if (out_total_bytes) *out_total_bytes = total_bytes;
    return 1;
}

static int validate_decode_cache_backing(NSString *cache_layout_path,
                                         NSString *cache_file_path,
                                         uint64_t max_cache_file_bytes) {
    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 0;
    uint64_t total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &total_bytes)) {
        return 0;
    }
    return validate_decode_cache_file_size(cache_file_path, total_bytes);
}

static int validate_resident_matrix(ResidentMatrixInfo matrix) {
    int bytes_per_value = matrix_dtype_bytes(matrix.dtype);
    if (!bytes_per_value) {
        fprintf(stderr, "unsupported resident matrix dtype %s for %s\n",
                matrix.dtype, matrix.name);
        return 0;
    }
    if (matrix.out_dim == 0 || matrix.in_dim == 0) {
        fprintf(stderr, "resident matrix %s has zero dimension [%u,%u]\n",
                matrix.name,
                matrix.out_dim,
                matrix.in_dim);
        return 0;
    }
    uint64_t row_bytes = (uint64_t)matrix.in_dim * (uint64_t)bytes_per_value;
    if ((uint64_t)matrix.out_dim > UINT64_MAX / row_bytes) {
        fprintf(stderr, "resident matrix %s byte size overflows uint64\n",
                matrix.name);
        return 0;
    }
    uint64_t expected = (uint64_t)matrix.out_dim * row_bytes;
    if (expected != matrix.size) {
        fprintf(stderr, "resident matrix %s size mismatch: layout=%llu expected=%llu\n",
                matrix.name,
                (unsigned long long)matrix.size,
                (unsigned long long)expected);
        return 0;
    }
    return 1;
}

static int enforce_resident_matrix_limit(ResidentMatrixInfo matrix,
                                         uint64_t max_matrix_bytes) {
    if (matrix.size > max_matrix_bytes) {
        fprintf(stderr, "resident matrix %s has %llu bytes, exceeds limit %llu\n",
                matrix.name,
                (unsigned long long)matrix.size,
                (unsigned long long)max_matrix_bytes);
        return 0;
    }
    return 1;
}

static int enforce_resident_tensor3d_limit(ResidentTensor3DInfo tensor,
                                           uint64_t max_matrix_bytes) {
    if (tensor.total_bytes > max_matrix_bytes) {
        fprintf(stderr, "resident tensor %s has %llu bytes, exceeds limit %llu\n",
                tensor.name,
                (unsigned long long)tensor.total_bytes,
                (unsigned long long)max_matrix_bytes);
        return 0;
    }
    return 1;
}

static int enforce_resident_tensor3d_f32_limit(ResidentTensor3DInfo tensor,
                                               uint64_t max_matrix_bytes) {
    uint64_t f32_bytes = 0;
    if (!resident_tensor3d_f32_bytes(tensor, &f32_bytes)) return 0;
    if (f32_bytes > max_matrix_bytes) {
        fprintf(stderr,
                "resident tensor %s f32 expansion has %llu bytes, exceeds limit %llu\n",
                tensor.name,
                (unsigned long long)f32_bytes,
                (unsigned long long)max_matrix_bytes);
        return 0;
    }
    return 1;
}

static int enforce_shared_component_matrix_limit(const char *label,
                                                 ResidentMatrixInfo matrix,
                                                 ResidentAffineInt4MatrixInfo affine,
                                                 ResidentMxfp4MatrixInfo mxfp4,
                                                 int is_affine_int4,
                                                 int is_mxfp4,
                                                 uint64_t max_matrix_bytes) {
    uint64_t size = is_mxfp4 ? mxfp4.total_bytes
                             : (is_affine_int4 ? affine.total_bytes : matrix.size);
    const char *name = is_mxfp4 ? mxfp4.name
                                : (is_affine_int4 ? affine.name : matrix.name);
    if (size > max_matrix_bytes) {
        fprintf(stderr,
                "resident %s matrix %s has %llu bytes, exceeds limit %llu\n",
                label,
                name,
                (unsigned long long)size,
                (unsigned long long)max_matrix_bytes);
        return 0;
    }
    return 1;
}

static int enforce_resident_linear_limit(const char *label,
                                         ResidentMatrixInfo matrix,
                                         ResidentAffineInt4MatrixInfo affine,
                                         ResidentMxfp4MatrixInfo mxfp4,
                                         int is_affine_int4,
                                         int is_mxfp4,
                                         uint64_t max_matrix_bytes) {
    return enforce_shared_component_matrix_limit(label,
                                                 matrix,
                                                 affine,
                                                 mxfp4,
                                                 is_affine_int4,
                                                 is_mxfp4,
                                                 max_matrix_bytes);
}

static void update_max_matrix_alloc_bytes(uint64_t *max_bytes, uint64_t matrix_bytes) {
    uint64_t aligned = align_up_u64(matrix_bytes, 2 * 1024 * 1024);
    if (aligned > *max_bytes) *max_bytes = aligned;
}

static int parse_shared_component_matrix(NSDictionary *resident_layout,
                                         ResidentMatrixInfo matrix,
                                         ResidentAffineInt4MatrixInfo *affine,
                                         ResidentMxfp4MatrixInfo *mxfp4,
                                         int *is_affine,
                                         int *is_mxfp4,
                                         uint32_t *out_dim,
                                         uint32_t *in_dim,
                                         uint64_t *storage_bytes) {
    *is_affine = 0;
    *is_mxfp4 = 0;
    if (resident_matrix_is_affine_int4_weight(matrix)) {
        if (find_resident_mxfp4_matrix(resident_layout, matrix, mxfp4)) {
            *is_mxfp4 = 1;
            *out_dim = mxfp4->out_dim;
            *in_dim = mxfp4->in_dim;
            *storage_bytes = mxfp4->total_bytes;
            return 1;
        }
        if (find_resident_affine_int4_matrix(resident_layout, matrix, affine)) {
            *is_affine = 1;
            *out_dim = affine->out_dim;
            *in_dim = affine->in_dim;
            *storage_bytes = affine->total_bytes;
            return 1;
        }
        return 0;
    }
    if (!validate_resident_matrix(matrix)) return 0;
    *out_dim = matrix.out_dim;
    *in_dim = matrix.in_dim;
    *storage_bytes = matrix.size;
    return 1;
}

static int parse_shared_expert_layout(NSDictionary *resident_layout,
                                      uint64_t layer_id,
                                      SharedExpertInfo *out) {
    memset(out, 0, sizeof(*out));
    int plural_ok =
        find_resident_matrix_tensor(resident_layout, layer_id,
                                    @".shared_experts.", @".gate_proj.weight", &out->gate) &&
        find_resident_matrix_tensor(resident_layout, layer_id,
                                    @".shared_experts.", @".up_proj.weight", &out->up) &&
        find_resident_matrix_tensor(resident_layout, layer_id,
                                    @".shared_experts.", @".down_proj.weight", &out->down);
    if (!plural_ok) {
        memset(out, 0, sizeof(*out));
        if (!(find_resident_matrix_tensor(resident_layout, layer_id,
                                          @".shared_expert.", @".gate_proj.weight", &out->gate) &&
              find_resident_matrix_tensor(resident_layout, layer_id,
                                          @".shared_expert.", @".up_proj.weight", &out->up) &&
              find_resident_matrix_tensor(resident_layout, layer_id,
                                          @".shared_expert.", @".down_proj.weight", &out->down))) {
            fprintf(stderr, "shared expert tensors for layer %llu not found\n",
                    (unsigned long long)layer_id);
            return 0;
        }
    }
    uint32_t gate_out = 0;
    uint32_t gate_in = 0;
    uint32_t up_out = 0;
    uint32_t up_in = 0;
    uint32_t down_out = 0;
    uint32_t down_in = 0;
    uint64_t gate_bytes = 0;
    uint64_t up_bytes = 0;
    uint64_t down_bytes = 0;
    if (!parse_shared_component_matrix(resident_layout,
                                       out->gate,
                                       &out->gate_affine,
                                       &out->gate_mxfp4,
                                       &out->gate_is_affine_int4,
                                       &out->gate_is_mxfp4,
                                       &gate_out,
                                       &gate_in,
                                       &gate_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->up,
                                       &out->up_affine,
                                       &out->up_mxfp4,
                                       &out->up_is_affine_int4,
                                       &out->up_is_mxfp4,
                                       &up_out,
                                       &up_in,
                                       &up_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->down,
                                       &out->down_affine,
                                       &out->down_mxfp4,
                                       &out->down_is_affine_int4,
                                       &out->down_is_mxfp4,
                                       &down_out,
                                       &down_in,
                                       &down_bytes)) {
        return 0;
    }
    if (gate_out != up_out ||
        gate_in != up_in ||
        down_out != gate_in ||
        down_in != gate_out) {
        fprintf(stderr,
                "shared expert shapes are inconsistent: gate=[%u,%u] "
                "up=[%u,%u] down=[%u,%u]\n",
                gate_out, gate_in,
                up_out, up_in,
                down_out, down_in);
        return 0;
    }
    out->hidden_dim = gate_in;
    out->intermediate_dim = gate_out;
    out->max_matrix_alloc_bytes = align_up_u64(gate_bytes, 2 * 1024 * 1024);
    uint64_t up_alloc = align_up_u64(up_bytes, 2 * 1024 * 1024);
    uint64_t down_alloc = align_up_u64(down_bytes, 2 * 1024 * 1024);
    if (up_alloc > out->max_matrix_alloc_bytes) out->max_matrix_alloc_bytes = up_alloc;
    if (down_alloc > out->max_matrix_alloc_bytes) out->max_matrix_alloc_bytes = down_alloc;
    return 1;
}

static int parse_dense_mlp_layout(NSDictionary *resident_layout,
                                  uint64_t layer_id,
                                  SharedExpertInfo *out) {
    memset(out, 0, sizeof(*out));
    int gate_ok =
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.gate_proj.weight", &out->gate, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.switch_mlp.gate_proj.weight", &out->gate, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".switch_mlp.gate_proj.weight", &out->gate, 0);
    int up_ok =
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.up_proj.weight", &out->up, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.switch_mlp.up_proj.weight", &out->up, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".switch_mlp.up_proj.weight", &out->up, 0);
    int down_ok =
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.down_proj.weight", &out->down, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".mlp.switch_mlp.down_proj.weight", &out->down, 0) ||
        find_resident_matrix_by_suffix_impl(resident_layout, layer_id,
                                            @".switch_mlp.down_proj.weight", &out->down, 0);
    if (!gate_ok || !up_ok || !down_ok) {
        fprintf(stderr, "dense MLP tensors for layer %llu not found\n",
                (unsigned long long)layer_id);
        return 0;
    }
    uint32_t gate_out = 0;
    uint32_t gate_in = 0;
    uint32_t up_out = 0;
    uint32_t up_in = 0;
    uint32_t down_out = 0;
    uint32_t down_in = 0;
    uint64_t gate_bytes = 0;
    uint64_t up_bytes = 0;
    uint64_t down_bytes = 0;
    if (!parse_shared_component_matrix(resident_layout,
                                       out->gate,
                                       &out->gate_affine,
                                       &out->gate_mxfp4,
                                       &out->gate_is_affine_int4,
                                       &out->gate_is_mxfp4,
                                       &gate_out,
                                       &gate_in,
                                       &gate_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->up,
                                       &out->up_affine,
                                       &out->up_mxfp4,
                                       &out->up_is_affine_int4,
                                       &out->up_is_mxfp4,
                                       &up_out,
                                       &up_in,
                                       &up_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->down,
                                       &out->down_affine,
                                       &out->down_mxfp4,
                                       &out->down_is_affine_int4,
                                       &out->down_is_mxfp4,
                                       &down_out,
                                       &down_in,
                                       &down_bytes)) {
        return 0;
    }
    if (gate_out != up_out ||
        gate_in != up_in ||
        down_out != gate_in ||
        down_in != gate_out) {
        fprintf(stderr,
                "dense MLP shapes are inconsistent: gate=[%u,%u] "
                "up=[%u,%u] down=[%u,%u]\n",
                gate_out, gate_in,
                up_out, up_in,
                down_out, down_in);
        return 0;
    }
    out->hidden_dim = gate_in;
    out->intermediate_dim = gate_out;
    out->max_matrix_alloc_bytes = align_up_u64(gate_bytes, 2 * 1024 * 1024);
    uint64_t up_alloc = align_up_u64(up_bytes, 2 * 1024 * 1024);
    uint64_t down_alloc = align_up_u64(down_bytes, 2 * 1024 * 1024);
    if (up_alloc > out->max_matrix_alloc_bytes) out->max_matrix_alloc_bytes = up_alloc;
    if (down_alloc > out->max_matrix_alloc_bytes) out->max_matrix_alloc_bytes = down_alloc;
    return 1;
}

static int parse_attention_projection_layout(NSDictionary *resident_layout,
                                             uint64_t layer_id,
                                             AttentionProjectionInfo *out) {
    memset(out, 0, sizeof(*out));
    if (!find_resident_matrix_by_suffix(resident_layout, layer_id,
                                        @".self_attn.q_a_proj.weight", &out->q_a) ||
        !find_resident_matrix_by_suffix(resident_layout, layer_id,
                                        @".self_attn.q_b_proj.weight", &out->q_b) ||
        !find_resident_matrix_by_suffix(resident_layout, layer_id,
                                        @".self_attn.kv_a_proj_with_mqa.weight", &out->kv_a)) {
        return 0;
    }
    out->has_kv_b = find_resident_matrix_by_suffix_impl(
        resident_layout,
        layer_id,
        @".self_attn.kv_b_proj.weight",
        &out->kv_b,
        0);
    if (!out->has_kv_b) {
        if (!find_resident_tensor3d_by_suffix(resident_layout,
                                              layer_id,
                                              @".self_attn.embed_q.weight",
                                              &out->embed_q_alias,
                                              1) ||
            !find_resident_tensor3d_by_suffix(resident_layout,
                                              layer_id,
                                              @".self_attn.unembed_out.weight",
                                              &out->unembed_out_alias,
                                              1)) {
            return 0;
        }
        out->has_absorbed_alias = 1;
    }
    if (!find_vector_tensor_by_suffix(resident_layout, layer_id,
                                      @".input_layernorm.weight", &out->input_norm) ||
        !find_vector_tensor_by_suffix(resident_layout, layer_id,
                                      @".self_attn.q_a_layernorm.weight", &out->q_a_norm) ||
        !find_vector_tensor_by_suffix(resident_layout, layer_id,
                                      @".self_attn.kv_a_layernorm.weight", &out->kv_a_norm)) {
        fprintf(stderr, "attention projection norm tensors for layer %llu not found\n",
                (unsigned long long)layer_id);
        return 0;
    }
    uint32_t q_a_out = 0;
    uint32_t q_a_in = 0;
    uint32_t q_b_out = 0;
    uint32_t q_b_in = 0;
    uint32_t kv_a_out = 0;
    uint32_t kv_a_in = 0;
    uint32_t kv_b_out = 0;
    uint32_t kv_b_in = 0;
    uint64_t q_a_bytes = 0;
    uint64_t q_b_bytes = 0;
    uint64_t kv_a_bytes = 0;
    uint64_t kv_b_bytes = 0;
    if (!parse_shared_component_matrix(resident_layout,
                                       out->q_a,
                                       &out->q_a_affine,
                                       &out->q_a_mxfp4,
                                       &out->q_a_is_affine_int4,
                                       &out->q_a_is_mxfp4,
                                       &q_a_out,
                                       &q_a_in,
                                       &q_a_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->q_b,
                                       &out->q_b_affine,
                                       &out->q_b_mxfp4,
                                       &out->q_b_is_affine_int4,
                                       &out->q_b_is_mxfp4,
                                       &q_b_out,
                                       &q_b_in,
                                       &q_b_bytes) ||
        !parse_shared_component_matrix(resident_layout,
                                       out->kv_a,
                                       &out->kv_a_affine,
                                       &out->kv_a_mxfp4,
                                       &out->kv_a_is_affine_int4,
                                       &out->kv_a_is_mxfp4,
                                       &kv_a_out,
                                       &kv_a_in,
                                       &kv_a_bytes)) {
        return 0;
    }
    if (out->has_kv_b) {
        if (!parse_shared_component_matrix(resident_layout,
                                           out->kv_b,
                                           &out->kv_b_affine,
                                           &out->kv_b_mxfp4,
                                           &out->kv_b_is_affine_int4,
                                           &out->kv_b_is_mxfp4,
                                           &kv_b_out,
                                           &kv_b_in,
                                           &kv_b_bytes)) {
            return 0;
        }
    } else {
        kv_b_in = out->kv_a_norm.dim0;
        if (out->embed_q_alias.dim1 != kv_b_in ||
            out->unembed_out_alias.dim2 != kv_b_in ||
            out->embed_q_alias.dim0 != out->unembed_out_alias.dim0) {
            fprintf(stderr,
                    "absorbed attention alias dims are inconsistent: "
                    "embed=[%u,%u,%u] unembed=[%u,%u,%u] kv_norm=%u\n",
                    out->embed_q_alias.dim0,
                    out->embed_q_alias.dim1,
                    out->embed_q_alias.dim2,
                    out->unembed_out_alias.dim0,
                    out->unembed_out_alias.dim1,
                    out->unembed_out_alias.dim2,
                    kv_b_in);
            return 0;
        }
        uint64_t equivalent_out = 0;
        if (!checked_add_u64((uint64_t)out->embed_q_alias.dim2,
                             (uint64_t)out->unembed_out_alias.dim1,
                             &equivalent_out) ||
            !checked_mul_u64(equivalent_out,
                             (uint64_t)out->embed_q_alias.dim0,
                             &equivalent_out) ||
            equivalent_out > UINT32_MAX) {
            fprintf(stderr, "absorbed attention equivalent kv_b dim overflows\n");
            return 0;
        }
        kv_b_out = (uint32_t)equivalent_out;
        kv_b_bytes = 0;
    }
    if (q_a_in != kv_a_in ||
        out->input_norm.dim0 != q_a_in) {
        fprintf(stderr,
                "attention input dims are inconsistent: q_a_in=%u kv_a_in=%u "
                "input_norm=%u\n",
                q_a_in, kv_a_in, out->input_norm.dim0);
        return 0;
    }
    if (q_a_out != q_b_in ||
        out->q_a_norm.dim0 != q_a_out) {
        fprintf(stderr,
                "attention Q dims are inconsistent: q_a_out=%u q_b_in=%u "
                "q_a_norm=%u\n",
                q_a_out, q_b_in, out->q_a_norm.dim0);
        return 0;
    }
    if (out->kv_a_norm.dim0 != kv_b_in ||
        kv_a_out < out->kv_a_norm.dim0) {
        fprintf(stderr,
                "attention KV dims are inconsistent: kv_a_out=%u kv_norm=%u "
                "kv_b_in=%u\n",
                kv_a_out, out->kv_a_norm.dim0, kv_b_in);
        return 0;
    }
    out->hidden_dim = q_a_in;
    out->q_lora_dim = q_a_out;
    out->q_out_dim = q_b_out;
    out->kv_lora_dim = out->kv_a_norm.dim0;
    out->kv_a_out_dim = kv_a_out;
    out->kv_out_dim = kv_b_out;
    out->kv_rope_dim = kv_a_out - out->kv_a_norm.dim0;
    update_max_matrix_alloc_bytes(&out->max_matrix_alloc_bytes, q_a_bytes);
    update_max_matrix_alloc_bytes(&out->max_matrix_alloc_bytes, q_b_bytes);
    update_max_matrix_alloc_bytes(&out->max_matrix_alloc_bytes, kv_a_bytes);
    if (out->has_kv_b) {
        update_max_matrix_alloc_bytes(&out->max_matrix_alloc_bytes, kv_b_bytes);
    }
    return 1;
}

static uint64_t estimate_attention_projection_peak(AttentionProjectionInfo info) {
    uint64_t hidden_bytes = (uint64_t)info.hidden_dim * sizeof(float);
    uint64_t q_lora_bytes = (uint64_t)info.q_lora_dim * sizeof(float);
    uint64_t q_out_bytes = (uint64_t)info.q_out_dim * sizeof(float);
    uint64_t kv_a_bytes = (uint64_t)info.kv_a_out_dim * sizeof(float);
    uint64_t kv_lora_bytes = (uint64_t)info.kv_lora_dim * sizeof(float);
    uint64_t kv_out_bytes =
        info.has_kv_b ? (uint64_t)info.kv_out_dim * sizeof(float) : 0;
    uint64_t live_projection_bytes =
        2 * hidden_bytes + 2 * q_lora_bytes + q_out_bytes +
        kv_a_bytes + kv_lora_bytes + kv_out_bytes;
    return info.max_matrix_alloc_bytes + live_projection_bytes;
}

static int find_decode_cache_segment(NSDictionary *cache_layout,
                                     uint64_t layer_id,
                                     NSString *kind,
                                     CacheSegmentInfo *out) {
    uint64_t layout_total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      UINT64_MAX,
                                      &layout_total_bytes)) {
        return 0;
    }
    (void)layout_total_bytes;
    NSDictionary *index =
        decode_cache_segment_index_cache()[decode_cache_layout_key(cache_layout)];
    NSString *segment_key = [NSString stringWithFormat:@"%@:%llu",
                             kind,
                             (unsigned long long)layer_id];
    NSValue *cached = index[segment_key];
    if (cached) {
        [cached getValue:out];
        return 1;
    }
    fprintf(stderr, "cache segment %s for layer %llu not found\n",
            kind.UTF8String, (unsigned long long)layer_id);
    return 0;
}

static int append_kv_a_to_decode_cache(NSString *cache_layout_path,
                                       NSString *cache_file_path,
                                       uint64_t layer_id,
                                       uint64_t position,
                                       AttentionProjectionInfo info,
                                       id<MTLBuffer> kv_a_f32,
                                       uint64_t max_cache_file_bytes) {
    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 0;
    uint64_t total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, total_bytes)) {
        return 0;
    }

    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 0;
    }
    if (position >= segment.max_context_tokens) {
        fprintf(stderr, "cache position %llu exceeds max context %llu\n",
                (unsigned long long)position,
                (unsigned long long)segment.max_context_tokens);
        return 0;
    }
    if (segment.width != info.kv_a_out_dim) {
        fprintf(stderr, "cache width %u does not match kv_a output dim %u\n",
                segment.width, info.kv_a_out_dim);
        return 0;
    }
    if (!(strcmp(segment.dtype, "BF16") == 0 ||
          strcmp(segment.dtype, "bfloat16") == 0 ||
          strcmp(segment.dtype, "F32") == 0 ||
          strcmp(segment.dtype, "float32") == 0)) {
        fprintf(stderr, "cache append supports BF16 or F32, got %s\n", segment.dtype);
        return 0;
    }
    uint32_t expected_dtype_bytes =
        (strcmp(segment.dtype, "F32") == 0 ||
         strcmp(segment.dtype, "float32") == 0) ? 4 : 2;
    if (segment.dtype_bytes != expected_dtype_bytes) {
        fprintf(stderr, "cache dtype bytes %u does not match dtype %s\n",
                segment.dtype_bytes, segment.dtype);
        return 0;
    }
    uint64_t token_bytes = (uint64_t)segment.width * segment.dtype_bytes;
    if (segment.total_bytes != token_bytes * segment.max_context_tokens) {
        fprintf(stderr, "cache segment total bytes mismatch for layer %llu\n",
                (unsigned long long)layer_id);
        return 0;
    }
    uint64_t write_offset = segment.offset + position * token_bytes;
    if (write_offset + token_bytes > total_bytes) {
        fprintf(stderr, "cache write exceeds layout total bytes\n");
        return 0;
    }

    float *src = (float *)kv_a_f32.contents;
    void *encoded = malloc((size_t)token_bytes);
    if (!encoded) return 0;
    if (segment.dtype_bytes == 4) {
        memcpy(encoded, src, (size_t)token_bytes);
    } else {
        uint16_t *dst = (uint16_t *)encoded;
        for (uint32_t i = 0; i < segment.width; i++) {
            dst[i] = f32_to_bf16_bits(src[i]);
        }
    }
    int ok = write_exact_at(cache_file_path, encoded, (size_t)token_bytes,
                            (off_t)write_offset);
    free(encoded);
    return ok;
}

static int read_decode_cache_segment_f32(NSString *cache_layout_path,
                                         NSString *cache_file_path,
                                         uint64_t layer_id,
                                         uint32_t context_len,
                                         uint32_t expected_width,
                                         uint64_t max_cache_file_bytes,
                                         uint64_t max_cache_read_bytes,
                                         float **out,
                                         uint64_t *out_bytes) {
    *out = NULL;
    *out_bytes = 0;
    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 0;
    uint64_t total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, total_bytes)) {
        return 0;
    }
    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 0;
    }
    if (context_len == 0 || context_len > segment.max_context_tokens) {
        fprintf(stderr, "context length %u exceeds max context %llu\n",
                context_len, (unsigned long long)segment.max_context_tokens);
        return 0;
    }
    if (segment.width != expected_width) {
        fprintf(stderr, "cache width %u does not match expected %u\n",
                segment.width, expected_width);
        return 0;
    }
    uint64_t token_bytes = (uint64_t)segment.width * segment.dtype_bytes;
    uint64_t raw_bytes = token_bytes * context_len;
    if (raw_bytes > max_cache_read_bytes) {
        fprintf(stderr, "cache read %llu bytes exceeds limit %llu\n",
                (unsigned long long)raw_bytes,
                (unsigned long long)max_cache_read_bytes);
        return 0;
    }
    if (segment.offset + raw_bytes > total_bytes) {
        fprintf(stderr, "cache read exceeds layout total bytes\n");
        return 0;
    }
    void *raw = malloc((size_t)raw_bytes);
    if (!raw) return 0;
    if (!read_exact_slot(cache_file_path.UTF8String, raw, (size_t)raw_bytes,
                         (off_t)segment.offset)) {
        free(raw);
        return 0;
    }
    float *values = NULL;
    uint64_t count = (uint64_t)context_len * expected_width;
    int ok = convert_raw_values_to_f32(raw, segment.dtype, count, &values);
    free(raw);
    if (!ok) return 0;
    *out = values;
    *out_bytes = count * sizeof(float);
    return 1;
}

static int read_decode_cache_indexed_rows_f32(NSDictionary *cache_layout,
                                              NSString *cache_file_path,
                                              uint64_t layer_id,
                                              uint32_t context_len,
                                              uint32_t topk_capacity,
                                              uint32_t batch_tokens,
                                              uint32_t expected_width,
                                              uint64_t max_cache_file_bytes,
                                              uint64_t max_cache_read_bytes,
                                              const uint32_t *indices,
                                              float **out,
                                              uint64_t *out_bytes,
                                              uint64_t *out_raw_bytes) {
    *out = NULL;
    *out_bytes = 0;
    *out_raw_bytes = 0;
    if (!indices || context_len == 0 || topk_capacity == 0 || batch_tokens == 0) {
        fprintf(stderr, "invalid indexed cache read arguments\n");
        return 0;
    }
    uint64_t total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, total_bytes)) {
        return 0;
    }
    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 0;
    }
    if (context_len > segment.max_context_tokens) {
        fprintf(stderr, "context length %u exceeds max context %llu\n",
                context_len, (unsigned long long)segment.max_context_tokens);
        return 0;
    }
    if (segment.width != expected_width) {
        fprintf(stderr, "cache width %u does not match expected %u\n",
                segment.width, expected_width);
        return 0;
    }
    uint64_t token_bytes = (uint64_t)segment.width * segment.dtype_bytes;
    uint32_t index_stride = topk_capacity + 1u;
    uint64_t raw_bytes = 0;
    for (uint32_t token = 0; token < batch_tokens; token++) {
        const uint32_t *row = indices + (uint64_t)token * index_stride;
        uint32_t count = row[0];
        if (count == 0 || count > topk_capacity) {
            fprintf(stderr, "indexed MLA row %u has invalid count %u\n", token, count);
            return 0;
        }
        for (uint32_t j = 0; j < count; j++) {
            uint32_t pos = row[1u + j];
            if (pos >= context_len || pos >= segment.max_context_tokens) {
                fprintf(stderr,
                        "indexed MLA row %u index %u is outside context %u\n",
                        token, pos, context_len);
                return 0;
            }
            if (segment.offset + ((uint64_t)pos + 1u) * token_bytes > total_bytes) {
                fprintf(stderr, "indexed MLA cache read exceeds layout total bytes\n");
                return 0;
            }
            raw_bytes += token_bytes;
            if (raw_bytes > max_cache_read_bytes) {
                fprintf(stderr, "indexed cache read %llu bytes exceeds limit %llu\n",
                        (unsigned long long)raw_bytes,
                        (unsigned long long)max_cache_read_bytes);
                return 0;
            }
        }
    }
    uint64_t staged_count = (uint64_t)batch_tokens * topk_capacity * expected_width;
    uint64_t staged_bytes = staged_count * sizeof(float);
    float *values = calloc((size_t)staged_count, sizeof(float));
    if (!values) {
        fprintf(stderr, "failed to allocate indexed MLA staged cache\n");
        return 0;
    }
    void *raw = malloc((size_t)token_bytes);
    if (!raw) {
        free(values);
        return 0;
    }
    for (uint32_t token = 0; token < batch_tokens; token++) {
        const uint32_t *row = indices + (uint64_t)token * index_stride;
        uint32_t count = row[0];
        for (uint32_t j = 0; j < count; j++) {
            uint32_t pos = row[1u + j];
            uint64_t read_offset = segment.offset + (uint64_t)pos * token_bytes;
            if (!read_exact_slot(cache_file_path.UTF8String, raw, (size_t)token_bytes,
                                 (off_t)read_offset)) {
                free(raw);
                free(values);
                return 0;
            }
            float *row_values = NULL;
            if (!convert_raw_values_to_f32(raw, segment.dtype, segment.width, &row_values)) {
                free(raw);
                free(values);
                return 0;
            }
            float *dst = values + ((uint64_t)token * topk_capacity + j) * expected_width;
            memcpy(dst, row_values, (size_t)expected_width * sizeof(float));
            free(row_values);
        }
    }
    free(raw);
    *out = values;
    *out_bytes = staged_bytes;
    *out_raw_bytes = raw_bytes;
    return 1;
}

static int run_dequant_self_test(void) {
    id<MTLDevice> device = MTLCreateSystemDefaultDevice();
    if (!device) {
        fprintf(stderr, "Metal device unavailable\n");
        return 1;
    }
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "inline float bf16_to_f32(uint16_t v) { return as_type<float>(uint(v) << 16); }\n"
         "kernel void dequant4(device const uint32_t* W [[buffer(0)]],\n"
         "                     device const uint16_t* S [[buffer(1)]],\n"
         "                     device const uint16_t* B [[buffer(2)]],\n"
         "                     device const float* x [[buffer(3)]],\n"
         "                     device float* out [[buffer(4)]],\n"
         "                     constant uint& out_dim [[buffer(5)]],\n"
         "                     constant uint& in_dim [[buffer(6)]],\n"
         "                     constant uint& group_size [[buffer(7)]],\n"
         "                     uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + tid * packed_cols;\n"
         "  device const uint16_t* srow = S + tid * num_groups;\n"
         "  device const uint16_t* brow = B + tid * num_groups;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = bf16_to_f32(srow[g]);\n"
         "    float bias = bf16_to_f32(brow[g]);\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = float((packed >> (i * 4)) & 0xF) * scale + bias;\n"
         "        acc += w * x[base_x + p * 8 + i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[tid] = acc;\n"
         "}\n";

    NSError *error = nil;
    id<MTLLibrary> library = [device newLibraryWithSource:source options:nil error:&error];
    if (!library) {
        fprintf(stderr, "failed to compile Metal kernel: %s\n",
                error.localizedDescription.UTF8String);
        return 1;
    }
    id<MTLFunction> fn = [library newFunctionWithName:@"dequant4"];
    id<MTLComputePipelineState> pipe = [device newComputePipelineStateWithFunction:fn
                                                                             error:&error];
    if (!pipe) {
        fprintf(stderr, "failed to create pipeline: %s\n",
                error.localizedDescription.UTF8String);
        return 1;
    }

    uint8_t row0[8] = {1, 2, 3, 4, 5, 6, 7, 8};
    uint8_t row1[8] = {0, 1, 2, 3, 4, 5, 6, 7};
    uint32_t packed[2] = {pack8(row0), pack8(row1)};
    uint16_t scales[2] = {0x3f80, 0x3f80};  // bf16 1.0
    uint16_t biases[2] = {0x0000, 0x0000};  // bf16 0.0
    float x[8] = {1, 1, 1, 1, 1, 1, 1, 1};
    float out[2] = {0, 0};

    id<MTLBuffer> bW = [device newBufferWithBytes:packed length:sizeof(packed) options:MTLResourceStorageModeShared];
    id<MTLBuffer> bS = [device newBufferWithBytes:scales length:sizeof(scales) options:MTLResourceStorageModeShared];
    id<MTLBuffer> bB = [device newBufferWithBytes:biases length:sizeof(biases) options:MTLResourceStorageModeShared];
    id<MTLBuffer> bX = [device newBufferWithBytes:x length:sizeof(x) options:MTLResourceStorageModeShared];
    id<MTLBuffer> bO = [device newBufferWithBytes:out length:sizeof(out) options:MTLResourceStorageModeShared];

    uint32_t out_dim = 2, in_dim = 8, group_size = 8;
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create dequant self-test command buffer\n");
        return 1;
    }
    id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
    if (!enc) {
        fprintf(stderr, "failed to create dequant self-test command encoder\n");
        return 1;
    }
    [enc setComputePipelineState:pipe];
    [enc setBuffer:bW offset:0 atIndex:0];
    [enc setBuffer:bS offset:0 atIndex:1];
    [enc setBuffer:bB offset:0 atIndex:2];
    [enc setBuffer:bX offset:0 atIndex:3];
    [enc setBuffer:bO offset:0 atIndex:4];
    [enc setBytes:&out_dim length:sizeof(out_dim) atIndex:5];
    [enc setBytes:&in_dim length:sizeof(in_dim) atIndex:6];
    [enc setBytes:&group_size length:sizeof(group_size) atIndex:7];
    [enc dispatchThreads:MTLSizeMake(out_dim, 1, 1)
   threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [enc endEncoding];
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "dequant self-test command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    float *got = (float *)bO.contents;
    int ok = (got[0] > 35.999f && got[0] < 36.001f &&
              got[1] > 27.999f && got[1] < 28.001f);
    printf("LargerLM dequant self-test\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  row0:               %.3f (expected 36.000)\n", got[0]);
    printf("  row1:               %.3f (expected 28.000)\n", got[1]);
    printf("  result:             %s\n", ok ? "ok" : "failed");
    return ok ? 0 : 1;
}

static int run_mpp_self_test(void) {
    id<MTLDevice> device = MTLCreateSystemDefaultDevice();
    if (!device) {
        fprintf(stderr, "Metal device unavailable\n");
        return 1;
    }

    if (@available(macOS 26.0, *)) {
        NSString *body =
            @"using namespace metal;\n"
             "using namespace mpp::tensor_ops;\n"
             "kernel void largerlm_mpp_self_test(\n"
             "    device half *a [[buffer(0)]],\n"
             "    device half *b [[buffer(1)]],\n"
             "    device half *d [[buffer(2)]]) {\n"
             "    constexpr int SM = 32;\n"
             "    constexpr int SN = 32;\n"
             "    constexpr int K = 32;\n"
             "    constexpr auto desc = matmul2d_descriptor(SM, SN);\n"
             "    matmul2d<desc, execution_simdgroup> op;\n"
             "    auto mA = tensor(a, dextents<int, 2>{K, SM}, array<int, 2>{1, K});\n"
             "    auto mB = tensor(b, dextents<int, 2>{SN, K}, array<int, 2>{1, SN});\n"
             "    auto mD = tensor(d, dextents<int, 2>{SN, SM}, array<int, 2>{1, SN});\n"
             "    op.run(mA, mB, mD);\n"
             "}\n";

        MTLCompileOptions *options = [MTLCompileOptions new];
        options.languageVersion = MTLLanguageVersion4_0;
        NSArray<NSArray<NSString *> *> *variants = @[
            @[@"metal_stdlib+metal_mpp",
              @"#include <metal_stdlib>\n#include <metal_mpp>\n"],
            @[@"metal_stdlib+metal_tensor+metal_mpp",
              @"#include <metal_stdlib>\n#include <metal_tensor>\n#include <metal_mpp>\n"],
            @[@"metal_stdlib+metal_performance_primitives",
              @"#include <metal_stdlib>\n#include <metal_performance_primitives>\n"],
        ];

        NSMutableArray<NSString *> *errors = [NSMutableArray array];
        id<MTLFunction> function = nil;
        NSString *compiled_variant = @"";
        for (NSArray<NSString *> *variant in variants) {
            NSString *name = variant[0];
            NSString *source = [variant[1] stringByAppendingString:body];
            NSError *error = nil;
            id<MTLLibrary> library = [device newLibraryWithSource:source
                                                          options:options
                                                            error:&error];
            if (!library) {
                NSString *message = error.localizedDescription ?: @"unknown compile error";
                [errors addObject:[NSString stringWithFormat:@"%@: %@", name, message]];
                continue;
            }
            function = [library newFunctionWithName:@"largerlm_mpp_self_test"];
            if (function) {
                compiled_variant = name;
                break;
            }
            [errors addObject:[NSString stringWithFormat:@"%@: function not found", name]];
        }
        if (!function) {
            fprintf(stderr, "failed to compile MPP self-test kernel:\n%s\n",
                    [errors componentsJoinedByString:@"\n"].UTF8String);
            return 1;
        }

        NSError *pipeline_error = nil;
        id<MTLComputePipelineState> pipeline =
            [device newComputePipelineStateWithFunction:function
                                                  error:&pipeline_error];
        if (!pipeline) {
            fprintf(stderr, "failed to create MPP self-test pipeline: %s\n",
                    (pipeline_error.localizedDescription ?: @"unknown error").UTF8String);
            return 1;
        }

        const NSUInteger elements = 32 * 32;
        NSMutableData *ones = [NSMutableData dataWithLength:elements * sizeof(uint16_t)];
        NSMutableData *zeros = [NSMutableData dataWithLength:elements * sizeof(uint16_t)];
        uint16_t *one_values = (uint16_t *)ones.mutableBytes;
        for (NSUInteger i = 0; i < elements; i++) {
            one_values[i] = 0x3c00u;
        }
        id<MTLBuffer> a_buffer = [device newBufferWithBytes:ones.bytes
                                                     length:ones.length
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> b_buffer = [device newBufferWithBytes:ones.bytes
                                                     length:ones.length
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> d_buffer = [device newBufferWithBytes:zeros.bytes
                                                     length:zeros.length
                                                    options:MTLResourceStorageModeShared];
        id<MTLCommandQueue> queue = shared_command_queue(device);
        if (!a_buffer || !b_buffer || !d_buffer || !queue) {
            fprintf(stderr, "failed to allocate tiny MPP self-test buffers\n");
            return 1;
        }

        id<MTLCommandBuffer> command = [queue commandBuffer];
        id<MTLComputeCommandEncoder> encoder = [command computeCommandEncoder];
        if (!command || !encoder) {
            fprintf(stderr, "failed to create MPP self-test command encoder\n");
            return 1;
        }
        [encoder setComputePipelineState:pipeline];
        [encoder setBuffer:a_buffer offset:0 atIndex:0];
        [encoder setBuffer:b_buffer offset:0 atIndex:1];
        [encoder setBuffer:d_buffer offset:0 atIndex:2];
        [encoder dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        [encoder endEncoding];
        [command commit];
        [command waitUntilCompleted];
        if (command.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "MPP self-test command failed: %s\n",
                    (command.error.localizedDescription ?: @"unknown error").UTF8String);
            return 1;
        }

        uint16_t *actual = (uint16_t *)d_buffer.contents;
        float max_abs_error = 0.0f;
        for (NSUInteger i = 0; i < elements; i++) {
            float value = half_to_float(actual[i]);
            float error = fabsf(value - 32.0f);
            if (error > max_abs_error) {
                max_abs_error = error;
            }
        }
        int ok = max_abs_error <= 0.05f;

        printf("LargerLM MPP self-test\n");
        printf("  Metal device:       %s\n", device.name.UTF8String);
        printf("  kernel variant:     %s\n", compiled_variant.UTF8String);
        printf("  shape:              32x32x32 half matmul2d\n");
        printf("  max abs error:      %.6g\n", max_abs_error);
        printf("  result:             %s\n", ok ? "ok" : "failed");
        return ok ? 0 : 1;
    }

    fprintf(stderr, "macOS 26.0 runtime is required for MPP self-test\n");
    return 1;
}

static NSString *expert_kernel_source(void) {
    return
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "inline float bf16_to_f32(uint16_t v) { return as_type<float>(uint(v) << 16); }\n"
         "inline float f16_to_f32(uint16_t v) { return float(as_type<half>(v)); }\n"
         "inline float meta16_to_f32(uint16_t v, uint meta_dtype) {\n"
         "  return meta_dtype == 1 ? f16_to_f32(v) : bf16_to_f32(v);\n"
         "}\n"
         "kernel void dequant4(device const uint32_t* W [[buffer(0)]],\n"
         "                     device const uint16_t* S [[buffer(1)]],\n"
         "                     device const uint16_t* B [[buffer(2)]],\n"
         "                     device const float* x [[buffer(3)]],\n"
         "                     device float* out [[buffer(4)]],\n"
         "                     constant uint& out_dim [[buffer(5)]],\n"
         "                     constant uint& in_dim [[buffer(6)]],\n"
         "                     constant uint& group_size [[buffer(7)]],\n"
         "                     constant uint& meta_dtype [[buffer(8)]],\n"
         "                     uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + tid * packed_cols;\n"
         "  device const uint16_t* srow = S + tid * num_groups;\n"
         "  device const uint16_t* brow = B + tid * num_groups;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = meta16_to_f32(srow[g], meta_dtype);\n"
         "    float bias = meta16_to_f32(brow[g], meta_dtype);\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = float((packed >> (i * 4)) & 0xF) * scale + bias;\n"
         "        acc += w * x[base_x + p * 8 + i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void dequant4_batch(device const uint32_t* W [[buffer(0)]],\n"
         "                           device const uint16_t* S [[buffer(1)]],\n"
         "                           device const uint16_t* B [[buffer(2)]],\n"
         "                           device const float* x [[buffer(3)]],\n"
         "                           device float* out [[buffer(4)]],\n"
         "                           constant uint& out_dim [[buffer(5)]],\n"
         "                           constant uint& in_dim [[buffer(6)]],\n"
         "                           constant uint& group_size [[buffer(7)]],\n"
         "                           constant uint& batch [[buffer(8)]],\n"
         "                           constant uint& meta_dtype [[buffer(9)]],\n"
         "                           uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + o * packed_cols;\n"
         "  device const uint16_t* srow = S + o * num_groups;\n"
         "  device const uint16_t* brow = B + o * num_groups;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = meta16_to_f32(srow[g], meta_dtype);\n"
         "    float bias = meta16_to_f32(brow[g], meta_dtype);\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = float((packed >> (i * 4)) & 0xF) * scale + bias;\n"
         "        acc += w * xrow[base_x + p * 8 + i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "constant float mxfp4_e2m1_lut[16] = {\n"
         "  0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f,\n"
         "  0.0f, -0.5f, -1.0f, -1.5f, -2.0f, -3.0f, -4.0f, -6.0f\n"
         "};\n"
         "inline float mxfp4_e2m1_to_f32(uint q) {\n"
         "  return mxfp4_e2m1_lut[q & 0xFu];\n"
         "}\n"
         "inline uint mxfp4_load_scale_byte(device const uint32_t* S, uint index) {\n"
         "  uint packed = S[index >> 2u];\n"
         "  return (packed >> ((index & 3u) * 8u)) & 0xFFu;\n"
         "}\n"
         "inline float mxfp4_e8m0_to_f32(uint v) {\n"
         "  return as_type<float>(uint(v) << 23);\n"
         "}\n"
         "inline float4 mxfp4_unpack4_scaled(uint packed, uint bit_shift, float scale) {\n"
         "  return float4(mxfp4_e2m1_to_f32((packed >> bit_shift) & 0xFu),\n"
         "                mxfp4_e2m1_to_f32((packed >> (bit_shift + 4u)) & 0xFu),\n"
         "                mxfp4_e2m1_to_f32((packed >> (bit_shift + 8u)) & 0xFu),\n"
         "                mxfp4_e2m1_to_f32((packed >> (bit_shift + 12u)) & 0xFu)) * scale;\n"
         "}\n"
         "inline float4 load_f32x4(device const float* x, uint offset) {\n"
         "  return float4(x[offset], x[offset + 1u], x[offset + 2u], x[offset + 3u]);\n"
         "}\n"
         "inline float mxfp4_swiglu_value(float gate_acc, float up_acc, uint activation_mode) {\n"
         "  if (activation_mode == 1u) {\n"
         "    return (gate_acc / (1.0f + fast::exp(-gate_acc))) * up_acc;\n"
         "  }\n"
         "  if (activation_mode == 2u) {\n"
         "    return gate_acc * up_acc;\n"
         "  }\n"
         "  return (gate_acc / (1.0f + exp(-gate_acc))) * up_acc;\n"
         "}\n"
         "inline float mxfp4_dot8_scaled(uint packed, float scale, device const float* x, uint offset) {\n"
         "  float acc = 0.0f;\n"
         "  acc += mxfp4_e2m1_to_f32(packed & 0xFu) * x[offset];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 4u) & 0xFu) * x[offset + 1u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 8u) & 0xFu) * x[offset + 2u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 12u) & 0xFu) * x[offset + 3u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 16u) & 0xFu) * x[offset + 4u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 20u) & 0xFu) * x[offset + 5u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 24u) & 0xFu) * x[offset + 6u];\n"
         "  acc += mxfp4_e2m1_to_f32((packed >> 28u) & 0xFu) * x[offset + 7u];\n"
         "  return acc * scale;\n"
         "}\n"
         "kernel void mxfp4_matvec(device const uint32_t* W [[buffer(0)]],\n"
         "                         device const uint32_t* S [[buffer(1)]],\n"
         "                         device const float* x [[buffer(2)]],\n"
         "                         device float* out [[buffer(3)]],\n"
         "                         constant uint& out_dim [[buffer(4)]],\n"
         "                         constant uint& in_dim [[buffer(5)]],\n"
         "                         constant uint& group_size [[buffer(6)]],\n"
         "                         uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + tid * packed_cols;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(S, tid * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = mxfp4_e2m1_to_f32((packed >> (i * 4)) & 0xFu) * scale;\n"
         "        acc += w * x[base_x + p * 8 + i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void mxfp4_matvec_batch(device const uint32_t* W [[buffer(0)]],\n"
         "                               device const uint32_t* S [[buffer(1)]],\n"
         "                               device const float* x [[buffer(2)]],\n"
         "                               device float* out [[buffer(3)]],\n"
         "                               constant uint& out_dim [[buffer(4)]],\n"
         "                               constant uint& in_dim [[buffer(5)]],\n"
         "                               constant uint& group_size [[buffer(6)]],\n"
         "                               constant uint& batch [[buffer(7)]],\n"
         "                               uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + o * packed_cols;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(S, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = mxfp4_e2m1_to_f32((packed >> (i * 4)) & 0xFu) * scale;\n"
         "        acc += w * xrow[base_x + p * 8 + i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "kernel void mxfp4_matvec_batch_gs32(device const uint32_t* W [[buffer(0)]],\n"
         "                                    device const uint32_t* S [[buffer(1)]],\n"
         "                                    device const float* x [[buffer(2)]],\n"
         "                                    device float* out [[buffer(3)]],\n"
         "                                    constant uint& out_dim [[buffer(4)]],\n"
         "                                    constant uint& in_dim [[buffer(5)]],\n"
         "                                    constant uint& group_size [[buffer(6)]],\n"
         "                                    constant uint& batch [[buffer(7)]],\n"
         "                                    uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch || group_size != 32u) return;\n"
         "  uint packed_cols = in_dim / 8u;\n"
         "  uint num_groups = in_dim / 32u;\n"
         "  device const uint32_t* row = W + o * packed_cols;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  uint scale_base = o * num_groups;\n"
         "  float acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(S, scale_base + g));\n"
         "    uint base_packed = g * 4u;\n"
         "    uint base_x = g * 32u;\n"
         "    acc += mxfp4_dot8_scaled(row[base_packed], scale, xrow, base_x);\n"
         "    acc += mxfp4_dot8_scaled(row[base_packed + 1u], scale, xrow, base_x + 8u);\n"
         "    acc += mxfp4_dot8_scaled(row[base_packed + 2u], scale, xrow, base_x + 16u);\n"
         "    acc += mxfp4_dot8_scaled(row[base_packed + 3u], scale, xrow, base_x + 24u);\n"
         "  }\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "kernel void mxfp4_matvec_batch_t2(device const uint32_t* W [[buffer(0)]],\n"
         "                                  device const uint32_t* S [[buffer(1)]],\n"
         "                                  device const float* x [[buffer(2)]],\n"
         "                                  device float* out [[buffer(3)]],\n"
         "                                  constant uint& out_dim [[buffer(4)]],\n"
         "                                  constant uint& in_dim [[buffer(5)]],\n"
         "                                  constant uint& group_size [[buffer(6)]],\n"
         "                                  constant uint& batch [[buffer(7)]],\n"
         "                                  uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t0 = tid.y * 2u;\n"
         "  if (o >= out_dim || t0 >= batch) return;\n"
         "  bool have1 = (t0 + 1u) < batch;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + o * packed_cols;\n"
         "  device const float* x0 = x + t0 * in_dim;\n"
         "  device const float* x1 = x0 + in_dim;\n"
         "  float acc0 = 0.0f;\n"
         "  float acc1 = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(S, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = mxfp4_e2m1_to_f32((packed >> (i * 4)) & 0xFu) * scale;\n"
         "        uint xidx = base_x + p * 8 + i;\n"
         "        acc0 += w * x0[xidx];\n"
         "        if (have1) acc1 += w * x1[xidx];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t0 * out_dim + o] = acc0;\n"
         "  if (have1) out[(t0 + 1u) * out_dim + o] = acc1;\n"
         "}\n"
         "kernel void mxfp4_matvec_batch_t4(device const uint32_t* W [[buffer(0)]],\n"
         "                                  device const uint32_t* S [[buffer(1)]],\n"
         "                                  device const float* x [[buffer(2)]],\n"
         "                                  device float* out [[buffer(3)]],\n"
         "                                  constant uint& out_dim [[buffer(4)]],\n"
         "                                  constant uint& in_dim [[buffer(5)]],\n"
         "                                  constant uint& group_size [[buffer(6)]],\n"
         "                                  constant uint& batch [[buffer(7)]],\n"
         "                                  uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t0 = tid.y * 4u;\n"
         "  if (o >= out_dim || t0 >= batch) return;\n"
         "  bool have1 = (t0 + 1u) < batch;\n"
         "  bool have2 = (t0 + 2u) < batch;\n"
         "  bool have3 = (t0 + 3u) < batch;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* row = W + o * packed_cols;\n"
         "  device const float* x0 = x + t0 * in_dim;\n"
         "  device const float* x1 = x0 + in_dim;\n"
         "  device const float* x2 = x1 + in_dim;\n"
         "  device const float* x3 = x2 + in_dim;\n"
         "  float acc0 = 0.0f;\n"
         "  float acc1 = 0.0f;\n"
         "  float acc2 = 0.0f;\n"
         "  float acc3 = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(S, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = mxfp4_e2m1_to_f32((packed >> (i * 4)) & 0xFu) * scale;\n"
         "        uint xidx = base_x + p * 8 + i;\n"
         "        acc0 += w * x0[xidx];\n"
         "        if (have1) acc1 += w * x1[xidx];\n"
         "        if (have2) acc2 += w * x2[xidx];\n"
         "        if (have3) acc3 += w * x3[xidx];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t0 * out_dim + o] = acc0;\n"
         "  if (have1) out[(t0 + 1u) * out_dim + o] = acc1;\n"
         "  if (have2) out[(t0 + 2u) * out_dim + o] = acc2;\n"
         "  if (have3) out[(t0 + 3u) * out_dim + o] = acc3;\n"
         "}\n"
         "kernel void mxfp4_swiglu_batch(device const uint32_t* gateW [[buffer(0)]],\n"
         "                               device const uint32_t* gateS [[buffer(1)]],\n"
         "                               device const uint32_t* upW [[buffer(2)]],\n"
         "                               device const uint32_t* upS [[buffer(3)]],\n"
         "                               device const float* x [[buffer(4)]],\n"
         "                               device float* out [[buffer(5)]],\n"
         "                               constant uint& out_dim [[buffer(6)]],\n"
         "                               constant uint& in_dim [[buffer(7)]],\n"
         "                               constant uint& group_size [[buffer(8)]],\n"
         "                               constant uint& batch [[buffer(9)]],\n"
         "                               constant uint& activation_mode [[buffer(10)]],\n"
         "                               uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* gate_row = gateW + o * packed_cols;\n"
         "  device const uint32_t* up_row = upW + o * packed_cols;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  float gate_acc = 0.0f;\n"
         "  float up_acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float gate_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(gateS, o * num_groups + g));\n"
         "    float up_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(upS, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t gate_packed = gate_row[base_packed + p];\n"
         "      uint32_t up_packed = up_row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float xv = xrow[base_x + p * 8 + i];\n"
         "        gate_acc += mxfp4_e2m1_to_f32((gate_packed >> (i * 4)) & 0xFu) * gate_scale * xv;\n"
         "        up_acc += mxfp4_e2m1_to_f32((up_packed >> (i * 4)) & 0xFu) * up_scale * xv;\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t * out_dim + o] = mxfp4_swiglu_value(gate_acc, up_acc, activation_mode);\n"
         "}\n"
         "kernel void mxfp4_swiglu_batch_gs32(device const uint32_t* gateW [[buffer(0)]],\n"
         "                                    device const uint32_t* gateS [[buffer(1)]],\n"
         "                                    device const uint32_t* upW [[buffer(2)]],\n"
         "                                    device const uint32_t* upS [[buffer(3)]],\n"
         "                                    device const float* x [[buffer(4)]],\n"
         "                                    device float* out [[buffer(5)]],\n"
         "                                    constant uint& out_dim [[buffer(6)]],\n"
         "                                    constant uint& in_dim [[buffer(7)]],\n"
         "                                    constant uint& group_size [[buffer(8)]],\n"
         "                                    constant uint& batch [[buffer(9)]],\n"
         "                                    constant uint& activation_mode [[buffer(10)]],\n"
         "                                    uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch || group_size != 32u) return;\n"
         "  uint packed_cols = in_dim / 8u;\n"
         "  uint num_groups = in_dim / 32u;\n"
         "  device const uint32_t* gate_row = gateW + o * packed_cols;\n"
         "  device const uint32_t* up_row = upW + o * packed_cols;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  uint scale_base = o * num_groups;\n"
         "  float gate_acc = 0.0f;\n"
         "  float up_acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float gate_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(gateS, scale_base + g));\n"
         "    float up_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(upS, scale_base + g));\n"
         "    uint base_packed = g * 4u;\n"
         "    uint base_x = g * 32u;\n"
         "    gate_acc += mxfp4_dot8_scaled(gate_row[base_packed], gate_scale, xrow, base_x);\n"
         "    gate_acc += mxfp4_dot8_scaled(gate_row[base_packed + 1u], gate_scale, xrow, base_x + 8u);\n"
         "    gate_acc += mxfp4_dot8_scaled(gate_row[base_packed + 2u], gate_scale, xrow, base_x + 16u);\n"
         "    gate_acc += mxfp4_dot8_scaled(gate_row[base_packed + 3u], gate_scale, xrow, base_x + 24u);\n"
         "    up_acc += mxfp4_dot8_scaled(up_row[base_packed], up_scale, xrow, base_x);\n"
         "    up_acc += mxfp4_dot8_scaled(up_row[base_packed + 1u], up_scale, xrow, base_x + 8u);\n"
         "    up_acc += mxfp4_dot8_scaled(up_row[base_packed + 2u], up_scale, xrow, base_x + 16u);\n"
         "    up_acc += mxfp4_dot8_scaled(up_row[base_packed + 3u], up_scale, xrow, base_x + 24u);\n"
         "  }\n"
         "  out[t * out_dim + o] = mxfp4_swiglu_value(gate_acc, up_acc, activation_mode);\n"
         "}\n"
         "kernel void mxfp4_swiglu_batch_v4(device const uint32_t* gateW [[buffer(0)]],\n"
         "                                  device const uint32_t* gateS [[buffer(1)]],\n"
         "                                  device const uint32_t* upW [[buffer(2)]],\n"
         "                                  device const uint32_t* upS [[buffer(3)]],\n"
         "                                  device const float* x [[buffer(4)]],\n"
         "                                  device float* out [[buffer(5)]],\n"
         "                                  constant uint& out_dim [[buffer(6)]],\n"
         "                                  constant uint& in_dim [[buffer(7)]],\n"
         "                                  constant uint& group_size [[buffer(8)]],\n"
         "                                  constant uint& batch [[buffer(9)]],\n"
         "                                  constant uint& activation_mode [[buffer(10)]],\n"
         "                                  uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* gate_row = gateW + o * packed_cols;\n"
         "  device const uint32_t* up_row = upW + o * packed_cols;\n"
         "  device const float* xrow = x + t * in_dim;\n"
         "  float gate_acc = 0.0f;\n"
         "  float up_acc = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float gate_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(gateS, o * num_groups + g));\n"
         "    float up_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(upS, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t gate_packed = gate_row[base_packed + p];\n"
         "      uint32_t up_packed = up_row[base_packed + p];\n"
         "      uint xidx = base_x + p * 8u;\n"
         "      float4 xlo = load_f32x4(xrow, xidx);\n"
         "      float4 xhi = load_f32x4(xrow, xidx + 4u);\n"
         "      gate_acc += dot(mxfp4_unpack4_scaled(gate_packed, 0u, gate_scale), xlo);\n"
         "      gate_acc += dot(mxfp4_unpack4_scaled(gate_packed, 16u, gate_scale), xhi);\n"
         "      up_acc += dot(mxfp4_unpack4_scaled(up_packed, 0u, up_scale), xlo);\n"
         "      up_acc += dot(mxfp4_unpack4_scaled(up_packed, 16u, up_scale), xhi);\n"
         "    }\n"
         "  }\n"
         "  out[t * out_dim + o] = mxfp4_swiglu_value(gate_acc, up_acc, activation_mode);\n"
         "}\n"
         "kernel void mxfp4_swiglu_batch_t2(device const uint32_t* gateW [[buffer(0)]],\n"
         "                                  device const uint32_t* gateS [[buffer(1)]],\n"
         "                                  device const uint32_t* upW [[buffer(2)]],\n"
         "                                  device const uint32_t* upS [[buffer(3)]],\n"
         "                                  device const float* x [[buffer(4)]],\n"
         "                                  device float* out [[buffer(5)]],\n"
         "                                  constant uint& out_dim [[buffer(6)]],\n"
         "                                  constant uint& in_dim [[buffer(7)]],\n"
         "                                  constant uint& group_size [[buffer(8)]],\n"
         "                                  constant uint& batch [[buffer(9)]],\n"
         "                                  constant uint& activation_mode [[buffer(10)]],\n"
         "                                  uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint o = tid.x;\n"
         "  uint t0 = tid.y * 2u;\n"
         "  if (o >= out_dim || t0 >= batch) return;\n"
         "  bool have1 = (t0 + 1u) < batch;\n"
         "  uint packed_cols = in_dim / 8;\n"
         "  uint num_groups = in_dim / group_size;\n"
         "  uint packed_per_group = group_size / 8;\n"
         "  device const uint32_t* gate_row = gateW + o * packed_cols;\n"
         "  device const uint32_t* up_row = upW + o * packed_cols;\n"
         "  device const float* x0 = x + t0 * in_dim;\n"
         "  device const float* x1 = x0 + in_dim;\n"
         "  float gate_acc0 = 0.0f;\n"
         "  float up_acc0 = 0.0f;\n"
         "  float gate_acc1 = 0.0f;\n"
         "  float up_acc1 = 0.0f;\n"
         "  for (uint g = 0; g < num_groups; g++) {\n"
         "    float gate_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(gateS, o * num_groups + g));\n"
         "    float up_scale = mxfp4_e8m0_to_f32(mxfp4_load_scale_byte(upS, o * num_groups + g));\n"
         "    uint base_packed = g * packed_per_group;\n"
         "    uint base_x = g * group_size;\n"
         "    for (uint p = 0; p < packed_per_group; p++) {\n"
         "      uint32_t gate_packed = gate_row[base_packed + p];\n"
         "      uint32_t up_packed = up_row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        uint xidx = base_x + p * 8 + i;\n"
         "        float gw = mxfp4_e2m1_to_f32((gate_packed >> (i * 4)) & 0xFu) * gate_scale;\n"
         "        float uw = mxfp4_e2m1_to_f32((up_packed >> (i * 4)) & 0xFu) * up_scale;\n"
         "        float xv0 = x0[xidx];\n"
         "        gate_acc0 += gw * xv0;\n"
         "        up_acc0 += uw * xv0;\n"
         "        if (have1) {\n"
         "          float xv1 = x1[xidx];\n"
         "          gate_acc1 += gw * xv1;\n"
         "          up_acc1 += uw * xv1;\n"
         "        }\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  out[t0 * out_dim + o] = mxfp4_swiglu_value(gate_acc0, up_acc0, activation_mode);\n"
         "  if (have1) out[(t0 + 1u) * out_dim + o] = mxfp4_swiglu_value(gate_acc1, up_acc1, activation_mode);\n"
         "}\n"
