         "      uint32_t packed = row[base_packed + p];\n"
         "      for (uint i = 0; i < 8; i++) {\n"
         "        float w = mxfp4_e2m1_to_f32((packed >> (i * 4)) & 0xFu) * scale;\n"
         "        uint xidx = base_x + p * 8 + i;\n"
         "        acc0 += w * x0[xidx];\n"
         "        if (have1) acc1 += w * x1[xidx];\n"
         "        if (have2) acc2 += w * x2[xidx];\n"
         "        if (have3) acc3 += w * x3[xidx];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "  dst[t0 * out_dim + o] += weights[t0] * acc0;\n"
         "  if (have1) dst[(t0 + 1u) * out_dim + o] += weights[t0 + 1u] * acc1;\n"
         "  if (have2) dst[(t0 + 2u) * out_dim + o] += weights[t0 + 2u] * acc2;\n"
         "  if (have3) dst[(t0 + 3u) * out_dim + o] += weights[t0 + 3u] * acc3;\n"
         "}\n"
         "kernel void swiglu(device const float* gate [[buffer(0)]],\n"
         "                    device const float* up [[buffer(1)]],\n"
         "                    device float* out [[buffer(2)]],\n"
         "                    constant uint& dim [[buffer(3)]],\n"
         "                    uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= dim) return;\n"
         "  float g = gate[tid];\n"
         "  out[tid] = (g / (1.0f + exp(-g))) * up[tid];\n"
         "}\n"
         "kernel void swiglu_batch(device const float* gate [[buffer(0)]],\n"
         "                          device const float* up [[buffer(1)]],\n"
         "                          device float* out [[buffer(2)]],\n"
         "                          constant uint& dim [[buffer(3)]],\n"
         "                          constant uint& batch [[buffer(4)]],\n"
         "                          uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint i = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (i >= dim || t >= batch) return;\n"
         "  uint offset = t * dim + i;\n"
         "  float g = gate[offset];\n"
         "  out[offset] = (g / (1.0f + exp(-g))) * up[offset];\n"
         "}\n"
         "kernel void clear_f32(device float* out [[buffer(0)]],\n"
         "                      constant uint& dim [[buffer(1)]],\n"
         "                      uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= dim) return;\n"
         "  out[tid] = 0.0f;\n"
         "}\n"
         "kernel void weighted_add(device const float* src [[buffer(0)]],\n"
         "                         device float* dst [[buffer(1)]],\n"
         "                         constant float& weight [[buffer(2)]],\n"
         "                         constant uint& dim [[buffer(3)]],\n"
         "                         uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= dim) return;\n"
