         "}\n"
         "kernel void weighted_add_batch(device const float* src [[buffer(0)]],\n"
         "                               device float* dst [[buffer(1)]],\n"
         "                               device const float* weights [[buffer(2)]],\n"
         "                               constant uint& dim [[buffer(3)]],\n"
