         "}\n"
         "kernel void add_f32_batch(device const float* src [[buffer(0)]],\n"
         "                          device float* dst [[buffer(1)]],\n"
         "                          constant uint& dim [[buffer(2)]],\n"
         "                          constant uint& batch [[buffer(3)]],\n"
         "                          uint2 tid [[thread_position_in_grid]]) {\n"
         "  uint i = tid.x;\n"
         "  uint t = tid.y;\n"
         "  if (i >= dim || t >= batch) return;\n"
         "  uint offset = t * dim + i;\n"
         "  dst[offset] += src[offset];\n"
         "}\n"
         "kernel void rmsnorm_f32(device const float* x [[buffer(0)]],\n"
         "                       device const float* weight [[buffer(1)]],\n"
         "                       device float* out [[buffer(2)]],\n"
         "                       constant uint& dim [[buffer(3)]],\n"
         "                       constant float& eps [[buffer(4)]],\n"
         "                       uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= dim) return;\n"
         "  float sumsq = 0.0f;\n"
         "  for (uint i = 0; i < dim; i++) sumsq += x[i] * x[i];\n"
         "  float inv = rsqrt(sumsq / float(dim) + eps);\n"
         "  out[tid] = x[tid] * inv * weight[tid];\n"
         "}\n"
         "kernel void rmsnorm_batch_f32(device const float* x [[buffer(0)]],\n"
         "                             device const float* weight [[buffer(1)]],\n"
         "                             device float* out [[buffer(2)]],\n"
         "                             constant uint& dim [[buffer(3)]],\n"
         "                             constant uint& batch [[buffer(4)]],\n"
         "                             constant float& eps [[buffer(5)]],\n"
         "                             uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint i = gid.x;\n"
         "  uint t = gid.y;\n"
         "  if (i >= dim || t >= batch) return;\n"
         "  uint base = t * dim;\n"
         "  float sumsq = 0.0f;\n"
         "  for (uint j = 0; j < dim; j++) sumsq += x[base + j] * x[base + j];\n"
         "  float inv = rsqrt(sumsq / float(dim) + eps);\n"
         "  out[base + i] = x[base + i] * inv * weight[i];\n"
         "}\n"
         "kernel void router_f32(device const float* W [[buffer(0)]],\n"
         "                       device const float* x [[buffer(1)]],\n"
         "                       device float* out [[buffer(2)]],\n"
         "                       constant uint& out_dim [[buffer(3)]],\n"
         "                       constant uint& in_dim [[buffer(4)]],\n"
         "                       uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  device const float* row = W + tid * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += row[i] * x[i];\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void router_bf16(device const uint16_t* W [[buffer(0)]],\n"
         "                        device const float* x [[buffer(1)]],\n"
         "                        device float* out [[buffer(2)]],\n"
         "                        constant uint& out_dim [[buffer(3)]],\n"
         "                        constant uint& in_dim [[buffer(4)]],\n"
         "                        uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  device const uint16_t* row = W + tid * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += bf16_to_f32(row[i]) * x[i];\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void linear_f16(device const half* W [[buffer(0)]],\n"
         "                       device const float* x [[buffer(1)]],\n"
         "                       device float* out [[buffer(2)]],\n"
         "                       constant uint& out_dim [[buffer(3)]],\n"
         "                       constant uint& in_dim [[buffer(4)]],\n"
         "                       uint tid [[thread_position_in_grid]]) {\n"
         "  if (tid >= out_dim) return;\n"
         "  device const half* row = W + tid * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += float(row[i]) * x[i];\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void linear_batch_f32(device const float* W [[buffer(0)]],\n"
         "                             device const float* x [[buffer(1)]],\n"
         "                             device float* out [[buffer(2)]],\n"
         "                             constant uint& out_dim [[buffer(3)]],\n"
         "                             constant uint& in_dim [[buffer(4)]],\n"
         "                             constant uint& batch [[buffer(5)]],\n"
         "                             uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint o = gid.x;\n"
         "  uint t = gid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  device const float* row = W + o * in_dim;\n"
         "  device const float* in = x + t * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += row[i] * in[i];\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "kernel void linear_batch_bf16(device const uint16_t* W [[buffer(0)]],\n"
         "                              device const float* x [[buffer(1)]],\n"
         "                              device float* out [[buffer(2)]],\n"
         "                              constant uint& out_dim [[buffer(3)]],\n"
         "                              constant uint& in_dim [[buffer(4)]],\n"
         "                              constant uint& batch [[buffer(5)]],\n"
         "                              uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint o = gid.x;\n"
         "  uint t = gid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  device const uint16_t* row = W + o * in_dim;\n"
         "  device const float* in = x + t * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += bf16_to_f32(row[i]) * in[i];\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "kernel void linear_batch_f16(device const half* W [[buffer(0)]],\n"
         "                             device const float* x [[buffer(1)]],\n"
         "                             device float* out [[buffer(2)]],\n"
         "                             constant uint& out_dim [[buffer(3)]],\n"
         "                             constant uint& in_dim [[buffer(4)]],\n"
         "                             constant uint& batch [[buffer(5)]],\n"
         "                             uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint o = gid.x;\n"
         "  uint t = gid.y;\n"
         "  if (o >= out_dim || t >= batch) return;\n"
         "  device const half* row = W + o * in_dim;\n"
         "  device const float* in = x + t * in_dim;\n"
         "  float acc = 0.0f;\n"
         "  for (uint i = 0; i < in_dim; i++) acc += float(row[i]) * in[i];\n"
         "  out[t * out_dim + o] = acc;\n"
         "}\n"
         "kernel void rope_f32(device const float* q [[buffer(0)]],\n"
         "                     device const float* k [[buffer(1)]],\n"
         "                     device float* out_q [[buffer(2)]],\n"
         "                     device float* out_k [[buffer(3)]],\n"
         "                     constant uint& num_heads [[buffer(4)]],\n"
         "                     constant uint& rope_dim [[buffer(5)]],\n"
         "                     constant uint& position [[buffer(6)]],\n"
         "                     constant float& theta [[buffer(7)]],\n"
         "                     constant uint& interleave [[buffer(8)]],\n"
         "                     uint tid [[thread_position_in_grid]]) {\n"
         "  uint q_count = num_heads * rope_dim;\n"
         "  uint total = q_count + rope_dim;\n"
         "  if (tid >= total) return;\n"
         "  uint half_dim = rope_dim / 2;\n"
         "  bool is_q = tid < q_count;\n"
         "  uint idx = is_q ? (tid % rope_dim) : (tid - q_count);\n"
         "  uint base = is_q ? (tid - idx) : 0;\n"
         "  device const float* src = is_q ? q : k;\n"
         "  float x = src[base + idx];\n"
         "  float rot = 0.0f;\n"
         "  uint freq_idx = 0;\n"
         "  if (interleave) {\n"
         "    uint pair = idx ^ 1u;\n"
         "    rot = (idx & 1u) ? src[base + pair] : -src[base + pair];\n"
         "    freq_idx = idx / 2u;\n"
         "  } else {\n"
         "    if (idx < half_dim) {\n"
         "      rot = -src[base + idx + half_dim];\n"
         "      freq_idx = idx;\n"
         "    } else {\n"
         "      rot = src[base + idx - half_dim];\n"
         "      freq_idx = idx - half_dim;\n"
         "    }\n"
         "  }\n"
         "  float angle = float(position) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "  float c = cos(angle);\n"
         "  float s = sin(angle);\n"
         "  float y = x * c + rot * s;\n"
         "  if (is_q) out_q[tid] = y; else out_k[idx] = y;\n"
         "}\n"
         "kernel void rope_batch_f32(device const float* q [[buffer(0)]],\n"
         "                           device const float* k [[buffer(1)]],\n"
         "                           device float* out_q [[buffer(2)]],\n"
         "                           device float* out_k [[buffer(3)]],\n"
         "                           constant uint& num_heads [[buffer(4)]],\n"
         "                           constant uint& rope_dim [[buffer(5)]],\n"
         "                           constant uint& start_position [[buffer(6)]],\n"
         "                           constant float& theta [[buffer(7)]],\n"
         "                           constant uint& interleave [[buffer(8)]],\n"
         "                           constant uint& batch [[buffer(9)]],\n"
         "                           uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint tid = gid.x;\n"
         "  uint token = gid.y;\n"
         "  uint q_count = num_heads * rope_dim;\n"
         "  uint total = q_count + rope_dim;\n"
         "  if (tid >= total || token >= batch) return;\n"
         "  uint half_dim = rope_dim / 2;\n"
         "  bool is_q = tid < q_count;\n"
         "  uint idx = is_q ? (tid % rope_dim) : (tid - q_count);\n"
         "  uint base = is_q ? (tid - idx) : 0;\n"
         "  uint q_token_base = token * q_count;\n"
         "  uint k_token_base = token * rope_dim;\n"
         "  device const float* src = is_q ? (q + q_token_base) : (k + k_token_base);\n"
         "  float x = src[base + idx];\n"
         "  float rot = 0.0f;\n"
         "  uint freq_idx = 0;\n"
         "  if (interleave) {\n"
         "    uint pair = idx ^ 1u;\n"
         "    rot = (idx & 1u) ? src[base + pair] : -src[base + pair];\n"
         "    freq_idx = idx / 2u;\n"
         "  } else {\n"
         "    if (idx < half_dim) {\n"
         "      rot = -src[base + idx + half_dim];\n"
         "      freq_idx = idx;\n"
         "    } else {\n"
         "      rot = src[base + idx - half_dim];\n"
         "      freq_idx = idx - half_dim;\n"
         "    }\n"
         "  }\n"
         "  uint position = start_position + token;\n"
         "  float angle = float(position) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "  float c = cos(angle);\n"
         "  float s = sin(angle);\n"
         "  float y = x * c + rot * s;\n"
         "  if (is_q) out_q[q_token_base + tid] = y; else out_k[k_token_base + idx] = y;\n"
         "}\n"
         "kernel void rope_split_batch_f32(device const float* q_b [[buffer(0)]],\n"
         "                                 device const float* k [[buffer(1)]],\n"
         "                                 device float* out_q_nope [[buffer(2)]],\n"
         "                                 device float* out_q_rope [[buffer(3)]],\n"
         "                                 device float* out_q [[buffer(4)]],\n"
         "                                 device float* out_k [[buffer(5)]],\n"
         "                                 constant uint& num_heads [[buffer(6)]],\n"
         "                                 constant uint& qk_nope_dim [[buffer(7)]],\n"
         "                                 constant uint& rope_dim [[buffer(8)]],\n"
         "                                 constant uint& start_position [[buffer(9)]],\n"
         "                                 constant float& theta [[buffer(10)]],\n"
         "                                 constant uint& interleave [[buffer(11)]],\n"
         "                                 constant uint& batch [[buffer(12)]],\n"
         "                                 uint2 gid [[thread_position_in_grid]]) {\n"
         "  uint tid = gid.x;\n"
         "  uint token = gid.y;\n"
         "  uint q_head_dim = qk_nope_dim + rope_dim;\n"
         "  uint q_b_count = num_heads * q_head_dim;\n"
         "  uint q_nope_count = num_heads * qk_nope_dim;\n"
         "  uint q_rope_count = num_heads * rope_dim;\n"
         "  uint total = q_b_count + rope_dim;\n"
         "  if (tid >= total || token >= batch) return;\n"
         "  uint half_dim = rope_dim / 2u;\n"
         "  uint position = start_position + token;\n"
         "  if (tid < q_b_count) {\n"
         "    uint head = tid / q_head_dim;\n"
         "    uint head_idx = tid - head * q_head_dim;\n"
         "    uint q_b_token_base = token * q_b_count;\n"
         "    float value = q_b[q_b_token_base + tid];\n"
         "    if (head_idx < qk_nope_dim) {\n"
         "      out_q_nope[token * q_nope_count + head * qk_nope_dim + head_idx] = value;\n"
         "      return;\n"
         "    }\n"
         "    uint idx = head_idx - qk_nope_dim;\n"
         "    uint src_base = q_b_token_base + head * q_head_dim + qk_nope_dim;\n"
         "    out_q_rope[token * q_rope_count + head * rope_dim + idx] = value;\n"
         "    float rot = 0.0f;\n"
         "    uint freq_idx = 0;\n"
         "    if (interleave) {\n"
         "      uint pair = idx ^ 1u;\n"
         "      rot = (idx & 1u) ? q_b[src_base + pair] : -q_b[src_base + pair];\n"
         "      freq_idx = idx / 2u;\n"
         "    } else {\n"
         "      if (idx < half_dim) {\n"
         "        rot = -q_b[src_base + idx + half_dim];\n"
         "        freq_idx = idx;\n"
         "      } else {\n"
         "        rot = q_b[src_base + idx - half_dim];\n"
         "        freq_idx = idx - half_dim;\n"
         "      }\n"
         "    }\n"
         "    float angle = float(position) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "    float c = cos(angle);\n"
         "    float s = sin(angle);\n"
         "    out_q[token * q_rope_count + head * rope_dim + idx] = value * c + rot * s;\n"
         "    return;\n"
         "  }\n"
         "  uint idx = tid - q_b_count;\n"
         "  uint k_token_base = token * rope_dim;\n"
         "  float value = k[k_token_base + idx];\n"
         "  float rot = 0.0f;\n"
         "  uint freq_idx = 0;\n"
         "  if (interleave) {\n"
         "    uint pair = idx ^ 1u;\n"
         "    rot = (idx & 1u) ? k[k_token_base + pair] : -k[k_token_base + pair];\n"
         "    freq_idx = idx / 2u;\n"
         "  } else {\n"
         "    if (idx < half_dim) {\n"
         "      rot = -k[k_token_base + idx + half_dim];\n"
         "      freq_idx = idx;\n"
         "    } else {\n"
         "      rot = k[k_token_base + idx - half_dim];\n"
         "      freq_idx = idx - half_dim;\n"
         "    }\n"
         "  }\n"
         "  float angle = float(position) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "  float c = cos(angle);\n"
         "  float s = sin(angle);\n"
         "  out_k[k_token_base + idx] = value * c + rot * s;\n"
         "}\n"
         "kernel void mla_attention_f32(device const float* q_nope [[buffer(0)]],\n"
         "                              device const float* q_rope [[buffer(1)]],\n"
         "                              device const float* cache [[buffer(2)]],\n"
         "                              device const float* kv_b [[buffer(3)]],\n"
         "                              device float* out [[buffer(4)]],\n"
         "                              constant uint& context_len [[buffer(5)]],\n"
         "                              constant uint& num_heads [[buffer(6)]],\n"
         "                              constant uint& kv_lora_dim [[buffer(7)]],\n"
         "                              constant uint& qk_nope_dim [[buffer(8)]],\n"
         "                              constant uint& rope_dim [[buffer(9)]],\n"
         "                              constant uint& v_head_dim [[buffer(10)]],\n"
         "                              constant float& scale [[buffer(11)]],\n"
         "                              constant float& theta [[buffer(12)]],\n"
         "                              constant uint& interleave [[buffer(13)]],\n"
         "                              constant uint& position_offset [[buffer(14)]],\n"
         "                              uint tid [[thread_position_in_grid]]) {\n"
         "  uint total = num_heads * v_head_dim;\n"
         "  if (tid >= total) return;\n"
         "  uint h = tid / v_head_dim;\n"
         "  uint vd = tid - h * v_head_dim;\n"
         "  uint head_row_base = h * (qk_nope_dim + v_head_dim);\n"
         "  uint cache_width = kv_lora_dim + rope_dim;\n"
         "  uint half_dim = rope_dim / 2;\n"
         "  float max_score = -INFINITY;\n"
         "  for (uint t = 0; t < context_len; t++) {\n"
         "    device const float* latent = cache + t * cache_width;\n"
         "    device const float* k_rope_raw = latent + kv_lora_dim;\n"
         "    float score = 0.0f;\n"
         "    for (uint d = 0; d < qk_nope_dim; d++) {\n"
         "      device const float* row = kv_b + (head_row_base + d) * kv_lora_dim;\n"
         "      float k_nope = 0.0f;\n"
         "      for (uint r = 0; r < kv_lora_dim; r++) k_nope += row[r] * latent[r];\n"
         "      score += q_nope[h * qk_nope_dim + d] * k_nope;\n"
         "    }\n"
         "    uint pos = position_offset + t;\n"
         "    for (uint d = 0; d < rope_dim; d++) {\n"
         "      float x = k_rope_raw[d];\n"
         "      float rot = 0.0f;\n"
         "      uint freq_idx = 0;\n"
         "      if (interleave) {\n"
         "        uint pair = d ^ 1u;\n"
         "        rot = (d & 1u) ? k_rope_raw[pair] : -k_rope_raw[pair];\n"
         "        freq_idx = d / 2u;\n"
         "      } else {\n"
         "        if (d < half_dim) {\n"
         "          rot = -k_rope_raw[d + half_dim];\n"
         "          freq_idx = d;\n"
         "        } else {\n"
         "          rot = k_rope_raw[d - half_dim];\n"
         "          freq_idx = d - half_dim;\n"
         "        }\n"
         "      }\n"
         "      float angle = float(pos) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "      float k_rope = x * cos(angle) + rot * sin(angle);\n"
         "      score += q_rope[h * rope_dim + d] * k_rope;\n"
         "    }\n"
         "    score *= scale;\n"
         "    if (score > max_score) max_score = score;\n"
         "  }\n"
         "  float denom = 0.0f;\n"
         "  float acc = 0.0f;\n"
         "  device const float* v_row = kv_b + (head_row_base + qk_nope_dim + vd) * kv_lora_dim;\n"
         "  for (uint t = 0; t < context_len; t++) {\n"
         "    device const float* latent = cache + t * cache_width;\n"
         "    device const float* k_rope_raw = latent + kv_lora_dim;\n"
         "    float score = 0.0f;\n"
         "    for (uint d = 0; d < qk_nope_dim; d++) {\n"
         "      device const float* row = kv_b + (head_row_base + d) * kv_lora_dim;\n"
         "      float k_nope = 0.0f;\n"
         "      for (uint r = 0; r < kv_lora_dim; r++) k_nope += row[r] * latent[r];\n"
         "      score += q_nope[h * qk_nope_dim + d] * k_nope;\n"
         "    }\n"
         "    uint pos = position_offset + t;\n"
         "    for (uint d = 0; d < rope_dim; d++) {\n"
         "      float x = k_rope_raw[d];\n"
         "      float rot = 0.0f;\n"
         "      uint freq_idx = 0;\n"
         "      if (interleave) {\n"
         "        uint pair = d ^ 1u;\n"
         "        rot = (d & 1u) ? k_rope_raw[pair] : -k_rope_raw[pair];\n"
         "        freq_idx = d / 2u;\n"
         "      } else {\n"
         "        if (d < half_dim) {\n"
         "          rot = -k_rope_raw[d + half_dim];\n"
         "          freq_idx = d;\n"
         "        } else {\n"
         "          rot = k_rope_raw[d - half_dim];\n"
         "          freq_idx = d - half_dim;\n"
         "        }\n"
         "      }\n"
         "      float angle = float(pos) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "      float k_rope = x * cos(angle) + rot * sin(angle);\n"
         "      score += q_rope[h * rope_dim + d] * k_rope;\n"
         "    }\n"
         "    float weight = exp(score * scale - max_score);\n"
         "    float value = 0.0f;\n"
         "    for (uint r = 0; r < kv_lora_dim; r++) value += v_row[r] * latent[r];\n"
         "    denom += weight;\n"
         "    acc += weight * value;\n"
         "  }\n"
         "  out[tid] = denom == 0.0f ? 0.0f : acc / denom;\n"
         "}\n"
         "kernel void mla_attention_indexed_batch_f32(device const float* q_nope [[buffer(0)]],\n"
         "                                            device const float* q_rope [[buffer(1)]],\n"
         "                                            device const float* cache [[buffer(2)]],\n"
         "                                            device const float* kv_b [[buffer(3)]],\n"
         "                                            device const uint* indices [[buffer(4)]],\n"
         "                                            device float* out [[buffer(5)]],\n"
         "                                            constant uint& context_len [[buffer(6)]],\n"
         "                                            constant uint& topk_capacity [[buffer(7)]],\n"
         "                                            constant uint& num_heads [[buffer(8)]],\n"
         "                                            constant uint& kv_lora_dim [[buffer(9)]],\n"
         "                                            constant uint& qk_nope_dim [[buffer(10)]],\n"
         "                                            constant uint& rope_dim [[buffer(11)]],\n"
         "                                            constant uint& v_head_dim [[buffer(12)]],\n"
         "                                            constant float& scale [[buffer(13)]],\n"
         "                                            constant float& theta [[buffer(14)]],\n"
         "                                            constant uint& interleave [[buffer(15)]],\n"
         "                                            constant uint& position_offset [[buffer(16)]],\n"
         "                                            constant uint& batch [[buffer(17)]],\n"
         "                                            uint tid [[thread_position_in_grid]]) {\n"
         "  uint total = batch * num_heads;\n"
         "  if (tid >= total) return;\n"
         "  uint token = tid / num_heads;\n"
         "  uint h = tid - token * num_heads;\n"
         "  uint token_stride = num_heads * v_head_dim;\n"
         "  uint head_row_base = h * (qk_nope_dim + v_head_dim);\n"
         "  uint cache_width = kv_lora_dim + rope_dim;\n"
         "  uint half_dim = rope_dim / 2;\n"
         "  uint index_stride = topk_capacity + 1u;\n"
         "  uint count = indices[token * index_stride];\n"
         "  if (count > topk_capacity) count = topk_capacity;\n"
         "  if (count == 0u) {\n"
         "    for (uint vd = 0; vd < v_head_dim; vd++) {\n"
         "      out[token * token_stride + h * v_head_dim + vd] = 0.0f;\n"
         "    }\n"
