         "  for (uint t = 0; t < q_context; t++) {\n"
         "    acc += weights[weights_base + t] * values[t * token_stride + value_offset];\n"
         "  }\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void mla_attention_batch_values_f32(device const float* cache [[buffer(0)]],\n"
         "                                           device const float* kv_b [[buffer(1)]],\n"
         "                                           device const float* weights [[buffer(2)]],\n"
         "                                           device float* out [[buffer(3)]],\n"
         "                                           constant uint& context_len [[buffer(4)]],\n"
         "                                           constant uint& num_heads [[buffer(5)]],\n"
         "                                           constant uint& kv_lora_dim [[buffer(6)]],\n"
         "                                           constant uint& qk_nope_dim [[buffer(7)]],\n"
         "                                           constant uint& rope_dim [[buffer(8)]],\n"
         "                                           constant uint& v_head_dim [[buffer(9)]],\n"
         "                                           constant uint& start_position [[buffer(10)]],\n"
         "                                           constant uint& batch [[buffer(11)]],\n"
         "                                           uint tid [[thread_position_in_grid]]) {\n"
         "  uint token_stride = num_heads * v_head_dim;\n"
         "  uint total = batch * token_stride;\n"
         "  if (tid >= total) return;\n"
         "  uint token = tid / token_stride;\n"
         "  uint rem = tid - token * token_stride;\n"
         "  uint h = rem / v_head_dim;\n"
         "  uint vd = rem - h * v_head_dim;\n"
         "  uint q_context = start_position + token + 1u;\n"
         "  if (q_context > context_len) q_context = context_len;\n"
         "  uint cache_width = kv_lora_dim + rope_dim;\n"
         "  uint head_row_base = h * (qk_nope_dim + v_head_dim);\n"
         "  device const float* v_row = kv_b + (head_row_base + qk_nope_dim + vd) * kv_lora_dim;\n"
         "  uint weights_base = (token * num_heads + h) * context_len;\n"
         "  float acc = 0.0f;\n"
         "  for (uint t = 0; t < q_context; t++) {\n"
         "    device const float* latent = cache + t * cache_width;\n"
         "    float value = 0.0f;\n"
         "    for (uint r = 0; r < kv_lora_dim; r++) value += v_row[r] * latent[r];\n"
         "    acc += weights[weights_base + t] * value;\n"
         "  }\n"
         "  out[tid] = acc;\n"
         "}\n"
         "kernel void mla_attention_batch_f32(device const float* q_nope [[buffer(0)]],\n"
         "                                    device const float* q_rope [[buffer(1)]],\n"
         "                                    device const float* cache [[buffer(2)]],\n"
         "                                    device const float* kv_b [[buffer(3)]],\n"
         "                                    device float* out [[buffer(4)]],\n"
         "                                    constant uint& context_len [[buffer(5)]],\n"
         "                                    constant uint& num_heads [[buffer(6)]],\n"
         "                                    constant uint& kv_lora_dim [[buffer(7)]],\n"
         "                                    constant uint& qk_nope_dim [[buffer(8)]],\n"
         "                                    constant uint& rope_dim [[buffer(9)]],\n"
         "                                    constant uint& v_head_dim [[buffer(10)]],\n"
         "                                    constant float& scale [[buffer(11)]],\n"
         "                                    constant float& theta [[buffer(12)]],\n"
         "                                    constant uint& interleave [[buffer(13)]],\n"
         "                                    constant uint& position_offset [[buffer(14)]],\n"
         "                                    constant uint& start_position [[buffer(15)]],\n"
         "                                    constant uint& batch [[buffer(16)]],\n"
         "                                    uint tid [[thread_position_in_grid]]) {\n"
         "  uint total = batch * num_heads;\n"
         "  if (tid >= total) return;\n"
         "  uint token = tid / num_heads;\n"
         "  uint h = tid - token * num_heads;\n"
         "  uint token_stride = num_heads * v_head_dim;\n"
         "  uint head_row_base = h * (qk_nope_dim + v_head_dim);\n"
         "  uint cache_width = kv_lora_dim + rope_dim;\n"
         "  uint half_dim = rope_dim / 2;\n"
         "  uint q_context = start_position + token + 1u;\n"
         "  if (q_context > context_len) q_context = context_len;\n"
         "  float max_score = -INFINITY;\n"
         "  for (uint t = 0; t < q_context; t++) {\n"
         "    device const float* latent = cache + t * cache_width;\n"
         "    device const float* k_rope_raw = latent + kv_lora_dim;\n"
         "    float score = 0.0f;\n"
         "    for (uint d = 0; d < qk_nope_dim; d++) {\n"
         "      device const float* row = kv_b + (head_row_base + d) * kv_lora_dim;\n"
         "      float k_nope = 0.0f;\n"
         "      for (uint r = 0; r < kv_lora_dim; r++) k_nope += row[r] * latent[r];\n"
         "      uint q_idx = token * num_heads * qk_nope_dim + h * qk_nope_dim + d;\n"
         "      score += q_nope[q_idx] * k_nope;\n"
         "    }\n"
         "    uint pos = position_offset + t;\n"
         "    for (uint d = 0; d < rope_dim; d++) {\n"
         "      float x = k_rope_raw[d];\n"
         "      float rot = 0.0f;\n"
         "      uint freq_idx = 0;\n"
         "      if (interleave) {\n"
         "        uint pair = d ^ 1u;\n"
         "        rot = (d & 1u) ? k_rope_raw[pair] : -k_rope_raw[pair];\n"
         "        freq_idx = d / 2u;\n"
         "      } else {\n"
         "        if (d < half_dim) {\n"
         "          rot = -k_rope_raw[d + half_dim];\n"
         "          freq_idx = d;\n"
         "        } else {\n"
         "          rot = k_rope_raw[d - half_dim];\n"
         "          freq_idx = d - half_dim;\n"
         "        }\n"
         "      }\n"
         "      float angle = float(pos) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "      float k_rope = x * cos(angle) + rot * sin(angle);\n"
         "      uint q_idx = token * num_heads * rope_dim + h * rope_dim + d;\n"
         "      score += q_rope[q_idx] * k_rope;\n"
         "    }\n"
         "    score *= scale;\n"
         "    if (score > max_score) max_score = score;\n"
         "  }\n"
         "  for (uint vd = 0; vd < v_head_dim; vd++) {\n"
         "    out[token * token_stride + h * v_head_dim + vd] = 0.0f;\n"
         "  }\n"
         "  float denom = 0.0f;\n"
         "  for (uint t = 0; t < q_context; t++) {\n"
         "    device const float* latent = cache + t * cache_width;\n"
         "    device const float* k_rope_raw = latent + kv_lora_dim;\n"
         "    float score = 0.0f;\n"
         "    for (uint d = 0; d < qk_nope_dim; d++) {\n"
         "      device const float* row = kv_b + (head_row_base + d) * kv_lora_dim;\n"
         "      float k_nope = 0.0f;\n"
         "      for (uint r = 0; r < kv_lora_dim; r++) k_nope += row[r] * latent[r];\n"
         "      uint q_idx = token * num_heads * qk_nope_dim + h * qk_nope_dim + d;\n"
         "      score += q_nope[q_idx] * k_nope;\n"
         "    }\n"
         "    uint pos = position_offset + t;\n"
         "    for (uint d = 0; d < rope_dim; d++) {\n"
         "      float x = k_rope_raw[d];\n"
         "      float rot = 0.0f;\n"
         "      uint freq_idx = 0;\n"
         "      if (interleave) {\n"
         "        uint pair = d ^ 1u;\n"
         "        rot = (d & 1u) ? k_rope_raw[pair] : -k_rope_raw[pair];\n"
         "        freq_idx = d / 2u;\n"
         "      } else {\n"
         "        if (d < half_dim) {\n"
         "          rot = -k_rope_raw[d + half_dim];\n"
         "          freq_idx = d;\n"
         "        } else {\n"
         "          rot = k_rope_raw[d - half_dim];\n"
         "          freq_idx = d - half_dim;\n"
         "        }\n"
         "      }\n"
         "      float angle = float(pos) / pow(theta, (2.0f * float(freq_idx)) / float(rope_dim));\n"
         "      float k_rope = x * cos(angle) + rot * sin(angle);\n"
         "      uint q_idx = token * num_heads * rope_dim + h * rope_dim + d;\n"
         "      score += q_rope[q_idx] * k_rope;\n"
         "    }\n"
         "    float weight = exp(score * scale - max_score);\n"
         "    denom += weight;\n"
         "    for (uint vd = 0; vd < v_head_dim; vd++) {\n"
         "      device const float* v_row = kv_b + (head_row_base + qk_nope_dim + vd) * kv_lora_dim;\n"
         "      float value = 0.0f;\n"
         "      for (uint r = 0; r < kv_lora_dim; r++) value += v_row[r] * latent[r];\n"
         "      uint out_idx = token * token_stride + h * v_head_dim + vd;\n"
         "      out[out_idx] += weight * value;\n"
         "    }\n"
         "  }\n"
         "  if (denom != 0.0f) {\n"
         "    for (uint vd = 0; vd < v_head_dim; vd++) {\n"
         "      uint out_idx = token * token_stride + h * v_head_dim + vd;\n"
         "      out[out_idx] /= denom;\n"
         "    }\n"
         "  }\n"
         "}\n";
}

static id<MTLComputePipelineState> make_pipeline(id<MTLDevice> device,
                                                  id<MTLLibrary> library,
                                                  NSString *name) {
    static NSMutableDictionary *pipeline_cache = nil;
    if (!pipeline_cache) {
        pipeline_cache = [NSMutableDictionary dictionary];
    }
    id<MTLComputePipelineState> cached = pipeline_cache[name];
    if (cached) {
        return cached;
    }
    NSError *error = nil;
    id<MTLFunction> fn = [library newFunctionWithName:name];
    if (!fn) {
        fprintf(stderr, "missing Metal function: %s\n", name.UTF8String);
        return nil;
    }
    id<MTLComputePipelineState> pipe = [device newComputePipelineStateWithFunction:fn
                                                                             error:&error];
    if (!pipe) {
        fprintf(stderr, "failed to create pipeline %s: %s\n",
                name.UTF8String, error.localizedDescription.UTF8String);
        return nil;
    }
    pipeline_cache[name] = pipe;
    return pipe;
}

static id<MTLLibrary> expert_kernel_library(id<MTLDevice> device,
                                            const char *label) {
    static id<MTLLibrary> library = nil;
    if (library) {
        return library;
    }
    NSError *error = nil;
    library = [device newLibraryWithSource:expert_kernel_source()
                                   options:nil
                                     error:&error];
    if (!library) {
        fprintf(stderr, "failed to compile %s kernels: %s\n",
                label,
                error.localizedDescription.UTF8String);
        return nil;
    }
    return library;
}

static id<MTLCommandQueue> shared_command_queue(id<MTLDevice> device) {
    static id<MTLCommandQueue> queue = nil;
    if (queue) {
        return queue;
    }
    queue = [device newCommandQueue];
    return queue;
}

static id<MTLComputeCommandEncoder> checked_compute_encoder(id<MTLCommandBuffer> cmd,
                                                            const char *label) {
    id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
    if (!enc) {
        fprintf(stderr, "failed to create %s command encoder\n", label);
    }
    return enc;
}

static MTLSize threadgroup_1d_for_pipeline(id<MTLComputePipelineState> pipe,
                                           NSUInteger total_threads) {
    NSUInteger max_threads = pipe.maxTotalThreadsPerThreadgroup;
    if (max_threads == 0 || max_threads > 256) {
        max_threads = 256;
    }
    NSUInteger width = total_threads < max_threads ? total_threads : max_threads;
    if (width == 0) width = 1;
    return MTLSizeMake(width, 1, 1);
}

static MTLSize threadgroup_2d_for_pipeline(id<MTLComputePipelineState> pipe,
                                           NSUInteger total_x,
                                           NSUInteger total_y) {
    NSUInteger max_threads = pipe.maxTotalThreadsPerThreadgroup;
    if (max_threads == 0 || max_threads > 256) {
        max_threads = 256;
    }
    NSUInteger width = total_x < 16 ? total_x : 16;
    if (width == 0) width = 1;
    if (width > max_threads) width = max_threads;
    NSUInteger max_height = max_threads / width;
    if (max_height == 0) max_height = 1;
    NSUInteger height = total_y < max_height ? total_y : max_height;
    if (height == 0) height = 1;
    return MTLSizeMake(width, height, 1);
}

static int encode_dequant4(id<MTLCommandBuffer> cmd,
                           id<MTLComputePipelineState> pipe,
                           id<MTLBuffer> data,
                           NSUInteger w_off,
                           NSUInteger s_off,
                           NSUInteger b_off,
                           id<MTLBuffer> input,
                           id<MTLBuffer> output,
                           uint32_t out_dim,
                           uint32_t in_dim,
                           uint32_t group_size,
                           uint32_t meta_dtype) {
    id<MTLComputeCommandEncoder> enc = checked_compute_encoder(cmd, "dequant4");
    if (!enc) return 0;
    [enc setComputePipelineState:pipe];
    [enc setBuffer:data offset:w_off atIndex:0];
    [enc setBuffer:data offset:s_off atIndex:1];
    [enc setBuffer:data offset:b_off atIndex:2];
    [enc setBuffer:input offset:0 atIndex:3];
    [enc setBuffer:output offset:0 atIndex:4];
    [enc setBytes:&out_dim length:sizeof(out_dim) atIndex:5];
    [enc setBytes:&in_dim length:sizeof(in_dim) atIndex:6];
    [enc setBytes:&group_size length:sizeof(group_size) atIndex:7];
    [enc setBytes:&meta_dtype length:sizeof(meta_dtype) atIndex:8];
    [enc dispatchThreads:MTLSizeMake(out_dim, 1, 1)
   threadsPerThreadgroup:threadgroup_1d_for_pipeline(pipe, out_dim)];
    [enc endEncoding];
    return 1;
}

static int encode_dequant4_batch(id<MTLCommandBuffer> cmd,
                                 id<MTLComputePipelineState> pipe,
                                 id<MTLBuffer> data,
                                 NSUInteger w_off,
