    [enc dispatchThreads:MTLSizeMake(out_dim, batch_tiles, 1)
   threadsPerThreadgroup:threadgroup_2d_for_pipeline(pipe, out_dim, batch_tiles)];
    [enc endEncoding];
    return 1;
}

