static int encode_mxfp4_matvec_weighted_add_batch(id<MTLCommandBuffer> cmd,
                                                  id<MTLComputePipelineState> pipe,
                                                  id<MTLBuffer> data,
                                                  NSUInteger w_off,
                                                  NSUInteger s_off,
                                                  id<MTLBuffer> input,
                                                  id<MTLBuffer> accum,
                                                  id<MTLBuffer> weights,
                                                  uint32_t out_dim,
                                                  uint32_t in_dim,
                                                  uint32_t group_size,
                                                  uint32_t batch) {
    id<MTLComputeCommandEncoder> enc =
        checked_compute_encoder(cmd, "mxfp4 matvec weighted add batch");
    if (!enc) return 0;
    [enc setComputePipelineState:pipe];
    [enc setBuffer:data offset:w_off atIndex:0];
    [enc setBuffer:data offset:s_off atIndex:1];
    [enc setBuffer:input offset:0 atIndex:2];
    [enc setBuffer:accum offset:0 atIndex:3];
    [enc setBuffer:weights offset:0 atIndex:4];
    [enc setBytes:&out_dim length:sizeof(out_dim) atIndex:5];
    [enc setBytes:&in_dim length:sizeof(in_dim) atIndex:6];
