static int encode_mxfp4_matvec_weighted_add_batch_token_tile(
    id<MTLCommandBuffer> cmd,
    id<MTLComputePipelineState> pipe,
    id<MTLBuffer> data,
    NSUInteger w_off,
    NSUInteger s_off,
    id<MTLBuffer> input,
    id<MTLBuffer> accum,
    id<MTLBuffer> weights,
    uint32_t out_dim,
    uint32_t in_dim,
    uint32_t group_size,
    uint32_t batch,
    uint32_t token_tile) {
    id<MTLComputeCommandEncoder> enc =
        checked_compute_encoder(cmd, "mxfp4 matvec weighted add batch token tile");
    if (!enc) return 0;
    uint32_t tile = token_tile ? token_tile : 1u;
    uint32_t batch_tiles = (batch + tile - 1u) / tile;
    [enc setComputePipelineState:pipe];
    [enc setBuffer:data offset:w_off atIndex:0];
    [enc setBuffer:data offset:s_off atIndex:1];
    [enc setBuffer:input offset:0 atIndex:2];
    [enc setBuffer:accum offset:0 atIndex:3];
    [enc setBuffer:weights offset:0 atIndex:4];
    [enc setBytes:&out_dim length:sizeof(out_dim) atIndex:5];
    [enc setBytes:&in_dim length:sizeof(in_dim) atIndex:6];
    [enc setBytes:&group_size length:sizeof(group_size) atIndex:7];
    [enc setBytes:&batch length:sizeof(batch) atIndex:8];
    [enc dispatchThreads:MTLSizeMake(out_dim, batch_tiles, 1)
   threadsPerThreadgroup:threadgroup_2d_for_pipeline(pipe, out_dim, batch_tiles)];
    [enc endEncoding];
    return 1;
}

