static float bf16_bits_to_f32(uint16_t v) {
    uint32_t bits = ((uint32_t)v) << 16;
    float out = 0.0f;
    memcpy(&out, &bits, sizeof(out));
    return out;
}

static uint16_t f32_to_bf16_bits(float v) {
    uint32_t bits = 0;
    memcpy(&bits, &v, sizeof(bits));
    uint32_t rounded = bits + 0x7FFFu + ((bits >> 16) & 1u);
    return (uint16_t)((rounded >> 16) & 0xFFFFu);
}

static float f16_bits_to_f32(uint16_t h) {
    uint32_t sign = ((uint32_t)h & 0x8000u) << 16;
    uint32_t exp = ((uint32_t)h >> 10) & 0x1Fu;
    uint32_t mant = (uint32_t)h & 0x03FFu;
    uint32_t bits = 0;
    if (exp == 0) {
        if (mant == 0) {
            bits = sign;
        } else {
            exp = 1;
            while ((mant & 0x0400u) == 0) {
                mant <<= 1;
                exp--;
            }
            mant &= 0x03FFu;
            bits = sign | ((exp + 112u) << 23) | (mant << 13);
        }
    } else if (exp == 31) {
        bits = sign | 0x7F800000u | (mant << 13);
    } else {
        bits = sign | ((exp + 112u) << 23) | (mant << 13);
    }
    float out = 0.0f;
    memcpy(&out, &bits, sizeof(out));
    return out;
}

static int vector_dtype_bytes(const char *dtype) {
    if (strcmp(dtype, "F32") == 0 || strcmp(dtype, "float32") == 0 ||
        strcmp(dtype, "FLOAT32") == 0) return 4;
    if (strcmp(dtype, "BF16") == 0 || strcmp(dtype, "bfloat16") == 0 ||
        strcmp(dtype, "BFLOAT16") == 0) return 2;
    if (strcmp(dtype, "F16") == 0 || strcmp(dtype, "float16") == 0 ||
        strcmp(dtype, "FLOAT16") == 0) return 2;
    return 0;
}

static int read_vector_f32(NSString *weight_path,
                           VectorTensorInfo info,
                           uint32_t expected_dim,
                           float **out) {
    *out = NULL;
    if (info.dim0 != expected_dim) {
        fprintf(stderr, "vector %s dim %u does not match expected %u\n",
                info.name, info.dim0, expected_dim);
        return 0;
    }
    int bytes_per_value = vector_dtype_bytes(info.dtype);
    if (!bytes_per_value) {
        fprintf(stderr, "unsupported vector dtype %s for %s\n", info.dtype, info.name);
        return 0;
    }
    uint64_t expected_bytes = (uint64_t)expected_dim * (uint64_t)bytes_per_value;
    if (expected_bytes != info.size) {
        fprintf(stderr, "vector %s size mismatch: layout=%llu expected=%llu\n",
                info.name,
                (unsigned long long)info.size,
                (unsigned long long)expected_bytes);
        return 0;
    }
    void *raw = malloc((size_t)info.size);
    if (!raw) return 0;
    if (!read_exact_slot(weight_path.UTF8String, raw, (size_t)info.size,
                         (off_t)info.offset)) {
        free(raw);
        return 0;
    }
    float *values = calloc(expected_dim, sizeof(float));
    if (!values) {
        free(raw);
        return 0;
    }
    if (strcmp(info.dtype, "F32") == 0 || strcmp(info.dtype, "float32") == 0 ||
        strcmp(info.dtype, "FLOAT32") == 0) {
        memcpy(values, raw, (size_t)expected_bytes);
    } else {
        uint16_t *src = (uint16_t *)raw;
        for (uint32_t i = 0; i < expected_dim; i++) {
            if (strcmp(info.dtype, "BF16") == 0 ||
                strcmp(info.dtype, "bfloat16") == 0 ||
                strcmp(info.dtype, "BFLOAT16") == 0) {
                values[i] = bf16_bits_to_f32(src[i]);
            } else {
                values[i] = f16_bits_to_f32(src[i]);
            }
        }
    }
    free(raw);
    *out = values;
    return 1;
}

static int convert_raw_values_to_f32_into(const void *raw,
                                          const char *dtype,
                                          uint64_t count,
                                          float *values);

static int convert_raw_values_to_f32(const void *raw,
                                     const char *dtype,
                                     uint64_t count,
                                     float **out) {
    *out = NULL;
    float *values = calloc((size_t)count, sizeof(float));
    if (!values) return 0;
    int ok = convert_raw_values_to_f32_into(raw, dtype, count, values);
    if (!ok) {
        free(values);
        return 0;
    }
    *out = values;
    return 1;
}

static int convert_raw_values_to_f32_into(const void *raw,
                                          const char *dtype,
                                          uint64_t count,
                                          float *values) {
    if (strcmp(dtype, "F32") == 0 || strcmp(dtype, "float32") == 0 ||
        strcmp(dtype, "FLOAT32") == 0) {
        memcpy(values, raw, (size_t)count * sizeof(float));
    } else if (strcmp(dtype, "BF16") == 0 || strcmp(dtype, "bfloat16") == 0 ||
               strcmp(dtype, "BFLOAT16") == 0) {
        const uint16_t *src = (const uint16_t *)raw;
        for (uint64_t i = 0; i < count; i++) values[i] = bf16_bits_to_f32(src[i]);
    } else if (strcmp(dtype, "F16") == 0 || strcmp(dtype, "float16") == 0 ||
               strcmp(dtype, "FLOAT16") == 0) {
        const uint16_t *src = (const uint16_t *)raw;
        for (uint64_t i = 0; i < count; i++) values[i] = f16_bits_to_f32(src[i]);
    } else {
        fprintf(stderr, "unsupported f32 conversion dtype %s\n", dtype);
        return 0;
    }
    return 1;
}

static int read_resident_matrix_f32(NSString *weight_path,
                                    ResidentMatrixInfo matrix,
                                    uint32_t expected_out,
                                    uint32_t expected_in,
                                    float **out,
                                    uint64_t *out_bytes) {
    *out = NULL;
    *out_bytes = 0;
    if (matrix.out_dim != expected_out || matrix.in_dim != expected_in) {
        fprintf(stderr, "matrix %s shape [%u,%u] does not match expected [%u,%u]\n",
                matrix.name, matrix.out_dim, matrix.in_dim,
                expected_out, expected_in);
        return 0;
    }
    if (!validate_resident_matrix(matrix)) return 0;
    void *raw = malloc((size_t)matrix.size);
    if (!raw) return 0;
    if (!read_exact_slot(weight_path.UTF8String, raw, (size_t)matrix.size,
                         (off_t)matrix.offset)) {
        free(raw);
        return 0;
    }
    uint64_t count = (uint64_t)expected_out * expected_in;
    float *values = NULL;
    int ok = convert_raw_values_to_f32(raw, matrix.dtype, count, &values);
    free(raw);
    if (!ok) return 0;
    *out = values;
    *out_bytes = count * sizeof(float);
    return 1;
}

static int read_resident_matrix_f32_into(NSString *weight_path,
                                         ResidentMatrixInfo matrix,
                                         uint32_t expected_out,
                                         uint32_t expected_in,
                                         float *out,
                                         uint64_t out_bytes) {
    if (matrix.out_dim != expected_out || matrix.in_dim != expected_in) {
        fprintf(stderr, "matrix %s shape [%u,%u] does not match expected [%u,%u]\n",
                matrix.name, matrix.out_dim, matrix.in_dim,
                expected_out, expected_in);
        return 0;
    }
    if (!validate_resident_matrix(matrix)) return 0;
    uint64_t count = (uint64_t)expected_out * expected_in;
    uint64_t f32_bytes = count * sizeof(float);
    if (out_bytes < f32_bytes) {
        fprintf(stderr, "matrix %s f32 output buffer too small: %llu < %llu\n",
                matrix.name,
                (unsigned long long)out_bytes,
                (unsigned long long)f32_bytes);
        return 0;
    }
    if (strcmp(matrix.dtype, "F32") == 0 ||
        strcmp(matrix.dtype, "float32") == 0 ||
        strcmp(matrix.dtype, "FLOAT32") == 0) {
        return read_exact_slot(weight_path.UTF8String, out, (size_t)f32_bytes,
                               (off_t)matrix.offset);
    }
    void *raw = malloc((size_t)matrix.size);
    if (!raw) return 0;
    if (!read_exact_slot(weight_path.UTF8String, raw, (size_t)matrix.size,
                         (off_t)matrix.offset)) {
        free(raw);
        return 0;
    }
    int ok = convert_raw_values_to_f32_into(raw, matrix.dtype, count, out);
    free(raw);
    return ok;
}

static float mxfp4_e2m1_to_f32_cpu(uint32_t q) {
    uint32_t mag = q & 0x7u;
    if (mag == 0u) return 0.0f;
    float sign = (q & 0x8u) ? -1.0f : 1.0f;
    float value = 0.0f;
    if (mag == 1u) value = 0.5f;
    else if (mag == 2u) value = 1.0f;
    else if (mag == 3u) value = 1.5f;
    else if (mag == 4u) value = 2.0f;
    else if (mag == 5u) value = 3.0f;
    else if (mag == 6u) value = 4.0f;
    else value = 6.0f;
    return sign * value;
}

static float mxfp4_e8m0_to_f32_cpu(uint8_t v) {
    uint32_t bits = ((uint32_t)v) << 23;
    float out = 0.0f;
    memcpy(&out, &bits, sizeof(out));
    return out;
}

static int read_resident_tensor3d_f32(NSString *weight_path,
                                      ResidentTensor3DInfo info,
                                      float **out,
                                      uint64_t *out_bytes) {
    *out = NULL;
    *out_bytes = 0;
    uint64_t f32_bytes = 0;
    if (!resident_tensor3d_f32_bytes(info, &f32_bytes)) return 0;
    if (f32_bytes > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "resident tensor %s f32 expansion is too large\n",
                info.name);
        return 0;
    }
    uint64_t count = f32_bytes / sizeof(float);
    float *values = calloc((size_t)count, sizeof(float));
    if (!values) return 0;

    if (info.is_mxfp4) {
        if (info.weight.size > (uint64_t)SIZE_MAX ||
            info.scales.size > (uint64_t)SIZE_MAX) {
            fprintf(stderr, "resident MXFP4 tensor %s is too large\n",
                    info.name);
            free(values);
            return 0;
        }
        uint32_t *raw_weight = malloc((size_t)info.weight.size);
        uint8_t *raw_scales = malloc((size_t)info.scales.size);
        if (!raw_weight || !raw_scales) {
            free(raw_weight);
            free(raw_scales);
            free(values);
            return 0;
        }
        if (!read_exact_slot(weight_path.UTF8String,
                             raw_weight,
                             (size_t)info.weight.size,
                             (off_t)info.weight.offset) ||
            !read_exact_slot(weight_path.UTF8String,
                             raw_scales,
                             (size_t)info.scales.size,
                             (off_t)info.scales.offset)) {
            free(raw_weight);
            free(raw_scales);
            free(values);
            return 0;
        }
        uint32_t packed_cols = info.weight.dims[2];
        uint32_t groups = info.scales.dims[2];
        uint64_t rows = 0;
        if (!checked_mul_u64((uint64_t)info.dim0, (uint64_t)info.dim1, &rows)) {
            free(raw_weight);
            free(raw_scales);
            free(values);
            return 0;
        }
        for (uint64_t row = 0; row < rows; row++) {
            uint64_t w_base = row * (uint64_t)packed_cols;
            uint64_t s_base = row * (uint64_t)groups;
            uint64_t out_base = row * (uint64_t)info.dim2;
            for (uint32_t p = 0; p < packed_cols; p++) {
                uint32_t packed = raw_weight[w_base + p];
                for (uint32_t i = 0; i < 8u; i++) {
                    uint32_t logical_col = p * 8u + i;
                    uint32_t group = logical_col / info.group_size;
                    float scale = mxfp4_e8m0_to_f32_cpu(raw_scales[s_base + group]);
                    float decoded =
                        mxfp4_e2m1_to_f32_cpu((packed >> (i * 4u)) & 0xFu) * scale;
                    values[out_base + logical_col] = decoded;
                }
            }
        }
        free(raw_weight);
        free(raw_scales);
    } else {
        uint64_t raw_count = 0;
        if (!resident_tensor_value_count(info.weight, &raw_count) ||
            raw_count != count ||
            info.weight.size > (uint64_t)SIZE_MAX) {
            fprintf(stderr, "resident tensor %s shape does not match f32 expansion\n",
                    info.name);
            free(values);
            return 0;
        }
        void *raw = malloc((size_t)info.weight.size);
        if (!raw) {
            free(values);
            return 0;
        }
        if (!read_exact_slot(weight_path.UTF8String,
                             raw,
                             (size_t)info.weight.size,
                             (off_t)info.weight.offset)) {
            free(raw);
            free(values);
            return 0;
        }
        int ok = convert_raw_values_to_f32_into(raw, info.weight.dtype, count, values);
        free(raw);
        if (!ok) {
            free(values);
            return 0;
        }
    }

    *out = values;
    *out_bytes = f32_bytes;
    return 1;
}

static int resolve_mla_attention_value_source(NSDictionary *resident_layout,
                                              uint64_t layer_id,
                                              uint32_t num_heads,
                                              uint32_t kv_lora_dim_arg,
                                              uint32_t qk_nope_dim,
                                              uint32_t v_head_dim,
                                              uint64_t max_matrix_bytes,
                                              MlaAttentionValueSourceInfo *out) {
    memset(out, 0, sizeof(*out));
    ResidentMatrixInfo kv_b = {0};
    if (find_resident_matrix_by_suffix_impl(resident_layout,
                                            layer_id,
                                            @".self_attn.kv_b_proj.weight",
                                            &kv_b,
                                            0)) {
        if (!validate_resident_matrix(kv_b)) return 0;
        if (!enforce_resident_matrix_limit(kv_b, max_matrix_bytes)) return 0;
        uint32_t kv_lora_dim = kv_lora_dim_arg ? kv_lora_dim_arg : kv_b.in_dim;
        uint64_t qv = 0;
        uint64_t expected_out_u64 = 0;
        uint64_t f32_values = 0;
        uint64_t f32_bytes = 0;
        if (!checked_add_u64((uint64_t)qk_nope_dim,
                             (uint64_t)v_head_dim,
                             &qv) ||
            !checked_mul_u64((uint64_t)num_heads, qv, &expected_out_u64) ||
            expected_out_u64 > UINT32_MAX ||
            !checked_mul_u64(expected_out_u64,
                             (uint64_t)kv_lora_dim,
                             &f32_values) ||
            !checked_mul_u64(f32_values, sizeof(float), &f32_bytes)) {
            fprintf(stderr, "kv_b attention value source byte size overflows uint64\n");
            return 0;
        }
        uint32_t expected_out = (uint32_t)expected_out_u64;
        if (kv_b.out_dim != expected_out || kv_b.in_dim != kv_lora_dim) {
            fprintf(stderr, "kv_b shape [%u,%u] does not match expected [%u,%u]\n",
                    kv_b.out_dim, kv_b.in_dim, expected_out, kv_lora_dim);
            return 0;
        }
        out->kv_b = kv_b;
        out->kv_lora_dim = kv_lora_dim;
        out->expected_kv_b_out = expected_out;
        out->storage_bytes = kv_b.size;
        out->kv_b_f32_bytes = f32_bytes;
        out->absorbed_source_f32_bytes = 0;
        out->use_absorbed_alias = 0;
        return 1;
    }

    ResidentTensor3DInfo embed_q = {0};
    ResidentTensor3DInfo unembed_out = {0};
    if (!find_resident_tensor3d_by_suffix(resident_layout,
                                          layer_id,
                                          @".self_attn.embed_q.weight",
                                          &embed_q,
                                          1) ||
        !find_resident_tensor3d_by_suffix(resident_layout,
                                          layer_id,
                                          @".self_attn.unembed_out.weight",
                                          &unembed_out,
                                          1)) {
        return 0;
    }
    if (!enforce_resident_tensor3d_limit(embed_q, max_matrix_bytes) ||
        !enforce_resident_tensor3d_limit(unembed_out, max_matrix_bytes) ||
        !enforce_resident_tensor3d_f32_limit(embed_q, max_matrix_bytes) ||
        !enforce_resident_tensor3d_f32_limit(unembed_out, max_matrix_bytes)) {
        return 0;
    }

    uint32_t kv_lora_dim = kv_lora_dim_arg ? kv_lora_dim_arg : embed_q.dim1;
    if (embed_q.dim0 != num_heads ||
        embed_q.dim1 != kv_lora_dim ||
        embed_q.dim2 != qk_nope_dim ||
        unembed_out.dim0 != num_heads ||
        unembed_out.dim1 != v_head_dim ||
        unembed_out.dim2 != kv_lora_dim) {
        fprintf(stderr,
                "absorbed attention alias shapes do not match expected "
                "embed_q [%u,%u,%u], unembed_out [%u,%u,%u]\n",
                num_heads,
                kv_lora_dim,
                qk_nope_dim,
                num_heads,
                v_head_dim,
                kv_lora_dim);
        return 0;
    }

    uint64_t qv = 0;
    uint64_t expected_out_u64 = 0;
    uint64_t kv_b_values = 0;
    uint64_t kv_b_bytes = 0;
    uint64_t storage_bytes = 0;
    uint64_t embed_f32_bytes = 0;
    uint64_t unembed_f32_bytes = 0;
    uint64_t source_f32_bytes = 0;
    if (!checked_add_u64((uint64_t)qk_nope_dim,
                         (uint64_t)v_head_dim,
                         &qv) ||
        !checked_mul_u64((uint64_t)num_heads, qv, &expected_out_u64) ||
        expected_out_u64 > UINT32_MAX ||
        !checked_mul_u64(expected_out_u64,
                         (uint64_t)kv_lora_dim,
                         &kv_b_values) ||
        !checked_mul_u64(kv_b_values, sizeof(float), &kv_b_bytes) ||
        !checked_add_u64(embed_q.total_bytes,
                         unembed_out.total_bytes,
                         &storage_bytes) ||
        !resident_tensor3d_f32_bytes(embed_q, &embed_f32_bytes) ||
        !resident_tensor3d_f32_bytes(unembed_out, &unembed_f32_bytes) ||
        !checked_add_u64(embed_f32_bytes,
                         unembed_f32_bytes,
                         &source_f32_bytes)) {
        fprintf(stderr, "absorbed attention value source byte size overflows uint64\n");
        return 0;
    }

    out->embed_q = embed_q;
    out->unembed_out = unembed_out;
    out->kv_lora_dim = kv_lora_dim;
    out->expected_kv_b_out = (uint32_t)expected_out_u64;
    out->storage_bytes = storage_bytes;
    out->kv_b_f32_bytes = kv_b_bytes;
    out->absorbed_source_f32_bytes = source_f32_bytes;
    out->use_absorbed_alias = 1;
    return 1;
}

static int read_absorbed_attention_kv_b_f32(NSString *weight_path,
                                            MlaAttentionValueSourceInfo source,
                                            uint32_t num_heads,
                                            uint32_t qk_nope_dim,
                                            uint32_t v_head_dim,
                                            float **out,
                                            uint64_t *out_bytes) {
    *out = NULL;
    *out_bytes = 0;
    if (source.kv_b_f32_bytes > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "absorbed attention kv_b f32 view is too large\n");
        return 0;
    }
    uint64_t kv_b_count = source.kv_b_f32_bytes / sizeof(float);
    float *kv_b = calloc((size_t)kv_b_count, sizeof(float));
    if (!kv_b) return 0;

    float *embed = NULL;
    uint64_t embed_bytes = 0;
    if (!read_resident_tensor3d_f32(weight_path,
                                    source.embed_q,
                                    &embed,
                                    &embed_bytes)) {
        free(kv_b);
        return 0;
    }
    uint32_t kv_lora_dim = source.kv_lora_dim;
    for (uint32_t h = 0; h < num_heads; h++) {
        uint64_t head_row_base =
            (uint64_t)h * (uint64_t)(qk_nope_dim + v_head_dim);
        for (uint32_t d = 0; d < qk_nope_dim; d++) {
            float *row = kv_b + (head_row_base + d) * (uint64_t)kv_lora_dim;
            for (uint32_t r = 0; r < kv_lora_dim; r++) {
                uint64_t src = ((uint64_t)h * kv_lora_dim + r) *
                               (uint64_t)qk_nope_dim + d;
                row[r] = embed[src];
            }
        }
    }
    free(embed);

    float *unembed = NULL;
    uint64_t unembed_bytes = 0;
    if (!read_resident_tensor3d_f32(weight_path,
                                    source.unembed_out,
                                    &unembed,
                                    &unembed_bytes)) {
        free(kv_b);
        return 0;
    }
    for (uint32_t h = 0; h < num_heads; h++) {
        uint64_t head_row_base =
            (uint64_t)h * (uint64_t)(qk_nope_dim + v_head_dim);
        for (uint32_t v = 0; v < v_head_dim; v++) {
            float *row =
                kv_b + (head_row_base + qk_nope_dim + v) *
                           (uint64_t)kv_lora_dim;
            for (uint32_t r = 0; r < kv_lora_dim; r++) {
                uint64_t src = ((uint64_t)h * v_head_dim + v) *
                               (uint64_t)kv_lora_dim + r;
                row[r] = unembed[src];
            }
        }
    }
    free(unembed);

    if (embed_bytes + unembed_bytes != source.absorbed_source_f32_bytes) {
        fprintf(stderr, "internal absorbed attention f32 byte estimate mismatch\n");
        free(kv_b);
        return 0;
    }
    *out = kv_b;
    *out_bytes = source.kv_b_f32_bytes;
    return 1;
}

static int read_mla_attention_value_source_f32(NSString *weight_path,
                                               MlaAttentionValueSourceInfo source,
                                               uint64_t layer_id,
                                               uint32_t num_heads,
                                               uint32_t qk_nope_dim,
                                               uint32_t v_head_dim,
                                               NSString *kv_b_cache_dir,
                                               float **out,
                                               uint64_t *out_bytes) {
    if (source.use_absorbed_alias) {
        if (kv_b_cache_dir) {
            NSString *cache_name = [NSString
                stringWithFormat:@"layer-%04llu-kvb-f32-h%u-kv%u-q%u-v%u-%llu-%llu-%llu-%llu.bin",
                                 (unsigned long long)layer_id,
                                 num_heads,
                                 source.kv_lora_dim,
                                 qk_nope_dim,
                                 v_head_dim,
                                 (unsigned long long)source.embed_q.weight.offset,
                                 (unsigned long long)source.embed_q.weight.size,
                                 (unsigned long long)source.unembed_out.weight.offset,
                                 (unsigned long long)source.unembed_out.weight.size];
            NSString *cache_path =
                [kv_b_cache_dir stringByAppendingPathComponent:cache_name];
            struct stat st;
            if (stat(cache_path.UTF8String, &st) == 0) {
                if (st.st_size < 0 ||
                    (uint64_t)st.st_size != source.kv_b_f32_bytes) {
                    fprintf(stderr,
                            "MLA kv_b cache %s has %llu bytes, expected %llu\n",
                            cache_path.UTF8String,
                            (unsigned long long)st.st_size,
                            (unsigned long long)source.kv_b_f32_bytes);
                    return 0;
                }
                if (source.kv_b_f32_bytes > (uint64_t)SIZE_MAX) {
                    fprintf(stderr, "MLA kv_b cache view is too large\n");
                    return 0;
                }
                float *cached = malloc((size_t)source.kv_b_f32_bytes);
                if (!cached) return 0;
                if (!read_exact_slot(cache_path.UTF8String,
                                     cached,
                                     (size_t)source.kv_b_f32_bytes,
                                     0)) {
                    free(cached);
                    return 0;
                }
                *out = cached;
                *out_bytes = source.kv_b_f32_bytes;
                return 1;
            }
            if (errno != ENOENT) {
                fprintf(stderr, "stat failed for MLA kv_b cache %s: %s\n",
                        cache_path.UTF8String, strerror(errno));
                return 0;
            }
            if (!read_absorbed_attention_kv_b_f32(weight_path,
                                                  source,
                                                  num_heads,
                                                  qk_nope_dim,
                                                  v_head_dim,
                                                  out,
                                                  out_bytes)) {
                return 0;
            }
            NSError *mkdir_error = nil;
            if (![[NSFileManager defaultManager]
                    createDirectoryAtPath:kv_b_cache_dir
              withIntermediateDirectories:YES
                               attributes:nil
                                    error:&mkdir_error]) {
                fprintf(stderr, "failed to create MLA kv_b cache dir %s: %s\n",
                        kv_b_cache_dir.UTF8String,
                        mkdir_error.localizedDescription.UTF8String);
                free(*out);
                *out = NULL;
                *out_bytes = 0;
                return 0;
            }
            NSString *tmp_path = [cache_path
                stringByAppendingFormat:@".tmp.%d", (int)getpid()];
            int fd = open(tmp_path.UTF8String,
                          O_WRONLY | O_CREAT | O_TRUNC,
                          0644);
            if (fd < 0) {
                fprintf(stderr, "open failed for MLA kv_b cache temp %s: %s\n",
                        tmp_path.UTF8String, strerror(errno));
                free(*out);
                *out = NULL;
                *out_bytes = 0;
                return 0;
            }
            int ok = write_exact_fd(fd,
                                    tmp_path.UTF8String,
                                    *out,
                                    (size_t)source.kv_b_f32_bytes,
                                    0);
            if (close(fd) != 0) ok = 0;
            if (!ok ||
                rename(tmp_path.UTF8String, cache_path.UTF8String) != 0) {
                fprintf(stderr, "failed to write MLA kv_b cache %s: %s\n",
                        cache_path.UTF8String, strerror(errno));
                unlink(tmp_path.UTF8String);
                free(*out);
                *out = NULL;
                *out_bytes = 0;
                return 0;
            }
            return 1;
        }
        return read_absorbed_attention_kv_b_f32(weight_path,
                                                source,
                                                num_heads,
                                                qk_nope_dim,
                                                v_head_dim,
                                                out,
                                                out_bytes);
    }
    return read_resident_matrix_f32(weight_path,
                                    source.kv_b,
                                    source.expected_kv_b_out,
                                    source.kv_lora_dim,
                                    out,
                                    out_bytes);
}

static NSString *linear_kernel_for_dtype(const char *dtype) {
    if (strcmp(dtype, "F32") == 0 || strcmp(dtype, "float32") == 0 ||
        strcmp(dtype, "FLOAT32") == 0) return @"router_f32";
    if (strcmp(dtype, "BF16") == 0 || strcmp(dtype, "bfloat16") == 0 ||
        strcmp(dtype, "BFLOAT16") == 0) return @"router_bf16";
    if (strcmp(dtype, "F16") == 0 || strcmp(dtype, "float16") == 0 ||
        strcmp(dtype, "FLOAT16") == 0) return @"linear_f16";
    return nil;
}

static NSString *linear_batch_kernel_for_dtype(const char *dtype) {
    if (strcmp(dtype, "F32") == 0 || strcmp(dtype, "float32") == 0 ||
        strcmp(dtype, "FLOAT32") == 0) return @"linear_batch_f32";
    if (strcmp(dtype, "BF16") == 0 || strcmp(dtype, "bfloat16") == 0 ||
        strcmp(dtype, "BFLOAT16") == 0) return @"linear_batch_bf16";
    if (strcmp(dtype, "F16") == 0 || strcmp(dtype, "float16") == 0 ||
        strcmp(dtype, "FLOAT16") == 0) return @"linear_batch_f16";
    return nil;
}

static int run_resident_matrix_matvec(id<MTLDevice> device,
                                      id<MTLCommandQueue> queue,
                                      id<MTLLibrary> library,
                                      NSString *weight_path,
                                      ResidentMatrixInfo matrix,
                                      id<MTLBuffer> input,
                                      id<MTLBuffer> output) {
    NSString *kernel_name = linear_kernel_for_dtype(matrix.dtype);
    if (!kernel_name) {
        fprintf(stderr, "unsupported matrix dtype %s for %s\n", matrix.dtype, matrix.name);
        return 0;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, kernel_name);
    if (!pipe) return 0;

    uint64_t alloc_size = align_up_u64(matrix.size, 2 * 1024 * 1024);
    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for resident matrix %s\n", matrix.name);
        return 0;
    }
    memset(aligned, 0, (size_t)alloc_size);
    if (!read_exact_slot(weight_path.UTF8String, aligned, (size_t)matrix.size,
                         (off_t)matrix.offset)) {
        free(aligned);
        return 0;
    }
    id<MTLBuffer> bMatrix =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bMatrix) {
        fprintf(stderr, "failed to wrap resident matrix %s as Metal buffer\n", matrix.name);
        free(aligned);
        return 0;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create resident matrix command buffer for %s\n",
                matrix.name);
        return 0;
    }
    if (!encode_router_matvec(cmd, pipe, bMatrix, input, output,
                              matrix.out_dim, matrix.in_dim)) {
        return 0;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "resident matrix command failed for %s: %s\n",
                matrix.name, cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

static int run_resident_matrix_batch_linear(id<MTLDevice> device,
                                            id<MTLCommandQueue> queue,
                                            id<MTLLibrary> library,
                                            NSString *weight_path,
                                            ResidentMatrixInfo matrix,
                                            id<MTLBuffer> input,
                                            id<MTLBuffer> output,
                                            uint32_t batch_tokens) {
    NSString *kernel_name = linear_batch_kernel_for_dtype(matrix.dtype);
    if (!kernel_name) {
        fprintf(stderr, "unsupported matrix dtype %s for %s\n", matrix.dtype, matrix.name);
        return 0;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, kernel_name);
    if (!pipe) return 0;

    uint64_t alloc_size = align_up_u64(matrix.size, 2 * 1024 * 1024);
    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for resident matrix %s\n", matrix.name);
        return 0;
    }
    memset(aligned, 0, (size_t)alloc_size);
    if (!read_exact_slot(weight_path.UTF8String, aligned, (size_t)matrix.size,
                         (off_t)matrix.offset)) {
        free(aligned);
        return 0;
    }
    id<MTLBuffer> bMatrix =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bMatrix) {
        fprintf(stderr, "failed to wrap resident matrix %s as Metal buffer\n", matrix.name);
        free(aligned);
        return 0;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create resident batch linear command buffer for %s\n",
                matrix.name);
        return 0;
    }
    id<MTLComputeCommandEncoder> enc =
        checked_compute_encoder(cmd, "resident batch linear");
    if (!enc) return 0;
    [enc setComputePipelineState:pipe];
    [enc setBuffer:bMatrix offset:0 atIndex:0];
    [enc setBuffer:input offset:0 atIndex:1];
    [enc setBuffer:output offset:0 atIndex:2];
    uint32_t out_dim = matrix.out_dim;
    uint32_t in_dim = matrix.in_dim;
    [enc setBytes:&out_dim length:sizeof(out_dim) atIndex:3];
    [enc setBytes:&in_dim length:sizeof(in_dim) atIndex:4];
    [enc setBytes:&batch_tokens length:sizeof(batch_tokens) atIndex:5];
    [enc dispatchThreads:MTLSizeMake(matrix.out_dim, batch_tokens, 1)
   threadsPerThreadgroup:MTLSizeMake(16, 16, 1)];
    [enc endEncoding];
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "resident batch linear command failed for %s: %s\n",
                matrix.name, cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

static id<MTLBuffer> new_resident_affine_int4_buffer(id<MTLDevice> device,
                                                     NSString *weight_path,
                                                     ResidentAffineInt4MatrixInfo info,
                                                     uint64_t *alloc_size_out) {
    if (info.total_bytes == 0 || info.total_bytes > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "resident affine-int4 matrix %s is too large\n", info.name);
        return nil;
    }
    uint64_t alloc_size = align_up_u64(info.total_bytes, 2 * 1024 * 1024);
    if (alloc_size > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "resident affine-int4 aligned buffer %s is too large\n",
                info.name);
        return nil;
    }
    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for resident affine-int4 matrix %s\n",
                info.name);
        return nil;
    }
    memset(aligned, 0, (size_t)alloc_size);
    char *dst = (char *)aligned;
    if (!read_exact_slot(weight_path.UTF8String,
                         dst,
                         (size_t)info.weight.size,
                         (off_t)info.weight.offset) ||
        !read_exact_slot(weight_path.UTF8String,
                         dst + info.weight.size,
                         (size_t)info.scales.size,
                         (off_t)info.scales.offset) ||
        !read_exact_slot(weight_path.UTF8String,
                         dst + info.weight.size + info.scales.size,
                         (size_t)info.biases.size,
                         (off_t)info.biases.offset)) {
        free(aligned);
        return nil;
    }
    id<MTLBuffer> buffer =
        [device newBufferWithBytesNoCopy:aligned
                                  length:(NSUInteger)alloc_size
                                 options:MTLResourceStorageModeShared
                             deallocator:^(void *pointer, NSUInteger length) {
                                 (void)length;
                                 free(pointer);
                             }];
    if (!buffer) {
        fprintf(stderr, "failed to wrap resident affine-int4 matrix %s as Metal buffer\n",
                info.name);
        free(aligned);
        return nil;
    }
    if (alloc_size_out) *alloc_size_out = alloc_size;
    return buffer;
}

