static int run_resident_affine_int4_matvec(id<MTLDevice> device,
                                           id<MTLCommandQueue> queue,
                                           id<MTLLibrary> library,
                                           NSString *weight_path,
                                           ResidentAffineInt4MatrixInfo info,
                                           id<MTLBuffer> input,
                                           id<MTLBuffer> output) {
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, @"dequant4");
    if (!pipe) return 0;
    uint64_t alloc_size = 0;
    id<MTLBuffer> bData = new_resident_affine_int4_buffer(device,
                                                          weight_path,
                                                          info,
                                                          &alloc_size);
    if (!bData) return 0;
    (void)alloc_size;
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create resident affine-int4 command buffer for %s\n",
                info.name);
        return 0;
    }
    if (!encode_dequant4(cmd,
                         pipe,
                         bData,
                         0,
                         info.weight.size,
                         info.weight.size + info.scales.size,
                         input,
                         output,
                         info.out_dim,
                         info.in_dim,
                         info.group_size,
                         info.meta_dtype)) {
        return 0;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "resident affine-int4 command failed for %s: %s\n",
                info.name,
                cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

