static uint32_t resident_mxfp4_batch_token_tile_from_env(int *ok) {
    if (ok) *ok = 1;
    const char *value = getenv("LARGERLM_MXFP4_BATCH_TOKEN_TILE");
    if (!value || value[0] == '\0' || strcmp(value, "1") == 0) {
        return 1u;
    }
    if (strcmp(value, "2") == 0) return 2u;
    if (strcmp(value, "4") == 0) return 4u;
    fprintf(stderr,
            "unsupported LARGERLM_MXFP4_BATCH_TOKEN_TILE=%s; expected 1, 2, or 4\n",
            value);
    if (ok) *ok = 0;
    return 1u;
}

static int resident_mxfp4_batch_group32_specialized_from_env(ResidentMxfp4MatrixInfo info,
                                                             uint32_t token_tile,
                                                             int *ok) {
    if (ok) *ok = 1;
    const char *value = getenv("LARGERLM_MXFP4_GROUP32_SPECIALIZED");
    int value_set = value && value[0] != '\0';
    int value_enable = 0;
    if (value_set) {
        value_enable =
            strcmp(value, "0") != 0 &&
            strcasecmp(value, "false") != 0 &&
            strcasecmp(value, "no") != 0 &&
            strcasecmp(value, "off") != 0;
    }
    int want_specialized =
        (value_set && value_enable) ||
        (!value_set && token_tile == 1u && info.group_size == 32u);
    if (!want_specialized) return 0;
    if (token_tile != 1u || info.group_size != 32u) {
        fprintf(stderr,
                "LARGERLM_MXFP4_GROUP32_SPECIALIZED requires MXFP4 token tile 1 and group size 32\n");
        if (ok) *ok = 0;
        return 0;
    }
    return 1;
}

static int resident_shared_mxfp4_group32_specialized_from_env(SharedExpertInfo info,
                                                              int *ok) {
    if (ok) *ok = 1;
    int all_group32 =
        info.gate_mxfp4.group_size == 32u &&
        info.up_mxfp4.group_size == 32u &&
        info.down_mxfp4.group_size == 32u;
    const char *value = getenv("LARGERLM_SHARED_MXFP4_GROUP32_SPECIALIZED");
    int value_set = value && value[0] != '\0';
    int want_specialized = 0;
    if (value_set) {
        want_specialized =
            strcmp(value, "0") != 0 &&
            strcasecmp(value, "false") != 0 &&
            strcasecmp(value, "no") != 0 &&
            strcasecmp(value, "off") != 0;
    }
    if (!want_specialized) return 0;
    if (!all_group32) {
        fprintf(stderr,
                "LARGERLM_SHARED_MXFP4_GROUP32_SPECIALIZED requires shared MXFP4 gate/up/down group size 32\n");
        if (ok) *ok = 0;
        return 0;
    }
    return 1;
}

static int run_resident_mxfp4_batch_linear(id<MTLDevice> device,
                                           id<MTLCommandQueue> queue,
                                           id<MTLLibrary> library,
                                           NSString *weight_path,
                                           ResidentMxfp4MatrixInfo info,
                                           id<MTLBuffer> input,
                                           id<MTLBuffer> output,
                                           uint32_t batch_tokens) {
    int token_tile_ok = 1;
    uint32_t token_tile = resident_mxfp4_batch_token_tile_from_env(&token_tile_ok);
    if (!token_tile_ok) return 0;
    int group32_ok = 1;
    int group32_specialized =
        resident_mxfp4_batch_group32_specialized_from_env(info,
                                                          token_tile,
                                                          &group32_ok);
    if (!group32_ok) return 0;
    NSString *kernel_name = @"mxfp4_matvec_batch";
    if (group32_specialized) {
        kernel_name = @"mxfp4_matvec_batch_gs32";
    } else if (token_tile == 2u) {
        kernel_name = @"mxfp4_matvec_batch_t2";
    } else if (token_tile == 4u) {
        kernel_name = @"mxfp4_matvec_batch_t4";
    }
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, kernel_name);
    if (!pipe) return 0;
    uint64_t alloc_size = 0;
    id<MTLBuffer> bData = new_resident_mxfp4_buffer(device,
                                                    weight_path,
                                                    info,
                                                    &alloc_size);
    if (!bData) return 0;
    (void)alloc_size;
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create resident MXFP4 batch command buffer for %s\n",
                info.name);
        return 0;
    }
    int encoded = 0;
    if (token_tile == 1u) {
        encoded = encode_mxfp4_matvec_batch(cmd,
                                            pipe,
                                            bData,
                                            0,
                                            info.weight.size,
                                            input,
                                            output,
                                            info.out_dim,
                                            info.in_dim,
                                            info.group_size,
                                            batch_tokens);
    } else {
        encoded = encode_mxfp4_matvec_batch_token_tile(cmd,
                                                       pipe,
                                                       bData,
                                                       0,
                                                       info.weight.size,
                                                       input,
                                                       output,
                                                       info.out_dim,
                                                       info.in_dim,
                                                       info.group_size,
                                                       batch_tokens,
                                                       token_tile);
    }
    if (!encoded) {
        return 0;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "resident MXFP4 batch command failed for %s: %s\n",
                info.name,
                cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

static int run_resident_shared_mxfp4_expert_batch(id<MTLDevice> device,
                                                  NSString *resident_layout_path,
                                                  uint64_t layer_id,
                                                  NSString *input_path,
                                                  NSString *output_path,
                                                  uint32_t batch_tokens,
                                                  uint64_t max_matrix_bytes,
                                                  uint64_t max_runner_scratch_bytes) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    SharedExpertInfo info = {0};
    if (!parse_shared_expert_layout(resident_layout, layer_id, &info)) return 1;
    if (!info.gate_is_mxfp4 || !info.up_is_mxfp4 || !info.down_is_mxfp4) {
        fprintf(stderr,
                "resident shared expert batch currently requires MXFP4 gate/up/down matrices\n");
        return 1;
    }
    if (info.gate_mxfp4.group_size != info.up_mxfp4.group_size) {
        fprintf(stderr,
                "shared MXFP4 gate/up group sizes differ: %u vs %u\n",
                info.gate_mxfp4.group_size,
                info.up_mxfp4.group_size);
        return 1;
    }
    if (!enforce_shared_component_matrix_limit("shared gate",
                                               info.gate,
                                               info.gate_affine,
                                               info.gate_mxfp4,
                                               info.gate_is_affine_int4,
                                               info.gate_is_mxfp4,
                                               max_matrix_bytes) ||
        !enforce_shared_component_matrix_limit("shared up",
                                               info.up,
                                               info.up_affine,
                                               info.up_mxfp4,
                                               info.up_is_affine_int4,
                                               info.up_is_mxfp4,
                                               max_matrix_bytes) ||
        !enforce_shared_component_matrix_limit("shared down",
                                               info.down,
                                               info.down_affine,
                                               info.down_mxfp4,
                                               info.down_is_affine_int4,
                                               info.down_is_mxfp4,
                                               max_matrix_bytes)) {
        return 1;
    }
    if (batch_tokens == 0) {
        fprintf(stderr, "--batch-tokens must be positive\n");
        return 1;
    }
    uint64_t input_row_bytes = (uint64_t)info.hidden_dim * sizeof(float);
    uint64_t act_row_bytes = (uint64_t)info.intermediate_dim * sizeof(float);
    if (input_row_bytes == 0 || act_row_bytes == 0 ||
        (uint64_t)batch_tokens > UINT64_MAX / input_row_bytes ||
        (uint64_t)batch_tokens > UINT64_MAX / act_row_bytes) {
        fprintf(stderr, "resident shared expert batch byte size overflow\n");
        return 1;
    }
    uint64_t input_bytes = (uint64_t)batch_tokens * input_row_bytes;
    uint64_t act_bytes = (uint64_t)batch_tokens * act_row_bytes;
    uint64_t output_bytes = input_bytes;
    if (input_bytes > (uint64_t)SIZE_MAX ||
        act_bytes > (uint64_t)SIZE_MAX ||
        output_bytes > (uint64_t)SIZE_MAX ||
        input_bytes > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "resident shared expert batch buffers are too large\n");
        return 1;
    }
    struct stat input_stat;
    if (stat(input_path.UTF8String, &input_stat) != 0) {
        fprintf(stderr, "stat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        return 1;
    }
    if (input_stat.st_size < 0 || (uint64_t)input_stat.st_size != input_bytes) {
        fprintf(stderr, "shared expert batch input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_stat.st_size,
                (unsigned long long)input_bytes);
        return 1;
    }
    uint64_t gate_alloc = align_up_u64(info.gate_mxfp4.total_bytes, 2 * 1024 * 1024);
    uint64_t up_alloc = align_up_u64(info.up_mxfp4.total_bytes, 2 * 1024 * 1024);
    uint64_t down_alloc = align_up_u64(info.down_mxfp4.total_bytes, 2 * 1024 * 1024);
    if (gate_alloc > UINT64_MAX - up_alloc ||
        gate_alloc + up_alloc > UINT64_MAX - down_alloc ||
        gate_alloc + up_alloc + down_alloc > UINT64_MAX - input_bytes ||
        gate_alloc + up_alloc + down_alloc + input_bytes > UINT64_MAX - act_bytes ||
        gate_alloc + up_alloc + down_alloc + input_bytes + act_bytes >
            UINT64_MAX - output_bytes) {
        fprintf(stderr, "resident shared expert estimated peak overflow\n");
        return 1;
    }
    uint64_t matrix_scratch_bytes = gate_alloc + up_alloc + down_alloc;
    uint64_t peak = matrix_scratch_bytes + input_bytes + act_bytes + output_bytes;
    if (!enforce_scratch_limit("resident shared expert batch", peak,
                               max_runner_scratch_bytes)) {
        return 1;
    }

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read shared expert input f32 file: %s\n",
                input_path.UTF8String);
        return 1;
    }
    if (input_data.length != (NSUInteger)input_bytes) {
        fprintf(stderr, "shared expert input bytes changed while reading: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)input_bytes);
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "resident shared expert batch");
    if (!library) return 1;
    int group32_ok = 1;
    int group32_specialized =
        resident_shared_mxfp4_group32_specialized_from_env(info, &group32_ok);
    if (!group32_ok) return 1;
    NSString *swiglu_kernel_name =
        group32_specialized ? @"mxfp4_swiglu_batch_gs32" : @"mxfp4_swiglu_batch";
    NSString *down_kernel_name =
        group32_specialized ? @"mxfp4_matvec_batch_gs32" : @"mxfp4_matvec_batch";
    id<MTLComputePipelineState> swiglu =
        make_pipeline(device, library, swiglu_kernel_name);
    id<MTLComputePipelineState> down =
        make_pipeline(device, library, down_kernel_name);
    if (!swiglu || !down) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:(NSUInteger)act_bytes
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bAct || !bOut) {
        fprintf(stderr, "failed to allocate resident shared expert buffers\n");
        return 1;
    }
    uint64_t gate_actual_alloc = 0;
    uint64_t up_actual_alloc = 0;
    uint64_t down_actual_alloc = 0;
    id<MTLBuffer> bGate = new_resident_mxfp4_buffer(device,
                                                    weight_path,
                                                    info.gate_mxfp4,
                                                    &gate_actual_alloc);
    id<MTLBuffer> bUp = new_resident_mxfp4_buffer(device,
                                                  weight_path,
                                                  info.up_mxfp4,
                                                  &up_actual_alloc);
    id<MTLBuffer> bDown = new_resident_mxfp4_buffer(device,
                                                    weight_path,
                                                    info.down_mxfp4,
                                                    &down_actual_alloc);
    if (!bGate || !bUp || !bDown) return 1;

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create resident shared expert command buffer\n");
        return 1;
    }
    CFAbsoluteTime backend_started = CFAbsoluteTimeGetCurrent();
    if (!encode_mxfp4_swiglu_batch(cmd,
                                   swiglu,
                                   bGate,
                                   0,
                                   info.gate_mxfp4.weight.size,
                                   bUp,
                                   0,
                                   info.up_mxfp4.weight.size,
                                   bInput,
                                   bAct,
                                   info.intermediate_dim,
                                   info.hidden_dim,
                                   info.gate_mxfp4.group_size,
                                   batch_tokens,
                                   0u) ||
        !encode_mxfp4_matvec_batch(cmd,
                                   down,
                                   bDown,
                                   0,
                                   info.down_mxfp4.weight.size,
                                   bAct,
                                   bOut,
                                   info.hidden_dim,
                                   info.intermediate_dim,
                                   info.down_mxfp4.group_size,
                                   batch_tokens)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    double backend_elapsed = CFAbsoluteTimeGetCurrent() - backend_started;
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "resident shared expert batch command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    if (output_path) {
        NSData *out_data = [NSData dataWithBytes:bOut.contents length:(NSUInteger)output_bytes];
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write shared expert output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }

    float *out = (float *)bOut.contents;
    printf("LargerLM resident shared expert batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  quantization:       mlx-mxfp4\n");
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  intermediate dim:   %u\n", info.intermediate_dim);
    printf("  gate tensor:        %s\n", info.gate.name);
    printf("  up tensor:          %s\n", info.up.name);
    printf("  down tensor:        %s\n", info.down.name);
    printf("  gate group size:    %u\n", info.gate_mxfp4.group_size);
    printf("  up group size:      %u\n", info.up_mxfp4.group_size);
    printf("  down group size:    %u\n", info.down_mxfp4.group_size);
    printf("  MXFP4 group32 path: %s\n", group32_specialized ? "yes" : "no");
    printf("  gate bytes:         %llu\n", (unsigned long long)info.gate_mxfp4.total_bytes);
    printf("  up bytes:           %llu\n", (unsigned long long)info.up_mxfp4.total_bytes);
    printf("  down bytes:         %llu\n", (unsigned long long)info.down_mxfp4.total_bytes);
    printf("  gate alloc bytes:   %llu\n", (unsigned long long)gate_actual_alloc);
    printf("  up alloc bytes:     %llu\n", (unsigned long long)up_actual_alloc);
    printf("  down alloc bytes:   %llu\n", (unsigned long long)down_actual_alloc);
    printf("  matrix scratch:     %llu\n", (unsigned long long)matrix_scratch_bytes);
    printf("  input bytes:        %llu\n", (unsigned long long)input_bytes);
    printf("  activation bytes:   %llu\n", (unsigned long long)act_bytes);
    printf("  output bytes:       %llu\n", (unsigned long long)output_bytes);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing backend:     %.6f\n", backend_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_resident_linear_matvec_dispatch(id<MTLDevice> device,
                                               id<MTLCommandQueue> queue,
                                               id<MTLLibrary> library,
                                               NSString *weight_path,
                                               ResidentMatrixInfo matrix,
                                               ResidentAffineInt4MatrixInfo affine,
                                               ResidentMxfp4MatrixInfo mxfp4,
                                               int is_affine_int4,
                                               int is_mxfp4,
                                               id<MTLBuffer> input,
                                               id<MTLBuffer> output) {
    if (is_mxfp4) {
        return run_resident_mxfp4_matvec(device, queue, library, weight_path,
                                         mxfp4, input, output);
    }
    if (is_affine_int4) {
        return run_resident_affine_int4_matvec(device, queue, library, weight_path,
                                               affine, input, output);
    }
    return run_resident_matrix_matvec(device, queue, library, weight_path,
                                      matrix, input, output);
}

static int run_resident_matrix_batch_linear_mpsgraph_f32(id<MTLDevice> device,
                                                         id<MTLCommandQueue> queue,
                                                         NSString *weight_path,
                                                         ResidentMatrixInfo matrix,
                                                         id<MTLBuffer> input,
                                                         id<MTLBuffer> output,
                                                         uint32_t batch_tokens,
                                                         double *matrix_f32_elapsed_seconds,
                                                         double *graph_elapsed_seconds) {
    if (matrix_f32_elapsed_seconds) *matrix_f32_elapsed_seconds = 0.0;
    if (graph_elapsed_seconds) *graph_elapsed_seconds = 0.0;
    int dtype_ok = (
        strcmp(matrix.dtype, "F32") == 0 ||
        strcmp(matrix.dtype, "float32") == 0 ||
        strcmp(matrix.dtype, "FLOAT32") == 0 ||
        strcmp(matrix.dtype, "BF16") == 0 ||
        strcmp(matrix.dtype, "bfloat16") == 0 ||
        strcmp(matrix.dtype, "BFLOAT16") == 0 ||
        strcmp(matrix.dtype, "F16") == 0 ||
        strcmp(matrix.dtype, "float16") == 0 ||
        strcmp(matrix.dtype, "FLOAT16") == 0
    );
    if (!dtype_ok) {
        fprintf(stderr,
                "mpsgraph-f32 backend supports F32/BF16/F16 resident matrices, got %s for %s\n",
                matrix.dtype,
                matrix.name);
        return 0;
    }
    CFAbsoluteTime matrix_f32_started = CFAbsoluteTimeGetCurrent();
    uint64_t matrix_f32_bytes = (uint64_t)matrix.out_dim * matrix.in_dim * sizeof(float);
    uint64_t alloc_size = align_up_u64(matrix_f32_bytes, 2 * 1024 * 1024);
    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for MPSGraph matrix %s\n", matrix.name);
        return 0;
    }
    memset(aligned, 0, (size_t)alloc_size);
    if (!read_resident_matrix_f32_into(weight_path, matrix, matrix.out_dim, matrix.in_dim,
                                       (float *)aligned, alloc_size)) {
        free(aligned);
        return 0;
    }
    id<MTLBuffer> bMatrix =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bMatrix) {
        fprintf(stderr, "failed to wrap MPSGraph matrix %s as Metal buffer\n", matrix.name);
        free(aligned);
        return 0;
    }
    if (matrix_f32_elapsed_seconds) {
        *matrix_f32_elapsed_seconds = CFAbsoluteTimeGetCurrent() - matrix_f32_started;
    }

    @autoreleasepool {
        @try {
            CFAbsoluteTime graph_started = CFAbsoluteTimeGetCurrent();
            MPSGraph *graph = [MPSGraph new];
            graph.options = MPSGraphOptionsSynchronizeResults;
            MPSShape *inputShape = @[@(batch_tokens), @(matrix.in_dim)];
            MPSShape *matrixShape = @[@(matrix.out_dim), @(matrix.in_dim)];
            MPSShape *outputShape = @[@(batch_tokens), @(matrix.out_dim)];
            MPSGraphTensor *inputTensor = [graph placeholderWithShape:inputShape
                                                             dataType:MPSDataTypeFloat32
                                                                 name:@"input"];
            MPSGraphTensor *matrixTensor = [graph placeholderWithShape:matrixShape
                                                              dataType:MPSDataTypeFloat32
                                                                  name:@"matrix_out_in"];
            MPSGraphTensor *matrixT = [graph transposeTensor:matrixTensor
                                                   dimension:0
                                               withDimension:1
                                                        name:@"matrix_in_out"];
            MPSGraphTensor *outTensor =
                [graph matrixMultiplicationWithPrimaryTensor:inputTensor
                                             secondaryTensor:matrixT
                                                        name:@"resident_batch_linear"];
            MPSGraphTensorData *inputData =
                [[MPSGraphTensorData alloc] initWithMTLBuffer:input
                                                        shape:inputShape
                                                     dataType:MPSDataTypeFloat32];
            MPSGraphTensorData *matrixData =
                [[MPSGraphTensorData alloc] initWithMTLBuffer:bMatrix
                                                        shape:matrixShape
                                                     dataType:MPSDataTypeFloat32];
            MPSGraphTensorData *outputData =
                [[MPSGraphTensorData alloc] initWithMTLBuffer:output
                                                        shape:outputShape
                                                     dataType:MPSDataTypeFloat32];
            if (!inputData || !matrixData || !outputData) {
                fprintf(stderr, "failed to create MPSGraph tensor data for %s\n", matrix.name);
                return 0;
            }
            MPSGraphTensorDataDictionary *feeds = @{
                inputTensor: inputData,
                matrixTensor: matrixData,
            };
            MPSGraphTensorDataDictionary *results = @{
                outTensor: outputData,
            };
            [graph runWithMTLCommandQueue:queue
                                    feeds:feeds
                         targetOperations:nil
                        resultsDictionary:results];
            if (graph_elapsed_seconds) {
                *graph_elapsed_seconds = CFAbsoluteTimeGetCurrent() - graph_started;
            }
        } @catch (NSException *exception) {
            fprintf(stderr,
                    "MPSGraph resident batch linear failed for %s: %s\n",
                    matrix.name,
                    exception.reason.UTF8String);
            return 0;
        }
    }
    return 1;
}

static int run_resident_matrix_batch_linear_mps_matrix_f32(id<MTLDevice> device,
                                                           id<MTLCommandQueue> queue,
                                                           NSString *weight_path,
                                                           ResidentMatrixInfo matrix,
                                                           id<MTLBuffer> input,
                                                           id<MTLBuffer> output,
                                                           uint32_t batch_tokens,
                                                           double *matrix_f32_elapsed_seconds,
                                                           double *mps_elapsed_seconds) {
    if (matrix_f32_elapsed_seconds) *matrix_f32_elapsed_seconds = 0.0;
    if (mps_elapsed_seconds) *mps_elapsed_seconds = 0.0;
    int dtype_ok = (
        strcmp(matrix.dtype, "F32") == 0 ||
        strcmp(matrix.dtype, "float32") == 0 ||
        strcmp(matrix.dtype, "FLOAT32") == 0 ||
        strcmp(matrix.dtype, "BF16") == 0 ||
        strcmp(matrix.dtype, "bfloat16") == 0 ||
        strcmp(matrix.dtype, "BFLOAT16") == 0 ||
        strcmp(matrix.dtype, "F16") == 0 ||
        strcmp(matrix.dtype, "float16") == 0 ||
        strcmp(matrix.dtype, "FLOAT16") == 0
    );
    if (!dtype_ok) {
        fprintf(stderr,
                "mps-matrix-f32 backend supports F32/BF16/F16 resident matrices, got %s for %s\n",
                matrix.dtype,
                matrix.name);
        return 0;
    }
    CFAbsoluteTime matrix_f32_started = CFAbsoluteTimeGetCurrent();
    uint64_t matrix_f32_bytes = (uint64_t)matrix.out_dim * matrix.in_dim * sizeof(float);
    uint64_t alloc_size = align_up_u64(matrix_f32_bytes, 2 * 1024 * 1024);
    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for MPSMatrix matrix %s\n", matrix.name);
        return 0;
    }
    memset(aligned, 0, (size_t)alloc_size);
    if (!read_resident_matrix_f32_into(weight_path, matrix, matrix.out_dim, matrix.in_dim,
                                       (float *)aligned, alloc_size)) {
        free(aligned);
        return 0;
    }
    id<MTLBuffer> bMatrix =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bMatrix) {
        fprintf(stderr, "failed to wrap MPSMatrix matrix %s as Metal buffer\n", matrix.name);
        free(aligned);
        return 0;
    }
    if (matrix_f32_elapsed_seconds) {
        *matrix_f32_elapsed_seconds = CFAbsoluteTimeGetCurrent() - matrix_f32_started;
    }

    @autoreleasepool {
        @try {
            CFAbsoluteTime mps_started = CFAbsoluteTimeGetCurrent();
            NSUInteger input_row_bytes = (NSUInteger)matrix.in_dim * sizeof(float);
            NSUInteger right_row_bytes = (NSUInteger)matrix.in_dim * sizeof(float);
            NSUInteger output_row_bytes = (NSUInteger)matrix.out_dim * sizeof(float);
            MPSMatrixDescriptor *inputDesc =
                [MPSMatrixDescriptor matrixDescriptorWithRows:batch_tokens
                                                      columns:matrix.in_dim
                                                     rowBytes:input_row_bytes
                                                     dataType:MPSDataTypeFloat32];
            MPSMatrixDescriptor *rightDesc =
                [MPSMatrixDescriptor matrixDescriptorWithRows:matrix.out_dim
                                                      columns:matrix.in_dim
                                                     rowBytes:right_row_bytes
                                                     dataType:MPSDataTypeFloat32];
            MPSMatrixDescriptor *outputDesc =
                [MPSMatrixDescriptor matrixDescriptorWithRows:batch_tokens
                                                      columns:matrix.out_dim
                                                     rowBytes:output_row_bytes
                                                     dataType:MPSDataTypeFloat32];
            MPSMatrix *inputMatrix = [[MPSMatrix alloc] initWithBuffer:input
                                                            descriptor:inputDesc];
            MPSMatrix *rightMatrix = [[MPSMatrix alloc] initWithBuffer:bMatrix
                                                            descriptor:rightDesc];
            MPSMatrix *outputMatrix = [[MPSMatrix alloc] initWithBuffer:output
                                                             descriptor:outputDesc];
            if (!inputMatrix || !rightMatrix || !outputMatrix) {
                fprintf(stderr, "failed to create MPSMatrix views for %s\n", matrix.name);
                return 0;
            }
            MPSMatrixMultiplication *matmul =
                [[MPSMatrixMultiplication alloc] initWithDevice:device
                                                  transposeLeft:NO
                                                 transposeRight:YES
                                                     resultRows:batch_tokens
                                                  resultColumns:matrix.out_dim
                                                interiorColumns:matrix.in_dim
                                                          alpha:1.0
                                                           beta:0.0];
            id<MTLCommandBuffer> cmd = [queue commandBuffer];
            if (!cmd) {
                fprintf(stderr, "failed to create MPSMatrix command buffer for %s\n",
                        matrix.name);
                return 0;
            }
            [matmul encodeToCommandBuffer:cmd
                                leftMatrix:inputMatrix
                               rightMatrix:rightMatrix
                              resultMatrix:outputMatrix];
            [cmd commit];
            [cmd waitUntilCompleted];
            if (cmd.status == MTLCommandBufferStatusError) {
                fprintf(stderr, "MPSMatrix resident batch linear failed for %s: %s\n",
                        matrix.name,
                        cmd.error.localizedDescription.UTF8String);
                return 0;
            }
            if (mps_elapsed_seconds) {
                *mps_elapsed_seconds = CFAbsoluteTimeGetCurrent() - mps_started;
            }
        } @catch (NSException *exception) {
            fprintf(stderr,
                    "MPSMatrix resident batch linear failed for %s: %s\n",
                    matrix.name,
                    exception.reason.UTF8String);
            return 0;
        }
    }
    return 1;
}

static NSData *run_resident_rmsnorm(id<MTLDevice> device,
                                    NSString *resident_layout_path,
                                    uint64_t layer_id,
                                    NSData *input_data,
                                    NSString *norm_suffix,
                                    float eps,
    uint64_t max_runner_scratch_bytes) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return nil;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return nil;
    VectorTensorInfo norm = {0};
    if (!find_vector_tensor_by_suffix(resident_layout, layer_id, norm_suffix, &norm)) {
        fprintf(stderr, "norm tensor with suffix %s for layer %llu not found\n",
                norm_suffix.UTF8String, (unsigned long long)layer_id);
        return nil;
    }
    uint32_t hidden_dim = norm.dim0;
    NSUInteger expected_input_bytes = (NSUInteger)hidden_dim * sizeof(float);
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "input bytes mismatch for RMSNorm: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return nil;
    }
    uint64_t peak = 3 * (uint64_t)expected_input_bytes;
    if (!enforce_scratch_limit("RMSNorm", peak, max_runner_scratch_bytes)) {
        return nil;
    }

    float *norm_weight = NULL;
    if (!read_vector_f32(weight_path, norm, hidden_dim, &norm_weight)) {
        return nil;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        free(norm_weight);
        fprintf(stderr, "failed to create Metal command queue\n");
        return nil;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "RMSNorm");
    if (!library) {
        free(norm_weight);
        return nil;
    }
    id<MTLComputePipelineState> rmsnorm = make_pipeline(device, library, @"rmsnorm_f32");
    if (!rmsnorm) {
        free(norm_weight);
        return nil;
    }

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bWeight = [device newBufferWithBytes:norm_weight
                                                length:expected_input_bytes
                                               options:MTLResourceStorageModeShared];
    free(norm_weight);
    id<MTLBuffer> bOut = [device newBufferWithLength:expected_input_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bWeight || !bOut) {
        fprintf(stderr, "failed to allocate RMSNorm buffers\n");
        return nil;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create RMSNorm command buffer\n");
        return nil;
    }
    if (!encode_rmsnorm_f32(cmd, rmsnorm, bInput, bWeight,
                            bOut, hidden_dim, eps)) {
        return nil;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "RMSNorm command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return nil;
    }
    return [NSData dataWithBytes:bOut.contents length:expected_input_bytes];
}

static int run_resident_rmsnorm_batch(id<MTLDevice> device,
                                      NSString *resident_layout_path,
                                      uint64_t layer_id,
                                      NSString *norm_suffix,
                                      NSString *input_path,
                                      NSString *output_path,
                                      uint32_t batch_tokens,
                                      float eps,
    uint64_t max_runner_scratch_bytes) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    VectorTensorInfo norm = {0};
    if (!find_vector_tensor_by_suffix(resident_layout, layer_id, norm_suffix, &norm)) {
        fprintf(stderr, "norm tensor with suffix %s for layer %llu not found\n",
                norm_suffix.UTF8String, (unsigned long long)layer_id);
        return 1;
    }
    uint32_t hidden_dim = norm.dim0;
    if (batch_tokens == 0) {
        fprintf(stderr, "--batch-tokens must be positive\n");
        return 1;
    }

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    uint64_t expected_input_bytes =
        (uint64_t)batch_tokens * hidden_dim * sizeof(float);
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "batch input bytes mismatch for RMSNorm: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }
    uint64_t weight_f32_bytes = (uint64_t)hidden_dim * sizeof(float);
    uint64_t peak = expected_input_bytes + expected_input_bytes +
                    weight_f32_bytes + norm.size;
    if (!enforce_scratch_limit("resident batch RMSNorm", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    float *norm_weight = NULL;
    if (!read_vector_f32(weight_path, norm, hidden_dim, &norm_weight)) {
        return 1;
    }
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        free(norm_weight);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "RMSNorm batch");
    if (!library) {
        free(norm_weight);
        return 1;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, @"rmsnorm_batch_f32");
    if (!pipe) {
        free(norm_weight);
        return 1;
    }

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bWeight = [device newBufferWithBytes:norm_weight
                                                length:(NSUInteger)weight_f32_bytes
                                               options:MTLResourceStorageModeShared];
    free(norm_weight);
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)expected_input_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bWeight || !bOut) {
        fprintf(stderr, "failed to allocate RMSNorm batch buffers\n");
        return 1;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create RMSNorm batch command buffer\n");
        return 1;
    }
    id<MTLComputeCommandEncoder> enc =
        checked_compute_encoder(cmd, "RMSNorm batch");
    if (!enc) return 1;
    [enc setComputePipelineState:pipe];
    [enc setBuffer:bInput offset:0 atIndex:0];
    [enc setBuffer:bWeight offset:0 atIndex:1];
    [enc setBuffer:bOut offset:0 atIndex:2];
    [enc setBytes:&hidden_dim length:sizeof(hidden_dim) atIndex:3];
    [enc setBytes:&batch_tokens length:sizeof(batch_tokens) atIndex:4];
    [enc setBytes:&eps length:sizeof(eps) atIndex:5];
    [enc dispatchThreads:MTLSizeMake(hidden_dim, batch_tokens, 1)
   threadsPerThreadgroup:MTLSizeMake(16, 16, 1)];
    [enc endEncoding];
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "RMSNorm batch command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    if (output_path) {
        NSData *out_data = [NSData dataWithBytes:bOut.contents
                                          length:(NSUInteger)expected_input_bytes];
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }

    float *out = (float *)bOut.contents;
    printf("LargerLM resident batch RMSNorm\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", norm.name);
    printf("  dtype:              %s\n", norm.dtype);
    printf("  hidden dim:         %u\n", hidden_dim);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  RMSNorm eps:        %.9g\n", eps);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_resident_linear(id<MTLDevice> device,
                               NSString *resident_layout_path,
                               uint64_t layer_id,
                               NSString *tensor_suffix,
                               NSString *input_path,
                               NSString *output_path,
                               uint64_t max_matrix_bytes,
    uint64_t max_runner_scratch_bytes) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;

    ResidentMatrixInfo matrix = {0};
    if (!find_resident_matrix_by_suffix(resident_layout, layer_id, tensor_suffix, &matrix)) {
        return 1;
    }
    ResidentAffineInt4MatrixInfo affine = {0};
    ResidentMxfp4MatrixInfo mxfp4 = {0};
    int is_u32_weight = resident_matrix_is_affine_int4_weight(matrix);
    int use_mxfp4 = 0;
    int use_affine_int4 = 0;
    if (is_u32_weight) {
        if (find_resident_mxfp4_matrix(resident_layout, matrix, &mxfp4)) {
            use_mxfp4 = 1;
        } else if (find_resident_affine_int4_matrix(resident_layout, matrix, &affine)) {
            use_affine_int4 = 1;
        } else {
            return 1;
        }
    }
    if (use_mxfp4) {
        if (mxfp4.total_bytes > max_matrix_bytes) {
            fprintf(stderr,
                    "resident MXFP4 matrix %s has %llu bytes, exceeds limit %llu\n",
                    mxfp4.name,
                    (unsigned long long)mxfp4.total_bytes,
                    (unsigned long long)max_matrix_bytes);
            return 1;
        }
    } else if (use_affine_int4) {
        if (affine.total_bytes > max_matrix_bytes) {
            fprintf(stderr,
                    "resident affine-int4 matrix %s has %llu bytes, exceeds limit %llu\n",
                    affine.name,
                    (unsigned long long)affine.total_bytes,
                    (unsigned long long)max_matrix_bytes);
            return 1;
        }
    } else {
        if (!validate_resident_matrix(matrix)) return 1;
        if (!enforce_resident_matrix_limit(matrix, max_matrix_bytes)) return 1;
    }
    uint32_t out_dim = use_mxfp4 ? mxfp4.out_dim : (use_affine_int4 ? affine.out_dim : matrix.out_dim);
    uint32_t in_dim = use_mxfp4 ? mxfp4.in_dim : (use_affine_int4 ? affine.in_dim : matrix.in_dim);
    uint64_t matrix_bytes = use_mxfp4 ? mxfp4.total_bytes
                                      : (use_affine_int4 ? affine.total_bytes
                                                        : (uint64_t)matrix.size);

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    uint64_t expected_input_bytes64 = (uint64_t)in_dim * sizeof(float);
    if (expected_input_bytes64 > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "resident linear input is too large\n");
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)expected_input_bytes64;
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }
    uint64_t output_bytes = (uint64_t)out_dim * sizeof(float);
    uint64_t peak = align_up_u64(matrix_bytes, 2 * 1024 * 1024) +
                    expected_input_bytes + output_bytes;
    if (!enforce_scratch_limit("resident linear", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "resident linear");
    if (!library) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bOut) {
        fprintf(stderr, "failed to allocate resident linear buffers\n");
        return 1;
    }
    if (use_mxfp4) {
        if (!run_resident_mxfp4_matvec(device, queue, library, weight_path,
                                       mxfp4, bInput, bOut)) {
            return 1;
        }
    } else if (use_affine_int4) {
        if (!run_resident_affine_int4_matvec(device, queue, library, weight_path,
                                             affine, bInput, bOut)) {
            return 1;
        }
    } else if (!run_resident_matrix_matvec(device, queue, library, weight_path,
                                           matrix, bInput, bOut)) {
        return 1;
    }
    if (output_path) {
        NSData *out_data = [NSData dataWithBytes:bOut.contents length:(NSUInteger)output_bytes];
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }

    float *out = (float *)bOut.contents;
    printf("LargerLM resident linear\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", matrix.name);
    printf("  dtype:              %s\n",
           use_mxfp4 ? "mlx-mxfp4" : (use_affine_int4 ? "affine-int4" : matrix.dtype));
    printf("  shape:              [%u,%u]\n", out_dim, in_dim);
    printf("  matrix bytes:       %llu\n", (unsigned long long)matrix_bytes);
    if (use_mxfp4 || use_affine_int4) {
        printf("  group size:         %u\n",
               use_mxfp4 ? mxfp4.group_size : affine.group_size);
    }
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_resident_linear_batch(id<MTLDevice> device,
                                     NSString *resident_layout_path,
                                     uint64_t layer_id,
                                     NSString *tensor_suffix,
                                     NSString *input_path,
                                     NSString *output_path,
                                     uint32_t batch_tokens,
                                     uint64_t max_matrix_bytes,
                                     uint64_t max_runner_scratch_bytes,
                                     NSString *backend) {
    if (!backend) backend = @"custom-metal";
    int use_custom_metal = [backend isEqualToString:@"custom-metal"];
    int use_mpsgraph_f32 = [backend isEqualToString:@"mpsgraph-f32"];
    int use_mps_matrix_f32 = [backend isEqualToString:@"mps-matrix-f32"];
    if (!use_custom_metal && !use_mpsgraph_f32 && !use_mps_matrix_f32) {
        fprintf(stderr,
                "unsupported --prefill-linear-backend %s; expected custom-metal, mpsgraph-f32, or mps-matrix-f32\n",
                backend.UTF8String);
        return 1;
    }
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;

    ResidentMatrixInfo matrix = {0};
    if (!find_resident_matrix_by_suffix(resident_layout, layer_id, tensor_suffix, &matrix)) {
        return 1;
    }
    ResidentAffineInt4MatrixInfo affine = {0};
    ResidentMxfp4MatrixInfo mxfp4 = {0};
    int is_u32_weight = resident_matrix_is_affine_int4_weight(matrix);
    int use_mxfp4 = 0;
    int use_affine_int4 = 0;
    if (is_u32_weight) {
        if (!use_custom_metal) {
            fprintf(stderr,
                    "quantized resident matrices require custom-metal backend; got %s\n",
                    backend.UTF8String);
            return 1;
        }
        if (find_resident_mxfp4_matrix(resident_layout, matrix, &mxfp4)) {
            use_mxfp4 = 1;
        } else if (find_resident_affine_int4_matrix(resident_layout, matrix, &affine)) {
            use_affine_int4 = 1;
        } else {
            return 1;
        }
    }
    if (use_mxfp4) {
        if (mxfp4.total_bytes > max_matrix_bytes) {
            fprintf(stderr,
                    "resident MXFP4 matrix %s has %llu bytes, exceeds limit %llu\n",
                    mxfp4.name,
                    (unsigned long long)mxfp4.total_bytes,
                    (unsigned long long)max_matrix_bytes);
            return 1;
        }
    } else if (use_affine_int4) {
        if (affine.total_bytes > max_matrix_bytes) {
            fprintf(stderr,
                    "resident affine-int4 matrix %s has %llu bytes, exceeds limit %llu\n",
                    affine.name,
                    (unsigned long long)affine.total_bytes,
                    (unsigned long long)max_matrix_bytes);
            return 1;
        }
    } else {
        if (!validate_resident_matrix(matrix)) return 1;
        if (!enforce_resident_matrix_limit(matrix, max_matrix_bytes)) return 1;
    }
    if (batch_tokens == 0) {
        fprintf(stderr, "--batch-tokens must be positive\n");
        return 1;
    }

    uint32_t out_dim = use_mxfp4 ? mxfp4.out_dim : (use_affine_int4 ? affine.out_dim : matrix.out_dim);
    uint32_t in_dim = use_mxfp4 ? mxfp4.in_dim : (use_affine_int4 ? affine.in_dim : matrix.in_dim);
    uint64_t matrix_bytes = use_mxfp4 ? mxfp4.total_bytes
                                      : (use_affine_int4 ? affine.total_bytes
                                                        : (uint64_t)matrix.size);
    uint64_t input_row_bytes = (uint64_t)in_dim * sizeof(float);
    uint64_t output_row_bytes = (uint64_t)out_dim * sizeof(float);
    if (input_row_bytes == 0 || output_row_bytes == 0 ||
        (uint64_t)batch_tokens > UINT64_MAX / input_row_bytes ||
        (uint64_t)batch_tokens > UINT64_MAX / output_row_bytes) {
        fprintf(stderr, "resident batch linear input/output byte size overflow\n");
        return 1;
    }
    uint64_t expected_input_bytes = (uint64_t)batch_tokens * input_row_bytes;
    uint64_t output_bytes = (uint64_t)batch_tokens * output_row_bytes;
    if (expected_input_bytes > (uint64_t)SIZE_MAX ||
        output_bytes > (uint64_t)SIZE_MAX ||
        expected_input_bytes > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "resident batch linear input/output is too large\n");
        return 1;
    }
    struct stat input_stat;
    if (stat(input_path.UTF8String, &input_stat) != 0) {
        fprintf(stderr, "stat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        return 1;
    }
    if (input_stat.st_size < 0 || (uint64_t)input_stat.st_size != expected_input_bytes) {
        fprintf(stderr, "batch input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_stat.st_size,
                (unsigned long long)expected_input_bytes);
        return 1;
    }
    uint64_t matrix_scratch_bytes = align_up_u64(matrix_bytes, 2 * 1024 * 1024);
    uint64_t matrix_f32_bytes = 0;
    uint64_t matrix_raw_conversion_bytes = 0;
    if (use_mpsgraph_f32 || use_mps_matrix_f32) {
        uint64_t matrix_row_f32_bytes = (uint64_t)in_dim * sizeof(float);
        if (matrix_row_f32_bytes == 0 ||
            (uint64_t)out_dim > UINT64_MAX / matrix_row_f32_bytes) {
            fprintf(stderr, "resident batch linear matrix f32 byte size overflow\n");
            return 1;
        }
        matrix_f32_bytes = (uint64_t)out_dim * matrix_row_f32_bytes;
        matrix_raw_conversion_bytes =
            (strcmp(matrix.dtype, "F32") == 0 ||
             strcmp(matrix.dtype, "float32") == 0 ||
             strcmp(matrix.dtype, "FLOAT32") == 0)
            ? 0
            : matrix_bytes;
        matrix_scratch_bytes = align_up_u64(matrix_f32_bytes, 2 * 1024 * 1024) +
                               matrix_raw_conversion_bytes;
    }
    uint64_t peak = matrix_scratch_bytes + expected_input_bytes + output_bytes;
    if (!enforce_scratch_limit("resident batch linear", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    if (input_data.length != (NSUInteger)expected_input_bytes) {
        fprintf(stderr, "batch input bytes changed while reading: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = nil;
    if (use_custom_metal) {
        library = expert_kernel_library(device, "resident batch linear");
        if (!library) return 1;
    }

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bOut) {
        fprintf(stderr, "failed to allocate resident batch linear buffers\n");
        return 1;
    }
    double backend_elapsed = 0.0;
    double matrix_f32_elapsed = 0.0;
    double accelerator_elapsed = 0.0;
    CFAbsoluteTime backend_started = CFAbsoluteTimeGetCurrent();
    if (use_mpsgraph_f32) {
        if (!run_resident_matrix_batch_linear_mpsgraph_f32(device, queue, weight_path,
                                                           matrix, bInput, bOut,
                                                           batch_tokens,
                                                           &matrix_f32_elapsed,
                                                           &accelerator_elapsed)) {
            return 1;
        }
    } else if (use_mps_matrix_f32) {
        if (!run_resident_matrix_batch_linear_mps_matrix_f32(device, queue, weight_path,
                                                             matrix, bInput, bOut,
                                                             batch_tokens,
                                                             &matrix_f32_elapsed,
                                                             &accelerator_elapsed)) {
            return 1;
        }
    } else {
        if (use_mxfp4) {
            if (!run_resident_mxfp4_batch_linear(device, queue, library,
                                                 weight_path, mxfp4,
                                                 bInput, bOut,
                                                 batch_tokens)) {
                return 1;
            }
        } else if (use_affine_int4) {
            if (!run_resident_affine_int4_batch_linear(device, queue, library,
                                                       weight_path, affine,
                                                       bInput, bOut,
                                                       batch_tokens)) {
                return 1;
            }
        } else if (!run_resident_matrix_batch_linear(device, queue, library, weight_path,
                                                     matrix, bInput, bOut, batch_tokens)) {
            return 1;
        }
    }
    backend_elapsed = CFAbsoluteTimeGetCurrent() - backend_started;
    if (output_path) {
        NSData *out_data = [NSData dataWithBytes:bOut.contents length:(NSUInteger)output_bytes];
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }

    float *out = (float *)bOut.contents;
    printf("LargerLM resident batch linear\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", matrix.name);
    printf("  dtype:              %s\n",
           use_mxfp4 ? "mlx-mxfp4" : (use_affine_int4 ? "affine-int4" : matrix.dtype));
    printf("  backend:            %s\n", backend.UTF8String);
    printf("  shape:              [%u,%u]\n", out_dim, in_dim);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  matrix bytes:       %llu\n", (unsigned long long)matrix_bytes);
    if (use_mxfp4 || use_affine_int4) {
        printf("  group size:         %u\n",
               use_mxfp4 ? mxfp4.group_size : affine.group_size);
    }
    if (use_mxfp4) {
        int token_tile_ok = 1;
        uint32_t token_tile = resident_mxfp4_batch_token_tile_from_env(&token_tile_ok);
        if (!token_tile_ok) return 1;
        int group32_ok = 1;
        int group32_specialized =
            resident_mxfp4_batch_group32_specialized_from_env(mxfp4,
                                                              token_tile,
                                                              &group32_ok);
        if (!group32_ok) return 1;
        printf("  MXFP4 token tile:   %u\n", token_tile);
        printf("  MXFP4 group32 path: %s\n", group32_specialized ? "yes" : "no");
    }
    printf("  matrix scratch:     %llu\n", (unsigned long long)matrix_scratch_bytes);
    printf("  matrix f32 bytes:   %llu\n", (unsigned long long)matrix_f32_bytes);
    printf("  matrix raw conv:    %llu\n", (unsigned long long)matrix_raw_conversion_bytes);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing backend:     %.6f\n", backend_elapsed);
    printf("  timing matrix f32:  %.6f\n", matrix_f32_elapsed);
    printf("  timing accelerator: %.6f\n", accelerator_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static void update_final_topk(float *scores,
                              uint64_t *ids,
                              uint32_t *count,
                              uint32_t top_k,
                              uint64_t token_id,
                              float score) {
    if (*count < top_k) {
        scores[*count] = score;
        ids[*count] = token_id;
        (*count)++;
        return;
    }
    uint32_t min_idx = 0;
    for (uint32_t i = 1; i < *count; i++) {
        if (scores[i] < scores[min_idx] ||
            (scores[i] == scores[min_idx] && ids[i] > ids[min_idx])) {
            min_idx = i;
        }
    }
    if (score > scores[min_idx] ||
        (score == scores[min_idx] && token_id < ids[min_idx])) {
        scores[min_idx] = score;
        ids[min_idx] = token_id;
    }
}

static void sort_final_topk(float *scores, uint64_t *ids, uint32_t count) {
    for (uint32_t i = 0; i < count; i++) {
        for (uint32_t j = i + 1; j < count; j++) {
            if (scores[j] > scores[i] ||
                (scores[j] == scores[i] && ids[j] < ids[i])) {
                float ts = scores[i];
                scores[i] = scores[j];
                scores[j] = ts;
                uint64_t ti = ids[i];
                ids[i] = ids[j];
                ids[j] = ti;
            }
        }
    }
}

static int write_final_topk_json(NSString *path,
                                 const float *scores,
                                 const uint64_t *ids,
                                 uint32_t count,
                                 double elapsed_seconds,
                                 uint64_t read_bytes,
                                 uint64_t chunk_rows,
                                 uint64_t chunks) {
    NSMutableArray *records = [NSMutableArray arrayWithCapacity:count];
    for (uint32_t i = 0; i < count; i++) {
        [records addObject:@{
            @"token_id": @(ids[i]),
            @"logit": @(scores[i]),
        }];
    }
    NSDictionary *payload = @{
        @"topk": records,
        @"elapsed_seconds": @(elapsed_seconds),
        @"read_bytes": @(read_bytes),
        @"chunk_rows": @(chunk_rows),
        @"chunks": @(chunks),
    };
    NSError *error = nil;
    NSData *data = [NSJSONSerialization dataWithJSONObject:payload
                                                   options:NSJSONWritingPrettyPrinted
                                                     error:&error];
    if (!data) {
        fprintf(stderr, "failed to encode top-k JSON: %s\n",
                error.localizedDescription.UTF8String);
        return 0;
    }
    if (![data writeToFile:path atomically:YES]) {
        fprintf(stderr, "failed to write top-k JSON: %s\n", path.UTF8String);
        return 0;
    }
    return 1;
}

static int run_final_logits(id<MTLDevice> device,
                            NSString *resident_layout_path,
                            NSString *input_path,
                            NSData *input_data_override,
                            NSString *output_topk_path,
                            uint32_t top_k,
                            uint32_t chunk_rows_arg,
                            float rms_norm_eps,
                            uint64_t max_chunk_bytes,
                            uint64_t max_runner_scratch_bytes,
                            int allow_tied_embeddings,
                            int skip_final_norm) {
    if (top_k == 0 || top_k > 64) {
        fprintf(stderr, "--top-k must be in 1..64 for Metal final logits\n");
        return 1;
    }
    if (max_chunk_bytes == 0 || max_runner_scratch_bytes == 0) {
        fprintf(stderr, "--max-chunk-mib and --max-runner-scratch-mib must be positive\n");
        return 1;
    }
    CFAbsoluteTime logits_started = CFAbsoluteTimeGetCurrent();

    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;

    ResidentMatrixInfo head = {0};
    int has_head = find_global_matrix_by_suffixes(
        resident_layout,
        @[@"lm_head.weight", @".lm_head.weight"],
        &head,
        0,
        "lm_head");
    if (!has_head && allow_tied_embeddings) {
        has_head = find_global_matrix_by_suffixes(
            resident_layout,
            @[@"model.embed_tokens.weight",
              @".embed_tokens.weight",
              @"transformer.word_embeddings.weight",
              @".word_embeddings.weight"],
            &head,
            0,
            "tied embedding");
    }
    if (!has_head) {
        fprintf(stderr, "lm_head.weight not found\n");
        return 1;
    }
    ResidentAffineInt4MatrixInfo head_affine = {0};
    ResidentMxfp4MatrixInfo head_mxfp4 = {0};
    int use_affine_int4 = 0;
    int use_mxfp4 = 0;
    if (resident_matrix_is_affine_int4_weight(head)) {
        if (find_resident_mxfp4_matrix(resident_layout, head, &head_mxfp4)) {
            use_mxfp4 = 1;
            head.out_dim = head_mxfp4.out_dim;
            head.in_dim = head_mxfp4.in_dim;
            head.size = (NSUInteger)head_mxfp4.total_bytes;
            snprintf(head.dtype, sizeof(head.dtype), "%s", "mlx-mxfp4");
        } else if (find_resident_affine_int4_matrix(resident_layout, head, &head_affine)) {
            use_affine_int4 = 1;
            head.out_dim = head_affine.out_dim;
            head.in_dim = head_affine.in_dim;
            head.size = (NSUInteger)head_affine.total_bytes;
            snprintf(head.dtype, sizeof(head.dtype), "%s", "affine-int4");
        } else {
            return 1;
        }
    } else if (!validate_resident_matrix(head)) {
        return 1;
    }
    if (top_k > head.out_dim) {
        fprintf(stderr, "--top-k exceeds vocab size %u\n", head.out_dim);
        return 1;
    }

    NSData *input_data = input_data_override ?: [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n",
                input_path ? input_path.UTF8String : "<memory>");
        return 1;
    }
    uint32_t hidden_dim = head.in_dim;
    uint64_t hidden_bytes = (uint64_t)hidden_dim * sizeof(float);
    if (input_data.length != hidden_bytes) {
        fprintf(stderr, "hidden bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)hidden_bytes);
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "final logits");
    if (!library) return 1;
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    id<MTLBuffer> bHidden = [device newBufferWithBytes:input_data.bytes
                                                length:(NSUInteger)hidden_bytes
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bNormed = bHidden;
    char norm_name[512] = "skipped";
    if (!skip_final_norm) {
        VectorTensorInfo norm = {0};
        if (!find_global_vector_by_suffixes(
                resident_layout,
                @[@"model.norm.weight",
                  @".model.norm.weight",
                  @"transformer.norm.weight",
                  @".transformer.norm.weight",
                  @"norm.weight",
                  @".norm.weight"],
                &norm,
                1,
                "final norm")) {
            return 1;
        }
        if (norm.dim0 != hidden_dim) {
            fprintf(stderr, "final norm dim %u does not match hidden dim %u\n",
                    norm.dim0, hidden_dim);
            return 1;
        }
        float *norm_weight = NULL;
        if (!read_vector_f32(weight_path, norm, hidden_dim, &norm_weight)) return 1;
        uint64_t norm_peak = 3 * hidden_bytes;
        if (!enforce_scratch_limit("final RMSNorm", norm_peak, max_runner_scratch_bytes)) {
            free(norm_weight);
            return 1;
        }
        id<MTLComputePipelineState> rmsnorm = make_pipeline(device, library, @"rmsnorm_f32");
        if (!rmsnorm) {
            free(norm_weight);
            return 1;
        }
        id<MTLBuffer> bWeight = [device newBufferWithBytes:norm_weight
                                                    length:(NSUInteger)hidden_bytes
                                                   options:MTLResourceStorageModeShared];
        free(norm_weight);
        bNormed = [device newBufferWithLength:(NSUInteger)hidden_bytes
                                      options:MTLResourceStorageModeShared];
        if (!bHidden || !bWeight || !bNormed) {
            fprintf(stderr, "failed to allocate final RMSNorm buffers\n");
            return 1;
        }
        id<MTLCommandBuffer> cmd = [queue commandBuffer];
        if (!cmd) {
            fprintf(stderr, "failed to create final RMSNorm command buffer\n");
            return 1;
        }
        if (!encode_rmsnorm_f32(cmd, rmsnorm, bHidden, bWeight, bNormed,
                                hidden_dim, rms_norm_eps)) {
            return 1;
        }
        [cmd commit];
        [cmd waitUntilCompleted];
        if (cmd.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "final RMSNorm command failed: %s\n",
                    cmd.error.localizedDescription.UTF8String);
            return 1;
        }
        snprintf(norm_name, sizeof(norm_name), "%s", norm.name);
    } else if (!bHidden) {
        fprintf(stderr, "failed to allocate hidden buffer\n");
        return 1;
    }

    NSString *kernel_name = use_mxfp4 ? @"mxfp4_matvec"
                                      : (use_affine_int4 ? @"dequant4"
                                                         : linear_kernel_for_dtype(head.dtype));
    if (!kernel_name) {
        fprintf(stderr, "unsupported lm_head dtype %s\n", head.dtype);
        return 1;
    }
    id<MTLComputePipelineState> matvec = make_pipeline(device, library, kernel_name);
    if (!matvec) return 1;
    uint64_t weight_row_bytes = 0;
    uint64_t scale_row_bytes = 0;
    uint64_t bias_row_bytes = 0;
    uint64_t row_bytes = 0;
    if (use_mxfp4) {
        weight_row_bytes = (uint64_t)head_mxfp4.weight.in_dim * sizeof(uint32_t);
        scale_row_bytes = (uint64_t)head_mxfp4.scales.in_dim * sizeof(uint8_t);
        if (!checked_add_u64(weight_row_bytes, scale_row_bytes, &row_bytes)) {
            fprintf(stderr, "lm_head MXFP4 row bytes overflow\n");
            return 1;
        }
    } else if (use_affine_int4) {
        weight_row_bytes = (uint64_t)head_affine.weight.in_dim * sizeof(uint32_t);
        scale_row_bytes = (uint64_t)head_affine.scales.in_dim * sizeof(uint16_t);
        bias_row_bytes = (uint64_t)head_affine.biases.in_dim * sizeof(uint16_t);
        if (!checked_add_u64(weight_row_bytes, scale_row_bytes, &row_bytes) ||
            !checked_add_u64(row_bytes, bias_row_bytes, &row_bytes)) {
            fprintf(stderr, "lm_head affine-int4 row bytes overflow\n");
            return 1;
        }
    } else {
        int dtype_bytes = matrix_dtype_bytes(head.dtype);
        row_bytes = (uint64_t)hidden_dim * (uint64_t)dtype_bytes;
    }
    if (row_bytes == 0 || row_bytes > max_chunk_bytes) {
        fprintf(stderr, "one lm_head row %llu bytes exceeds chunk limit %llu\n",
                (unsigned long long)row_bytes,
                (unsigned long long)max_chunk_bytes);
        return 1;
    }
    uint64_t rows_per_chunk = chunk_rows_arg ? chunk_rows_arg : (max_chunk_bytes / row_bytes);
    if (rows_per_chunk == 0) rows_per_chunk = 1;
    if (rows_per_chunk > head.out_dim) rows_per_chunk = head.out_dim;
    uint64_t chunk_bytes = rows_per_chunk * row_bytes;
    if (chunk_bytes > max_chunk_bytes) {
        fprintf(stderr, "lm_head chunk %llu bytes exceeds limit %llu\n",
                (unsigned long long)chunk_bytes,
                (unsigned long long)max_chunk_bytes);
        return 1;
    }

    float top_scores[64] = {0};
    uint64_t top_ids[64] = {0};
    uint32_t top_count = 0;
    uint64_t chunks = 0;
    uint64_t read_bytes = 0;
    for (uint64_t row_start = 0; row_start < head.out_dim; row_start += rows_per_chunk) {
        uint64_t rows = rows_per_chunk;
        if (row_start + rows > head.out_dim) rows = head.out_dim - row_start;
        uint64_t raw_bytes = 0;
        uint64_t weight_chunk_bytes = 0;
        uint64_t scale_chunk_bytes = 0;
        uint64_t bias_chunk_bytes = 0;
        if (use_mxfp4) {
            if (!checked_mul_u64(rows, weight_row_bytes, &weight_chunk_bytes) ||
                !checked_mul_u64(rows, scale_row_bytes, &scale_chunk_bytes) ||
                !checked_add_u64(weight_chunk_bytes, scale_chunk_bytes, &raw_bytes)) {
                fprintf(stderr, "lm_head MXFP4 chunk bytes overflow\n");
                return 1;
            }
        } else if (use_affine_int4) {
            if (!checked_mul_u64(rows, weight_row_bytes, &weight_chunk_bytes) ||
                !checked_mul_u64(rows, scale_row_bytes, &scale_chunk_bytes) ||
                !checked_mul_u64(rows, bias_row_bytes, &bias_chunk_bytes) ||
                !checked_add_u64(weight_chunk_bytes, scale_chunk_bytes, &raw_bytes) ||
                !checked_add_u64(raw_bytes, bias_chunk_bytes, &raw_bytes)) {
                fprintf(stderr, "lm_head affine-int4 chunk bytes overflow\n");
                return 1;
            }
        } else if (!checked_mul_u64(rows, row_bytes, &raw_bytes)) {
            fprintf(stderr, "lm_head chunk bytes overflow\n");
            return 1;
        }
        uint64_t output_bytes = rows * sizeof(float);
        uint64_t alloc_size = align_up_u64(raw_bytes, 2 * 1024 * 1024);
        uint64_t peak = alloc_size + hidden_bytes + output_bytes;
        if (!enforce_scratch_limit("final logits chunk", peak, max_runner_scratch_bytes)) {
            return 1;
        }
        void *aligned = NULL;
        if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
            fprintf(stderr, "posix_memalign failed for lm_head chunk\n");
            return 1;
        }
        memset(aligned, 0, (size_t)alloc_size);
        if (use_mxfp4) {
            char *dst = (char *)aligned;
            off_t w_offset = (off_t)(head_mxfp4.weight.offset + row_start * weight_row_bytes);
            off_t s_offset = (off_t)(head_mxfp4.scales.offset + row_start * scale_row_bytes);
            if (!read_exact_slot(weight_path.UTF8String, dst,
                                 (size_t)weight_chunk_bytes, w_offset) ||
                !read_exact_slot(weight_path.UTF8String,
                                 dst + weight_chunk_bytes,
                                 (size_t)scale_chunk_bytes,
                                 s_offset)) {
                free(aligned);
                return 1;
            }
        } else if (use_affine_int4) {
            char *dst = (char *)aligned;
            off_t w_offset = (off_t)(head_affine.weight.offset + row_start * weight_row_bytes);
            off_t s_offset = (off_t)(head_affine.scales.offset + row_start * scale_row_bytes);
            off_t b_offset = (off_t)(head_affine.biases.offset + row_start * bias_row_bytes);
            if (!read_exact_slot(weight_path.UTF8String, dst, (size_t)weight_chunk_bytes, w_offset) ||
                !read_exact_slot(weight_path.UTF8String,
                                 dst + weight_chunk_bytes,
                                 (size_t)scale_chunk_bytes,
                                 s_offset) ||
                !read_exact_slot(weight_path.UTF8String,
                                 dst + weight_chunk_bytes + scale_chunk_bytes,
                                 (size_t)bias_chunk_bytes,
                                 b_offset)) {
                free(aligned);
                return 1;
            }
        } else {
            off_t offset = (off_t)(head.offset + row_start * row_bytes);
            if (!read_exact_slot(weight_path.UTF8String, aligned, (size_t)raw_bytes, offset)) {
                free(aligned);
                return 1;
            }
        }
        id<MTLBuffer> bMatrix =
            [device newBufferWithBytesNoCopy:aligned
                                       length:(NSUInteger)alloc_size
                                      options:MTLResourceStorageModeShared
                                  deallocator:^(void *pointer, NSUInteger length) {
                                      (void)length;
                                      free(pointer);
                                  }];
        id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                                 options:MTLResourceStorageModeShared];
        if (!bMatrix || !bOut) {
            fprintf(stderr, "failed to allocate final logits chunk buffers\n");
            if (!bMatrix) free(aligned);
            return 1;
        }
        id<MTLCommandBuffer> cmd = [queue commandBuffer];
        if (!cmd) {
            fprintf(stderr, "failed to create final logits chunk command buffer\n");
            return 1;
        }
        int encoded = 0;
        if (use_mxfp4) {
            encoded = encode_mxfp4_matvec(cmd,
                                          matvec,
                                          bMatrix,
                                          0,
                                          (NSUInteger)weight_chunk_bytes,
                                          bNormed,
                                          bOut,
                                          (uint32_t)rows,
                                          hidden_dim,
                                          head_mxfp4.group_size);
        } else if (use_affine_int4) {
            encoded = encode_dequant4(cmd,
                                      matvec,
                                      bMatrix,
                                      0,
                                      (NSUInteger)weight_chunk_bytes,
                                      (NSUInteger)(weight_chunk_bytes + scale_chunk_bytes),
                                      bNormed,
                                      bOut,
                                      (uint32_t)rows,
                                      hidden_dim,
                                      head_affine.group_size,
                                      head_affine.meta_dtype);
        } else {
            encoded = encode_router_matvec(cmd, matvec, bMatrix, bNormed, bOut,
                                           (uint32_t)rows, hidden_dim);
        }
        if (!encoded) {
            return 1;
        }
        [cmd commit];
        [cmd waitUntilCompleted];
        if (cmd.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "final logits chunk command failed: %s\n",
                    cmd.error.localizedDescription.UTF8String);
            return 1;
        }
        float *logits = (float *)bOut.contents;
        for (uint64_t i = 0; i < rows; i++) {
            update_final_topk(top_scores, top_ids, &top_count, top_k,
                              row_start + i, logits[i]);
        }
        chunks++;
        read_bytes += raw_bytes;
    }
    sort_final_topk(top_scores, top_ids, top_count);
    double logits_elapsed = CFAbsoluteTimeGetCurrent() - logits_started;
    if (output_topk_path) {
        if (!write_final_topk_json(output_topk_path,
                                   top_scores,
                                   top_ids,
                                   top_count,
                                   logits_elapsed,
                                   read_bytes,
                                   rows_per_chunk,
                                   chunks)) {
            return 1;
        }
    }

    printf("LargerLM final logits\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  resident layout:    %s\n", resident_layout_path.UTF8String);
    printf("  input f32:          %s\n",
           input_path ? input_path.UTF8String : "<memory>");
    printf("  norm tensor:        %s\n", norm_name);
    printf("  head tensor:        %s\n", head.name);
    printf("  hidden dim:         %u\n", hidden_dim);
    printf("  vocab size:         %u\n", head.out_dim);
    printf("  dtype:              %s\n", head.dtype);
    if (use_mxfp4 || use_affine_int4) {
        printf("  group size:         %u\n",
               use_mxfp4 ? head_mxfp4.group_size : head_affine.group_size);
    }
    printf("  chunk rows:         %llu\n", (unsigned long long)rows_per_chunk);
    printf("  chunks:             %llu\n", (unsigned long long)chunks);
    printf("  read bytes:         %llu\n", (unsigned long long)read_bytes);
    printf("  elapsed seconds:    %.6f\n", logits_elapsed);
    printf("  top-k:\n");
    for (uint32_t i = 0; i < top_count; i++) {
        printf("    %llu: %.9g\n",
               (unsigned long long)top_ids[i],
               top_scores[i]);
    }
    if (output_topk_path) {
        printf("  top-k json:         %s\n", output_topk_path.UTF8String);
    }
    return 0;
}

static int run_rope(id<MTLDevice> device,
                    NSString *q_path,
                    NSString *k_path,
                    NSString *out_q_path,
                    NSString *out_k_path,
                    uint32_t num_heads,
                    uint32_t rope_dim,
                    uint32_t position,
                    float theta,
                    int interleave,
                    uint64_t max_runner_scratch_bytes) {
    if (num_heads == 0 || rope_dim == 0 || (rope_dim % 2) != 0) {
        fprintf(stderr, "--num-heads and even --rope-dim must be positive\n");
        return 1;
    }
    if (theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    NSData *q_data = [NSData dataWithContentsOfFile:q_path];
    NSData *k_data = [NSData dataWithContentsOfFile:k_path];
    if (!q_data || !k_data) {
        fprintf(stderr, "failed to read q/k f32 inputs\n");
        return 1;
    }
    NSUInteger q_bytes = (NSUInteger)num_heads * rope_dim * sizeof(float);
    NSUInteger k_bytes = (NSUInteger)rope_dim * sizeof(float);
    if (q_data.length != q_bytes || k_data.length != k_bytes) {
        fprintf(stderr, "RoPE input bytes mismatch: q got %llu expected %llu; k got %llu expected %llu\n",
                (unsigned long long)q_data.length,
                (unsigned long long)q_bytes,
                (unsigned long long)k_data.length,
                (unsigned long long)k_bytes);
        return 1;
    }
    uint64_t peak = 2 * (uint64_t)q_bytes + 2 * (uint64_t)k_bytes;
    if (!enforce_scratch_limit("RoPE", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "RoPE");
    if (!library) return 1;
    id<MTLComputePipelineState> rope = make_pipeline(device, library, @"rope_f32");
    if (!rope) return 1;

    id<MTLBuffer> bQ = [device newBufferWithBytes:q_data.bytes
                                           length:q_data.length
                                          options:MTLResourceStorageModeShared];
    id<MTLBuffer> bK = [device newBufferWithBytes:k_data.bytes
                                           length:k_data.length
                                          options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutQ = [device newBufferWithLength:q_bytes
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutK = [device newBufferWithLength:k_bytes
                                              options:MTLResourceStorageModeShared];
    if (!bQ || !bK || !bOutQ || !bOutK) {
        fprintf(stderr, "failed to allocate RoPE buffers\n");
        return 1;
    }
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create RoPE command buffer\n");
        return 1;
    }
    if (!encode_rope_f32(cmd, rope, bQ, bK, bOutQ, bOutK,
                         num_heads, rope_dim, position, theta,
                         interleave ? 1u : 0u)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "RoPE command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    NSData *out_q = [NSData dataWithBytes:bOutQ.contents length:q_bytes];
    NSData *out_k = [NSData dataWithBytes:bOutK.contents length:k_bytes];
    if (![out_q writeToFile:out_q_path atomically:YES] ||
        ![out_k writeToFile:out_k_path atomically:YES]) {
        fprintf(stderr, "failed to write RoPE outputs\n");
        return 1;
    }
    float *q0 = (float *)bOutQ.contents;
    float *k0 = (float *)bOutK.contents;
    printf("LargerLM RoPE\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  num heads:          %u\n", num_heads);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  position:           %u\n", position);
    printf("  theta:              %.6f\n", theta);
    printf("  interleave:         %s\n", interleave ? "yes" : "no");
    printf("  q_out[0]:           %.6f\n", q0[0]);
    printf("  k_out[0]:           %.6f\n", k0[0]);
    printf("  output q f32:       %s\n", out_q_path.UTF8String);
    printf("  output k f32:       %s\n", out_k_path.UTF8String);
    return 0;
}

static int run_rope_batch(id<MTLDevice> device,
                          NSString *q_path,
                          NSString *k_path,
                          NSString *out_q_path,
                          NSString *out_k_path,
                          uint32_t num_heads,
                          uint32_t rope_dim,
                          uint32_t start_position,
                          uint32_t batch_tokens,
                          float theta,
                          int interleave,
                          uint64_t max_runner_scratch_bytes) {
    if (num_heads == 0 || rope_dim == 0 || (rope_dim % 2) != 0 || batch_tokens == 0) {
        fprintf(stderr, "--num-heads, even --rope-dim, and --batch-tokens must be positive\n");
        return 1;
    }
    if (theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    NSData *q_data = [NSData dataWithContentsOfFile:q_path];
    NSData *k_data = [NSData dataWithContentsOfFile:k_path];
    if (!q_data || !k_data) {
        fprintf(stderr, "failed to read batch q/k f32 inputs\n");
        return 1;
    }
    NSUInteger q_bytes = (NSUInteger)batch_tokens * num_heads * rope_dim * sizeof(float);
    NSUInteger k_bytes = (NSUInteger)batch_tokens * rope_dim * sizeof(float);
    if (q_data.length != q_bytes || k_data.length != k_bytes) {
        fprintf(stderr, "RoPE batch input bytes mismatch: q got %llu expected %llu; k got %llu expected %llu\n",
                (unsigned long long)q_data.length,
                (unsigned long long)q_bytes,
                (unsigned long long)k_data.length,
                (unsigned long long)k_bytes);
        return 1;
    }
    uint64_t peak = 2 * (uint64_t)q_bytes + 2 * (uint64_t)k_bytes;
    if (!enforce_scratch_limit("RoPE batch", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "RoPE batch");
    if (!library) return 1;
    id<MTLComputePipelineState> rope = make_pipeline(device, library, @"rope_batch_f32");
    if (!rope) return 1;

    id<MTLBuffer> bQ = [device newBufferWithBytes:q_data.bytes
                                           length:q_data.length
                                          options:MTLResourceStorageModeShared];
    id<MTLBuffer> bK = [device newBufferWithBytes:k_data.bytes
                                           length:k_data.length
                                          options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutQ = [device newBufferWithLength:q_bytes
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutK = [device newBufferWithLength:k_bytes
                                              options:MTLResourceStorageModeShared];
    if (!bQ || !bK || !bOutQ || !bOutK) {
        fprintf(stderr, "failed to allocate RoPE batch buffers\n");
        return 1;
    }
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create RoPE batch command buffer\n");
        return 1;
    }
    if (!encode_rope_batch_f32(cmd, rope, bQ, bK, bOutQ, bOutK,
                               num_heads, rope_dim, start_position, theta,
                               interleave ? 1u : 0u, batch_tokens)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "RoPE batch command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    NSData *out_q = [NSData dataWithBytes:bOutQ.contents length:q_bytes];
    NSData *out_k = [NSData dataWithBytes:bOutK.contents length:k_bytes];
    if (![out_q writeToFile:out_q_path atomically:YES] ||
        ![out_k writeToFile:out_k_path atomically:YES]) {
        fprintf(stderr, "failed to write RoPE batch outputs\n");
        return 1;
    }
    float *q0 = (float *)bOutQ.contents;
    float *k0 = (float *)bOutK.contents;
    printf("LargerLM RoPE batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  num heads:          %u\n", num_heads);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  start position:     %u\n", start_position);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  theta:              %.6f\n", theta);
    printf("  interleave:         %s\n", interleave ? "yes" : "no");
    printf("  q_out[0]:           %.6f\n", q0[0]);
    printf("  k_out[0]:           %.6f\n", k0[0]);
    printf("  output q f32:       %s\n", out_q_path.UTF8String);
    printf("  output k f32:       %s\n", out_k_path.UTF8String);
    return 0;
}

static int run_rope_split_batch(id<MTLDevice> device,
                                NSString *q_b_path,
                                NSString *k_path,
                                NSString *out_q_nope_path,
                                NSString *out_q_rope_path,
                                NSString *out_q_path,
                                NSString *out_k_path,
                                uint32_t num_heads,
                                uint32_t qk_nope_dim,
                                uint32_t rope_dim,
                                uint32_t start_position,
                                uint32_t batch_tokens,
                                float theta,
                                int interleave,
                                uint64_t max_runner_scratch_bytes) {
    if (num_heads == 0 || qk_nope_dim == 0 ||
        rope_dim == 0 || (rope_dim % 2) != 0 || batch_tokens == 0) {
        fprintf(stderr, "--num-heads, --qk-nope-dim, even --rope-dim, and --batch-tokens must be positive\n");
        return 1;
    }
    if (theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    if (qk_nope_dim > UINT32_MAX - rope_dim) {
        fprintf(stderr, "q head dimension overflows uint32\n");
        return 1;
    }
    uint32_t q_head_dim = qk_nope_dim + rope_dim;
    uint64_t q_b_values = 0;
    uint64_t q_nope_values = 0;
    uint64_t q_rope_values = 0;
    uint64_t k_values = 0;
    uint64_t q_b_bytes_u64 = 0;
    uint64_t q_nope_bytes_u64 = 0;
    uint64_t q_rope_bytes_u64 = 0;
    uint64_t k_bytes_u64 = 0;
    if (!checked_mul_u64((uint64_t)batch_tokens, (uint64_t)num_heads, &q_b_values) ||
        !checked_mul_u64(q_b_values, (uint64_t)q_head_dim, &q_b_values) ||
        !checked_mul_u64((uint64_t)batch_tokens, (uint64_t)num_heads, &q_nope_values) ||
        !checked_mul_u64(q_nope_values, (uint64_t)qk_nope_dim, &q_nope_values) ||
        !checked_mul_u64((uint64_t)batch_tokens, (uint64_t)num_heads, &q_rope_values) ||
        !checked_mul_u64(q_rope_values, (uint64_t)rope_dim, &q_rope_values) ||
        !checked_mul_u64((uint64_t)batch_tokens, (uint64_t)rope_dim, &k_values) ||
        !checked_mul_u64(q_b_values, sizeof(float), &q_b_bytes_u64) ||
        !checked_mul_u64(q_nope_values, sizeof(float), &q_nope_bytes_u64) ||
        !checked_mul_u64(q_rope_values, sizeof(float), &q_rope_bytes_u64) ||
        !checked_mul_u64(k_values, sizeof(float), &k_bytes_u64) ||
        q_b_bytes_u64 > (uint64_t)SIZE_MAX ||
        q_nope_bytes_u64 > (uint64_t)SIZE_MAX ||
        q_rope_bytes_u64 > (uint64_t)SIZE_MAX ||
        k_bytes_u64 > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "RoPE split batch byte size overflow\n");
        return 1;
    }
    NSUInteger q_b_bytes = (NSUInteger)q_b_bytes_u64;
    NSUInteger q_nope_bytes = (NSUInteger)q_nope_bytes_u64;
    NSUInteger q_rope_bytes = (NSUInteger)q_rope_bytes_u64;
    NSUInteger k_bytes = (NSUInteger)k_bytes_u64;
    NSData *q_b_data = [NSData dataWithContentsOfFile:q_b_path];
    NSData *k_data = [NSData dataWithContentsOfFile:k_path];
    if (!q_b_data || !k_data) {
        fprintf(stderr, "failed to read batch q_b/k f32 inputs\n");
        return 1;
    }
    if (q_b_data.length != q_b_bytes || k_data.length != k_bytes) {
        fprintf(stderr,
                "RoPE split batch input bytes mismatch: q_b got %llu expected %llu; k got %llu expected %llu\n",
                (unsigned long long)q_b_data.length,
                (unsigned long long)q_b_bytes,
                (unsigned long long)k_data.length,
                (unsigned long long)k_bytes);
        return 1;
    }
    uint64_t peak = q_b_bytes_u64;
    if (!checked_add_u64(peak, k_bytes_u64, &peak) ||
        !checked_add_u64(peak, q_nope_bytes_u64, &peak) ||
        !checked_add_u64(peak, q_rope_bytes_u64, &peak) ||
        !checked_add_u64(peak, q_rope_bytes_u64, &peak) ||
        !checked_add_u64(peak, k_bytes_u64, &peak)) {
        fprintf(stderr, "RoPE split batch peak byte size overflow\n");
        return 1;
    }
    if (!enforce_scratch_limit("RoPE split batch", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "RoPE split batch");
    if (!library) return 1;
    id<MTLComputePipelineState> rope =
        make_pipeline(device, library, @"rope_split_batch_f32");
    if (!rope) return 1;

    id<MTLBuffer> bQB = [device newBufferWithBytes:q_b_data.bytes
                                            length:q_b_data.length
                                           options:MTLResourceStorageModeShared];
    id<MTLBuffer> bK = [device newBufferWithBytes:k_data.bytes
                                           length:k_data.length
                                          options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutQNope = [device newBufferWithLength:q_nope_bytes
                                                   options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutQRope = [device newBufferWithLength:q_rope_bytes
                                                   options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutQ = [device newBufferWithLength:q_rope_bytes
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOutK = [device newBufferWithLength:k_bytes
                                              options:MTLResourceStorageModeShared];
    if (!bQB || !bK || !bOutQNope || !bOutQRope || !bOutQ || !bOutK) {
        fprintf(stderr, "failed to allocate RoPE split batch buffers\n");
        return 1;
    }
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create RoPE split batch command buffer\n");
        return 1;
    }
    if (!encode_rope_split_batch_f32(cmd, rope, bQB, bK,
                                     bOutQNope, bOutQRope, bOutQ, bOutK,
                                     num_heads, qk_nope_dim, rope_dim,
                                     start_position, theta,
                                     interleave ? 1u : 0u,
                                     batch_tokens)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "RoPE split batch command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    NSData *out_q_nope =
        [NSData dataWithBytes:bOutQNope.contents length:q_nope_bytes];
    NSData *out_q_rope =
        [NSData dataWithBytes:bOutQRope.contents length:q_rope_bytes];
    NSData *out_q = [NSData dataWithBytes:bOutQ.contents length:q_rope_bytes];
    NSData *out_k = [NSData dataWithBytes:bOutK.contents length:k_bytes];
    if (![out_q_nope writeToFile:out_q_nope_path atomically:YES] ||
        ![out_q_rope writeToFile:out_q_rope_path atomically:YES] ||
        ![out_q writeToFile:out_q_path atomically:YES] ||
        ![out_k writeToFile:out_k_path atomically:YES]) {
        fprintf(stderr, "failed to write RoPE split batch outputs\n");
        return 1;
    }
    float *q0 = (float *)bOutQ.contents;
    float *k0 = (float *)bOutK.contents;
    printf("LargerLM RoPE split batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  num heads:          %u\n", num_heads);
    printf("  qk nope dim:        %u\n", qk_nope_dim);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  start position:     %u\n", start_position);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  theta:              %.6f\n", theta);
    printf("  interleave:         %s\n", interleave ? "yes" : "no");
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  q_out[0]:           %.6f\n", q0[0]);
    printf("  k_out[0]:           %.6f\n", k0[0]);
    printf("  output q nope f32:  %s\n", out_q_nope_path.UTF8String);
    printf("  output q rope f32:  %s\n", out_q_rope_path.UTF8String);
    printf("  output q f32:       %s\n", out_q_path.UTF8String);
    printf("  output k f32:       %s\n", out_k_path.UTF8String);
    return 0;
}

static int run_mla_attention(id<MTLDevice> device,
                             NSString *resident_layout_path,
                             NSString *cache_layout_path,
                             NSString *cache_file_path,
                             uint64_t layer_id,
                             NSString *q_nope_path,
                             NSString *q_rope_path,
                             NSString *output_path,
                             uint32_t context_len,
                             uint32_t num_heads,
                             uint32_t kv_lora_dim_arg,
                             uint32_t qk_nope_dim,
                             uint32_t rope_dim,
                             uint32_t v_head_dim,
                             uint32_t position_offset,
                             float attention_scale,
                             float rope_theta,
                             int rope_interleave,
                             NSString *mla_kv_b_cache_dir,
                             uint64_t max_cache_file_bytes,
                             uint64_t max_cache_read_bytes,
                             uint64_t max_matrix_bytes,
                             uint64_t max_runner_scratch_bytes,
                             NSData *q_nope_data_override,
                             NSData *q_rope_data_override,
                             NSData *__strong *output_data) {
    if (context_len == 0 || num_heads == 0 || qk_nope_dim == 0 ||
        rope_dim == 0 || v_head_dim == 0 || (rope_dim % 2) != 0) {
        fprintf(stderr, "invalid MLA attention dimensions\n");
        return 1;
    }
    if (rope_theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();

    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    MlaAttentionValueSourceInfo value_source = {0};
    if (!resolve_mla_attention_value_source(resident_layout,
                                            layer_id,
                                            num_heads,
                                            kv_lora_dim_arg,
                                            qk_nope_dim,
                                            v_head_dim,
                                            max_matrix_bytes,
                                            &value_source)) {
        return 1;
    }
    uint32_t kv_lora_dim = value_source.kv_lora_dim;

    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 1;
    uint64_t layout_total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &layout_total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, layout_total_bytes)) {
        return 1;
    }
    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 1;
    }
    uint32_t cache_width = kv_lora_dim + rope_dim;
    if (segment.width != cache_width) {
        fprintf(stderr, "cache width %u does not match kv_lora+rope %u\n",
                segment.width, cache_width);
        return 1;
    }
    if (context_len > segment.max_context_tokens) {
        fprintf(stderr, "context length %u exceeds max context %llu\n",
                context_len, (unsigned long long)segment.max_context_tokens);
        return 1;
    }
    uint64_t raw_cache_bytes = (uint64_t)context_len * segment.width * segment.dtype_bytes;
    if (raw_cache_bytes > max_cache_read_bytes) {
        fprintf(stderr, "cache read %llu bytes exceeds limit %llu\n",
                (unsigned long long)raw_cache_bytes,
                (unsigned long long)max_cache_read_bytes);
        return 1;
    }

    CFAbsoluteTime input_started = CFAbsoluteTimeGetCurrent();
    NSData *q_nope_data = q_nope_data_override ?: [NSData dataWithContentsOfFile:q_nope_path];
    NSData *q_rope_data = q_rope_data_override ?: [NSData dataWithContentsOfFile:q_rope_path];
    if (!q_nope_data || !q_rope_data) {
        fprintf(stderr, "failed to read q_nope/q_rope f32 files\n");
        return 1;
    }
    NSUInteger q_nope_bytes = (NSUInteger)num_heads * qk_nope_dim * sizeof(float);
    NSUInteger q_rope_bytes = (NSUInteger)num_heads * rope_dim * sizeof(float);
    if (q_nope_data.length != q_nope_bytes || q_rope_data.length != q_rope_bytes) {
        fprintf(stderr,
                "query bytes mismatch: q_nope got %llu expected %llu; "
                "q_rope got %llu expected %llu\n",
                (unsigned long long)q_nope_data.length,
                (unsigned long long)q_nope_bytes,
                (unsigned long long)q_rope_data.length,
                (unsigned long long)q_rope_bytes);
        return 1;
    }
    double input_elapsed = CFAbsoluteTimeGetCurrent() - input_started;

    uint64_t cache_f32_bytes = (uint64_t)context_len * cache_width * sizeof(float);
    uint64_t kv_b_f32_bytes = value_source.kv_b_f32_bytes;
    uint64_t output_bytes = (uint64_t)num_heads * v_head_dim * sizeof(float);
    uint64_t peak = raw_cache_bytes + cache_f32_bytes + value_source.storage_bytes +
                    value_source.absorbed_source_f32_bytes + kv_b_f32_bytes +
                    q_nope_bytes + q_rope_bytes + output_bytes;
    if (!enforce_scratch_limit("MLA attention", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    CFAbsoluteTime cache_started = CFAbsoluteTimeGetCurrent();
    float *cache_f32 = NULL;
    uint64_t cache_bytes = 0;
    if (!read_decode_cache_segment_f32(cache_layout_path,
                                       cache_file_path,
                                       layer_id,
                                       context_len,
                                       cache_width,
                                       max_cache_file_bytes,
                                       max_cache_read_bytes,
                                       &cache_f32,
                                       &cache_bytes)) {
        return 1;
    }
    double cache_elapsed = CFAbsoluteTimeGetCurrent() - cache_started;
    CFAbsoluteTime value_started = CFAbsoluteTimeGetCurrent();
    float *kv_b_f32 = NULL;
    uint64_t matrix_bytes = 0;
    if (!read_mla_attention_value_source_f32(weight_path,
                                             value_source,
                                             layer_id,
                                             num_heads,
                                             qk_nope_dim,
                                             v_head_dim,
                                             mla_kv_b_cache_dir,
                                             &kv_b_f32,
                                             &matrix_bytes)) {
        free(cache_f32);
        return 1;
    }
    double value_elapsed = CFAbsoluteTimeGetCurrent() - value_started;
    if (cache_bytes != cache_f32_bytes || matrix_bytes != kv_b_f32_bytes) {
        fprintf(stderr, "internal MLA attention byte estimate mismatch\n");
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }

    CFAbsoluteTime metal_setup_started = CFAbsoluteTimeGetCurrent();
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        free(cache_f32);
        free(kv_b_f32);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "MLA attention");
    if (!library) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(device, library, @"mla_attention_f32");
    if (!pipe) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLBuffer> bQNope = [device newBufferWithBytes:q_nope_data.bytes
                                               length:q_nope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bQRope = [device newBufferWithBytes:q_rope_data.bytes
                                               length:q_rope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bCache =
        [device newBufferWithBytesNoCopy:cache_f32
                                   length:(NSUInteger)cache_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    cache_f32 = NULL;
    id<MTLBuffer> bKVB =
        [device newBufferWithBytesNoCopy:kv_b_f32
                                   length:(NSUInteger)kv_b_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    kv_b_f32 = NULL;
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bQNope || !bQRope || !bCache || !bKVB || !bOut) {
        fprintf(stderr, "failed to allocate MLA attention buffers\n");
        return 1;
    }
    if (attention_scale == 0.0f) {
        attention_scale = 1.0f / sqrtf((float)(qk_nope_dim + rope_dim));
    }
    double metal_setup_elapsed = CFAbsoluteTimeGetCurrent() - metal_setup_started;
    CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create MLA attention command buffer\n");
        return 1;
    }
    if (!encode_mla_attention_f32(cmd, pipe, bQNope, bQRope, bCache, bKVB, bOut,
                                  context_len, num_heads, kv_lora_dim,
                                  qk_nope_dim, rope_dim, v_head_dim,
                                  attention_scale, rope_theta,
                                  rope_interleave ? 1u : 0u,
                                  position_offset)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "MLA attention command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    double kernel_elapsed = CFAbsoluteTimeGetCurrent() - kernel_started;
    CFAbsoluteTime write_started = CFAbsoluteTimeGetCurrent();
    NSData *out_data = [[NSData alloc] initWithBytes:bOut.contents
                                              length:(NSUInteger)output_bytes];
    if (output_data) {
        *output_data = out_data;
    }
    if (output_path) {
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write MLA attention output: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }
    double write_elapsed = CFAbsoluteTimeGetCurrent() - write_started;
    double total_elapsed = CFAbsoluteTimeGetCurrent() - total_started;
    float *out = (float *)bOut.contents;
    printf("LargerLM MLA attention\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  context length:     %u\n", context_len);
    printf("  num heads:          %u\n", num_heads);
    printf("  kv lora dim:        %u\n", kv_lora_dim);
    printf("  qk nope dim:        %u\n", qk_nope_dim);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  v head dim:         %u\n", v_head_dim);
    printf("  value source:       %s\n",
           value_source.use_absorbed_alias ? "absorbed-alias" : "kv_b_proj");
    if (mla_kv_b_cache_dir && value_source.use_absorbed_alias) {
        printf("  kv_b cache dir:      %s\n", mla_kv_b_cache_dir.UTF8String);
    }
    printf("  scale:              %.9g\n", attention_scale);
    printf("  rope theta:         %.6f\n", rope_theta);
    printf("  rope interleave:    %s\n", rope_interleave ? "yes" : "no");
    printf("  cache read bytes:   %llu\n", (unsigned long long)raw_cache_bytes);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing input:       %.6f\n", input_elapsed);
    printf("  timing cache read:  %.6f\n", cache_elapsed);
    printf("  timing value read:  %.6f\n", value_elapsed);
    printf("  timing metal setup: %.6f\n", metal_setup_elapsed);
    printf("  timing kernel:      %.6f\n", kernel_elapsed);
    printf("  timing write:       %.6f\n", write_elapsed);
    printf("  timing total:       %.6f\n", total_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

typedef struct {
    double input_elapsed_seconds;
    double cache_read_elapsed_seconds;
    double value_read_elapsed_seconds;
    double metal_setup_elapsed_seconds;
    double kernel_elapsed_seconds;
    double kernel_weights_elapsed_seconds;
    double kernel_values_elapsed_seconds;
    double write_elapsed_seconds;
    double total_elapsed_seconds;
    uint64_t weights_bytes;
    uint64_t key_cache_bytes;
    uint64_t rope_cache_bytes;
    uint64_t value_cache_bytes;
    uint64_t estimated_peak_bytes;
    int singleton_kernel;
    int split_kernel_timing_enabled;
    int key_cache_enabled;
    int rope_cache_enabled;
    int value_cache_enabled;
} MlaAttentionBatchTimings;

static void reset_mla_attention_batch_timings(MlaAttentionBatchTimings *timings) {
    if (timings) {
        memset(timings, 0, sizeof(*timings));
    }
}

static int run_mla_attention_batch(id<MTLDevice> device,
                                   NSString *resident_layout_path,
                                   NSString *cache_layout_path,
                                   NSString *cache_file_path,
                                   uint64_t layer_id,
                                   NSString *q_nope_path,
                                   NSString *q_rope_path,
                                   NSString *output_path,
                                   uint32_t context_len,
                                   uint32_t start_position,
                                   uint32_t batch_tokens,
                                   uint32_t num_heads,
                                   uint32_t kv_lora_dim_arg,
                                   uint32_t qk_nope_dim,
                                   uint32_t rope_dim,
                                   uint32_t v_head_dim,
                                   uint32_t position_offset,
                                   float attention_scale,
                                   float rope_theta,
                                   int rope_interleave,
                                   NSString *mla_kv_b_cache_dir,
                                   uint64_t max_cache_file_bytes,
                                   uint64_t max_cache_read_bytes,
                                   uint64_t max_matrix_bytes,
                                   uint64_t max_runner_scratch_bytes,
                                   MlaAttentionBatchTimings *timings) {
    reset_mla_attention_batch_timings(timings);
    if (context_len == 0 || batch_tokens == 0 || num_heads == 0 ||
        qk_nope_dim == 0 || rope_dim == 0 || v_head_dim == 0 ||
        (rope_dim % 2) != 0) {
        fprintf(stderr, "invalid batch MLA attention dimensions\n");
        return 1;
    }
    if (start_position + batch_tokens > context_len) {
        fprintf(stderr, "start-position + batch-tokens exceeds context length\n");
        return 1;
    }
    if (rope_theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();

    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    MlaAttentionValueSourceInfo value_source = {0};
    if (!resolve_mla_attention_value_source(resident_layout,
                                            layer_id,
                                            num_heads,
                                            kv_lora_dim_arg,
                                            qk_nope_dim,
                                            v_head_dim,
                                            max_matrix_bytes,
                                            &value_source)) {
        return 1;
    }
    uint32_t kv_lora_dim = value_source.kv_lora_dim;

    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 1;
    uint64_t layout_total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &layout_total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, layout_total_bytes)) {
        return 1;
    }
    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 1;
    }
    uint32_t cache_width = kv_lora_dim + rope_dim;
    if (segment.width != cache_width) {
        fprintf(stderr, "cache width %u does not match kv_lora+rope %u\n",
                segment.width, cache_width);
        return 1;
    }
    if (context_len > segment.max_context_tokens) {
        fprintf(stderr, "context length %u exceeds max context %llu\n",
                context_len, (unsigned long long)segment.max_context_tokens);
        return 1;
    }
    uint64_t raw_cache_bytes = (uint64_t)context_len * segment.width * segment.dtype_bytes;
    if (raw_cache_bytes > max_cache_read_bytes) {
        fprintf(stderr, "cache read %llu bytes exceeds limit %llu\n",
                (unsigned long long)raw_cache_bytes,
                (unsigned long long)max_cache_read_bytes);
        return 1;
    }

    CFAbsoluteTime input_started = CFAbsoluteTimeGetCurrent();
    NSData *q_nope_data = [NSData dataWithContentsOfFile:q_nope_path];
    NSData *q_rope_data = [NSData dataWithContentsOfFile:q_rope_path];
    if (!q_nope_data || !q_rope_data) {
        fprintf(stderr, "failed to read batch q_nope/q_rope f32 files\n");
        return 1;
    }
    NSUInteger q_nope_bytes =
        (NSUInteger)batch_tokens * num_heads * qk_nope_dim * sizeof(float);
    NSUInteger q_rope_bytes =
        (NSUInteger)batch_tokens * num_heads * rope_dim * sizeof(float);
    if (q_nope_data.length != q_nope_bytes || q_rope_data.length != q_rope_bytes) {
        fprintf(stderr,
                "batch query bytes mismatch: q_nope got %llu expected %llu; "
                "q_rope got %llu expected %llu\n",
                (unsigned long long)q_nope_data.length,
                (unsigned long long)q_nope_bytes,
                (unsigned long long)q_rope_data.length,
                (unsigned long long)q_rope_bytes);
        return 1;
    }
    double input_elapsed = CFAbsoluteTimeGetCurrent() - input_started;

    uint64_t cache_f32_bytes = (uint64_t)context_len * cache_width * sizeof(float);
    uint64_t kv_b_f32_bytes = value_source.kv_b_f32_bytes;
    uint64_t output_bytes =
        (uint64_t)batch_tokens * num_heads * v_head_dim * sizeof(float);
    int use_singleton_kernel =
        getenv("LARGERLM_MLA_LEGACY_SINGLETON") != NULL &&
        (batch_tokens == 1u && start_position + 1u == context_len);
    uint64_t weights_values = 0;
    uint64_t weights_bytes = 0;
    if (!use_singleton_kernel &&
        (!checked_mul_u64((uint64_t)batch_tokens,
                          (uint64_t)num_heads,
                          &weights_values) ||
         !checked_mul_u64(weights_values,
                          (uint64_t)context_len,
                          &weights_values) ||
         !checked_mul_u64(weights_values, sizeof(float), &weights_bytes))) {
        fprintf(stderr, "batch MLA attention weights byte size overflows uint64\n");
        return 1;
    }
    uint64_t value_cache_values = 0;
    uint64_t value_cache_bytes = 0;
    if (!use_singleton_kernel &&
        getenv("LARGERLM_MLA_DISABLE_VALUE_CACHE") == NULL &&
        (batch_tokens > 1u ||
         getenv("LARGERLM_MLA_VALUE_CACHE_SINGLETON") != NULL) &&
        checked_mul_u64((uint64_t)context_len,
                        (uint64_t)num_heads,
                        &value_cache_values) &&
        checked_mul_u64(value_cache_values,
                        (uint64_t)v_head_dim,
                        &value_cache_values) &&
        checked_mul_u64(value_cache_values, sizeof(float), &value_cache_bytes)) {
        /* optional cache; used below only if it fits the configured scratch cap */
    } else {
        value_cache_bytes = 0;
    }
    uint64_t key_cache_values = 0;
    uint64_t key_cache_bytes = 0;
    if (!use_singleton_kernel &&
        getenv("LARGERLM_MLA_KEY_CACHE") != NULL &&
        checked_mul_u64((uint64_t)context_len,
                        (uint64_t)num_heads,
                        &key_cache_values) &&
        checked_mul_u64(key_cache_values,
                        (uint64_t)qk_nope_dim,
                        &key_cache_values) &&
        checked_mul_u64(key_cache_values, sizeof(float), &key_cache_bytes)) {
        /* optional cache; used below only if it fits the configured scratch cap */
    } else {
        key_cache_bytes = 0;
    }
    uint64_t rope_cache_values = 0;
    uint64_t rope_cache_bytes = 0;
    if (!use_singleton_kernel &&
        key_cache_bytes > 0 &&
        getenv("LARGERLM_MLA_ROPE_CACHE") != NULL &&
        checked_mul_u64((uint64_t)context_len,
                        (uint64_t)rope_dim,
                        &rope_cache_values) &&
        checked_mul_u64(rope_cache_values, sizeof(float), &rope_cache_bytes)) {
        /* optional cache; used below only if it fits the configured scratch cap */
    } else {
        rope_cache_bytes = 0;
    }
    uint64_t base_peak = raw_cache_bytes + cache_f32_bytes + value_source.storage_bytes +
                         value_source.absorbed_source_f32_bytes + kv_b_f32_bytes +
                         weights_bytes + q_nope_bytes + q_rope_bytes + output_bytes;
    uint64_t peak = base_peak;
    int use_key_cache = 0;
    if (key_cache_bytes > 0) {
        uint64_t cached_peak = 0;
        if (checked_add_u64(peak, key_cache_bytes, &cached_peak) &&
            cached_peak <= max_runner_scratch_bytes) {
            peak = cached_peak;
            use_key_cache = 1;
        }
    }
    int use_rope_cache = 0;
    if (use_key_cache && rope_cache_bytes > 0) {
        uint64_t cached_peak = 0;
        if (checked_add_u64(peak, rope_cache_bytes, &cached_peak) &&
            cached_peak <= max_runner_scratch_bytes) {
            peak = cached_peak;
            use_rope_cache = 1;
        }
    }
    int use_value_cache = 0;
    if (value_cache_bytes > 0) {
        uint64_t cached_peak = 0;
        if (checked_add_u64(peak, value_cache_bytes, &cached_peak) &&
            cached_peak <= max_runner_scratch_bytes) {
            peak = cached_peak;
            use_value_cache = 1;
        }
    }
    if (!enforce_scratch_limit("batch MLA attention", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    CFAbsoluteTime cache_started = CFAbsoluteTimeGetCurrent();
    float *cache_f32 = NULL;
    uint64_t cache_bytes = 0;
    if (!read_decode_cache_segment_f32(cache_layout_path,
                                       cache_file_path,
                                       layer_id,
                                       context_len,
                                       cache_width,
                                       max_cache_file_bytes,
                                       max_cache_read_bytes,
                                       &cache_f32,
                                       &cache_bytes)) {
        return 1;
    }
    double cache_elapsed = CFAbsoluteTimeGetCurrent() - cache_started;
    CFAbsoluteTime value_started = CFAbsoluteTimeGetCurrent();
    float *kv_b_f32 = NULL;
    uint64_t matrix_bytes = 0;
    if (!read_mla_attention_value_source_f32(weight_path,
                                             value_source,
                                             layer_id,
                                             num_heads,
                                             qk_nope_dim,
                                             v_head_dim,
                                             mla_kv_b_cache_dir,
                                             &kv_b_f32,
                                             &matrix_bytes)) {
        free(cache_f32);
        return 1;
    }
    double value_elapsed = CFAbsoluteTimeGetCurrent() - value_started;
    if (cache_bytes != cache_f32_bytes || matrix_bytes != kv_b_f32_bytes) {
        fprintf(stderr, "internal batch MLA attention byte estimate mismatch\n");
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }

    CFAbsoluteTime metal_setup_started = CFAbsoluteTimeGetCurrent();
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        free(cache_f32);
        free(kv_b_f32);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "batch MLA attention");
    if (!library) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLComputePipelineState> pipe = nil;
    id<MTLComputePipelineState> weights_pipe = nil;
    id<MTLComputePipelineState> project_keys_pipe = nil;
    id<MTLComputePipelineState> project_rope_pipe = nil;
    id<MTLComputePipelineState> weights_key_cached_pipe = nil;
    id<MTLComputePipelineState> weights_key_rope_cached_pipe = nil;
    id<MTLComputePipelineState> values_pipe = nil;
    id<MTLComputePipelineState> project_values_pipe = nil;
    id<MTLComputePipelineState> values_cached_pipe = nil;
    if (use_singleton_kernel) {
        pipe = make_pipeline(device, library, @"mla_attention_f32");
    } else {
        weights_pipe =
            make_pipeline(device, library, @"mla_attention_batch_weights_f32");
        if (use_key_cache) {
            project_keys_pipe =
                make_pipeline(device, library, @"mla_attention_project_keys_f32");
            if (use_rope_cache) {
                project_rope_pipe =
                    make_pipeline(device, library, @"mla_attention_project_rope_f32");
                weights_key_rope_cached_pipe =
                    make_pipeline(device, library, @"mla_attention_batch_weights_key_rope_cached_f32");
            } else {
                weights_key_cached_pipe =
                    make_pipeline(device, library, @"mla_attention_batch_weights_key_cached_f32");
            }
        }
        if (use_value_cache) {
            project_values_pipe =
                make_pipeline(device, library, @"mla_attention_project_values_f32");
            values_cached_pipe =
                make_pipeline(device, library, @"mla_attention_batch_values_cached_f32");
        } else {
            values_pipe =
                make_pipeline(device, library, @"mla_attention_batch_values_f32");
        }
    }
    if ((use_singleton_kernel && !pipe) ||
        (!use_singleton_kernel && use_key_cache &&
         (!weights_pipe || !project_keys_pipe ||
          (use_rope_cache && (!project_rope_pipe || !weights_key_rope_cached_pipe)) ||
          (!use_rope_cache && !weights_key_cached_pipe))) ||
        (!use_singleton_kernel && use_value_cache &&
         (!weights_pipe || !project_values_pipe || !values_cached_pipe)) ||
        (!use_singleton_kernel && !use_value_cache && (!weights_pipe || !values_pipe))) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLBuffer> bQNope = [device newBufferWithBytes:q_nope_data.bytes
                                               length:q_nope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bQRope = [device newBufferWithBytes:q_rope_data.bytes
                                               length:q_rope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bCache =
        [device newBufferWithBytesNoCopy:cache_f32
                                   length:(NSUInteger)cache_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    cache_f32 = NULL;
    id<MTLBuffer> bKVB =
        [device newBufferWithBytesNoCopy:kv_b_f32
                                   length:(NSUInteger)kv_b_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    kv_b_f32 = NULL;
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bWeights = nil;
    if (!use_singleton_kernel) {
        bWeights = [device newBufferWithLength:(NSUInteger)weights_bytes
                                       options:MTLResourceStorageModeShared];
    }
    id<MTLBuffer> bKeyCache = nil;
    if (use_key_cache) {
        bKeyCache = [device newBufferWithLength:(NSUInteger)key_cache_bytes
                                        options:MTLResourceStorageModeShared];
    }
    id<MTLBuffer> bRopeCache = nil;
    if (use_rope_cache) {
        bRopeCache = [device newBufferWithLength:(NSUInteger)rope_cache_bytes
                                         options:MTLResourceStorageModeShared];
    }
    id<MTLBuffer> bValueCache = nil;
    if (use_value_cache) {
        bValueCache = [device newBufferWithLength:(NSUInteger)value_cache_bytes
                                          options:MTLResourceStorageModeShared];
    }
    if (!bQNope || !bQRope || !bCache || !bKVB || !bOut ||
        (!use_singleton_kernel && !bWeights) ||
        (use_key_cache && !bKeyCache) ||
        (use_rope_cache && !bRopeCache) ||
        (use_value_cache && !bValueCache)) {
        fprintf(stderr, "failed to allocate batch MLA attention buffers\n");
        return 1;
    }
    if (attention_scale == 0.0f) {
        attention_scale = 1.0f / sqrtf((float)(qk_nope_dim + rope_dim));
    }
    int split_kernel_timing =
        getenv("LARGERLM_MLA_SPLIT_KERNEL_TIMING") != NULL &&
        !use_singleton_kernel;
    double kernel_weights_elapsed = 0.0;
    double kernel_values_elapsed = 0.0;
    double metal_setup_elapsed = CFAbsoluteTimeGetCurrent() - metal_setup_started;
    CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
    CFAbsoluteTime kernel_weights_started = kernel_started;
    CFAbsoluteTime kernel_values_started = 0.0;
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create batch MLA attention command buffer\n");
        return 1;
    }
    int encoded = 0;
    if (use_singleton_kernel) {
        encoded = encode_mla_attention_f32(cmd, pipe, bQNope, bQRope, bCache, bKVB,
                                           bOut, context_len, num_heads, kv_lora_dim,
                                           qk_nope_dim, rope_dim, v_head_dim,
                                           attention_scale, rope_theta,
                                           rope_interleave ? 1u : 0u,
                                           position_offset);
    } else {
        if (use_key_cache) {
            encoded = encode_mla_attention_project_keys_f32(
                cmd, project_keys_pipe, bCache, bKVB, bKeyCache,
                context_len, num_heads, kv_lora_dim, qk_nope_dim,
                rope_dim, v_head_dim);
            if (encoded && use_rope_cache) {
                encoded = encode_mla_attention_project_rope_f32(
                              cmd, project_rope_pipe, bCache, bRopeCache,
                              context_len, kv_lora_dim, rope_dim, rope_theta,
                              rope_interleave ? 1u : 0u, position_offset) &&
                          encode_mla_attention_batch_weights_key_rope_cached_f32(
                              cmd, weights_key_rope_cached_pipe, bQNope, bQRope,
                              bKeyCache, bRopeCache, bWeights, context_len,
                              num_heads, qk_nope_dim, rope_dim, attention_scale,
                              start_position, batch_tokens);
            } else if (encoded) {
                encoded = encode_mla_attention_batch_weights_key_cached_f32(
                    cmd, weights_key_cached_pipe, bQNope, bQRope, bCache,
                    bKeyCache, bWeights, context_len, num_heads, kv_lora_dim,
                    qk_nope_dim, rope_dim, attention_scale, rope_theta,
                    rope_interleave ? 1u : 0u, position_offset,
                    start_position, batch_tokens);
            }
        } else {
            encoded = encode_mla_attention_batch_weights_f32(
                          cmd, weights_pipe, bQNope, bQRope, bCache, bKVB, bWeights,
                          context_len, num_heads, kv_lora_dim, qk_nope_dim,
                          rope_dim, v_head_dim, attention_scale, rope_theta,
                          rope_interleave ? 1u : 0u, position_offset,
                          start_position, batch_tokens);
        }
        if (split_kernel_timing) {
            if (!encoded) return 1;
            [cmd commit];
            [cmd waitUntilCompleted];
            if (cmd.status == MTLCommandBufferStatusError) {
                fprintf(stderr, "batch MLA attention weights command failed: %s\n",
                        cmd.error.localizedDescription.UTF8String);
                return 1;
            }
            kernel_weights_elapsed =
                CFAbsoluteTimeGetCurrent() - kernel_weights_started;
            cmd = [queue commandBuffer];
            if (!cmd) {
                fprintf(stderr,
                        "failed to create batch MLA attention values command buffer\n");
                return 1;
            }
        }
        kernel_values_started = CFAbsoluteTimeGetCurrent();
        if (encoded && use_value_cache) {
            encoded = encode_mla_attention_project_values_f32(
                          cmd, project_values_pipe, bCache, bKVB, bValueCache,
                          context_len, num_heads, kv_lora_dim, qk_nope_dim,
                          rope_dim, v_head_dim) &&
                      encode_mla_attention_batch_values_cached_f32(
                          cmd, values_cached_pipe, bValueCache, bWeights, bOut,
                          context_len, num_heads, v_head_dim, start_position,
                          batch_tokens);
        } else if (encoded) {
            encoded = encode_mla_attention_batch_values_f32(
                          cmd, values_pipe, bCache, bKVB, bWeights, bOut,
                          context_len, num_heads, kv_lora_dim, qk_nope_dim,
                          rope_dim, v_head_dim, start_position, batch_tokens);
        }
    }
    if (!encoded) return 1;
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "batch MLA attention command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    double kernel_elapsed = CFAbsoluteTimeGetCurrent() - kernel_started;
    if (split_kernel_timing) {
        kernel_values_elapsed =
            CFAbsoluteTimeGetCurrent() - kernel_values_started;
    }
    CFAbsoluteTime write_started = CFAbsoluteTimeGetCurrent();
    NSData *out_data = [NSData dataWithBytes:bOut.contents length:(NSUInteger)output_bytes];
    if (![out_data writeToFile:output_path atomically:YES]) {
        fprintf(stderr, "failed to write batch MLA attention output: %s\n",
                output_path.UTF8String);
        return 1;
    }
    double write_elapsed = CFAbsoluteTimeGetCurrent() - write_started;
    double total_elapsed = CFAbsoluteTimeGetCurrent() - total_started;
    float *out = (float *)bOut.contents;
    printf("LargerLM batch MLA attention\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  context length:     %u\n", context_len);
    printf("  start position:     %u\n", start_position);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  num heads:          %u\n", num_heads);
    printf("  kv lora dim:        %u\n", kv_lora_dim);
    printf("  qk nope dim:        %u\n", qk_nope_dim);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  v head dim:         %u\n", v_head_dim);
    printf("  value source:       %s\n",
           value_source.use_absorbed_alias ? "absorbed-alias" : "kv_b_proj");
    printf("  singleton kernel:   %s\n", use_singleton_kernel ? "yes" : "no");
    if (mla_kv_b_cache_dir && value_source.use_absorbed_alias) {
        printf("  kv_b cache dir:      %s\n", mla_kv_b_cache_dir.UTF8String);
    }
    printf("  scale:              %.9g\n", attention_scale);
    printf("  rope theta:         %.6f\n", rope_theta);
    printf("  rope interleave:    %s\n", rope_interleave ? "yes" : "no");
    printf("  cache read bytes:   %llu\n", (unsigned long long)raw_cache_bytes);
    if (!use_singleton_kernel) {
        printf("  weights bytes:      %llu\n", (unsigned long long)weights_bytes);
        printf("  key cache bytes:    %llu\n", (unsigned long long)(use_key_cache ? key_cache_bytes : 0));
        printf("  rope cache bytes:   %llu\n", (unsigned long long)(use_rope_cache ? rope_cache_bytes : 0));
        printf("  value cache bytes:  %llu\n", (unsigned long long)(use_value_cache ? value_cache_bytes : 0));
    }
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing input:       %.6f\n", input_elapsed);
    printf("  timing cache read:  %.6f\n", cache_elapsed);
    printf("  timing value read:  %.6f\n", value_elapsed);
    printf("  timing metal setup: %.6f\n", metal_setup_elapsed);
    printf("  timing kernel:      %.6f\n", kernel_elapsed);
    printf("  timing write:       %.6f\n", write_elapsed);
    printf("  timing total:       %.6f\n", total_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    printf("  output f32:         %s\n", output_path.UTF8String);
    if (timings) {
        timings->input_elapsed_seconds = input_elapsed;
        timings->cache_read_elapsed_seconds = cache_elapsed;
        timings->value_read_elapsed_seconds = value_elapsed;
        timings->metal_setup_elapsed_seconds = metal_setup_elapsed;
        timings->kernel_elapsed_seconds = kernel_elapsed;
        timings->kernel_weights_elapsed_seconds = kernel_weights_elapsed;
        timings->kernel_values_elapsed_seconds = kernel_values_elapsed;
        timings->write_elapsed_seconds = write_elapsed;
        timings->total_elapsed_seconds = total_elapsed;
        timings->weights_bytes = use_singleton_kernel ? 0 : weights_bytes;
        timings->key_cache_bytes = use_key_cache ? key_cache_bytes : 0;
        timings->rope_cache_bytes = use_rope_cache ? rope_cache_bytes : 0;
        timings->value_cache_bytes = use_value_cache ? value_cache_bytes : 0;
        timings->estimated_peak_bytes = peak;
        timings->singleton_kernel = use_singleton_kernel;
        timings->split_kernel_timing_enabled = split_kernel_timing;
        timings->key_cache_enabled = use_key_cache;
        timings->rope_cache_enabled = use_rope_cache;
        timings->value_cache_enabled = use_value_cache;
    }
    return 0;
}

static int run_mla_attention_indexed_batch(id<MTLDevice> device,
                                           NSString *resident_layout_path,
                                           NSString *cache_layout_path,
                                           NSString *cache_file_path,
                                           uint64_t layer_id,
                                           NSString *q_nope_path,
                                           NSString *q_rope_path,
                                           NSString *indices_path,
                                           NSString *output_path,
                                           uint32_t context_len,
                                           uint32_t batch_tokens,
                                           uint32_t index_topk,
                                           uint32_t num_heads,
                                           uint32_t kv_lora_dim_arg,
                                           uint32_t qk_nope_dim,
                                           uint32_t rope_dim,
                                           uint32_t v_head_dim,
                                           uint32_t position_offset,
                                           float attention_scale,
                                           float rope_theta,
                                           int rope_interleave,
                                           NSString *mla_kv_b_cache_dir,
                                           uint64_t max_cache_file_bytes,
                                           uint64_t max_cache_read_bytes,
                                           uint64_t max_matrix_bytes,
                                           uint64_t max_runner_scratch_bytes) {
    if (context_len == 0 || batch_tokens == 0 || index_topk == 0 ||
        num_heads == 0 || qk_nope_dim == 0 || rope_dim == 0 ||
        v_head_dim == 0 || (rope_dim % 2) != 0) {
        fprintf(stderr, "invalid indexed batch MLA attention dimensions\n");
        return 1;
    }
    if (rope_theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 1;
    }
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();

    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    MlaAttentionValueSourceInfo value_source = {0};
    if (!resolve_mla_attention_value_source(resident_layout,
                                            layer_id,
                                            num_heads,
                                            kv_lora_dim_arg,
                                            qk_nope_dim,
                                            v_head_dim,
                                            max_matrix_bytes,
                                            &value_source)) {
        return 1;
    }
    uint32_t kv_lora_dim = value_source.kv_lora_dim;

    NSDictionary *cache_layout = load_json(cache_layout_path);
    if (!cache_layout) return 1;
    uint64_t layout_total_bytes = 0;
    if (!validate_decode_cache_layout(cache_layout,
                                      max_cache_file_bytes,
                                      &layout_total_bytes) ||
        !validate_decode_cache_file_size(cache_file_path, layout_total_bytes)) {
        return 1;
    }
    CacheSegmentInfo segment = {0};
    if (!find_decode_cache_segment(cache_layout, layer_id, @"mla_kv", &segment)) {
        return 1;
    }
    uint32_t cache_width = kv_lora_dim + rope_dim;
    if (segment.width != cache_width) {
        fprintf(stderr, "cache width %u does not match kv_lora+rope %u\n",
                segment.width, cache_width);
        return 1;
    }
    if (context_len > segment.max_context_tokens) {
        fprintf(stderr, "context length %u exceeds max context %llu\n",
                context_len, (unsigned long long)segment.max_context_tokens);
        return 1;
    }

    CFAbsoluteTime input_started = CFAbsoluteTimeGetCurrent();
    NSData *q_nope_data = [NSData dataWithContentsOfFile:q_nope_path];
    NSData *q_rope_data = [NSData dataWithContentsOfFile:q_rope_path];
    NSData *indices_data = [NSData dataWithContentsOfFile:indices_path];
    if (!q_nope_data || !q_rope_data || !indices_data) {
        fprintf(stderr, "failed to read indexed MLA q_nope/q_rope/indices files\n");
        return 1;
    }
    NSUInteger q_nope_bytes =
        (NSUInteger)batch_tokens * num_heads * qk_nope_dim * sizeof(float);
    NSUInteger q_rope_bytes =
        (NSUInteger)batch_tokens * num_heads * rope_dim * sizeof(float);
    uint64_t index_stride = (uint64_t)index_topk + 1u;
    uint64_t indices_bytes = (uint64_t)batch_tokens * index_stride * sizeof(uint32_t);
    if (q_nope_data.length != q_nope_bytes ||
        q_rope_data.length != q_rope_bytes ||
        indices_data.length != (NSUInteger)indices_bytes) {
        fprintf(stderr,
                "indexed MLA input byte mismatch: q_nope %llu/%llu "
                "q_rope %llu/%llu indices %llu/%llu\n",
                (unsigned long long)q_nope_data.length,
                (unsigned long long)q_nope_bytes,
                (unsigned long long)q_rope_data.length,
                (unsigned long long)q_rope_bytes,
                (unsigned long long)indices_data.length,
                (unsigned long long)indices_bytes);
        return 1;
    }
    const uint32_t *indices = (const uint32_t *)indices_data.bytes;
    uint64_t raw_cache_bytes = 0;
    uint64_t token_bytes = (uint64_t)segment.width * segment.dtype_bytes;
    for (uint32_t token = 0; token < batch_tokens; token++) {
        const uint32_t *row = indices + (uint64_t)token * index_stride;
        uint32_t count = row[0];
        if (count == 0 || count > index_topk) {
            fprintf(stderr, "indexed MLA row %u has invalid count %u\n", token, count);
            return 1;
        }
        for (uint32_t j = 0; j < count; j++) {
            uint32_t pos = row[1u + j];
            if (pos >= context_len) {
                fprintf(stderr, "indexed MLA row %u index %u outside context %u\n",
                        token, pos, context_len);
                return 1;
            }
            raw_cache_bytes += token_bytes;
            if (raw_cache_bytes > max_cache_read_bytes) {
                fprintf(stderr, "indexed cache read %llu bytes exceeds limit %llu\n",
                        (unsigned long long)raw_cache_bytes,
                        (unsigned long long)max_cache_read_bytes);
                return 1;
            }
        }
    }
    double input_elapsed = CFAbsoluteTimeGetCurrent() - input_started;

    uint64_t staged_cache_f32_bytes =
        (uint64_t)batch_tokens * index_topk * cache_width * sizeof(float);
    uint64_t kv_b_f32_bytes = value_source.kv_b_f32_bytes;
    uint64_t output_bytes =
        (uint64_t)batch_tokens * num_heads * v_head_dim * sizeof(float);
    uint64_t peak = raw_cache_bytes + staged_cache_f32_bytes +
                    value_source.storage_bytes +
                    value_source.absorbed_source_f32_bytes + kv_b_f32_bytes +
                    q_nope_bytes + q_rope_bytes + indices_bytes + output_bytes;
    if (!enforce_scratch_limit("indexed batch MLA attention", peak,
                               max_runner_scratch_bytes)) {
        return 1;
    }

    CFAbsoluteTime cache_started = CFAbsoluteTimeGetCurrent();
    float *cache_f32 = NULL;
    uint64_t staged_bytes = 0;
    uint64_t staged_raw_bytes = 0;
    if (!read_decode_cache_indexed_rows_f32(cache_layout,
                                            cache_file_path,
                                            layer_id,
                                            context_len,
                                            index_topk,
                                            batch_tokens,
                                            cache_width,
                                            max_cache_file_bytes,
                                            max_cache_read_bytes,
                                            indices,
                                            &cache_f32,
                                            &staged_bytes,
                                            &staged_raw_bytes)) {
        return 1;
    }
    double cache_elapsed = CFAbsoluteTimeGetCurrent() - cache_started;
    if (staged_bytes != staged_cache_f32_bytes || staged_raw_bytes != raw_cache_bytes) {
        fprintf(stderr, "internal indexed MLA cache byte estimate mismatch\n");
        free(cache_f32);
        return 1;
    }

    CFAbsoluteTime value_started = CFAbsoluteTimeGetCurrent();
    float *kv_b_f32 = NULL;
    uint64_t matrix_bytes = 0;
    if (!read_mla_attention_value_source_f32(weight_path,
                                             value_source,
                                             layer_id,
                                             num_heads,
                                             qk_nope_dim,
                                             v_head_dim,
                                             mla_kv_b_cache_dir,
                                             &kv_b_f32,
                                             &matrix_bytes)) {
        free(cache_f32);
        return 1;
    }
    double value_elapsed = CFAbsoluteTimeGetCurrent() - value_started;
    if (matrix_bytes != kv_b_f32_bytes) {
        fprintf(stderr, "internal indexed MLA kv_b byte estimate mismatch\n");
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }

    CFAbsoluteTime metal_setup_started = CFAbsoluteTimeGetCurrent();
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        free(cache_f32);
        free(kv_b_f32);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "indexed batch MLA");
    if (!library) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLComputePipelineState> pipe =
        make_pipeline(device, library, @"mla_attention_indexed_batch_f32");
    if (!pipe) {
        free(cache_f32);
        free(kv_b_f32);
        return 1;
    }
    id<MTLBuffer> bQNope = [device newBufferWithBytes:q_nope_data.bytes
                                               length:q_nope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bQRope = [device newBufferWithBytes:q_rope_data.bytes
                                               length:q_rope_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bIndices = [device newBufferWithBytes:indices_data.bytes
                                                 length:indices_data.length
                                                options:MTLResourceStorageModeShared];
    id<MTLBuffer> bCache =
        [device newBufferWithBytesNoCopy:cache_f32
                                   length:(NSUInteger)staged_cache_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    cache_f32 = NULL;
    id<MTLBuffer> bKVB =
        [device newBufferWithBytesNoCopy:kv_b_f32
                                   length:(NSUInteger)kv_b_f32_bytes
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    kv_b_f32 = NULL;
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)output_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bQNope || !bQRope || !bIndices || !bCache || !bKVB || !bOut) {
        fprintf(stderr, "failed to allocate indexed batch MLA attention buffers\n");
        return 1;
    }
    if (attention_scale == 0.0f) {
        attention_scale = 1.0f / sqrtf((float)(qk_nope_dim + rope_dim));
    }
    double metal_setup_elapsed = CFAbsoluteTimeGetCurrent() - metal_setup_started;
    CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create indexed batch MLA attention command buffer\n");
        return 1;
    }
    if (!encode_mla_attention_indexed_batch_f32(cmd, pipe, bQNope, bQRope, bCache,
                                                bKVB, bIndices, bOut, context_len,
                                                index_topk, num_heads, kv_lora_dim,
                                                qk_nope_dim, rope_dim, v_head_dim,
                                                attention_scale, rope_theta,
                                                rope_interleave ? 1u : 0u,
                                                position_offset, batch_tokens)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "indexed batch MLA attention command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    double kernel_elapsed = CFAbsoluteTimeGetCurrent() - kernel_started;
    CFAbsoluteTime write_started = CFAbsoluteTimeGetCurrent();
    NSData *out_data = [NSData dataWithBytes:bOut.contents length:(NSUInteger)output_bytes];
    if (![out_data writeToFile:output_path atomically:YES]) {
        fprintf(stderr, "failed to write indexed batch MLA attention output: %s\n",
                output_path.UTF8String);
        return 1;
    }
    double write_elapsed = CFAbsoluteTimeGetCurrent() - write_started;
    double total_elapsed = CFAbsoluteTimeGetCurrent() - total_started;
    float *out = (float *)bOut.contents;
    printf("LargerLM indexed batch MLA attention\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  context length:     %u\n", context_len);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  index top-k:        %u\n", index_topk);
    printf("  num heads:          %u\n", num_heads);
    printf("  kv lora dim:        %u\n", kv_lora_dim);
    printf("  qk nope dim:        %u\n", qk_nope_dim);
    printf("  rope dim:           %u\n", rope_dim);
    printf("  v head dim:         %u\n", v_head_dim);
    printf("  value source:       %s\n",
           value_source.use_absorbed_alias ? "absorbed-alias" : "kv_b_proj");
    if (mla_kv_b_cache_dir && value_source.use_absorbed_alias) {
        printf("  kv_b cache dir:      %s\n", mla_kv_b_cache_dir.UTF8String);
    }
    printf("  scale:              %.9g\n", attention_scale);
    printf("  rope theta:         %.6f\n", rope_theta);
    printf("  rope interleave:    %s\n", rope_interleave ? "yes" : "no");
    printf("  cache read bytes:   %llu\n", (unsigned long long)raw_cache_bytes);
    printf("  staged cache bytes: %llu\n", (unsigned long long)staged_cache_f32_bytes);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing input:       %.6f\n", input_elapsed);
    printf("  timing cache read:  %.6f\n", cache_elapsed);
    printf("  timing value read:  %.6f\n", value_elapsed);
    printf("  timing metal setup: %.6f\n", metal_setup_elapsed);
    printf("  timing kernel:      %.6f\n", kernel_elapsed);
    printf("  timing write:       %.6f\n", write_elapsed);
    printf("  timing total:       %.6f\n", total_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    printf("  output f32:         %s\n", output_path.UTF8String);
    return 0;
}

static int run_attention_output(id<MTLDevice> device,
                                NSString *resident_layout_path,
                                uint64_t layer_id,
                                NSString *input_path,
                                NSString *residual_path,
                                NSData *residual_data_override,
                                NSString *projection_path,
                                NSString *output_path,
                                uint64_t max_matrix_bytes,
                                uint64_t max_runner_scratch_bytes,
                                NSData *input_data_override,
                                NSData *__strong *output_data) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    ResidentMatrixInfo o_proj = {0};
    if (!find_resident_matrix_by_suffix(resident_layout, layer_id,
                                        @".self_attn.o_proj.weight", &o_proj)) {
        return 1;
    }
    ResidentAffineInt4MatrixInfo o_affine = {0};
    ResidentMxfp4MatrixInfo o_mxfp4 = {0};
    int o_is_affine_int4 = 0;
    int o_is_mxfp4 = 0;
    uint32_t o_out_dim = 0;
    uint32_t o_in_dim = 0;
    uint64_t o_storage_bytes = 0;
    if (!parse_shared_component_matrix(resident_layout,
                                       o_proj,
                                       &o_affine,
                                       &o_mxfp4,
                                       &o_is_affine_int4,
                                       &o_is_mxfp4,
                                       &o_out_dim,
                                       &o_in_dim,
                                       &o_storage_bytes)) {
        return 1;
    }
    if (!enforce_resident_linear_limit("attention o_proj",
                                       o_proj,
                                       o_affine,
                                       o_mxfp4,
                                       o_is_affine_int4,
                                       o_is_mxfp4,
                                       max_matrix_bytes)) return 1;

    NSData *input_data = input_data_override ?: [NSData dataWithContentsOfFile:input_path];
    NSData *residual_data = residual_data_override ?: [NSData dataWithContentsOfFile:residual_path];
    if (!input_data || !residual_data) {
        fprintf(stderr, "failed to read attention output input/residual files\n");
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)o_in_dim * sizeof(float);
    NSUInteger hidden_bytes = (NSUInteger)o_out_dim * sizeof(float);
    if (input_data.length != expected_input_bytes ||
        residual_data.length != hidden_bytes) {
        fprintf(stderr,
                "attention output bytes mismatch: input got %llu expected %llu; "
                "residual got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes,
                (unsigned long long)residual_data.length,
                (unsigned long long)hidden_bytes);
        return 1;
    }
    uint64_t peak = align_up_u64(o_storage_bytes, 2 * 1024 * 1024) +
                    expected_input_bytes + 2 * (uint64_t)hidden_bytes;
    if (!enforce_scratch_limit("attention output", peak,
                               max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "attention output");
    if (!library) return 1;
    id<MTLComputePipelineState> add = make_pipeline(device, library, @"weighted_add");
    if (!add) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:hidden_bytes
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bResidual = [device newBufferWithBytes:residual_data.bytes
                                                  length:residual_data.length
                                                 options:MTLResourceStorageModeShared];
    if (!bInput || !bOut || !bResidual) {
        fprintf(stderr, "failed to allocate attention output buffers\n");
        return 1;
    }
    if (!run_resident_linear_matvec_dispatch(device, queue, library, weight_path,
                                             o_proj,
                                             o_affine,
                                             o_mxfp4,
                                             o_is_affine_int4,
                                             o_is_mxfp4,
                                             bInput,
                                             bOut)) {
        return 1;
    }
    if (projection_path) {
        NSData *projection_data = [NSData dataWithBytes:bOut.contents length:hidden_bytes];
        if (![projection_data writeToFile:projection_path atomically:YES]) {
            fprintf(stderr, "failed to write attention projection output: %s\n",
                    projection_path.UTF8String);
            return 1;
        }
    }
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create attention residual add command buffer\n");
        return 1;
    }
    if (!encode_weighted_add(cmd, add, bResidual, bOut, 1.0f, o_out_dim)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "attention residual add command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    NSData *out_data = [[NSData alloc] initWithBytes:bOut.contents length:hidden_bytes];
    if (output_data) {
        *output_data = out_data;
    }
    if (output_path) {
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write attention output: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }
    float *out = (float *)bOut.contents;
    printf("LargerLM attention output\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", o_proj.name);
    printf("  dtype:              %s\n",
           o_is_mxfp4 ? "mlx-mxfp4" : (o_is_affine_int4 ? "affine-int4" : o_proj.dtype));
    printf("  shape:              [%u,%u]\n", o_out_dim, o_in_dim);
    printf("  residual add:       yes\n");
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_attention_output_batch(id<MTLDevice> device,
                                      NSString *resident_layout_path,
                                      uint64_t layer_id,
                                      NSString *input_path,
                                      NSString *residual_path,
                                      NSString *projection_path,
                                      NSString *output_path,
                                      uint32_t batch_tokens,
                                      uint64_t max_matrix_bytes,
                                      uint64_t max_runner_scratch_bytes) {
    if (batch_tokens == 0) {
        fprintf(stderr, "--batch-tokens must be positive\n");
        return 1;
    }
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    ResidentMatrixInfo o_proj = {0};
    if (!find_resident_matrix_by_suffix(resident_layout, layer_id,
                                        @".self_attn.o_proj.weight", &o_proj)) {
        return 1;
    }
    ResidentAffineInt4MatrixInfo o_affine = {0};
    ResidentMxfp4MatrixInfo o_mxfp4 = {0};
    int o_is_affine_int4 = 0;
    int o_is_mxfp4 = 0;
    uint32_t o_out_dim = 0;
    uint32_t o_in_dim = 0;
    uint64_t o_storage_bytes = 0;
    if (!parse_shared_component_matrix(resident_layout,
                                       o_proj,
                                       &o_affine,
                                       &o_mxfp4,
                                       &o_is_affine_int4,
                                       &o_is_mxfp4,
                                       &o_out_dim,
                                       &o_in_dim,
                                       &o_storage_bytes)) {
        return 1;
    }
    if (!enforce_resident_linear_limit("attention o_proj",
                                       o_proj,
                                       o_affine,
                                       o_mxfp4,
                                       o_is_affine_int4,
                                       o_is_mxfp4,
                                       max_matrix_bytes)) return 1;

    uint64_t input_values = 0;
    uint64_t output_values = 0;
    uint64_t expected_input_bytes_u64 = 0;
    uint64_t hidden_bytes_u64 = 0;
    if (!checked_mul_u64((uint64_t)batch_tokens, (uint64_t)o_in_dim, &input_values) ||
        !checked_mul_u64(input_values, sizeof(float), &expected_input_bytes_u64) ||
        !checked_mul_u64((uint64_t)batch_tokens, (uint64_t)o_out_dim, &output_values) ||
        !checked_mul_u64(output_values, sizeof(float), &hidden_bytes_u64) ||
        expected_input_bytes_u64 > (uint64_t)SIZE_MAX ||
        hidden_bytes_u64 > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "attention output batch byte size overflow\n");
        return 1;
    }

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    NSData *residual_data = [NSData dataWithContentsOfFile:residual_path];
    if (!input_data || !residual_data) {
        fprintf(stderr, "failed to read attention output batch input/residual files\n");
        return 1;
    }
    if ((uint64_t)input_data.length != expected_input_bytes_u64 ||
        (uint64_t)residual_data.length != hidden_bytes_u64) {
        fprintf(stderr,
                "attention output batch bytes mismatch: input got %llu expected %llu; "
                "residual got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes_u64,
                (unsigned long long)residual_data.length,
                (unsigned long long)hidden_bytes_u64);
        return 1;
    }
    uint64_t peak = align_up_u64(o_storage_bytes, 2 * 1024 * 1024);
    if (!checked_add_u64(peak, expected_input_bytes_u64, &peak) ||
        !checked_add_u64(peak, hidden_bytes_u64, &peak) ||
        !checked_add_u64(peak, hidden_bytes_u64, &peak)) {
        fprintf(stderr, "attention output batch peak byte size overflow\n");
        return 1;
    }
    if (!enforce_scratch_limit("attention output batch", peak,
                               max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "attention output batch");
    if (!library) return 1;
    id<MTLComputePipelineState> add = make_pipeline(device, library, @"add_f32_batch");
    if (!add) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:(NSUInteger)expected_input_bytes_u64
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:(NSUInteger)hidden_bytes_u64
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bResidual = [device newBufferWithBytes:residual_data.bytes
                                                  length:(NSUInteger)hidden_bytes_u64
                                                 options:MTLResourceStorageModeShared];
    if (!bInput || !bOut || !bResidual) {
        fprintf(stderr, "failed to allocate attention output batch buffers\n");
        return 1;
    }

    CFAbsoluteTime backend_started = CFAbsoluteTimeGetCurrent();
    int linear_ok = 0;
    if (o_is_mxfp4) {
        linear_ok = run_resident_mxfp4_batch_linear(device, queue, library,
                                                    weight_path, o_mxfp4,
                                                    bInput, bOut, batch_tokens);
    } else if (o_is_affine_int4) {
        linear_ok = run_resident_affine_int4_batch_linear(device, queue, library,
                                                          weight_path, o_affine,
                                                          bInput, bOut,
                                                          batch_tokens);
    } else {
        linear_ok = run_resident_matrix_batch_linear(device, queue, library, weight_path,
                                                     o_proj, bInput, bOut,
                                                     batch_tokens);
    }
    if (!linear_ok) {
        return 1;
    }
    if (projection_path) {
        NSData *projection_data =
            [NSData dataWithBytes:bOut.contents length:(NSUInteger)hidden_bytes_u64];
        if (![projection_data writeToFile:projection_path atomically:YES]) {
            fprintf(stderr, "failed to write attention projection batch output: %s\n",
                    projection_path.UTF8String);
            return 1;
        }
    }
    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create attention residual batch add command buffer\n");
        return 1;
    }
    if (!encode_add_f32_batch(cmd, add, bResidual, bOut, o_out_dim, batch_tokens)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "attention residual batch add command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }
    double backend_elapsed = CFAbsoluteTimeGetCurrent() - backend_started;
    NSData *out_data =
        [[NSData alloc] initWithBytes:bOut.contents length:(NSUInteger)hidden_bytes_u64];
    if (output_path) {
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write attention output batch: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }
    float *out = (float *)bOut.contents;
    printf("LargerLM attention output batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", o_proj.name);
    printf("  dtype:              %s\n",
           o_is_mxfp4 ? "mlx-mxfp4" : (o_is_affine_int4 ? "affine-int4" : o_proj.dtype));
    printf("  shape:              [%u,%u]\n", o_out_dim, o_in_dim);
    printf("  batch tokens:       %u\n", batch_tokens);
    if (o_is_mxfp4) {
        int token_tile_ok = 1;
        uint32_t token_tile = resident_mxfp4_batch_token_tile_from_env(&token_tile_ok);
        if (!token_tile_ok) return 1;
        int group32_ok = 1;
        int group32_specialized =
            resident_mxfp4_batch_group32_specialized_from_env(o_mxfp4,
                                                              token_tile,
                                                              &group32_ok);
        if (!group32_ok) return 1;
        printf("  MXFP4 token tile:   %u\n", token_tile);
        printf("  MXFP4 group32 path: %s\n", group32_specialized ? "yes" : "no");
    }
    printf("  residual add:       yes\n");
    printf("  input bytes:        %llu\n", (unsigned long long)expected_input_bytes_u64);
    printf("  residual bytes:     %llu\n", (unsigned long long)hidden_bytes_u64);
    printf("  output bytes:       %llu\n", (unsigned long long)hidden_bytes_u64);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  timing backend:     %.6f\n", backend_elapsed);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int ensure_output_dir(NSString *output_dir) {
    if (!output_dir) return 1;
    NSError *error = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:output_dir
                                   withIntermediateDirectories:YES
                                                    attributes:nil
                                                         error:&error]) {
        fprintf(stderr, "failed to create output dir %s: %s\n",
                output_dir.UTF8String, error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

static int write_data_to_output_dir(NSString *output_dir,
                                    NSString *filename,
                                    NSData *data) {
    if (!output_dir) return 1;
    NSString *path = [output_dir stringByAppendingPathComponent:filename];
    if (![data writeToFile:path atomically:YES]) {
        fprintf(stderr, "failed to write output f32 file: %s\n", path.UTF8String);
        return 0;
    }
    return 1;
}

static int write_buffer_to_output_dir(NSString *output_dir,
                                      NSString *filename,
                                      id<MTLBuffer> buffer,
                                      NSUInteger length) {
    if (!output_dir) return 1;
    NSData *data = [NSData dataWithBytes:buffer.contents length:length];
    return write_data_to_output_dir(output_dir, filename, data);
}

static int split_f32_row_prefix_file(NSString *input_path,
                                     NSString *prefix_output_path,
                                     NSString *suffix_output_path,
                                     uint32_t batch_tokens,
                                     uint32_t row_dim,
                                     uint32_t prefix_dim,
                                     uint64_t max_runner_scratch_bytes) {
    if (batch_tokens == 0 || row_dim == 0 || prefix_dim > row_dim) {
        fprintf(stderr, "invalid split dimensions for attention KV-A\n");
        return 0;
    }
    uint64_t row_bytes = 0;
    uint64_t expected_input_bytes = 0;
    uint64_t prefix_row_bytes = 0;
    uint64_t prefix_bytes = 0;
    uint64_t suffix_row_bytes = 0;
    uint64_t suffix_bytes = 0;
    if (!checked_mul_u64((uint64_t)row_dim, sizeof(float), &row_bytes) ||
        !checked_mul_u64((uint64_t)batch_tokens, row_bytes, &expected_input_bytes) ||
        !checked_mul_u64((uint64_t)prefix_dim, sizeof(float), &prefix_row_bytes) ||
        !checked_mul_u64((uint64_t)batch_tokens, prefix_row_bytes, &prefix_bytes) ||
        !checked_mul_u64((uint64_t)(row_dim - prefix_dim), sizeof(float), &suffix_row_bytes) ||
        !checked_mul_u64((uint64_t)batch_tokens, suffix_row_bytes, &suffix_bytes) ||
        expected_input_bytes > (uint64_t)SIZE_MAX ||
        prefix_bytes > (uint64_t)SIZE_MAX ||
        suffix_bytes > (uint64_t)SIZE_MAX ||
        expected_input_bytes > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "attention KV-A split byte size overflow\n");
        return 0;
    }
    struct stat input_stat;
    if (stat(input_path.UTF8String, &input_stat) != 0) {
        fprintf(stderr, "stat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        return 0;
    }
    if (input_stat.st_size < 0 || (uint64_t)input_stat.st_size != expected_input_bytes) {
        fprintf(stderr, "attention KV-A split input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_stat.st_size,
                (unsigned long long)expected_input_bytes);
        return 0;
    }
    uint64_t peak = 0;
    if (!checked_add_u64(expected_input_bytes, prefix_bytes, &peak) ||
        !checked_add_u64(peak, suffix_bytes, &peak)) {
        fprintf(stderr, "attention KV-A split peak overflows\n");
        return 0;
    }
    if (!enforce_scratch_limit("attention KV-A split", peak,
                               max_runner_scratch_bytes)) {
        return 0;
    }

    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read attention KV-A file: %s\n", input_path.UTF8String);
        return 0;
    }
    if (input_data.length != (NSUInteger)expected_input_bytes) {
        fprintf(stderr, "attention KV-A split input changed while reading\n");
        return 0;
    }
    NSMutableData *prefix_data =
        [NSMutableData dataWithLength:(NSUInteger)prefix_bytes];
    NSMutableData *suffix_data =
        [NSMutableData dataWithLength:(NSUInteger)suffix_bytes];
    if (!prefix_data || !suffix_data) {
        fprintf(stderr, "failed to allocate attention KV-A split buffers\n");
        return 0;
    }
    const uint8_t *src = (const uint8_t *)input_data.bytes;
    uint8_t *prefix_dst = (uint8_t *)prefix_data.mutableBytes;
    uint8_t *suffix_dst = (uint8_t *)suffix_data.mutableBytes;
    for (uint32_t token = 0; token < batch_tokens; ++token) {
        const uint8_t *row = src + (uint64_t)token * row_bytes;
        memcpy(prefix_dst + (uint64_t)token * prefix_row_bytes,
               row,
               (size_t)prefix_row_bytes);
        if (suffix_row_bytes > 0) {
            memcpy(suffix_dst + (uint64_t)token * suffix_row_bytes,
                   row + prefix_row_bytes,
                   (size_t)suffix_row_bytes);
        }
    }
    if (![prefix_data writeToFile:prefix_output_path atomically:YES]) {
        fprintf(stderr, "failed to write attention KV-A lora file: %s\n",
                prefix_output_path.UTF8String);
        return 0;
    }
    if (![suffix_data writeToFile:suffix_output_path atomically:YES]) {
        fprintf(stderr, "failed to write attention KV-A rope file: %s\n",
                suffix_output_path.UTF8String);
        return 0;
    }
    return 1;
}

static int run_attention_projections_batch_staged(id<MTLDevice> device,
                                                  NSString *resident_layout_path,
                                                  uint64_t layer_id,
                                                  NSString *input_path,
                                                  NSString *output_dir,
                                                  AttentionProjectionInfo info,
                                                  uint32_t batch_tokens,
                                                  float rms_norm_eps,
                                                  uint64_t max_matrix_bytes,
                                                  uint64_t max_runner_scratch_bytes) {
    if (!ensure_output_dir(output_dir)) return 1;
    NSString *input_norm_path =
        [output_dir stringByAppendingPathComponent:@"attn_input_norm.f32"];
    NSString *q_a_path =
        [output_dir stringByAppendingPathComponent:@"attn_q_a.f32"];
    NSString *q_a_norm_path =
        [output_dir stringByAppendingPathComponent:@"attn_q_a_norm.f32"];
    NSString *q_b_path =
        [output_dir stringByAppendingPathComponent:@"attn_q_b.f32"];
    NSString *kv_a_path =
        [output_dir stringByAppendingPathComponent:@"attn_kv_a.f32"];
    NSString *kv_a_lora_path =
        [output_dir stringByAppendingPathComponent:@"kv_a_lora.f32"];
    NSString *kv_a_rope_path =
        [output_dir stringByAppendingPathComponent:@"kv_a_rope.f32"];
    NSString *kv_a_norm_path =
        [output_dir stringByAppendingPathComponent:@"attn_kv_a_norm.f32"];
    NSString *kv_b_path =
        [output_dir stringByAppendingPathComponent:@"attn_kv_b.f32"];
    NSString *linear_backend = @"custom-metal";

    if (run_resident_rmsnorm_batch(device,
                                   resident_layout_path,
                                   layer_id,
                                   @".input_layernorm.weight",
                                   input_path,
                                   input_norm_path,
                                   batch_tokens,
                                   rms_norm_eps,
                                   max_runner_scratch_bytes) != 0) {
        return 1;
    }
    if (run_resident_linear_batch(device,
                                  resident_layout_path,
                                  layer_id,
                                  @".self_attn.q_a_proj.weight",
                                  input_norm_path,
                                  q_a_path,
                                  batch_tokens,
                                  max_matrix_bytes,
                                  max_runner_scratch_bytes,
                                  linear_backend) != 0) {
        return 1;
    }
    if (run_resident_rmsnorm_batch(device,
                                   resident_layout_path,
                                   layer_id,
                                   @".self_attn.q_a_layernorm.weight",
                                   q_a_path,
                                   q_a_norm_path,
                                   batch_tokens,
                                   rms_norm_eps,
                                   max_runner_scratch_bytes) != 0) {
        return 1;
    }
    if (run_resident_linear_batch(device,
                                  resident_layout_path,
                                  layer_id,
                                  @".self_attn.q_b_proj.weight",
                                  q_a_norm_path,
                                  q_b_path,
                                  batch_tokens,
                                  max_matrix_bytes,
                                  max_runner_scratch_bytes,
                                  linear_backend) != 0) {
        return 1;
    }
    if (run_resident_linear_batch(device,
                                  resident_layout_path,
                                  layer_id,
                                  @".self_attn.kv_a_proj_with_mqa.weight",
                                  input_norm_path,
                                  kv_a_path,
                                  batch_tokens,
                                  max_matrix_bytes,
                                  max_runner_scratch_bytes,
                                  linear_backend) != 0) {
        return 1;
    }
    if (!split_f32_row_prefix_file(kv_a_path,
                                   kv_a_lora_path,
                                   kv_a_rope_path,
                                   batch_tokens,
                                   info.kv_a_out_dim,
                                   info.kv_lora_dim,
                                   max_runner_scratch_bytes)) {
        return 1;
    }
    if (run_resident_rmsnorm_batch(device,
                                   resident_layout_path,
                                   layer_id,
                                   @".self_attn.kv_a_layernorm.weight",
                                   kv_a_lora_path,
                                   kv_a_norm_path,
                                   batch_tokens,
                                   rms_norm_eps,
                                   max_runner_scratch_bytes) != 0) {
        return 1;
    }
    if (info.has_kv_b &&
        run_resident_linear_batch(device,
                                  resident_layout_path,
                                  layer_id,
                                  @".self_attn.kv_b_proj.weight",
                                  kv_a_norm_path,
                                  kv_b_path,
                                  batch_tokens,
                                  max_matrix_bytes,
                                  max_runner_scratch_bytes,
                                  linear_backend) != 0) {
        return 1;
    }

    printf("LargerLM attention projections\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  q lora dim:         %u\n", info.q_lora_dim);
    printf("  q output dim:       %u\n", info.q_out_dim);
    printf("  kv lora dim:        %u\n", info.kv_lora_dim);
    printf("  kv rope dim:        %u\n", info.kv_rope_dim);
    printf("  kv output dim:      %u\n", info.kv_out_dim);
    printf("  value source:       %s\n",
           info.has_kv_b ? "kv_b_proj" : "absorbed-alias");
    printf("  fused batch staged: yes\n");
    printf("  output dir:         %s\n", output_dir.UTF8String);
    return 0;
}

static int run_attention_projections(id<MTLDevice> device,
                                     NSString *resident_layout_path,
                                     uint64_t layer_id,
                                     NSString *input_path,
                                     NSData *input_data_override,
                                     NSString *output_dir,
                                     uint32_t batch_tokens,
                                     NSString *cache_layout_path,
                                     NSString *cache_file_path,
                                     uint64_t cache_position,
                                     int append_cache,
                                     float rms_norm_eps,
                                     uint64_t max_matrix_bytes,
                                     uint64_t max_cache_file_bytes,
                                     uint64_t max_runner_scratch_bytes,
                                     NSData *__strong *q_b_output_data) {
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;

    AttentionProjectionInfo info = {0};
    if (!parse_attention_projection_layout(resident_layout, layer_id, &info)) {
        return 1;
    }
    if (!enforce_resident_linear_limit("attention q_a",
                                       info.q_a,
                                       info.q_a_affine,
                                       info.q_a_mxfp4,
                                       info.q_a_is_affine_int4,
                                       info.q_a_is_mxfp4,
                                       max_matrix_bytes) ||
        !enforce_resident_linear_limit("attention q_b",
                                       info.q_b,
                                       info.q_b_affine,
                                       info.q_b_mxfp4,
                                       info.q_b_is_affine_int4,
                                       info.q_b_is_mxfp4,
                                       max_matrix_bytes) ||
        !enforce_resident_linear_limit("attention kv_a",
                                       info.kv_a,
                                       info.kv_a_affine,
                                       info.kv_a_mxfp4,
                                       info.kv_a_is_affine_int4,
                                       info.kv_a_is_mxfp4,
                                       max_matrix_bytes)) {
        return 1;
    }
    if (info.has_kv_b &&
        !enforce_resident_linear_limit("attention kv_b",
                                       info.kv_b,
                                       info.kv_b_affine,
                                       info.kv_b_mxfp4,
                                       info.kv_b_is_affine_int4,
                                       info.kv_b_is_mxfp4,
                                       max_matrix_bytes)) {
        return 1;
    }

    if (batch_tokens == 0) {
        fprintf(stderr, "--batch-tokens must be positive\n");
        return 1;
    }
    if (append_cache && batch_tokens != 1) {
        fprintf(stderr, "cache append is only supported with --batch-tokens 1\n");
        return 1;
    }
    uint64_t hidden_bytes_u64 = 0;
    uint64_t expected_input_bytes = 0;
    if (!checked_mul_u64((uint64_t)info.hidden_dim,
                         sizeof(float),
                         &hidden_bytes_u64) ||
        !checked_mul_u64((uint64_t)batch_tokens,
                         hidden_bytes_u64,
                         &expected_input_bytes) ||
        expected_input_bytes > (uint64_t)SIZE_MAX ||
        expected_input_bytes > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "attention projection input byte size overflow\n");
        return 1;
    }
    if (!input_data_override) {
        struct stat input_stat;
        if (stat(input_path.UTF8String, &input_stat) != 0) {
            fprintf(stderr, "stat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
            return 1;
        }
        if (input_stat.st_size < 0 || (uint64_t)input_stat.st_size != expected_input_bytes) {
            fprintf(stderr, "input bytes mismatch: got %llu expected %llu\n",
                    (unsigned long long)input_stat.st_size,
                    (unsigned long long)expected_input_bytes);
            return 1;
        }
    }
    if (batch_tokens > 1) {
        if (q_b_output_data) {
            fprintf(stderr, "attention projection q_b memory output is single-token only\n");
            return 1;
        }
        if (input_data_override) {
            fprintf(stderr, "attention projection memory input is single-token only\n");
            return 1;
        }
        return run_attention_projections_batch_staged(device,
                                                      resident_layout_path,
                                                      layer_id,
                                                      input_path,
                                                      output_dir,
                                                      info,
                                                      batch_tokens,
                                                      rms_norm_eps,
                                                      max_matrix_bytes,
                                                      max_runner_scratch_bytes);
    }

    NSData *input_data = input_data_override ?: [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    if (input_data.length != (NSUInteger)hidden_bytes_u64) {
        fprintf(stderr, "input bytes changed while reading: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)hidden_bytes_u64);
        return 1;
    }
    uint64_t peak = estimate_attention_projection_peak(info);
    if (!enforce_scratch_limit("attention projections", peak,
                               max_runner_scratch_bytes)) {
        return 1;
    }
    if (!ensure_output_dir(output_dir)) return 1;

    NSData *input_norm = run_resident_rmsnorm(device,
                                              resident_layout_path,
                                              layer_id,
                                              input_data,
                                              @".input_layernorm.weight",
                                              rms_norm_eps,
                                              max_runner_scratch_bytes);
    if (!input_norm) return 1;
    if (!write_data_to_output_dir(output_dir, @"attn_input_norm.f32", input_norm)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "attention projection");
    if (!library) return 1;

    id<MTLBuffer> bInputNorm = [device newBufferWithBytes:input_norm.bytes
                                                   length:input_norm.length
                                                  options:MTLResourceStorageModeShared];
    NSUInteger q_lora_bytes = (NSUInteger)info.q_lora_dim * sizeof(float);
    NSUInteger q_out_bytes = (NSUInteger)info.q_out_dim * sizeof(float);
    NSUInteger kv_a_bytes = (NSUInteger)info.kv_a_out_dim * sizeof(float);
    NSUInteger kv_lora_bytes = (NSUInteger)info.kv_lora_dim * sizeof(float);
    NSUInteger kv_out_bytes =
        info.has_kv_b ? (NSUInteger)info.kv_out_dim * sizeof(float) : 0;
    id<MTLBuffer> bQA = [device newBufferWithLength:q_lora_bytes
                                            options:MTLResourceStorageModeShared];
    if (!bInputNorm || !bQA) {
        fprintf(stderr, "failed to allocate attention Q buffers\n");
        return 1;
    }
    if (!run_resident_linear_matvec_dispatch(device, queue, library, weight_path,
                                             info.q_a,
                                             info.q_a_affine,
                                             info.q_a_mxfp4,
                                             info.q_a_is_affine_int4,
                                             info.q_a_is_mxfp4,
                                             bInputNorm,
                                             bQA)) {
        return 1;
    }
    if (!write_buffer_to_output_dir(output_dir, @"attn_q_a.f32", bQA,
                                    q_lora_bytes)) {
        return 1;
    }

    NSData *q_a_data = [NSData dataWithBytes:bQA.contents length:q_lora_bytes];
    NSData *q_a_norm = run_resident_rmsnorm(device,
                                            resident_layout_path,
                                            layer_id,
                                            q_a_data,
                                            @".self_attn.q_a_layernorm.weight",
                                            rms_norm_eps,
                                            max_runner_scratch_bytes);
    if (!q_a_norm) return 1;
    if (!write_data_to_output_dir(output_dir, @"attn_q_a_norm.f32", q_a_norm)) {
        return 1;
    }

    id<MTLBuffer> bQANorm = [device newBufferWithBytes:q_a_norm.bytes
                                                length:q_a_norm.length
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bQB = [device newBufferWithLength:q_out_bytes
                                            options:MTLResourceStorageModeShared];
    if (!bQANorm || !bQB) {
        fprintf(stderr, "failed to allocate attention Q output buffers\n");
        return 1;
    }
    if (!run_resident_linear_matvec_dispatch(device, queue, library, weight_path,
                                             info.q_b,
                                             info.q_b_affine,
                                             info.q_b_mxfp4,
                                             info.q_b_is_affine_int4,
                                             info.q_b_is_mxfp4,
                                             bQANorm,
                                             bQB)) {
        return 1;
    }
    if (q_b_output_data) {
        *q_b_output_data = [[NSData alloc] initWithBytes:bQB.contents length:q_out_bytes];
    }
    if (!write_buffer_to_output_dir(output_dir, @"attn_q_b.f32", bQB,
                                    q_out_bytes)) {
        return 1;
    }

    id<MTLBuffer> bKVA = [device newBufferWithLength:kv_a_bytes
                                             options:MTLResourceStorageModeShared];
    if (!bKVA) {
        fprintf(stderr, "failed to allocate attention KV-A buffer\n");
        return 1;
    }
    if (!run_resident_linear_matvec_dispatch(device, queue, library, weight_path,
                                             info.kv_a,
                                             info.kv_a_affine,
                                             info.kv_a_mxfp4,
                                             info.kv_a_is_affine_int4,
                                             info.kv_a_is_mxfp4,
                                             bInputNorm,
                                             bKVA)) {
        return 1;
    }
    if (!write_buffer_to_output_dir(output_dir, @"attn_kv_a.f32", bKVA,
                                    kv_a_bytes)) {
        return 1;
    }
    if (append_cache) {
        if (!append_kv_a_to_decode_cache(cache_layout_path,
                                         cache_file_path,
                                         layer_id,
                                         cache_position,
                                         info,
                                         bKVA,
                                         max_cache_file_bytes)) {
            return 1;
        }
    }

    NSData *kv_a_prefix = [NSData dataWithBytes:bKVA.contents length:kv_lora_bytes];
    NSData *kv_a_norm = run_resident_rmsnorm(device,
                                             resident_layout_path,
                                             layer_id,
                                             kv_a_prefix,
                                             @".self_attn.kv_a_layernorm.weight",
                                             rms_norm_eps,
                                             max_runner_scratch_bytes);
    if (!kv_a_norm) return 1;
    if (!write_data_to_output_dir(output_dir, @"attn_kv_a_norm.f32", kv_a_norm)) {
        return 1;
    }

    id<MTLBuffer> bKVB = nil;
    if (info.has_kv_b) {
        id<MTLBuffer> bKVANorm = [device newBufferWithBytes:kv_a_norm.bytes
                                                     length:kv_a_norm.length
                                                    options:MTLResourceStorageModeShared];
        bKVB = [device newBufferWithLength:kv_out_bytes
                                   options:MTLResourceStorageModeShared];
        if (!bKVANorm || !bKVB) {
            fprintf(stderr, "failed to allocate attention KV-B buffers\n");
            return 1;
        }
        if (!run_resident_linear_matvec_dispatch(device, queue, library, weight_path,
                                                 info.kv_b,
                                                 info.kv_b_affine,
                                                 info.kv_b_mxfp4,
                                                 info.kv_b_is_affine_int4,
                                                 info.kv_b_is_mxfp4,
                                                 bKVANorm,
                                                 bKVB)) {
            return 1;
        }
        if (!write_buffer_to_output_dir(output_dir, @"attn_kv_b.f32", bKVB,
                                        kv_out_bytes)) {
            return 1;
        }
    }

    float *q_b = (float *)bQB.contents;
    printf("LargerLM attention projections\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  q lora dim:         %u\n", info.q_lora_dim);
    printf("  q output dim:       %u\n", info.q_out_dim);
    printf("  kv lora dim:        %u\n", info.kv_lora_dim);
    printf("  kv rope dim:        %u\n", info.kv_rope_dim);
    printf("  kv output dim:      %u\n", info.kv_out_dim);
    printf("  value source:       %s\n",
           info.has_kv_b ? "kv_b_proj" : "absorbed-alias");
    printf("  max matrix alloc:   %llu\n",
           (unsigned long long)info.max_matrix_alloc_bytes);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  RMSNorm eps:        %.9g\n", rms_norm_eps);
    printf("  q_b[0]:             %.6f\n", q_b[0]);
    if (info.has_kv_b) {
        float *kv_b = (float *)bKVB.contents;
        printf("  kv_b[0]:            %.6f\n", kv_b[0]);
    } else {
        printf("  kv_b skipped:       yes\n");
    }
    if (output_dir) {
        printf("  output dir:         %s\n", output_dir.UTF8String);
    }
    if (append_cache) {
        printf("  cache append:       yes\n");
        printf("  cache position:     %llu\n", (unsigned long long)cache_position);
        printf("  cache file:         %s\n", cache_file_path.UTF8String);
    } else {
        printf("  cache append:       no\n");
    }
    return 0;
}

static float router_score(float logit, NSString *mode) {
    if ([mode isEqualToString:@"raw"]) return logit;
    if ([mode isEqualToString:@"softmax"]) return logit;
    // GLM MoE DSA configs use sigmoid router scores with normalized top-k.
    return 1.0f / (1.0f + expf(-logit));
}

static int topk_scores(const float *logits,
                       uint32_t n,
                       uint32_t k,
                       NSString *mode,
                       const float *selection_bias,
                       RouterOptions options,
                       uint32_t *indices,
                       float *weights) {
    if (!logits || !indices || !weights || n == 0 || k == 0 || k > n) return 0;
    float *scores = calloc(n, sizeof(float));
    float *choice_scores = calloc(n, sizeof(float));
    uint8_t *allowed = calloc(n, sizeof(uint8_t));
    if (!scores || !choice_scores || !allowed) {
        free(scores);
        free(choice_scores);
        free(allowed);
        return 0;
    }
    if ([mode isEqualToString:@"softmax"]) {
        float maxv = logits[0];
        for (uint32_t i = 1; i < n; i++) if (logits[i] > maxv) maxv = logits[i];
        for (uint32_t i = 0; i < n; i++) scores[i] = expf(logits[i] - maxv);
    } else {
        for (uint32_t i = 0; i < n; i++) scores[i] = router_score(logits[i], mode);
    }
    for (uint32_t i = 0; i < n; i++) {
        choice_scores[i] = scores[i] + (selection_bias ? selection_bias[i] : 0.0f);
        allowed[i] = 1;
    }

    uint32_t n_group = options.n_group ? options.n_group : 1;
    uint32_t topk_group = options.topk_group ? options.topk_group : n_group;
    if (n_group > 1) {
        if (n % n_group != 0 || topk_group == 0 || topk_group > n_group) {
            fprintf(stderr, "invalid router grouping: n=%u n_group=%u topk_group=%u\n",
                    n, n_group, topk_group);
            free(scores);
            free(choice_scores);
            free(allowed);
            return 0;
        }
        uint32_t per_group = n / n_group;
        float *group_scores = calloc(n_group, sizeof(float));
        uint8_t *group_used = calloc(n_group, sizeof(uint8_t));
        if (!group_scores || !group_used) {
            free(group_scores);
            free(group_used);
            free(scores);
            free(choice_scores);
            free(allowed);
            return 0;
        }
        for (uint32_t g = 0; g < n_group; g++) {
            float best1 = -INFINITY;
            float best2 = -INFINITY;
            for (uint32_t i = 0; i < per_group; i++) {
                float v = choice_scores[g * per_group + i];
                if (v > best1) {
                    best2 = best1;
                    best1 = v;
                } else if (v > best2) {
                    best2 = v;
                }
            }
            group_scores[g] = best1 + best2;
        }
        memset(allowed, 0, n);
        for (uint32_t out = 0; out < topk_group; out++) {
            uint32_t best = 0;
            float best_score = -INFINITY;
            for (uint32_t g = 0; g < n_group; g++) {
                if (!group_used[g] && group_scores[g] > best_score) {
                    best = g;
                    best_score = group_scores[g];
                }
            }
            group_used[best] = 1;
            for (uint32_t i = 0; i < per_group; i++) {
                allowed[best * per_group + i] = 1;
            }
        }
        free(group_scores);
        free(group_used);
    }

    uint8_t *used = calloc(n, sizeof(uint8_t));
    if (!used) {
        free(scores);
        free(choice_scores);
        free(allowed);
        return 0;
    }
    for (uint32_t out = 0; out < k; out++) {
        uint32_t best = 0;
        float best_score = -INFINITY;
        for (uint32_t i = 0; i < n; i++) {
            if (allowed[i] && !used[i] && choice_scores[i] > best_score) {
                best = i;
                best_score = choice_scores[i];
            }
        }
        used[best] = 1;
        indices[out] = best;
        weights[out] = scores[best];
    }
    float sum = 0.0f;
    for (uint32_t i = 0; i < k; i++) sum += weights[i];
    if (options.norm_topk_prob && sum != 0.0f) {
        for (uint32_t i = 0; i < k; i++) weights[i] /= sum;
    }
    float scale = options.routed_scaling_factor;
    for (uint32_t i = 0; i < k; i++) weights[i] *= scale;
    free(used);
    free(allowed);
    free(choice_scores);
    free(scores);
    return 1;
}

static int write_router_json(NSString *path,
                             uint32_t *indices,
                             float *weights,
                             float *logits,
                             uint32_t k,
                             uint32_t n,
                             NSString *mode,
                             RouterOptions options,
                             int used_correction_bias) {
    NSMutableArray *idx = [NSMutableArray arrayWithCapacity:k];
    NSMutableArray *w = [NSMutableArray arrayWithCapacity:k];
    for (uint32_t i = 0; i < k; i++) {
        [idx addObject:@(indices[i])];
        [w addObject:@(weights[i])];
    }
    NSMutableArray *logit_values = [NSMutableArray arrayWithCapacity:n];
    for (uint32_t i = 0; i < n; i++) {
        [logit_values addObject:@(logits[i])];
    }
    NSDictionary *payload = @{
        @"router_score": mode,
        @"top_k": @(k),
        @"norm_topk_prob": @(options.norm_topk_prob ? YES : NO),
        @"routed_scaling_factor": @(options.routed_scaling_factor),
        @"n_group": @(options.n_group),
        @"topk_group": @(options.topk_group),
        @"used_correction_bias": @(used_correction_bias ? YES : NO),
        @"experts": idx,
        @"weights": w,
        @"logits": logit_values,
    };
    NSError *error = nil;
    NSData *json = [NSJSONSerialization dataWithJSONObject:payload
                                                   options:NSJSONWritingPrettyPrinted
                                                     error:&error];
    if (!json) {
        fprintf(stderr, "failed to serialize router JSON: %s\n",
                error.localizedDescription.UTF8String);
        return 0;
    }
    return [json writeToFile:path atomically:YES] ? 1 : 0;
}

static int load_moe_batch_routes(NSString *path,
                                 uint32_t batch_tokens,
                                 int max_k,
                                 uint64_t num_experts,
                                 MoEBatchRoute **out_routes) {
    if (!path || !out_routes || batch_tokens == 0 || max_k <= 0 || max_k > 64) {
        return 0;
    }
    NSData *data = [NSData dataWithContentsOfFile:path];
    if (!data) {
        fprintf(stderr, "failed to read MoE batch routes JSON: %s\n", path.UTF8String);
        return 0;
    }
    NSError *error = nil;
    id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
    if (error || ![obj isKindOfClass:[NSDictionary class]]) {
        fprintf(stderr, "failed to parse MoE batch routes JSON: %s\n",
                error.localizedDescription.UTF8String);
        return 0;
    }
    NSDictionary *payload = (NSDictionary *)obj;
    id payload_batch = payload[@"batch_tokens"];
    if (payload_batch) {
        uint64_t parsed_batch = 0;
        if (!read_json_u64_number(payload_batch,
                                  "routes batch_tokens",
                                  1,
                                  &parsed_batch)) {
            return 0;
        }
        if (parsed_batch != batch_tokens) {
            fprintf(stderr, "routes batch_tokens %llu does not match --batch-tokens %u\n",
                    (unsigned long long)parsed_batch, batch_tokens);
            return 0;
        }
    }
    NSArray *routes = payload[@"routes"];
    if (![routes isKindOfClass:[NSArray class]] || routes.count != batch_tokens) {
        fprintf(stderr, "routes JSON must contain exactly %u routes\n", batch_tokens);
        return 0;
    }
    MoEBatchRoute *items = calloc((size_t)batch_tokens, sizeof(MoEBatchRoute));
    if (!items) {
        fprintf(stderr, "failed to allocate MoE batch routes\n");
        return 0;
    }
    for (NSUInteger token = 0; token < routes.count; token++) {
        id route_obj = routes[token];
        if (![route_obj isKindOfClass:[NSDictionary class]]) {
            fprintf(stderr, "route %lu must be an object\n", (unsigned long)token);
            free(items);
            return 0;
        }
        NSDictionary *route = (NSDictionary *)route_obj;
        NSArray *experts = route[@"experts"];
        NSArray *weights = route[@"weights"];
        if (![experts isKindOfClass:[NSArray class]] ||
            ![weights isKindOfClass:[NSArray class]] ||
            experts.count == 0 ||
            experts.count != weights.count ||
            experts.count > (NSUInteger)max_k) {
            fprintf(stderr, "route %lu has invalid experts/weights\n", (unsigned long)token);
            free(items);
            return 0;
        }
        items[token].count = (int)experts.count;
        for (NSUInteger i = 0; i < experts.count; i++) {
            id expert_obj = experts[i];
            id weight_obj = weights[i];
            uint64_t expert = 0;
            float weight = 0.0f;
            if (!read_json_u64_number(expert_obj, "route expert", 0, &expert) ||
                !read_json_f32_number(weight_obj, "route weight", &weight)) {
                free(items);
                return 0;
            }
            if (expert >= num_experts) {
                fprintf(stderr,
                        "route %lu expert %llu out of range for %llu compact experts\n",
                        (unsigned long)token,
                        (unsigned long long)expert,
                        (unsigned long long)num_experts);
                free(items);
                return 0;
            }
            for (NSUInteger prev = 0; prev < i; prev++) {
                if (items[token].experts[prev] == expert) {
                    fprintf(stderr,
                            "route %lu contains duplicate expert %llu\n",
                            (unsigned long)token,
                            (unsigned long long)expert);
                    free(items);
                    return 0;
                }
            }
            items[token].experts[i] = expert;
            items[token].weights[i] = weight;
        }
    }
    *out_routes = items;
    return 1;
}

static uint32_t read_u32_le(const uint8_t *p) {
    return ((uint32_t)p[0]) |
           ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static float read_f32_le(const uint8_t *p) {
    uint32_t bits = read_u32_le(p);
    float value = 0.0f;
    memcpy(&value, &bits, sizeof(float));
    return value;
}

static int append_moe_batch_assignment(MoEBatchAssignment *assignments,
                                       uint64_t assignment_capacity,
                                       uint64_t *assignment_count,
                                       uint8_t *token_counts,
                                       uint32_t batch_tokens,
                                       int max_k,
                                       uint64_t num_experts,
                                       uint32_t token,
                                       uint64_t expert,
                                       float weight,
                                       int *assignments_sorted) {
    if (!isfinite(weight)) {
        fprintf(stderr, "static capacity route weight must be finite\n");
        return 0;
    }
    if (token >= batch_tokens) {
        fprintf(stderr, "static capacity route token %u out of range for %u tokens\n",
                token, batch_tokens);
        return 0;
    }
    if (expert >= num_experts) {
        fprintf(stderr,
                "static capacity route expert %llu out of range for %llu compact experts\n",
                (unsigned long long)expert,
                (unsigned long long)num_experts);
        return 0;
    }
    if (*assignment_count >= assignment_capacity) {
        fprintf(stderr, "static capacity assignments exceed header capacity\n");
        return 0;
    }
    if (token_counts[token] >= max_k) {
        fprintf(stderr, "static capacity route token %u exceeds --max-k=%d\n",
                token, max_k);
        return 0;
    }
    if (*assignment_count > 0) {
        const MoEBatchAssignment *previous = &assignments[*assignment_count - 1];
        if (previous->expert > expert ||
            (previous->expert == expert && previous->token > token)) {
            *assignments_sorted = 0;
        }
    }
    assignments[*assignment_count].expert = expert;
    assignments[*assignment_count].token = token;
    assignments[*assignment_count].weight = weight;
    (*assignment_count)++;
    token_counts[token]++;
    return 1;
}

static int validate_moe_assignment_pairs(const MoEBatchAssignment *assignments,
                                         uint64_t assignment_count) {
    if (!assignments || assignment_count == 0) {
        fprintf(stderr, "MoE batch assignments are empty\n");
        return 0;
    }
    if (assignment_count > (uint64_t)(SIZE_MAX / sizeof(MoEBatchAssignment))) {
        fprintf(stderr, "MoE batch assignment table is too large\n");
        return 0;
    }
    for (uint64_t i = 0; i < assignment_count; i++) {
        if (!isfinite(assignments[i].weight)) {
            fprintf(stderr, "MoE batch route weight must be finite\n");
            return 0;
        }
    }
    MoEBatchAssignment *copy =
        malloc((size_t)assignment_count * sizeof(MoEBatchAssignment));
    if (!copy) {
        fprintf(stderr, "failed to allocate MoE assignment validation table\n");
        return 0;
    }
    memcpy(copy,
           assignments,
           (size_t)assignment_count * sizeof(MoEBatchAssignment));
    qsort(copy,
          (size_t)assignment_count,
          sizeof(MoEBatchAssignment),
          compare_moe_batch_assignments);
    for (uint64_t i = 1; i < assignment_count; i++) {
        if (copy[i - 1].expert == copy[i].expert &&
            copy[i - 1].token == copy[i].token) {
            fprintf(stderr,
                    "duplicate MoE batch assignment for token %u expert %llu\n",
                    copy[i].token,
                    (unsigned long long)copy[i].expert);
            free(copy);
            return 0;
        }
    }
    free(copy);
    return 1;
}

static int load_moe_batch_assignments_bin(NSString *path,
                                          uint32_t batch_tokens,
                                          int max_k,
                                          uint64_t num_experts,
                                          uint64_t max_assignment_bytes,
                                          MoEBatchAssignment **out_assignments,
                                          uint64_t *out_assignment_count,
                                          int *out_assignments_sorted) {
    if (!path || !out_assignments || !out_assignment_count ||
        batch_tokens == 0 || max_k <= 0 || max_k > 64) {
        return 0;
    }
    *out_assignments = NULL;
    *out_assignment_count = 0;
    if (out_assignments_sorted) *out_assignments_sorted = 0;
    NSData *data = [NSData dataWithContentsOfFile:path];
    if (!data) {
        fprintf(stderr, "failed to read MoE batch routes binary: %s\n", path.UTF8String);
        return 0;
    }
    const uint8_t *bytes = (const uint8_t *)data.bytes;
    NSUInteger length = data.length;
    const NSUInteger header_bytes = 40;
    if (length < header_bytes || memcmp(bytes, "LLMSCAP1", 8) != 0) {
        fprintf(stderr, "invalid static capacity route binary header: %s\n", path.UTF8String);
        return 0;
    }
    uint32_t version = read_u32_le(bytes + 8);
    uint32_t payload_batch = read_u32_le(bytes + 12);
    uint32_t expert_count = read_u32_le(bytes + 16);
    uint32_t capacity = read_u32_le(bytes + 20);
    uint32_t total_assignments = read_u32_le(bytes + 24);
    uint32_t used_slots = read_u32_le(bytes + 28);
    uint32_t overflow_records = read_u32_le(bytes + 32);
    if (version != 1 ||
        payload_batch != batch_tokens ||
        expert_count == 0 ||
        capacity == 0 ||
        expert_count > UINT32_MAX / capacity) {
        fprintf(stderr, "invalid static capacity route metadata in %s\n", path.UTF8String);
        return 0;
    }
    uint64_t slot_records = (uint64_t)expert_count * (uint64_t)capacity;
    if (total_assignments == 0 ||
        (uint64_t)total_assignments > (uint64_t)batch_tokens * (uint64_t)max_k ||
        (uint64_t)total_assignments > (uint64_t)(SIZE_MAX / sizeof(MoEBatchAssignment))) {
        fprintf(stderr, "invalid static capacity assignment count %u\n",
                total_assignments);
        return 0;
    }
    uint64_t assignment_bytes =
        (uint64_t)total_assignments * (uint64_t)sizeof(MoEBatchAssignment);
    if (max_assignment_bytes > 0 && assignment_bytes > max_assignment_bytes) {
        fprintf(stderr,
                "static capacity assignment table %llu bytes exceeds configured limit %llu\n",
                (unsigned long long)assignment_bytes,
                (unsigned long long)max_assignment_bytes);
        return 0;
    }
    uint64_t expected = (uint64_t)header_bytes +
                        (uint64_t)expert_count * 4ull +
                        slot_records * 12ull +
                        (uint64_t)overflow_records * 16ull;
    if ((uint64_t)length != expected) {
        fprintf(stderr,
                "static capacity route binary size %lu does not match expected %llu\n",
                (unsigned long)length,
                (unsigned long long)expected);
        return 0;
    }
    MoEBatchAssignment *assignments =
        calloc((size_t)total_assignments, sizeof(MoEBatchAssignment));
    if (!assignments) {
        fprintf(stderr, "failed to allocate static capacity assignments\n");
        return 0;
    }
    uint8_t *token_counts = calloc((size_t)batch_tokens, sizeof(uint8_t));
    if (!token_counts) {
        fprintf(stderr, "failed to allocate static capacity token counts\n");
        free(assignments);
        return 0;
    }
    const uint8_t *cursor = bytes + header_bytes;
    uint32_t *experts = calloc((size_t)expert_count, sizeof(uint32_t));
    if (!experts) {
        fprintf(stderr, "failed to allocate static capacity expert table\n");
        free(token_counts);
        free(assignments);
        return 0;
    }
    for (uint32_t i = 0; i < expert_count; i++) {
        uint32_t expert = read_u32_le(cursor);
        if ((uint64_t)expert >= num_experts) {
            fprintf(stderr,
                    "static capacity expert %u out of range for %llu compact experts\n",
                    expert,
                    (unsigned long long)num_experts);
            free(experts);
            free(token_counts);
            free(assignments);
            return 0;
        }
        experts[i] = expert;
        cursor += 4;
    }
    uint32_t active_slots = 0;
    uint64_t assignment_cursor = 0;
    int assignments_sorted = 1;
    for (uint32_t expert_index = 0; expert_index < expert_count; expert_index++) {
        uint32_t expert = experts[expert_index];
        for (uint32_t slot = 0; slot < capacity; slot++) {
            uint32_t token = read_u32_le(cursor);
            float weight = read_f32_le(cursor + 4);
            uint32_t active = read_u32_le(cursor + 8);
            cursor += 12;
            if (active) {
                if (!append_moe_batch_assignment(assignments,
                                                 total_assignments,
                                                 &assignment_cursor,
                                                 token_counts,
                                                 batch_tokens,
                                                 max_k,
                                                 num_experts,
                                                 token,
                                                 expert,
                                                 weight,
                                                 &assignments_sorted)) {
                    free(experts);
                    free(token_counts);
                    free(assignments);
                    return 0;
                }
                active_slots++;
            } else if (token != 0xffffffffu) {
                fprintf(stderr, "inactive static capacity slot has non-sentinel token\n");
                free(experts);
                free(token_counts);
                free(assignments);
                return 0;
            }
        }
    }
    if (active_slots != used_slots) {
        fprintf(stderr, "static capacity active slots %u do not match header %u\n",
                active_slots, used_slots);
        free(experts);
        free(token_counts);
        free(assignments);
        return 0;
    }
    for (uint32_t i = 0; i < overflow_records; i++) {
        uint32_t expert = read_u32_le(cursor);
        uint32_t overflow_index = read_u32_le(cursor + 4);
        uint32_t token = read_u32_le(cursor + 8);
        float weight = read_f32_le(cursor + 12);
        cursor += 16;
        (void)overflow_index;
        if (!append_moe_batch_assignment(assignments,
                                         total_assignments,
                                         &assignment_cursor,
                                         token_counts,
                                         batch_tokens,
                                         max_k,
                                         num_experts,
                                         token,
                                         expert,
                                         weight,
                                         &assignments_sorted)) {
            free(experts);
            free(token_counts);
            free(assignments);
            return 0;
        }
    }
    if ((uint64_t)active_slots + (uint64_t)overflow_records != total_assignments ||
        assignment_cursor != total_assignments) {
        fprintf(stderr,
                "static capacity assignments %u+%u do not match header %u\n",
                active_slots,
                overflow_records,
                total_assignments);
        free(experts);
        free(token_counts);
        free(assignments);
        return 0;
    }
    for (uint32_t token = 0; token < batch_tokens; token++) {
        if (token_counts[token] == 0) {
            fprintf(stderr, "static capacity route token %u has no assignments\n", token);
            free(experts);
            free(token_counts);
            free(assignments);
            return 0;
        }
    }
    if (!validate_moe_assignment_pairs(assignments, assignment_cursor)) {
        free(experts);
        free(token_counts);
        free(assignments);
        return 0;
    }
    free(experts);
    free(token_counts);
    *out_assignments = assignments;
    *out_assignment_count = assignment_cursor;
    if (out_assignments_sorted) *out_assignments_sorted = assignments_sorted;
    return 1;
}

static void apply_router_layout_metadata(NSDictionary *resident_layout,
                                         RouterOptions *options) {
    NSDictionary *router_meta = resident_layout[@"router"];
    if (![router_meta isKindOfClass:[NSDictionary class]]) return;
    if (!options->routed_scaling_factor_set) {
        NSNumber *scale = router_meta[@"routed_scaling_factor"];
        if (scale) options->routed_scaling_factor = scale.floatValue;
    }
    if (!options->norm_topk_prob_set) {
        NSNumber *norm = router_meta[@"norm_topk_prob"];
        if (norm) options->norm_topk_prob = norm.boolValue ? 1 : 0;
    }
    if (!options->n_group_set) {
        NSNumber *n_group = router_meta[@"n_group"];
        if (n_group) options->n_group = n_group.unsignedIntValue;
    }
    if (!options->topk_group_set) {
        NSNumber *topk_group = router_meta[@"topk_group"];
        if (topk_group) options->topk_group = topk_group.unsignedIntValue;
    }
}

static void finalize_router_options(RouterOptions *options) {
    if (!options->routed_scaling_factor_set && options->routed_scaling_factor == 0.0f) {
        options->routed_scaling_factor = 1.0f;
    }
    if (!options->norm_topk_prob_set) {
        options->norm_topk_prob = 1;
    }
    if (!options->n_group) options->n_group = 1;
    if (!options->topk_group) options->topk_group = options->n_group;
}

static int encode_expert_forward_to(id<MTLCommandBuffer> cmd,
                                    id<MTLComputePipelineState> dequant,
                                    id<MTLComputePipelineState> swiglu,
                                    id<MTLBuffer> expert_data,
                                    ExpertLayoutInfo info,
                                    id<MTLBuffer> input,
                                    id<MTLBuffer> gate,
                                    id<MTLBuffer> up,
                                    id<MTLBuffer> act,
                                    id<MTLBuffer> out) {
    if (info.is_mxfp4) {
        if (!encode_mxfp4_matvec(cmd, dequant, expert_data,
                                 info.gate_w.offset, info.gate_s.offset,
                                 input, gate, info.intermediate_dim, info.hidden_dim,
                                 info.group_size)) {
            return 0;
        }
        if (!encode_mxfp4_matvec(cmd, dequant, expert_data,
                                 info.up_w.offset, info.up_s.offset,
                                 input, up, info.intermediate_dim, info.hidden_dim,
                                 info.group_size)) {
            return 0;
        }
        if (!encode_swiglu(cmd, swiglu, gate, up, act, info.intermediate_dim)) {
            return 0;
        }
        if (!encode_mxfp4_matvec(cmd, dequant, expert_data,
                                 info.down_w.offset, info.down_s.offset,
                                 act, out, info.hidden_dim, info.intermediate_dim,
                                 info.group_size)) {
            return 0;
        }
        return 1;
    }
    uint32_t gate_meta_dtype = 0;
    uint32_t up_meta_dtype = 0;
    uint32_t down_meta_dtype = 0;
    if (!affine_meta_dtype_mode(info.gate_s.dtype, info.gate_b.dtype,
                                &gate_meta_dtype) ||
        !affine_meta_dtype_mode(info.up_s.dtype, info.up_b.dtype,
                                &up_meta_dtype) ||
        !affine_meta_dtype_mode(info.down_s.dtype, info.down_b.dtype,
                                &down_meta_dtype)) {
        return 0;
    }
    if (!encode_dequant4(cmd, dequant, expert_data,
                         info.gate_w.offset, info.gate_s.offset, info.gate_b.offset,
                         input, gate, info.intermediate_dim, info.hidden_dim,
                         info.group_size, gate_meta_dtype)) {
        return 0;
    }
    if (!encode_dequant4(cmd, dequant, expert_data,
                         info.up_w.offset, info.up_s.offset, info.up_b.offset,
                         input, up, info.intermediate_dim, info.hidden_dim,
                         info.group_size, up_meta_dtype)) {
        return 0;
    }
    if (!encode_swiglu(cmd, swiglu, gate, up, act, info.intermediate_dim)) {
        return 0;
    }
    if (!encode_dequant4(cmd, dequant, expert_data,
                         info.down_w.offset, info.down_s.offset, info.down_b.offset,
                         act, out, info.hidden_dim, info.intermediate_dim,
                         info.group_size, down_meta_dtype)) {
        return 0;
    }
    return 1;
}

static int expert_layout_with_base_offset(ExpertLayoutInfo info,
                                          uint64_t base_offset,
                                          ExpertLayoutInfo *out) {
    if (!out) return 0;
    if (base_offset > (uint64_t)SIZE_MAX) return 0;
    *out = info;
    ComponentInfo *components[] = {
        &out->gate_w, &out->gate_s, &out->gate_b,
        &out->up_w, &out->up_s, &out->up_b,
        &out->down_w, &out->down_s, &out->down_b,
    };
    for (size_t i = 0; i < sizeof(components) / sizeof(components[0]); i++) {
        uint64_t shifted = 0;
        if (!checked_add_u64((uint64_t)components[i]->offset,
                             base_offset,
                             &shifted) ||
            shifted > (uint64_t)SIZE_MAX) {
            return 0;
        }
        components[i]->offset = (NSUInteger)shifted;
    }
    return 1;
}

static int encode_expert_forward_batch_to(id<MTLCommandBuffer> cmd,
                                          id<MTLComputePipelineState> dequant,
                                          id<MTLComputePipelineState> swiglu,
                                          id<MTLComputePipelineState> mxfp4_swiglu,
                                          id<MTLBuffer> expert_data,
                                          ExpertLayoutInfo info,
                                          id<MTLBuffer> input,
                                          id<MTLBuffer> gate,
                                          id<MTLBuffer> up,
                                          id<MTLBuffer> act,
                                          id<MTLBuffer> out,
                                          uint32_t batch) {
    if (info.is_mxfp4) {
        (void)swiglu;
        (void)gate;
        (void)up;
        if (!mxfp4_swiglu) {
            fprintf(stderr, "missing MXFP4 fused SwiGLU pipeline\n");
            return 0;
        }
        if (!encode_mxfp4_swiglu_batch(cmd, mxfp4_swiglu, expert_data,
                                       info.gate_w.offset, info.gate_s.offset,
                                       expert_data,
                                       info.up_w.offset, info.up_s.offset,
                                       input, act, info.intermediate_dim,
                                       info.hidden_dim, info.group_size, batch, 0u)) {
            return 0;
        }
        if (!encode_mxfp4_matvec_batch(cmd, dequant, expert_data,
                                       info.down_w.offset, info.down_s.offset,
                                       act, out, info.hidden_dim, info.intermediate_dim,
                                       info.group_size, batch)) {
            return 0;
        }
        return 1;
    }
    uint32_t gate_meta_dtype = 0;
    uint32_t up_meta_dtype = 0;
    uint32_t down_meta_dtype = 0;
    if (!affine_meta_dtype_mode(info.gate_s.dtype, info.gate_b.dtype,
                                &gate_meta_dtype) ||
        !affine_meta_dtype_mode(info.up_s.dtype, info.up_b.dtype,
                                &up_meta_dtype) ||
        !affine_meta_dtype_mode(info.down_s.dtype, info.down_b.dtype,
                                &down_meta_dtype)) {
        return 0;
    }
    if (!encode_dequant4_batch(cmd, dequant, expert_data,
                               info.gate_w.offset, info.gate_s.offset, info.gate_b.offset,
                               input, gate, info.intermediate_dim, info.hidden_dim,
                               info.group_size, batch, gate_meta_dtype)) {
        return 0;
    }
    if (!encode_dequant4_batch(cmd, dequant, expert_data,
                               info.up_w.offset, info.up_s.offset, info.up_b.offset,
                               input, up, info.intermediate_dim, info.hidden_dim,
                               info.group_size, batch, up_meta_dtype)) {
        return 0;
    }
    if (!encode_swiglu_batch(cmd, swiglu, gate, up, act,
                             info.intermediate_dim, batch)) {
        return 0;
    }
    if (!encode_dequant4_batch(cmd, dequant, expert_data,
                               info.down_w.offset, info.down_s.offset, info.down_b.offset,
                               act, out, info.hidden_dim, info.intermediate_dim,
                               info.group_size, batch, down_meta_dtype)) {
        return 0;
    }
    return 1;
}

static int encode_mxfp4_expert_forward_weighted_batch_to(
    id<MTLCommandBuffer> cmd,
    id<MTLComputePipelineState> mxfp4_swiglu,
    id<MTLComputePipelineState> mxfp4_down_add,
    id<MTLBuffer> expert_data,
    ExpertLayoutInfo info,
    id<MTLBuffer> input,
    id<MTLBuffer> act,
    id<MTLBuffer> accum,
    id<MTLBuffer> weights,
    uint32_t batch,
    uint32_t token_tile,
    uint32_t activation_mode) {
    if (!mxfp4_swiglu || !mxfp4_down_add) {
        fprintf(stderr, "missing MXFP4 fused expert pipelines\n");
        return 0;
    }
    if (token_tile > 1u) {
        if (!encode_mxfp4_swiglu_batch_token_tile(cmd, mxfp4_swiglu, expert_data,
                                                  info.gate_w.offset,
                                                  info.gate_s.offset,
                                                  expert_data,
                                                  info.up_w.offset,
                                                  info.up_s.offset,
                                                  input, act,
                                                  info.intermediate_dim,
                                                  info.hidden_dim,
                                                  info.group_size,
                                                  batch,
                                                  token_tile,
                                                  activation_mode)) {
            return 0;
        }
        if (!encode_mxfp4_matvec_weighted_add_batch_token_tile(
                cmd, mxfp4_down_add, expert_data,
                info.down_w.offset, info.down_s.offset,
                act, accum, weights,
                info.hidden_dim, info.intermediate_dim,
                info.group_size, batch, token_tile)) {
            return 0;
        }
    } else {
        if (!encode_mxfp4_swiglu_batch(cmd, mxfp4_swiglu, expert_data,
                                       info.gate_w.offset, info.gate_s.offset,
                                       expert_data,
                                       info.up_w.offset, info.up_s.offset,
                                       input, act, info.intermediate_dim,
                                       info.hidden_dim, info.group_size, batch,
                                       activation_mode)) {
            return 0;
        }
        if (!encode_mxfp4_matvec_weighted_add_batch(cmd, mxfp4_down_add, expert_data,
                                                    info.down_w.offset,
                                                    info.down_s.offset,
                                                    act, accum, weights,
                                                    info.hidden_dim,
                                                    info.intermediate_dim,
                                                    info.group_size, batch)) {
            return 0;
        }
    }
    return 1;
}

typedef struct {
    double rmsnorm_elapsed_seconds;
    double router_elapsed_seconds;
    double moe_elapsed_seconds;
    double moe_setup_elapsed_seconds;
    double moe_clear_elapsed_seconds;
    double expert_read_elapsed_seconds;
    double expert_kernel_elapsed_seconds;
    double shared_elapsed_seconds;
    double residual_elapsed_seconds;
    double output_elapsed_seconds;
    double total_elapsed_seconds;
    uint64_t preload_selected_bytes;
    int preload_selected_enabled;
    int mxfp4_fused_decode_enabled;
} MlpBlockTimings;

static void reset_mlp_block_timings(MlpBlockTimings *timings) {
    if (timings) {
        memset(timings, 0, sizeof(*timings));
    }
}

static int run_shared_expert_to_accum(id<MTLDevice> device,
                                      id<MTLCommandQueue> queue,
                                      id<MTLLibrary> library,
                                      id<MTLComputePipelineState> swiglu,
                                      id<MTLComputePipelineState> add,
                                      NSString *weight_path,
                                      SharedExpertInfo info,
                                      id<MTLBuffer> input,
                                      id<MTLBuffer> gate,
                                      id<MTLBuffer> up,
                                      id<MTLBuffer> act,
                                      id<MTLBuffer> out,
                                      id<MTLBuffer> accum) {
    if (info.gate_is_mxfp4) {
        if (!run_resident_mxfp4_matvec(device, queue, library, weight_path,
                                       info.gate_mxfp4, input, gate)) {
            return 0;
        }
    } else if (info.gate_is_affine_int4) {
        if (!run_resident_affine_int4_matvec(device, queue, library, weight_path,
                                             info.gate_affine, input, gate)) {
            return 0;
        }
    } else if (!run_resident_matrix_matvec(device, queue, library, weight_path,
                                           info.gate, input, gate)) {
        return 0;
    }
    if (info.up_is_mxfp4) {
        if (!run_resident_mxfp4_matvec(device, queue, library, weight_path,
                                       info.up_mxfp4, input, up)) {
            return 0;
        }
    } else if (info.up_is_affine_int4) {
        if (!run_resident_affine_int4_matvec(device, queue, library, weight_path,
                                             info.up_affine, input, up)) {
            return 0;
        }
    } else if (!run_resident_matrix_matvec(device, queue, library, weight_path,
                                           info.up, input, up)) {
        return 0;
    }
    id<MTLCommandBuffer> act_cmd = [queue commandBuffer];
    if (!act_cmd) {
        fprintf(stderr, "failed to create shared expert SwiGLU command buffer\n");
        return 0;
    }
    if (!encode_swiglu(act_cmd, swiglu, gate, up, act, info.intermediate_dim)) {
        return 0;
    }
    [act_cmd commit];
    [act_cmd waitUntilCompleted];
    if (act_cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "shared expert SwiGLU command failed: %s\n",
                act_cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    if (info.down_is_mxfp4) {
        if (!run_resident_mxfp4_matvec(device, queue, library, weight_path,
                                       info.down_mxfp4, act, out)) {
            return 0;
        }
    } else if (info.down_is_affine_int4) {
        if (!run_resident_affine_int4_matvec(device, queue, library, weight_path,
                                             info.down_affine, act, out)) {
            return 0;
        }
    } else if (!run_resident_matrix_matvec(device, queue, library, weight_path,
                                           info.down, act, out)) {
        return 0;
    }
    id<MTLCommandBuffer> add_cmd = [queue commandBuffer];
    if (!add_cmd) {
        fprintf(stderr, "failed to create shared expert add command buffer\n");
        return 0;
    }
    if (!encode_weighted_add(add_cmd, add, out, accum, 1.0f, info.hidden_dim)) {
        return 0;
    }
    [add_cmd commit];
    [add_cmd waitUntilCompleted];
    if (add_cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "shared expert add command failed: %s\n",
                add_cmd.error.localizedDescription.UTF8String);
        return 0;
    }
    return 1;
}

static int run_expert_self_test(void) {
    id<MTLDevice> device = MTLCreateSystemDefaultDevice();
    if (!device) {
        fprintf(stderr, "Metal device unavailable\n");
        return 1;
    }
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "expert");
    if (!library) return 1;
    id<MTLComputePipelineState> dequant = make_pipeline(device, library, @"dequant4");
    id<MTLComputePipelineState> swiglu = make_pipeline(device, library, @"swiglu");
    if (!dequant || !swiglu) return 1;

    const uint32_t hidden_dim = 8;
    const uint32_t intermediate_dim = 8;
    const uint32_t group_size = 8;
    const size_t w_bytes = intermediate_dim * sizeof(uint32_t); // one packed word per row
    const size_t sb_bytes = intermediate_dim * sizeof(uint16_t);
    const size_t projection_bytes = w_bytes + sb_bytes + sb_bytes;
    const size_t slot_bytes = projection_bytes * 3;

    uint8_t *slot = calloc(1, slot_bytes);
    if (!slot) return 1;
    uint8_t ones[8] = {1, 1, 1, 1, 1, 1, 1, 1};
    uint32_t packed_ones = pack8(ones);
    uint16_t bf16_one = 0x3f80;

    size_t offsets[9] = {
        0,
        w_bytes,
        w_bytes + sb_bytes,
        projection_bytes,
        projection_bytes + w_bytes,
        projection_bytes + w_bytes + sb_bytes,
        projection_bytes * 2,
        projection_bytes * 2 + w_bytes,
        projection_bytes * 2 + w_bytes + sb_bytes,
    };

    for (int proj = 0; proj < 3; proj++) {
        uint32_t *W = (uint32_t *)(slot + offsets[proj * 3]);
        uint16_t *S = (uint16_t *)(slot + offsets[proj * 3 + 1]);
        uint16_t *B = (uint16_t *)(slot + offsets[proj * 3 + 2]);
        for (uint32_t i = 0; i < intermediate_dim; i++) {
            W[i] = packed_ones;
            S[i] = bf16_one;
            B[i] = 0;
        }
    }

    float input[8] = {1, 1, 1, 1, 1, 1, 1, 1};
    id<MTLBuffer> bData = [device newBufferWithBytes:slot
                                              length:slot_bytes
                                             options:MTLResourceStorageModeShared];
    free(slot);
    id<MTLBuffer> bInput = [device newBufferWithBytes:input
                                               length:sizeof(input)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bGate = [device newBufferWithLength:intermediate_dim * sizeof(float)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bUp = [device newBufferWithLength:intermediate_dim * sizeof(float)
                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:intermediate_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:hidden_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    if (!bData || !bInput || !bGate || !bUp || !bAct || !bOut) {
        fprintf(stderr, "failed to allocate expert self-test buffers\n");
        return 1;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create expert self-test command buffer\n");
        return 1;
    }
    if (!encode_dequant4(cmd, dequant, bData,
                         offsets[0], offsets[1], offsets[2],
                         bInput, bGate, intermediate_dim, hidden_dim, group_size, 0) ||
        !encode_dequant4(cmd, dequant, bData,
                         offsets[3], offsets[4], offsets[5],
                         bInput, bUp, intermediate_dim, hidden_dim, group_size, 0) ||
        !encode_swiglu(cmd, swiglu, bGate, bUp, bAct, intermediate_dim) ||
        !encode_dequant4(cmd, dequant, bData,
                         offsets[6], offsets[7], offsets[8],
                         bAct, bOut, hidden_dim, intermediate_dim, group_size, 0)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "expert self-test command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    float *got = (float *)bOut.contents;
    double expected_gate = 8.0;
    double expected_act = (expected_gate / (1.0 + exp(-expected_gate))) * 8.0;
    double expected = expected_act * 8.0;
    int ok = 1;
    for (uint32_t i = 0; i < hidden_dim; i++) {
        if (fabs(got[i] - expected) > 0.02) {
            ok = 0;
            break;
        }
    }

    printf("LargerLM expert self-test\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  hidden dim:         %u\n", hidden_dim);
    printf("  intermediate dim:   %u\n", intermediate_dim);
    printf("  slot bytes:         %zu\n", slot_bytes);
    printf("  output[0]:          %.3f (expected %.3f)\n", got[0], expected);
    printf("  result:             %s\n", ok ? "ok" : "failed");
    return ok ? 0 : 1;
}

static int run_mxfp4_self_test(void) {
    id<MTLDevice> device = MTLCreateSystemDefaultDevice();
    if (!device) {
        fprintf(stderr, "Metal device unavailable\n");
        return 1;
    }
    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "expert");
    if (!library) return 1;
    id<MTLComputePipelineState> mxfp4 = make_pipeline(device, library, @"mxfp4_matvec");
    if (!mxfp4) return 1;

    const uint32_t hidden_dim = 32;
    const uint32_t out_dim = 32;
    const uint32_t group_size = 32;
    const size_t packed_cols = hidden_dim / 8;
    const size_t w_bytes = out_dim * packed_cols * sizeof(uint32_t);
    const size_t s_bytes = out_dim * (hidden_dim / group_size) * sizeof(uint8_t);
    const size_t slot_bytes = w_bytes + s_bytes;
    uint8_t *slot = calloc(1, slot_bytes);
    if (!slot) return 1;
    uint8_t one_code[8] = {2, 2, 2, 2, 2, 2, 2, 2};
    uint32_t packed_one = pack8(one_code);
    for (uint32_t row = 0; row < out_dim; row++) {
        uint32_t *W = (uint32_t *)(slot + (uint64_t)row * packed_cols * sizeof(uint32_t));
        for (uint32_t col = 0; col < packed_cols; col++) {
            W[col] = packed_one;
        }
    }
    memset(slot + w_bytes, 127, s_bytes);

    float input[32];
    for (uint32_t i = 0; i < hidden_dim; i++) {
        input[i] = 1.0f / (float)hidden_dim;
    }
    id<MTLBuffer> bData = [device newBufferWithBytes:slot
                                              length:slot_bytes
                                             options:MTLResourceStorageModeShared];
    free(slot);
    id<MTLBuffer> bInput = [device newBufferWithBytes:input
                                               length:sizeof(input)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:out_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    if (!bData || !bInput || !bOut) {
        fprintf(stderr, "failed to allocate mxfp4 self-test buffers\n");
        return 1;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create mxfp4 self-test command buffer\n");
        return 1;
    }
    if (!encode_mxfp4_matvec(cmd, mxfp4, bData, 0, w_bytes,
                             bInput, bOut, out_dim, hidden_dim, group_size)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "mxfp4 self-test command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    float *got = (float *)bOut.contents;
    int ok = 1;
    for (uint32_t i = 0; i < out_dim; i++) {
        if (fabsf(got[i] - 1.0f) > 0.002f) {
            ok = 0;
            break;
        }
    }
    printf("LargerLM MXFP4 self-test\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  hidden dim:         %u\n", hidden_dim);
    printf("  out dim:            %u\n", out_dim);
    printf("  slot bytes:         %zu\n", slot_bytes);
    printf("  output[0]:          %.6f (expected 1.000000)\n", got[0]);
    printf("  result:             %s\n", ok ? "ok" : "failed");
    return ok ? 0 : 1;
}

static int run_expert_forward(id<MTLDevice> device,
                              id<MTLBuffer> expert_data,
                              ExpertLayoutInfo info,
                              NSString *input_path,
                              NSString *output_path,
                              uint64_t slot_alloc_bytes,
                              uint64_t max_runner_scratch_bytes) {
    uint64_t peak = estimate_expert_forward_peak(slot_alloc_bytes,
                                                 info.hidden_dim,
                                                 info.intermediate_dim);
    if (!enforce_scratch_limit("expert forward", peak, max_runner_scratch_bytes)) {
        return 1;
    }
    NSData *input_data = [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)info.hidden_dim * sizeof(float);
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "expert");
    if (!library) return 1;
    id<MTLComputePipelineState> dequant =
        make_pipeline(device, library, info.is_mxfp4 ? @"mxfp4_matvec" : @"dequant4");
    id<MTLComputePipelineState> swiglu = make_pipeline(device, library, @"swiglu");
    if (!dequant || !swiglu) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bGate = [device newBufferWithLength:info.intermediate_dim * sizeof(float)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bUp = [device newBufferWithLength:info.intermediate_dim * sizeof(float)
                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:info.intermediate_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:info.hidden_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    if (!bInput || !bGate || !bUp || !bAct || !bOut) {
        fprintf(stderr, "failed to allocate expert forward buffers\n");
        return 1;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        fprintf(stderr, "failed to create expert forward command buffer\n");
        return 1;
    }
    if (!encode_expert_forward_to(cmd, dequant, swiglu, expert_data, info,
                                  bInput, bGate, bUp, bAct, bOut)) {
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        fprintf(stderr, "expert forward command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    NSUInteger output_bytes = (NSUInteger)info.hidden_dim * sizeof(float);
    if (output_path) {
        NSData *out_data = [NSData dataWithBytes:bOut.contents length:output_bytes];
        if (![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }

    float *out = (float *)bOut.contents;
    printf("  expert forward:     ok\n");
    printf("  quantization:       %s\n", info.is_mxfp4 ? "mlx-mxfp4" : "affine-int4");
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  intermediate dim:   %u\n", info.intermediate_dim);
    printf("  group size:         %u\n", info.group_size);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_moe_forward(id<MTLDevice> device,
                           const char *layer_file_path,
                           uint64_t slot_bytes,
                           uint64_t layer_file_bytes,
                           uint64_t *expert_ids,
                           float *weights,
                           int expert_count,
                           ExpertLayoutInfo info,
                           NSString *input_path,
                           NSData *input_override_data,
                           NSData *residual_data,
                           NSString *output_path,
                           NSData *__strong *output_data,
                           uint64_t alloc_size,
                           uint64_t extra_live_bytes,
                           uint64_t max_runner_scratch_bytes,
                           uint64_t expert_read_advise_merge_gap_bytes,
                           uint64_t expert_read_advise_align_bytes,
                           SharedExpertInfo *shared_info,
                           NSString *shared_weight_path,
                           MlpBlockTimings *timings) {
    int trace_moe = getenv("LARGERLM_TRACE_MOE") != NULL;
    CFAbsoluteTime moe_started = CFAbsoluteTimeGetCurrent();
    CFAbsoluteTime setup_started = moe_started;
    int preload_selected_requested =
        getenv("LARGERLM_MOE_DECODE_PRELOAD_SELECTED") != NULL;
    int preload_selected_enabled = 0;
    int mxfp4_fused_decode_requested =
        getenv("LARGERLM_MOE_DECODE_MXFP4_FUSED") != NULL;
    int mxfp4_fused_decode_enabled = 0;
    uint64_t selected_alloc_size = alloc_size;
    uint32_t scratch_intermediate_dim = info.intermediate_dim;
    uint64_t shared_matrix_alloc_bytes = 0;
    uint64_t residual_live_bytes = residual_data ? (uint64_t)info.hidden_dim * sizeof(float) : 0;
    if (shared_info) {
        if (shared_info->hidden_dim != info.hidden_dim) {
            fprintf(stderr, "shared expert hidden dim %u does not match routed dim %u\n",
                    shared_info->hidden_dim, info.hidden_dim);
            return 1;
        }
        if (shared_info->intermediate_dim > scratch_intermediate_dim) {
            scratch_intermediate_dim = shared_info->intermediate_dim;
        }
        shared_matrix_alloc_bytes = shared_info->max_matrix_alloc_bytes;
    }
    uint64_t peak = estimate_moe_forward_peak_with_shared(alloc_size,
                                                          info.hidden_dim,
                                                          scratch_intermediate_dim,
                                                          extra_live_bytes +
                                                              residual_live_bytes,
                                                          shared_matrix_alloc_bytes);
    if (preload_selected_requested && expert_count > 1) {
        uint64_t requested_alloc_size = 0;
        if (checked_mul_u64(alloc_size,
                            (uint64_t)expert_count,
                            &requested_alloc_size)) {
            uint64_t requested_peak =
                estimate_moe_forward_peak_with_shared(requested_alloc_size,
                                                      info.hidden_dim,
                                                      scratch_intermediate_dim,
                                                      extra_live_bytes +
                                                          residual_live_bytes,
                                                      shared_matrix_alloc_bytes);
            if (requested_peak <= max_runner_scratch_bytes) {
                preload_selected_enabled = 1;
                selected_alloc_size = requested_alloc_size;
                peak = requested_peak;
            } else {
                fprintf(stderr,
                        "decode MoE selected-expert preload disabled: estimated peak %llu exceeds limit %llu\n",
                        (unsigned long long)requested_peak,
                        (unsigned long long)max_runner_scratch_bytes);
            }
        } else {
            fprintf(stderr,
                    "decode MoE selected-expert preload disabled: slot buffer byte size overflows uint64\n");
        }
    }
    if (mxfp4_fused_decode_requested && info.is_mxfp4) {
        if (preload_selected_enabled) {
            fprintf(stderr,
                    "decode MXFP4 fused expert path disabled while selected-expert preload is enabled\n");
        } else {
            mxfp4_fused_decode_enabled = 1;
        }
    }
    if (!enforce_scratch_limit("MoE forward", peak, max_runner_scratch_bytes)) {
        return 1;
    }
    NSData *input_data = input_override_data ?: [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)info.hidden_dim * sizeof(float);
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }
    if (residual_data && residual_data.length != expected_input_bytes) {
        fprintf(stderr, "residual bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)residual_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "expert");
    if (!library) return 1;
    id<MTLComputePipelineState> dequant =
        make_pipeline(device, library, info.is_mxfp4 ? @"mxfp4_matvec" : @"dequant4");
    id<MTLComputePipelineState> swiglu = make_pipeline(device, library, @"swiglu");
    id<MTLComputePipelineState> clear = make_pipeline(device, library, @"clear_f32");
    id<MTLComputePipelineState> add = make_pipeline(device, library, @"weighted_add");
    if (!dequant || !swiglu || !clear || !add) return 1;
    uint32_t mxfp4_swiglu_activation_mode = 0u;
    if (mxfp4_fused_decode_enabled) {
        const char *activation_env = getenv("LARGERLM_MOE_MXFP4_SWIGLU_ACTIVATION");
        if (activation_env && activation_env[0] != '\0') {
            if (strcmp(activation_env, "0") == 0 ||
                strcasecmp(activation_env, "silu") == 0 ||
                strcasecmp(activation_env, "exact") == 0) {
                mxfp4_swiglu_activation_mode = 0u;
            } else if (strcmp(activation_env, "1") == 0 ||
                       strcasecmp(activation_env, "fast") == 0 ||
                       strcasecmp(activation_env, "fast-exp") == 0) {
                mxfp4_swiglu_activation_mode = 1u;
            } else if (strcmp(activation_env, "2") == 0 ||
                       strcasecmp(activation_env, "linear") == 0 ||
                       strcasecmp(activation_env, "skip-silu") == 0) {
                mxfp4_swiglu_activation_mode = 2u;
            } else {
                fprintf(stderr,
                        "unsupported LARGERLM_MOE_MXFP4_SWIGLU_ACTIVATION=%s; expected silu, fast-exp, or linear\n",
                        activation_env);
                return 1;
            }
        }
    }
    NSString *mxfp4_swiglu_kernel_name =
        (mxfp4_fused_decode_enabled && info.group_size == 32u)
            ? @"mxfp4_swiglu_batch_gs32"
            : @"mxfp4_swiglu_batch";
    NSString *mxfp4_down_add_kernel_name =
        (mxfp4_fused_decode_enabled && info.group_size == 32u)
            ? @"mxfp4_matvec_weighted_add_batch_gs32"
            : @"mxfp4_matvec_weighted_add_batch";
    id<MTLComputePipelineState> mxfp4_swiglu =
        mxfp4_fused_decode_enabled
            ? make_pipeline(device, library, mxfp4_swiglu_kernel_name)
            : nil;
    id<MTLComputePipelineState> mxfp4_down_add =
        mxfp4_fused_decode_enabled
            ? make_pipeline(device, library, mxfp4_down_add_kernel_name)
            : nil;
    if (mxfp4_fused_decode_enabled && (!mxfp4_swiglu || !mxfp4_down_add)) {
        return 1;
    }

    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)selected_alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for %llu bytes\n",
                (unsigned long long)selected_alloc_size);
        return 1;
    }
    memset(aligned, 0, (size_t)selected_alloc_size);
    id<MTLBuffer> bData =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)selected_alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bData) {
        fprintf(stderr, "failed to wrap aligned expert slot buffer\n");
        free(aligned);
        return 1;
    }

    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bGate = [device newBufferWithLength:scratch_intermediate_dim * sizeof(float)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bUp = [device newBufferWithLength:scratch_intermediate_dim * sizeof(float)
                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:scratch_intermediate_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bExpertOut = [device newBufferWithLength:info.hidden_dim * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAccum = [device newBufferWithLength:info.hidden_dim * sizeof(float)
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bRouteWeight =
        mxfp4_fused_decode_enabled
            ? [device newBufferWithLength:sizeof(float)
                                  options:MTLResourceStorageModeShared]
            : nil;
    if (!bInput || !bGate || !bUp || !bAct || !bExpertOut || !bAccum) {
        fprintf(stderr, "failed to allocate MoE forward buffers\n");
        return 1;
    }
    if (mxfp4_fused_decode_enabled && !bRouteWeight) {
        fprintf(stderr, "failed to allocate MoE route weight buffer\n");
        return 1;
    }
    if (timings) {
        timings->moe_setup_elapsed_seconds +=
            CFAbsoluteTimeGetCurrent() - setup_started;
        timings->preload_selected_enabled = preload_selected_enabled;
        timings->preload_selected_bytes = preload_selected_enabled ? selected_alloc_size : 0;
        timings->mxfp4_fused_decode_enabled = mxfp4_fused_decode_enabled;
    }

    CFAbsoluteTime clear_started = CFAbsoluteTimeGetCurrent();
    if (info.is_mxfp4) {
        memset(bAccum.contents, 0, (size_t)info.hidden_dim * sizeof(float));
        [bAccum didModifyRange:NSMakeRange(0, (NSUInteger)info.hidden_dim * sizeof(float))];
    } else {
        id<MTLCommandBuffer> clear_cmd = [queue commandBuffer];
        if (!clear_cmd) {
            fprintf(stderr, "failed to create MoE forward clear command buffer\n");
            return 1;
        }
        if (!encode_clear_f32(clear_cmd, clear, bAccum, info.hidden_dim)) {
            return 1;
        }
        if (trace_moe) {
            fprintf(stderr, "trace moe: wait clear\n");
            fflush(stderr);
        }
        [clear_cmd commit];
        [clear_cmd waitUntilCompleted];
        if (trace_moe) {
            fprintf(stderr, "trace moe: clear done\n");
            fflush(stderr);
        }
        if (clear_cmd.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "MoE forward clear command failed: %s\n",
                    clear_cmd.error.localizedDescription.UTF8String);
            return 1;
        }
    }
    if (timings) {
        timings->moe_clear_elapsed_seconds +=
            CFAbsoluteTimeGetCurrent() - clear_started;
    }

    CFAbsoluteTime io_started = CFAbsoluteTimeGetCurrent();
    int expert_fd = open(layer_file_path, O_RDONLY);
    if (expert_fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", layer_file_path, strerror(errno));
        return 1;
    }
    if (expert_read_advise_align_bytes > 0) {
        advise_expert_read_ranges(expert_fd,
                                  slot_bytes,
                                  layer_file_bytes,
                                  expert_ids,
                                  expert_count,
                                  expert_read_advise_merge_gap_bytes,
                                  expert_read_advise_align_bytes);
    }
    if (timings) {
        timings->expert_read_elapsed_seconds +=
            CFAbsoluteTimeGetCurrent() - io_started;
    }

    if (preload_selected_enabled) {
        for (int i = 0; i < expert_count; i++) {
            off_t expert_offset = (off_t)(expert_ids[i] * slot_bytes);
            void *slot_dst = (uint8_t *)bData.contents + (uint64_t)i * alloc_size;
            CFAbsoluteTime read_started = CFAbsoluteTimeGetCurrent();
            if (!read_exact_fd(expert_fd,
                               layer_file_path,
                               slot_dst,
                               (size_t)slot_bytes,
                               expert_offset)) {
                close(expert_fd);
                return 1;
            }
            if (timings) {
                timings->expert_read_elapsed_seconds +=
                    CFAbsoluteTimeGetCurrent() - read_started;
            }
            [bData didModifyRange:NSMakeRange((NSUInteger)((uint64_t)i * alloc_size),
                                              (NSUInteger)slot_bytes)];
        }
        CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
        id<MTLCommandBuffer> cmd = [queue commandBuffer];
        if (!cmd) {
            fprintf(stderr, "failed to create preloaded MoE forward command buffer\n");
            close(expert_fd);
            return 1;
        }
        for (int i = 0; i < expert_count; i++) {
            ExpertLayoutInfo shifted_info = {0};
            uint64_t base_offset = (uint64_t)i * alloc_size;
            if (!expert_layout_with_base_offset(info, base_offset, &shifted_info)) {
                fprintf(stderr, "failed to shift preloaded expert layout offsets\n");
                close(expert_fd);
                return 1;
            }
            if (!encode_expert_forward_to(cmd, dequant, swiglu, bData, shifted_info,
                                          bInput, bGate, bUp, bAct, bExpertOut) ||
                !encode_weighted_add(cmd, add, bExpertOut, bAccum,
                                     weights[i], info.hidden_dim)) {
                close(expert_fd);
                return 1;
            }
        }
        if (trace_moe) {
            fprintf(stderr, "trace moe: wait preloaded experts add\n");
            fflush(stderr);
        }
        [cmd commit];
        [cmd waitUntilCompleted];
        if (trace_moe) {
            fprintf(stderr, "trace moe: preloaded experts add done\n");
            fflush(stderr);
        }
        if (cmd.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "preloaded MoE forward command failed: %s\n",
                    cmd.error.localizedDescription.UTF8String);
            close(expert_fd);
            return 1;
        }
        if (timings) {
            timings->expert_kernel_elapsed_seconds +=
                CFAbsoluteTimeGetCurrent() - kernel_started;
        }
    } else {
        for (int i = 0; i < expert_count; i++) {
            off_t expert_offset = (off_t)(expert_ids[i] * slot_bytes);
            CFAbsoluteTime read_started = CFAbsoluteTimeGetCurrent();
            if (!read_exact_fd(expert_fd,
                               layer_file_path,
                               bData.contents,
                               (size_t)slot_bytes,
                               expert_offset)) {
                close(expert_fd);
                return 1;
            }
            if (timings) {
                timings->expert_read_elapsed_seconds +=
                    CFAbsoluteTimeGetCurrent() - read_started;
            }
            [bData didModifyRange:NSMakeRange(0, (NSUInteger)slot_bytes)];
            CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
            id<MTLCommandBuffer> cmd = [queue commandBuffer];
            if (!cmd) {
                fprintf(stderr, "failed to create MoE forward expert %llu command buffer\n",
                        (unsigned long long)expert_ids[i]);
                close(expert_fd);
                return 1;
            }
            if (mxfp4_fused_decode_enabled) {
                ((float *)bRouteWeight.contents)[0] = weights[i];
                [bRouteWeight didModifyRange:NSMakeRange(0, sizeof(float))];
                if (!encode_mxfp4_expert_forward_weighted_batch_to(
                        cmd, mxfp4_swiglu, mxfp4_down_add, bData, info,
                        bInput, bAct, bAccum, bRouteWeight, 1u, 1u,
                        mxfp4_swiglu_activation_mode)) {
                    close(expert_fd);
                    return 1;
                }
            } else {
                if (!encode_expert_forward_to(cmd, dequant, swiglu, bData, info,
                                              bInput, bGate, bUp, bAct, bExpertOut) ||
                    !encode_weighted_add(cmd, add, bExpertOut, bAccum,
                                         weights[i], info.hidden_dim)) {
                    close(expert_fd);
                    return 1;
                }
            }
            if (trace_moe) {
                fprintf(stderr, "trace moe: wait expert %llu add\n",
                        (unsigned long long)expert_ids[i]);
                fflush(stderr);
            }
            [cmd commit];
            [cmd waitUntilCompleted];
            if (trace_moe) {
                fprintf(stderr, "trace moe: expert %llu add done\n",
                        (unsigned long long)expert_ids[i]);
                fflush(stderr);
            }
            if (cmd.status == MTLCommandBufferStatusError) {
                fprintf(stderr, "MoE forward expert %llu command failed: %s\n",
                        (unsigned long long)expert_ids[i],
                        cmd.error.localizedDescription.UTF8String);
                close(expert_fd);
                return 1;
            }
            if (timings) {
                timings->expert_kernel_elapsed_seconds +=
                    CFAbsoluteTimeGetCurrent() - kernel_started;
            }
        }
    }
    close(expert_fd);

    if (shared_info) {
        CFAbsoluteTime shared_started = CFAbsoluteTimeGetCurrent();
        if (!shared_weight_path) {
            fprintf(stderr, "shared expert requested but resident weight path is missing\n");
            return 1;
        }
        if (!run_shared_expert_to_accum(device, queue, library, swiglu, add,
                                        shared_weight_path, *shared_info,
                                        bInput, bGate, bUp, bAct,
                                        bExpertOut, bAccum)) {
            return 1;
        }
        if (timings) {
            timings->shared_elapsed_seconds +=
                CFAbsoluteTimeGetCurrent() - shared_started;
        }
    }

    if (residual_data) {
        CFAbsoluteTime residual_started = CFAbsoluteTimeGetCurrent();
        id<MTLBuffer> bResidual = [device newBufferWithBytes:residual_data.bytes
                                                      length:residual_data.length
                                                     options:MTLResourceStorageModeShared];
        if (!bResidual) {
            fprintf(stderr, "failed to allocate residual buffer\n");
            return 1;
        }
        id<MTLCommandBuffer> add_residual_cmd = [queue commandBuffer];
        if (!add_residual_cmd) {
            fprintf(stderr, "failed to create residual add command buffer\n");
            return 1;
        }
        if (!encode_weighted_add(add_residual_cmd, add, bResidual,
                                 bAccum, 1.0f, info.hidden_dim)) {
            return 1;
        }
        [add_residual_cmd commit];
        [add_residual_cmd waitUntilCompleted];
        if (add_residual_cmd.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "residual add command failed: %s\n",
                    add_residual_cmd.error.localizedDescription.UTF8String);
            return 1;
        }
        if (timings) {
            timings->residual_elapsed_seconds +=
                CFAbsoluteTimeGetCurrent() - residual_started;
        }
    }

    CFAbsoluteTime output_started = CFAbsoluteTimeGetCurrent();
    NSUInteger output_bytes = (NSUInteger)info.hidden_dim * sizeof(float);
    if (output_path || output_data) {
        NSData *out_data = [[NSData alloc] initWithBytes:bAccum.contents length:output_bytes];
        if (output_data) {
            *output_data = out_data;
        }
        if (output_path && ![out_data writeToFile:output_path atomically:YES]) {
            fprintf(stderr, "failed to write MoE output f32 file: %s\n",
                    output_path.UTF8String);
            return 1;
        }
    }
    if (timings) {
        timings->output_elapsed_seconds +=
            CFAbsoluteTimeGetCurrent() - output_started;
        timings->moe_elapsed_seconds += CFAbsoluteTimeGetCurrent() - moe_started;
    }

    float *out = (float *)bAccum.contents;
    printf("  moe forward:        ok\n");
    printf("  quantization:       %s\n", info.is_mxfp4 ? "mlx-mxfp4" : "affine-int4");
    if (info.is_mxfp4) {
        printf("  MXFP4 fused decode: %s\n",
               mxfp4_fused_decode_enabled ? "yes" : "no");
    }
    printf("  experts:            %d\n", expert_count);
    if (expert_read_advise_align_bytes > 0) {
        printf("  read advise:        merge_gap=%llu align=%llu\n",
               (unsigned long long)expert_read_advise_merge_gap_bytes,
               (unsigned long long)expert_read_advise_align_bytes);
    }
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  intermediate dim:   %u\n", info.intermediate_dim);
    if (shared_info) {
        printf("  shared expert:      yes\n");
        printf("  shared intermediate:%u\n", shared_info->intermediate_dim);
    } else {
        printf("  shared expert:      no\n");
    }
    printf("  residual add:       %s\n", residual_data ? "yes" : "no");
    printf("  group size:         %u\n", info.group_size);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_path) {
        printf("  output f32:         %s\n", output_path.UTF8String);
    }
    return 0;
}

static int run_moe_forward_batch_assignments(id<MTLDevice> device,
                                             const char *layer_file_path,
                                             uint64_t slot_bytes,
                                             uint64_t layer_file_bytes,
                                             MoEBatchAssignment *assignments,
                                             uint64_t route_assignment_count,
                                             int assignments_sorted,
                                             uint32_t batch_tokens,
                                             uint32_t token_block,
                                             ExpertLayoutInfo info,
                                             NSString *input_path,
                                             NSString *output_path,
                                             uint64_t alloc_size,
                                             uint64_t max_runner_scratch_bytes,
                                             uint64_t expert_read_advise_merge_gap_bytes,
                                             uint64_t expert_read_advise_align_bytes) {
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();
    double sort_elapsed = 0.0;
    double setup_elapsed = 0.0;
    double expert_read_elapsed = 0.0;
    double input_read_elapsed = 0.0;
    double output_read_elapsed = 0.0;
    double kernel_elapsed = 0.0;
    double mxfp4_swiglu_kernel_elapsed = 0.0;
    double mxfp4_down_add_kernel_elapsed = 0.0;
    double output_write_elapsed = 0.0;
    double final_read_elapsed = 0.0;
    if (!assignments || route_assignment_count == 0 ||
        batch_tokens == 0 || !input_path || !output_path) {
        fprintf(stderr, "invalid MoE batch arguments\n");
        free(assignments);
        return 1;
    }
    if (slot_bytes == 0 || layer_file_bytes == 0 || layer_file_bytes % slot_bytes != 0) {
        fprintf(stderr, "invalid MoE batch layer size or slot size\n");
        free(assignments);
        return 1;
    }
    uint64_t compact_expert_count = layer_file_bytes / slot_bytes;
    size_t row_bytes = (size_t)info.hidden_dim * sizeof(float);
    uint64_t expected_input_bytes = (uint64_t)batch_tokens * row_bytes;
    if (expected_input_bytes > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "batch input/output is too large for file offsets\n");
        free(assignments);
        return 1;
    }
    int use_memory_accumulator = 0;
    if (!moe_batch_memory_accumulator_from_env(&use_memory_accumulator)) {
        free(assignments);
        return 1;
    }
    uint64_t output_accumulator_live_bytes =
        use_memory_accumulator ? expected_input_bytes : 0;
    if (route_assignment_count == 0 ||
        route_assignment_count > (uint64_t)(SIZE_MAX / sizeof(MoEBatchAssignment)) ||
        route_assignment_count > (uint64_t)(UINT64_MAX / sizeof(MoEBatchAssignment))) {
        fprintf(stderr, "invalid MoE batch assignment count %llu\n",
                (unsigned long long)route_assignment_count);
        free(assignments);
        return 1;
    }
    for (uint64_t i = 0; i < route_assignment_count; i++) {
        if (assignments[i].expert >= compact_expert_count) {
            fprintf(stderr,
                    "route assignment %llu expert %llu out of range for %llu compact experts\n",
                    (unsigned long long)i,
                    (unsigned long long)assignments[i].expert,
                    (unsigned long long)compact_expert_count);
            free(assignments);
            return 1;
        }
        if (assignments[i].token >= batch_tokens) {
            fprintf(stderr,
                    "route assignment %llu token %u out of range for %u tokens\n",
                    (unsigned long long)i,
                    assignments[i].token,
                    batch_tokens);
            free(assignments);
            return 1;
        }
    }
    uint64_t assignment_bytes =
        route_assignment_count * (uint64_t)sizeof(MoEBatchAssignment);
    uint64_t token_seen_bytes = (uint64_t)batch_tokens * sizeof(uint8_t);
    uint64_t route_live_bytes = 0;
    if (assignment_bytes > UINT64_MAX - token_seen_bytes ||
        assignment_bytes + token_seen_bytes > UINT64_MAX - output_accumulator_live_bytes) {
        fprintf(stderr, "MoE batch route live bytes overflow\n");
        free(assignments);
        return 1;
    }
    route_live_bytes =
        assignment_bytes + token_seen_bytes + output_accumulator_live_bytes;
    int used_assignment_sort = assignments_sorted ? 0 : 1;
    if (used_assignment_sort) {
        CFAbsoluteTime sort_started = CFAbsoluteTimeGetCurrent();
        qsort(assignments,
              (size_t)route_assignment_count,
              sizeof(MoEBatchAssignment),
              compare_moe_batch_assignments);
        sort_elapsed = CFAbsoluteTimeGetCurrent() - sort_started;
    }
    uint64_t max_expert_assignments = 1;
    uint64_t current_expert_assignments = 1;
    for (uint64_t i = 1; i < route_assignment_count; i++) {
        if (assignments[i - 1].expert == assignments[i].expert &&
            assignments[i - 1].token == assignments[i].token) {
            fprintf(stderr,
                    "duplicate MoE batch assignment for token %u expert %llu\n",
                    assignments[i].token,
                    (unsigned long long)assignments[i].expert);
            free(assignments);
            return 1;
        }
        if (assignments[i - 1].expert == assignments[i].expert) {
            current_expert_assignments++;
        } else {
            if (current_expert_assignments > max_expert_assignments) {
                max_expert_assignments = current_expert_assignments;
            }
            current_expert_assignments = 1;
        }
    }
    if (current_expert_assignments > max_expert_assignments) {
        max_expert_assignments = current_expert_assignments;
    }
    uint32_t effective_token_block = 0;
    uint64_t batch_buffer_bytes = 0;
    uint64_t peak = 0;
    if (!choose_moe_batch_token_block(alloc_size,
                                      info.hidden_dim,
                                      info.intermediate_dim,
                                      token_block,
                                      max_expert_assignments,
                                      route_live_bytes,
                                      max_runner_scratch_bytes,
                                      &effective_token_block,
                                      &batch_buffer_bytes,
                                      &peak)) {
        fprintf(stderr, "MoE batch forward token block cannot fit scratch limit\n");
        free(assignments);
        return 1;
    }
    if (!enforce_scratch_limit("MoE batch forward", peak, max_runner_scratch_bytes)) {
        free(assignments);
        return 1;
    }

    int input_fd = open(input_path.UTF8String, O_RDONLY);
    if (input_fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        free(assignments);
        return 1;
    }
    struct stat input_stat;
    if (fstat(input_fd, &input_stat) != 0) {
        fprintf(stderr, "fstat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        close(input_fd);
        free(assignments);
        return 1;
    }
    if ((uint64_t)input_stat.st_size != expected_input_bytes) {
        fprintf(stderr, "batch input bytes %llu do not match expected %llu\n",
                (unsigned long long)input_stat.st_size,
                (unsigned long long)expected_input_bytes);
        close(input_fd);
        free(assignments);
        return 1;
    }
    int output_fd = open(output_path.UTF8String, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (output_fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", output_path.UTF8String, strerror(errno));
        close(input_fd);
        free(assignments);
        return 1;
    }
    if (ftruncate(output_fd, (off_t)expected_input_bytes) != 0) {
        fprintf(stderr, "ftruncate failed for %s: %s\n",
                output_path.UTF8String,
                strerror(errno));
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }

    id<MTLLibrary> library = expert_kernel_library(device, "expert");
    if (!library) {
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }
    uint32_t mxfp4_moe_token_tile = 1u;
    if (info.is_mxfp4) {
        const char *tile_env = getenv("LARGERLM_MOE_MXFP4_BATCH_TOKEN_TILE");
        if (tile_env && tile_env[0] != '\0') {
            if (strcmp(tile_env, "1") == 0) {
                mxfp4_moe_token_tile = 1u;
            } else if (strcmp(tile_env, "2") == 0) {
                mxfp4_moe_token_tile = 2u;
            } else if (strcmp(tile_env, "4") == 0) {
                mxfp4_moe_token_tile = 4u;
            } else {
                fprintf(stderr,
                        "unsupported LARGERLM_MOE_MXFP4_BATCH_TOKEN_TILE=%s; expected 1, 2, or 4\n",
                        tile_env);
                close(input_fd);
                close(output_fd);
                free(assignments);
                return 1;
            }
        }
    }
    int split_mxfp4_kernel_timing = 0;
    if (info.is_mxfp4) {
        const char *split_env = getenv("LARGERLM_MOE_MXFP4_SPLIT_KERNEL_TIMING");
        if (split_env && split_env[0] != '\0' &&
            strcmp(split_env, "0") != 0 &&
            strcasecmp(split_env, "false") != 0 &&
            strcasecmp(split_env, "no") != 0 &&
            strcasecmp(split_env, "off") != 0) {
            split_mxfp4_kernel_timing = 1;
        }
    }
    int vector_mxfp4_swiglu = 0;
    if (info.is_mxfp4 && mxfp4_moe_token_tile == 1u) {
        const char *vector_env = getenv("LARGERLM_MOE_MXFP4_VECTOR_SWIGLU");
        if (vector_env && vector_env[0] != '\0' &&
            strcmp(vector_env, "0") != 0 &&
            strcasecmp(vector_env, "false") != 0 &&
            strcasecmp(vector_env, "no") != 0 &&
            strcasecmp(vector_env, "off") != 0) {
            vector_mxfp4_swiglu = 1;
        }
    }
    int group32_mxfp4_specialized = 0;
    if (info.is_mxfp4) {
        const char *group32_env = getenv("LARGERLM_MOE_MXFP4_GROUP32_SPECIALIZED");
        int group32_env_set = group32_env && group32_env[0] != '\0';
        int group32_env_enable = 0;
        if (group32_env_set) {
            group32_env_enable =
                strcmp(group32_env, "0") != 0 &&
                strcasecmp(group32_env, "false") != 0 &&
                strcasecmp(group32_env, "no") != 0 &&
                strcasecmp(group32_env, "off") != 0;
        }
        if ((group32_env_set && group32_env_enable) ||
            (!group32_env_set &&
             !vector_mxfp4_swiglu &&
             mxfp4_moe_token_tile == 1u &&
             info.group_size == 32u)) {
            if (mxfp4_moe_token_tile != 1u || info.group_size != 32u) {
                fprintf(stderr,
                        "LARGERLM_MOE_MXFP4_GROUP32_SPECIALIZED requires MXFP4 token tile 1 and group size 32\n");
                close(input_fd);
                close(output_fd);
                free(assignments);
                return 1;
            }
            group32_mxfp4_specialized = 1;
        }
    }
    if (vector_mxfp4_swiglu && group32_mxfp4_specialized) {
        fprintf(stderr,
                "LARGERLM_MOE_MXFP4_VECTOR_SWIGLU and LARGERLM_MOE_MXFP4_GROUP32_SPECIALIZED cannot be combined\n");
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }
    uint32_t mxfp4_swiglu_activation_mode = 0u;
    const char *mxfp4_swiglu_activation_label = "silu";
    if (info.is_mxfp4) {
        const char *activation_env = getenv("LARGERLM_MOE_MXFP4_SWIGLU_ACTIVATION");
        if (activation_env && activation_env[0] != '\0') {
            if (strcmp(activation_env, "0") == 0 ||
                strcasecmp(activation_env, "silu") == 0 ||
                strcasecmp(activation_env, "exact") == 0) {
                mxfp4_swiglu_activation_mode = 0u;
                mxfp4_swiglu_activation_label = "silu";
            } else if (strcmp(activation_env, "1") == 0 ||
                       strcasecmp(activation_env, "fast") == 0 ||
                       strcasecmp(activation_env, "fast-exp") == 0) {
                mxfp4_swiglu_activation_mode = 1u;
                mxfp4_swiglu_activation_label = "fast-exp";
            } else if (strcmp(activation_env, "2") == 0 ||
                       strcasecmp(activation_env, "linear") == 0 ||
                       strcasecmp(activation_env, "skip-silu") == 0) {
                mxfp4_swiglu_activation_mode = 2u;
                mxfp4_swiglu_activation_label = "linear-diagnostic";
            } else {
                fprintf(stderr,
                        "unsupported LARGERLM_MOE_MXFP4_SWIGLU_ACTIVATION=%s; expected silu, fast-exp, or linear\n",
                        activation_env);
                close(input_fd);
                close(output_fd);
                free(assignments);
                return 1;
            }
        }
    }
    id<MTLComputePipelineState> dequant =
        info.is_mxfp4 ? nil : make_pipeline(device, library, @"dequant4_batch");
    id<MTLComputePipelineState> swiglu =
        info.is_mxfp4 ? nil : make_pipeline(device, library, @"swiglu_batch");
    NSString *mxfp4_swiglu_kernel_name = @"mxfp4_swiglu_batch";
    NSString *mxfp4_down_add_kernel_name = @"mxfp4_matvec_weighted_add_batch";
    if (group32_mxfp4_specialized) {
        mxfp4_swiglu_kernel_name = @"mxfp4_swiglu_batch_gs32";
        mxfp4_down_add_kernel_name = @"mxfp4_matvec_weighted_add_batch_gs32";
    } else if (vector_mxfp4_swiglu) {
        mxfp4_swiglu_kernel_name = @"mxfp4_swiglu_batch_v4";
    } else if (mxfp4_moe_token_tile == 2u) {
        mxfp4_swiglu_kernel_name = @"mxfp4_swiglu_batch_t2";
        mxfp4_down_add_kernel_name = @"mxfp4_matvec_weighted_add_batch_t2";
    } else if (mxfp4_moe_token_tile == 4u) {
        mxfp4_swiglu_kernel_name = @"mxfp4_swiglu_batch_t4";
        mxfp4_down_add_kernel_name = @"mxfp4_matvec_weighted_add_batch_t4";
    }
    id<MTLComputePipelineState> mxfp4_swiglu =
        info.is_mxfp4
            ? make_pipeline(device, library, mxfp4_swiglu_kernel_name)
            : nil;
    id<MTLComputePipelineState> mxfp4_down_add =
        info.is_mxfp4
            ? make_pipeline(device, library, mxfp4_down_add_kernel_name)
            : nil;
    id<MTLComputePipelineState> add =
        info.is_mxfp4 ? nil : make_pipeline(device, library, @"weighted_add_batch");
    if ((info.is_mxfp4 && (!mxfp4_swiglu || !mxfp4_down_add)) ||
        (!info.is_mxfp4 && (!dequant || !swiglu || !add))) {
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }

    void *aligned = NULL;
    if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
        fprintf(stderr, "posix_memalign failed for %llu bytes\n",
                (unsigned long long)alloc_size);
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }
    memset(aligned, 0, (size_t)alloc_size);
    id<MTLBuffer> bData =
        [device newBufferWithBytesNoCopy:aligned
                                   length:(NSUInteger)alloc_size
                                  options:MTLResourceStorageModeShared
                              deallocator:^(void *pointer, NSUInteger length) {
                                  (void)length;
                                  free(pointer);
                              }];
    if (!bData) {
        fprintf(stderr, "failed to wrap aligned expert slot buffer\n");
        free(aligned);
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }

    NSUInteger input_batch_bytes =
        (NSUInteger)((uint64_t)effective_token_block * (uint64_t)row_bytes);
    NSUInteger intermediate_batch_bytes =
        (NSUInteger)((uint64_t)effective_token_block *
                     (uint64_t)info.intermediate_dim * sizeof(float));
    NSUInteger weight_batch_bytes =
        (NSUInteger)((uint64_t)effective_token_block * sizeof(float));
    id<MTLBuffer> bInput = [device newBufferWithLength:input_batch_bytes
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bGate = [device newBufferWithLength:intermediate_batch_bytes
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bUp = [device newBufferWithLength:intermediate_batch_bytes
                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:intermediate_batch_bytes
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bExpertOut = [device newBufferWithLength:input_batch_bytes
                                                   options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAccum = [device newBufferWithLength:input_batch_bytes
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bWeights = [device newBufferWithLength:weight_batch_bytes
                                                 options:MTLResourceStorageModeShared];
    if (!bInput || !bGate || !bUp || !bAct || !bExpertOut || !bAccum || !bWeights) {
        fprintf(stderr, "failed to allocate MoE batch buffers\n");
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }
    NSMutableData *outputAccumulator = nil;
    uint8_t *outputAccumulatorBytes = NULL;
    if (use_memory_accumulator) {
        if (expected_input_bytes > (uint64_t)NSUIntegerMax) {
            fprintf(stderr, "MoE batch memory accumulator is too large\n");
            close(input_fd);
            close(output_fd);
            free(assignments);
            return 1;
        }
        outputAccumulator =
            [NSMutableData dataWithLength:(NSUInteger)expected_input_bytes];
        outputAccumulatorBytes = (uint8_t *)outputAccumulator.mutableBytes;
        if (!outputAccumulator || !outputAccumulatorBytes) {
            fprintf(stderr, "failed to allocate MoE batch memory accumulator\n");
            close(input_fd);
            close(output_fd);
            free(assignments);
            return 1;
        }
    }

    int expert_fd = open(layer_file_path, O_RDONLY);
    if (expert_fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", layer_file_path, strerror(errno));
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }
    if (expert_read_advise_align_bytes > 0) {
        advise_sorted_moe_assignment_ranges(expert_fd,
                                            slot_bytes,
                                            layer_file_bytes,
                                            assignments,
                                            route_assignment_count,
                                            expert_read_advise_merge_gap_bytes,
                                            expert_read_advise_align_bytes);
    }
    uint8_t *token_seen = calloc((size_t)batch_tokens, sizeof(uint8_t));
    if (!token_seen) {
        fprintf(stderr, "failed to allocate MoE batch token seen table\n");
        close(expert_fd);
        close(input_fd);
        close(output_fd);
        free(assignments);
        return 1;
    }

    setup_elapsed = CFAbsoluteTimeGetCurrent() - total_started - sort_elapsed;
    uint64_t used_compact_experts = 0;
    uint64_t processed_assignments = 0;
    uint64_t output_zero_rows = 0;
    uint64_t output_read_rows = 0;
    uint64_t cursor = 0;
    while (cursor < route_assignment_count) {
        uint64_t expert = assignments[cursor].expert;
        off_t expert_offset = (off_t)(expert * slot_bytes);
        CFAbsoluteTime expert_read_started = CFAbsoluteTimeGetCurrent();
        if (!read_exact_fd(expert_fd,
                           layer_file_path,
                           bData.contents,
                           (size_t)slot_bytes,
                           expert_offset)) {
            close(expert_fd);
            close(input_fd);
            close(output_fd);
            free(token_seen);
            free(assignments);
            return 1;
        }
        expert_read_elapsed += CFAbsoluteTimeGetCurrent() - expert_read_started;
        [bData didModifyRange:NSMakeRange(0, (NSUInteger)slot_bytes)];
        used_compact_experts++;

        uint64_t group_end = cursor + 1;
        while (group_end < route_assignment_count &&
               assignments[group_end].expert == expert) {
            group_end++;
        }
        uint64_t group_cursor = cursor;
        while (group_cursor < group_end) {
            uint64_t remaining = group_end - group_cursor;
            uint32_t block_count = remaining < (uint64_t)effective_token_block
                ? (uint32_t)remaining
                : effective_token_block;
            float *weights = (float *)bWeights.contents;
            for (uint32_t row = 0; row < block_count; row++) {
                MoEBatchAssignment assignment = assignments[group_cursor + row];
                uint32_t token = assignment.token;
                off_t token_offset = (off_t)((uint64_t)token * row_bytes);
                void *input_row = (uint8_t *)bInput.contents + (uint64_t)row * row_bytes;
                void *accum_row = (uint8_t *)bAccum.contents + (uint64_t)row * row_bytes;
                CFAbsoluteTime input_read_started = CFAbsoluteTimeGetCurrent();
                if (!read_exact_fd(input_fd,
                                   input_path.UTF8String,
                                   input_row,
                                   row_bytes,
                                   token_offset)) {
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                input_read_elapsed += CFAbsoluteTimeGetCurrent() - input_read_started;
                if (token_seen[token]) {
                    CFAbsoluteTime output_read_started = CFAbsoluteTimeGetCurrent();
                    if (use_memory_accumulator) {
                        memcpy(accum_row,
                               outputAccumulatorBytes + (uint64_t)token * row_bytes,
                               row_bytes);
                    } else {
                        if (!read_exact_fd(output_fd,
                                           output_path.UTF8String,
                                           accum_row,
                                           row_bytes,
                                           token_offset)) {
                            close(expert_fd);
                            close(input_fd);
                            close(output_fd);
                            free(token_seen);
                            free(assignments);
                            return 1;
                        }
                    }
                    output_read_elapsed += CFAbsoluteTimeGetCurrent() - output_read_started;
                    output_read_rows++;
                } else {
                    memset(accum_row, 0, row_bytes);
                    token_seen[token] = 1;
                    output_zero_rows++;
                }
                weights[row] = assignment.weight;
            }
            [bInput didModifyRange:NSMakeRange(0, input_batch_bytes)];
            [bAccum didModifyRange:NSMakeRange(0, input_batch_bytes)];
            [bWeights didModifyRange:NSMakeRange(0, weight_batch_bytes)];

            CFAbsoluteTime kernel_started = CFAbsoluteTimeGetCurrent();
            if (info.is_mxfp4 && split_mxfp4_kernel_timing) {
                id<MTLCommandBuffer> swiglu_cmd = [queue commandBuffer];
                if (!swiglu_cmd) {
                    fprintf(stderr,
                            "failed to create MoE batch expert %llu SwiGLU timing command buffer\n",
                            (unsigned long long)expert);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                int swiglu_ok = 0;
                if (mxfp4_moe_token_tile > 1u) {
                    swiglu_ok = encode_mxfp4_swiglu_batch_token_tile(
                        swiglu_cmd, mxfp4_swiglu, bData,
                        info.gate_w.offset, info.gate_s.offset,
                        bData, info.up_w.offset, info.up_s.offset,
                        bInput, bAct, info.intermediate_dim, info.hidden_dim,
                        info.group_size, block_count, mxfp4_moe_token_tile,
                        mxfp4_swiglu_activation_mode);
                } else {
                    swiglu_ok = encode_mxfp4_swiglu_batch(
                        swiglu_cmd, mxfp4_swiglu, bData,
                        info.gate_w.offset, info.gate_s.offset,
                        bData, info.up_w.offset, info.up_s.offset,
                        bInput, bAct, info.intermediate_dim, info.hidden_dim,
                        info.group_size, block_count,
                        mxfp4_swiglu_activation_mode);
                }
                if (!swiglu_ok) {
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                CFAbsoluteTime swiglu_started = CFAbsoluteTimeGetCurrent();
                [swiglu_cmd commit];
                [swiglu_cmd waitUntilCompleted];
                mxfp4_swiglu_kernel_elapsed += CFAbsoluteTimeGetCurrent() - swiglu_started;
                if (swiglu_cmd.status == MTLCommandBufferStatusError) {
                    fprintf(stderr, "MoE batch expert %llu SwiGLU command failed: %s\n",
                            (unsigned long long)expert,
                            swiglu_cmd.error.localizedDescription.UTF8String);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }

                id<MTLCommandBuffer> down_cmd = [queue commandBuffer];
                if (!down_cmd) {
                    fprintf(stderr,
                            "failed to create MoE batch expert %llu down/add timing command buffer\n",
                            (unsigned long long)expert);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                int down_ok = 0;
                if (mxfp4_moe_token_tile > 1u) {
                    down_ok = encode_mxfp4_matvec_weighted_add_batch_token_tile(
                        down_cmd, mxfp4_down_add, bData,
                        info.down_w.offset, info.down_s.offset,
                        bAct, bAccum, bWeights,
                        info.hidden_dim, info.intermediate_dim,
                        info.group_size, block_count, mxfp4_moe_token_tile);
                } else {
                    down_ok = encode_mxfp4_matvec_weighted_add_batch(
                        down_cmd, mxfp4_down_add, bData,
                        info.down_w.offset, info.down_s.offset,
                        bAct, bAccum, bWeights,
                        info.hidden_dim, info.intermediate_dim,
                        info.group_size, block_count);
                }
                if (!down_ok) {
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                CFAbsoluteTime down_started = CFAbsoluteTimeGetCurrent();
                [down_cmd commit];
                [down_cmd waitUntilCompleted];
                mxfp4_down_add_kernel_elapsed += CFAbsoluteTimeGetCurrent() - down_started;
                if (down_cmd.status == MTLCommandBufferStatusError) {
                    fprintf(stderr, "MoE batch expert %llu down/add command failed: %s\n",
                            (unsigned long long)expert,
                            down_cmd.error.localizedDescription.UTF8String);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
            } else {
                id<MTLCommandBuffer> cmd = [queue commandBuffer];
                if (!cmd) {
                    fprintf(stderr, "failed to create MoE batch expert %llu block command buffer\n",
                            (unsigned long long)expert);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                int encoded_ok = 0;
                if (info.is_mxfp4) {
                    encoded_ok = encode_mxfp4_expert_forward_weighted_batch_to(
                        cmd, mxfp4_swiglu, mxfp4_down_add, bData, info,
                        bInput, bAct, bAccum, bWeights, block_count,
                        mxfp4_moe_token_tile, mxfp4_swiglu_activation_mode);
                } else {
                    encoded_ok =
                        encode_expert_forward_batch_to(cmd, dequant, swiglu,
                                                       mxfp4_swiglu, bData, info,
                                                       bInput, bGate, bUp, bAct,
                                                       bExpertOut, block_count) &&
                        encode_weighted_add_batch(cmd, add, bExpertOut, bAccum,
                                                  bWeights, info.hidden_dim,
                                                  block_count);
                }
                if (!encoded_ok) {
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
                [cmd commit];
                [cmd waitUntilCompleted];
                if (cmd.status == MTLCommandBufferStatusError) {
                    fprintf(stderr, "MoE batch expert %llu block command failed: %s\n",
                            (unsigned long long)expert,
                            cmd.error.localizedDescription.UTF8String);
                    close(expert_fd);
                    close(input_fd);
                    close(output_fd);
                    free(token_seen);
                    free(assignments);
                    return 1;
                }
            }
            kernel_elapsed += CFAbsoluteTimeGetCurrent() - kernel_started;

            for (uint32_t row = 0; row < block_count; row++) {
                uint32_t token = assignments[group_cursor + row].token;
                off_t token_offset = (off_t)((uint64_t)token * row_bytes);
                void *accum_row = (uint8_t *)bAccum.contents + (uint64_t)row * row_bytes;
                CFAbsoluteTime output_write_started = CFAbsoluteTimeGetCurrent();
                if (use_memory_accumulator) {
                    memcpy(outputAccumulatorBytes + (uint64_t)token * row_bytes,
                           accum_row,
                           row_bytes);
                } else {
                    if (!write_exact_fd(output_fd,
                                        output_path.UTF8String,
                                        accum_row,
                                        row_bytes,
                                        token_offset)) {
                        close(expert_fd);
                        close(input_fd);
                        close(output_fd);
                        free(token_seen);
                        free(assignments);
                        return 1;
                    }
                }
                output_write_elapsed += CFAbsoluteTimeGetCurrent() - output_write_started;
            }
            group_cursor += block_count;
            processed_assignments += block_count;
        }
        cursor = group_end;
    }

    float last_output0 = 0.0f;
    CFAbsoluteTime final_read_started = CFAbsoluteTimeGetCurrent();
    if (use_memory_accumulator) {
        memcpy(bAccum.contents,
               outputAccumulatorBytes + (uint64_t)(batch_tokens - 1) * row_bytes,
               row_bytes);
    } else {
        if (!read_exact_fd(output_fd,
                           output_path.UTF8String,
                           bAccum.contents,
                           row_bytes,
                           (off_t)((uint64_t)(batch_tokens - 1) * row_bytes))) {
            close(expert_fd);
            close(input_fd);
            close(output_fd);
            free(token_seen);
            free(assignments);
            return 1;
        }
    }
    final_read_elapsed = CFAbsoluteTimeGetCurrent() - final_read_started;
    last_output0 = ((float *)bAccum.contents)[0];
    if (use_memory_accumulator) {
        CFAbsoluteTime output_flush_started = CFAbsoluteTimeGetCurrent();
        if (!write_exact_fd(output_fd,
                            output_path.UTF8String,
                            outputAccumulatorBytes,
                            (size_t)expected_input_bytes,
                            0)) {
            close(expert_fd);
            close(input_fd);
            close(output_fd);
            free(token_seen);
            free(assignments);
            return 1;
        }
        output_write_elapsed += CFAbsoluteTimeGetCurrent() - output_flush_started;
    }

    close(expert_fd);
    close(input_fd);
    close(output_fd);
    free(token_seen);
    free(assignments);
    printf("LargerLM MoE batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  quantization:       %s\n", info.is_mxfp4 ? "mlx-mxfp4" : "affine-int4");
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  compact experts:    %llu\n", (unsigned long long)compact_expert_count);
    printf("  used compact experts: %llu\n", (unsigned long long)used_compact_experts);
    printf("  route assignments:  %llu\n", (unsigned long long)processed_assignments);
    printf("  assignment order:   %s\n", used_assignment_sort ? "qsort" : "pre-sorted");
    printf("  assignment bytes:   %llu\n", (unsigned long long)assignment_bytes);
    printf("  token block mode:   %s\n", token_block == 0 ? "auto" : "fixed");
    if (token_block != 0) {
        printf("  token block request:%u\n", token_block);
    }
    printf("  max expert tokens:  %llu\n", (unsigned long long)max_expert_assignments);
    printf("  token block:        %u\n", effective_token_block);
    if (info.is_mxfp4) {
        printf("  MXFP4 token tile:   %u\n", mxfp4_moe_token_tile);
        printf("  MXFP4 vector SwiGLU:%s\n", vector_mxfp4_swiglu ? "yes" : "no");
        printf("  MXFP4 group32 path: %s\n", group32_mxfp4_specialized ? "yes" : "no");
        printf("  MXFP4 SwiGLU act:   %s\n", mxfp4_swiglu_activation_label);
    }
    printf("  output accumulator: %s\n", use_memory_accumulator ? "memory" : "file");
    printf("  output accum bytes: %llu\n",
           (unsigned long long)output_accumulator_live_bytes);
    printf("  batch buffer bytes: %llu\n", (unsigned long long)batch_buffer_bytes);
    printf("  output zero rows:   %llu\n", (unsigned long long)output_zero_rows);
    printf("  output read rows:   %llu\n", (unsigned long long)output_read_rows);
    printf("  timing sort:        %.6f\n", sort_elapsed);
    printf("  timing setup:       %.6f\n", setup_elapsed);
    printf("  timing expert read: %.6f\n", expert_read_elapsed);
    printf("  timing input read:  %.6f\n", input_read_elapsed);
    printf("  timing output read: %.6f\n", output_read_elapsed);
    printf("  timing kernel:      %.6f\n", kernel_elapsed);
    if (split_mxfp4_kernel_timing) {
        printf("  timing mxfp4 swiglu kernel: %.6f\n", mxfp4_swiglu_kernel_elapsed);
        printf("  timing mxfp4 down add kernel: %.6f\n", mxfp4_down_add_kernel_elapsed);
    }
    printf("  timing output write:%.6f\n", output_write_elapsed);
    printf("  timing final read:  %.6f\n", final_read_elapsed);
    printf("  timing total:       %.6f\n", CFAbsoluteTimeGetCurrent() - total_started);
    printf("  hidden dim:         %u\n", info.hidden_dim);
    printf("  intermediate dim:   %u\n", info.intermediate_dim);
    printf("  slot bytes:         %llu\n", (unsigned long long)slot_bytes);
    printf("  2MB alloc bytes:    %llu\n", (unsigned long long)alloc_size);
    printf("  estimated peak:     %llu\n", (unsigned long long)peak);
    printf("  last output[0]:     %.6f\n", last_output0);
    printf("  output f32:         %s\n", output_path.UTF8String);
    return 0;
}

static int run_moe_forward_batch(id<MTLDevice> device,
                                 const char *layer_file_path,
                                 uint64_t slot_bytes,
                                 uint64_t layer_file_bytes,
                                 MoEBatchRoute *routes,
                                 uint32_t batch_tokens,
                                 uint32_t token_block,
                                 ExpertLayoutInfo info,
                                 NSString *input_path,
                                 NSString *output_path,
                                 uint64_t alloc_size,
                                 uint64_t max_runner_scratch_bytes,
                                 uint64_t expert_read_advise_merge_gap_bytes,
                                 uint64_t expert_read_advise_align_bytes) {
    if (!routes || batch_tokens == 0 || !input_path || !output_path) {
        fprintf(stderr, "invalid MoE batch arguments\n");
        return 1;
    }
    if (slot_bytes == 0 || layer_file_bytes == 0 || layer_file_bytes % slot_bytes != 0) {
        fprintf(stderr, "invalid MoE batch layer size or slot size\n");
        return 1;
    }
    uint64_t compact_expert_count = layer_file_bytes / slot_bytes;
    uint64_t route_assignment_count = 0;
    for (uint32_t token = 0; token < batch_tokens; token++) {
        MoEBatchRoute route = routes[token];
        if (route.count <= 0 || route.count > 64) {
            fprintf(stderr, "invalid route count for token %u\n", token);
            return 1;
        }
        for (int i = 0; i < route.count; i++) {
            if (route.experts[i] >= compact_expert_count) {
                fprintf(stderr,
                        "route token %u expert %llu out of range for %llu compact experts\n",
                        token,
                        (unsigned long long)route.experts[i],
                        (unsigned long long)compact_expert_count);
                return 1;
            }
        }
        route_assignment_count += (uint64_t)route.count;
    }
    if (route_assignment_count == 0 ||
        route_assignment_count > (uint64_t)(SIZE_MAX / sizeof(MoEBatchAssignment)) ||
        route_assignment_count > (uint64_t)(UINT64_MAX / sizeof(MoEBatchAssignment))) {
        fprintf(stderr, "invalid MoE batch assignment count %llu\n",
                (unsigned long long)route_assignment_count);
        return 1;
    }
    MoEBatchAssignment *assignments =
        calloc((size_t)route_assignment_count, sizeof(MoEBatchAssignment));
    if (!assignments) {
        fprintf(stderr, "failed to allocate MoE batch assignments\n");
        return 1;
    }
    uint64_t assignment_cursor = 0;
    for (uint32_t token = 0; token < batch_tokens; token++) {
        MoEBatchRoute route = routes[token];
        for (int i = 0; i < route.count; i++) {
            assignments[assignment_cursor].expert = route.experts[i];
            assignments[assignment_cursor].token = token;
            assignments[assignment_cursor].weight = route.weights[i];
            assignment_cursor++;
        }
    }
    return run_moe_forward_batch_assignments(device,
                                             layer_file_path,
                                             slot_bytes,
                                             layer_file_bytes,
                                             assignments,
                                             route_assignment_count,
                                             0,
                                             batch_tokens,
                                             token_block,
                                             info,
                                             input_path,
                                             output_path,
                                             alloc_size,
                                             max_runner_scratch_bytes,
                                             expert_read_advise_merge_gap_bytes,
                                             expert_read_advise_align_bytes);
}

static NSString *moe_plan_string(NSDictionary *job,
                                 NSString *primary_key,
                                 NSString *secondary_key,
                                 const char *label,
                                 int required) {
    id value = job[primary_key];
    if (![value isKindOfClass:[NSString class]] && secondary_key) {
        value = job[secondary_key];
    }
    if (![value isKindOfClass:[NSString class]] ||
        ((NSString *)value).length == 0) {
        if (required) {
            fprintf(stderr, "%s must be a non-empty string\n", label);
        }
        return nil;
    }
    return (NSString *)value;
}

static int moe_plan_optional_u64(NSDictionary *job,
                                 NSString *key,
                                 const char *label,
                                 int require_positive,
                                 uint64_t fallback,
                                 uint64_t *out) {
    id value = job[key];
    if (!value || value == [NSNull null]) {
        *out = fallback;
        return 1;
    }
    return read_json_u64_number(value, label, require_positive, out);
}

static int read_optional_json_bool(NSDictionary *job,
                                   NSString *key,
                                   const char *label,
                                   int fallback,
                                   int *out) {
    id value = job[key];
    if (!value || value == [NSNull null]) {
        *out = fallback ? 1 : 0;
        return 1;
    }
    if (![value isKindOfClass:[NSNumber class]]) {
        fprintf(stderr, "%s must be a boolean\n", label);
        return 0;
    }
    NSNumber *number = (NSNumber *)value;
    const char *type = number.objCType;
    if (strcmp(type, "c") != 0 && strcmp(type, "B") != 0) {
        fprintf(stderr, "%s must be a boolean\n", label);
        return 0;
    }
    *out = number.boolValue ? 1 : 0;
    return 1;
}

static int moe_plan_token_block(NSDictionary *job, uint32_t *out) {
    id value = job[@"moe_token_block"];
    if (!value || value == [NSNull null]) {
        *out = 0;
        return 1;
    }
    if ([value isKindOfClass:[NSString class]]) {
        NSString *text = [(NSString *)value stringByTrimmingCharactersInSet:
                          [NSCharacterSet whitespaceAndNewlineCharacterSet]];
        if ([text isEqualToString:@"auto"]) {
            *out = 0;
            return 1;
        }
        uint64_t parsed = 0;
        if (!parse_u64_strict_value(text, "plan job moe_token_block", &parsed)) {
            return 0;
        }
        if (parsed == 0 || parsed > UINT32_MAX) {
            fprintf(stderr, "plan job moe_token_block must be auto or in 1..%u\n",
                    UINT32_MAX);
            return 0;
        }
        *out = (uint32_t)parsed;
        return 1;
    }
    uint64_t parsed = 0;
    if (!read_json_u64_number(value, "plan job moe_token_block", 1, &parsed)) {
        return 0;
    }
    if (parsed > UINT32_MAX) {
        fprintf(stderr, "plan job moe_token_block must be auto or in 1..%u\n",
                UINT32_MAX);
        return 0;
    }
    *out = (uint32_t)parsed;
    return 1;
}

static int run_moe_batch_plan(id<MTLDevice> device, NSString *plan_path) {
    if (!device || !plan_path) {
        fprintf(stderr, "invalid MoE batch plan arguments\n");
        return 2;
    }
    NSDictionary *plan = load_json(plan_path);
    if (!plan) return 1;
    uint64_t version = 0;
    if (!read_json_u64_number(plan[@"version"],
                              "MoE batch plan version",
                              1,
                              &version) ||
        version != 1) {
        fprintf(stderr, "MoE batch plan version must be 1\n");
        return 1;
    }
    NSArray *jobs = plan[@"jobs"];
    if (![jobs isKindOfClass:[NSArray class]] || jobs.count == 0) {
        fprintf(stderr, "MoE batch plan must contain at least one job\n");
        return 1;
    }
    CFAbsoluteTime plan_started = CFAbsoluteTimeGetCurrent();
    for (NSUInteger index = 0; index < jobs.count; index++) {
        @autoreleasepool {
            id job_obj = jobs[index];
            if (![job_obj isKindOfClass:[NSDictionary class]]) {
                fprintf(stderr, "MoE batch plan job %lu must be an object\n",
                        (unsigned long)index);
                return 1;
            }
            NSDictionary *job = (NSDictionary *)job_obj;
            NSString *layout_path =
                moe_plan_string(job, @"layout", @"layout_path", "plan job layout", 1);
            NSString *input_f32 =
                moe_plan_string(job, @"input_f32", @"input_f32_path", "plan job input_f32", 1);
            NSString *output_f32 =
                moe_plan_string(job, @"output_f32", @"output_f32_path", "plan job output_f32", 1);
            NSString *routes_json =
                moe_plan_string(job, @"routes_json", @"routes_json_path", "plan job routes_json", 0);
            NSString *routes_bin =
                moe_plan_string(job, @"routes_bin", @"routes_bin_path", "plan job routes_bin", 0);
            if (!layout_path || !input_f32 || !output_f32 ||
                ((routes_json ? 1 : 0) + (routes_bin ? 1 : 0) != 1)) {
                fprintf(stderr,
                        "MoE batch plan job %lu requires layout, input_f32, output_f32, "
                        "and exactly one of routes_json/routes_bin\n",
                        (unsigned long)index);
                return 1;
            }
            uint64_t layer_id = 0;
            uint64_t batch_tokens_u64 = 0;
            uint64_t max_k_u64 = 0;
            uint64_t max_slot_mib = 0;
            uint64_t max_runner_scratch_mib = 0;
            uint64_t expert_read_advise_merge_gap_bytes = 0;
            uint64_t expert_read_advise_align_bytes = 0;
            if (!read_json_u64_number(job[@"layer"],
                                      "plan job layer",
                                      0,
                                      &layer_id) ||
                !read_json_u64_number(job[@"batch_tokens"],
                                      "plan job batch_tokens",
                                      1,
                                      &batch_tokens_u64) ||
                !moe_plan_optional_u64(job,
                                       @"max_k",
                                       "plan job max_k",
                                       1,
                                       8,
                                       &max_k_u64) ||
                !moe_plan_optional_u64(job,
                                       @"max_slot_mib",
                                       "plan job max_slot_mib",
                                       1,
                                       256,
                                       &max_slot_mib) ||
                !moe_plan_optional_u64(job,
                                       @"max_runner_scratch_mib",
                                       "plan job max_runner_scratch_mib",
                                       1,
                                       4096,
                                       &max_runner_scratch_mib) ||
                !moe_plan_optional_u64(job,
                                       @"expert_read_advise_merge_gap_bytes",
                                       "plan job expert_read_advise_merge_gap_bytes",
                                       0,
                                       0,
                                       &expert_read_advise_merge_gap_bytes) ||
                !moe_plan_optional_u64(job,
                                       @"expert_read_advise_align_bytes",
                                       "plan job expert_read_advise_align_bytes",
                                       0,
                                       0,
                                       &expert_read_advise_align_bytes)) {
                return 1;
            }
            if (batch_tokens_u64 == 0 || batch_tokens_u64 > UINT32_MAX) {
                fprintf(stderr, "plan job batch_tokens must be in 1..%u\n",
                        UINT32_MAX);
                return 1;
            }
            if (max_k_u64 == 0 || max_k_u64 > 64) {
                fprintf(stderr, "plan job max_k must be in 1..64\n");
                return 1;
            }
            uint32_t moe_token_block = 0;
            if (!moe_plan_token_block(job, &moe_token_block)) {
                return 1;
            }
            uint64_t max_slot_bytes = 0;
            uint64_t max_runner_scratch_bytes = 0;
            if (!mib_to_bytes_arg(max_slot_mib,
                                  "plan job max_slot_mib",
                                  &max_slot_bytes) ||
                !mib_to_bytes_arg(max_runner_scratch_mib,
                                  "plan job max_runner_scratch_mib",
                                  &max_runner_scratch_bytes)) {
                return 1;
            }

            NSDictionary *layout = load_json(layout_path);
            if (!layout) return 1;
            NSArray *layers = layout[@"layers"];
            if (![layers isKindOfClass:[NSArray class]]) {
                fprintf(stderr, "layout missing layers array\n");
                return 1;
            }
            NSDictionary *layer = find_layer(layers, layer_id);
            if (!layer) {
                fprintf(stderr, "layer %llu not found in layout\n",
                        (unsigned long long)layer_id);
                return 1;
            }
            NSString *layer_file = nil;
            uint64_t num_experts = 0;
            uint64_t slot_bytes = 0;
            uint64_t layer_file_bytes = 0;
            if (!parse_expert_layer_fields(layer,
                                           max_slot_bytes,
                                           &layer_file,
                                           &num_experts,
                                           &slot_bytes,
                                           &layer_file_bytes)) {
                return 1;
            }
            NSString *layout_dir = [layout_path stringByDeletingLastPathComponent];
            NSString *expert_path = [layout_dir stringByAppendingPathComponent:layer_file];
            if (!validate_expert_layer_file_size(expert_path, layer_file_bytes)) {
                return 1;
            }
            ExpertLayoutInfo expert_info = {0};
            if (!parse_expert_layout(layout, layer, &expert_info)) {
                return 1;
            }

            MoEBatchRoute *preloaded_routes = NULL;
            MoEBatchAssignment *preloaded_assignments = NULL;
            uint64_t preloaded_assignment_count = 0;
            int preloaded_assignments_sorted = 0;
            const int max_k = (int)max_k_u64;
            if (routes_json) {
                if (!load_moe_batch_routes(routes_json,
                                           (uint32_t)batch_tokens_u64,
                                           max_k,
                                           num_experts,
                                           &preloaded_routes)) {
                    return 1;
                }
            } else {
                if (!load_moe_batch_assignments_bin(routes_bin,
                                                    (uint32_t)batch_tokens_u64,
                                                    max_k,
                                                    num_experts,
                                                    max_runner_scratch_bytes,
                                                    &preloaded_assignments,
                                                    &preloaded_assignment_count,
                                                    &preloaded_assignments_sorted)) {
                    return 1;
                }
            }

            uint64_t alloc_size = align_up_u64(slot_bytes, 2 * 1024 * 1024);
            printf("LargerLM MoE batch plan job\n");
            printf("  job:                 %lu/%lu\n",
                   (unsigned long)(index + 1),
                   (unsigned long)jobs.count);
            printf("  plan:                %s\n", plan_path.UTF8String);
            printf("  layer:               %llu\n",
                   (unsigned long long)layer_id);
            int status = 0;
            if (routes_json) {
                status = run_moe_forward_batch(device,
                                               expert_path.UTF8String,
                                               slot_bytes,
                                               num_experts * slot_bytes,
                                               preloaded_routes,
                                               (uint32_t)batch_tokens_u64,
                                               moe_token_block,
                                               expert_info,
                                               input_f32,
                                               output_f32,
                                               alloc_size,
                                               max_runner_scratch_bytes,
                                               expert_read_advise_merge_gap_bytes,
                                               expert_read_advise_align_bytes);
                free(preloaded_routes);
            } else {
                status = run_moe_forward_batch_assignments(
                    device,
                    expert_path.UTF8String,
                    slot_bytes,
                    num_experts * slot_bytes,
                    preloaded_assignments,
                    preloaded_assignment_count,
                    preloaded_assignments_sorted,
                    (uint32_t)batch_tokens_u64,
                    moe_token_block,
                    expert_info,
                    input_f32,
                    output_f32,
                    alloc_size,
                    max_runner_scratch_bytes,
                    expert_read_advise_merge_gap_bytes,
                    expert_read_advise_align_bytes);
            }
            if (status != 0) return status;
        }
    }
    printf("LargerLM MoE batch plan\n");
    printf("  jobs:                %lu\n", (unsigned long)jobs.count);
    printf("  plan timing total:   %.6f\n",
           CFAbsoluteTimeGetCurrent() - plan_started);
    return 0;
}

static int run_moe_batch_plan_server_jsonl(id<MTLDevice> device) {
    if (!device) {
        fprintf(stderr, "invalid MoE batch plan server arguments\n");
        return 2;
    }
    printf("LargerLM MoE batch plan server\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  protocol:           jsonl\n");
    fflush(stdout);

    char *line = NULL;
    size_t line_cap = 0;
    ssize_t line_len = 0;
    uint64_t job_count = 0;
    CFAbsoluteTime server_started = CFAbsoluteTimeGetCurrent();
    while ((line_len = getline(&line, &line_cap, stdin)) >= 0) {
        @autoreleasepool {
            while (line_len > 0 &&
                   (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
                line[line_len - 1] = '\0';
                line_len--;
            }
            if (line_len == 0) {
                continue;
            }
            NSData *data = [NSData dataWithBytes:line length:(NSUInteger)line_len];
            NSError *error = nil;
            id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
            if (error || ![obj isKindOfClass:[NSDictionary class]]) {
                fprintf(stderr, "failed to parse MoE batch plan server JSON: %s\n",
                        error.localizedDescription.UTF8String);
                free(line);
                return 1;
            }
            NSDictionary *request = (NSDictionary *)obj;
            NSString *command = request[@"command"];
            if ([command isKindOfClass:[NSString class]] &&
                [command isEqualToString:@"quit"]) {
                break;
            }
            NSString *plan_path =
                moe_plan_string(request,
                                @"batch_plan_json",
                                @"plan_path",
                                "server batch_plan_json",
                                1);
            if (!plan_path) {
                free(line);
                return 1;
            }
            job_count++;
            printf("LargerLM MoE batch plan server request\n");
            printf("  request:             %llu\n",
                   (unsigned long long)job_count);
            printf("  plan:                %s\n", plan_path.UTF8String);
            fflush(stdout);
            int status = run_moe_batch_plan(device, plan_path);
            if (status != 0) {
                printf("  server request:      failed\n");
                fflush(stdout);
                free(line);
                return status;
            }
            printf("  server request:      ok\n");
            fflush(stdout);
        }
    }
    free(line);
    printf("LargerLM MoE batch plan server done\n");
    printf("  requests:            %llu\n", (unsigned long long)job_count);
    printf("  server timing total: %.6f\n",
           CFAbsoluteTimeGetCurrent() - server_started);
    fflush(stdout);
    return 0;
}

static NSString *resident_linear_server_backend(NSDictionary *request) {
    id value = request[@"prefill_linear_backend"];
    if ((!value || value == [NSNull null]) && request[@"backend"]) {
        value = request[@"backend"];
    }
    if (!value || value == [NSNull null]) {
        return @"custom-metal";
    }
    if (![value isKindOfClass:[NSString class]] ||
        ((NSString *)value).length == 0) {
        fprintf(stderr,
                "server prefill_linear_backend must be a non-empty string\n");
        return nil;
    }
    NSString *backend = (NSString *)value;
    if (![backend isEqualToString:@"custom-metal"] &&
        ![backend isEqualToString:@"mpsgraph-f32"] &&
        ![backend isEqualToString:@"mps-matrix-f32"]) {
        fprintf(stderr,
                "server prefill_linear_backend must be custom-metal, mpsgraph-f32, or mps-matrix-f32\n");
        return nil;
    }
    return backend;
}

static int run_resident_linear_batch_plan_server_jsonl(id<MTLDevice> device) {
    if (!device) {
        fprintf(stderr, "invalid resident linear batch server arguments\n");
        return 2;
    }
    printf("LargerLM resident batch linear server\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  protocol:           jsonl\n");
    fflush(stdout);

    char *line = NULL;
    size_t line_cap = 0;
    ssize_t line_len = 0;
    uint64_t request_count = 0;
    CFAbsoluteTime server_started = CFAbsoluteTimeGetCurrent();
    while ((line_len = getline(&line, &line_cap, stdin)) >= 0) {
        @autoreleasepool {
            while (line_len > 0 &&
                   (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
                line[line_len - 1] = '\0';
                line_len--;
            }
            if (line_len == 0) {
                continue;
            }
            NSData *data = [NSData dataWithBytes:line length:(NSUInteger)line_len];
            NSError *error = nil;
            id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
            if (error || ![obj isKindOfClass:[NSDictionary class]]) {
                fprintf(stderr,
                        "failed to parse resident linear batch server JSON: %s\n",
                        error.localizedDescription.UTF8String);
                free(line);
                return 1;
            }
            NSDictionary *request = (NSDictionary *)obj;
            NSString *command = request[@"command"];
            if ([command isKindOfClass:[NSString class]] &&
                [command isEqualToString:@"quit"]) {
                break;
            }

            NSString *resident_layout_path =
                moe_plan_string(request,
                                @"resident_layout",
                                @"resident_layout_path",
                                "server resident_layout",
                                1);
            NSString *tensor_suffix =
                moe_plan_string(request,
                                @"tensor_suffix",
                                nil,
                                "server tensor_suffix",
                                1);
            NSString *input_f32 =
                moe_plan_string(request,
                                @"input_f32",
                                @"input_f32_path",
                                "server input_f32",
                                1);
            NSString *output_f32 =
                moe_plan_string(request,
