                start_u64 + batch_u64 - 1 > UINT32_MAX) {
                fprintf(stderr,
                        "server num_heads, qk_nope_dim, rope_dim, start_position, and batch_tokens are out of range\n");
                free(line);
                return 1;
            }
            float theta = 10000.0f;
            id theta_value = request[@"rope_theta"];
            if (theta_value && theta_value != [NSNull null] &&
                !read_json_f32_number(theta_value, "server rope_theta", &theta)) {
                free(line);
                return 1;
            }
            int interleave = 0;
            id interleave_value = request[@"rope_interleave"];
            if (interleave_value && interleave_value != [NSNull null]) {
                if (![interleave_value isKindOfClass:[NSNumber class]]) {
                    fprintf(stderr, "server rope_interleave must be a boolean\n");
                    free(line);
                    return 1;
                }
                NSNumber *interleave_number = (NSNumber *)interleave_value;
                const char *type = interleave_number.objCType;
                if (strcmp(type, "c") != 0 && strcmp(type, "B") != 0) {
                    fprintf(stderr, "server rope_interleave must be a boolean\n");
                    free(line);
                    return 1;
                }
                interleave = interleave_number.boolValue ? 1 : 0;
            }
            uint64_t max_runner_scratch_bytes = 0;
            if (!mib_to_bytes_arg(max_runner_scratch_mib,
                                  "server max_runner_scratch_mib",
                                  &max_runner_scratch_bytes)) {
                free(line);
                return 1;
            }

            request_count++;
            printf("LargerLM RoPE split batch server request\n");
            printf("  request:             %llu\n",
                   (unsigned long long)request_count);
            printf("  start position:      %llu\n",
                   (unsigned long long)start_u64);
            printf("  batch tokens:        %llu\n",
                   (unsigned long long)batch_u64);
            fflush(stdout);
            int status = run_rope_split_batch(device,
                                              q_b_f32,
                                              k_f32,
                                              out_q_nope,
                                              out_q_rope,
                                              out_q,
                                              out_k,
                                              (uint32_t)num_heads_u64,
                                              (uint32_t)qk_nope_u64,
                                              (uint32_t)rope_dim_u64,
                                              (uint32_t)start_u64,
                                              (uint32_t)batch_u64,
                                              theta,
                                              interleave,
                                              max_runner_scratch_bytes);
            if (status != 0) {
                printf("  server request:      failed\n");
                fflush(stdout);
                free(line);
                return status;
            }
            printf("  server request:      ok\n");
            fflush(stdout);
        }
    }
    free(line);
    printf("LargerLM RoPE split batch server done\n");
    printf("  requests:            %llu\n", (unsigned long long)request_count);
    printf("  server timing total: %.6f\n",
           CFAbsoluteTimeGetCurrent() - server_started);
    fflush(stdout);
    return 0;
}

static int run_resident_rmsnorm_batch_server_jsonl(id<MTLDevice> device) {
    if (!device) {
        fprintf(stderr, "invalid RMSNorm batch server arguments\n");
        return 2;
    }
    printf("LargerLM resident RMSNorm batch server\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  protocol:           jsonl\n");
    fflush(stdout);

    char *line = NULL;
    size_t line_cap = 0;
    ssize_t line_len = 0;
    uint64_t request_count = 0;
    CFAbsoluteTime server_started = CFAbsoluteTimeGetCurrent();
    while ((line_len = getline(&line, &line_cap, stdin)) >= 0) {
        @autoreleasepool {
            while (line_len > 0 &&
                   (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
                line[line_len - 1] = '\0';
                line_len--;
            }
            if (line_len == 0) {
                continue;
            }
            NSData *data = [NSData dataWithBytes:line length:(NSUInteger)line_len];
            NSError *error = nil;
            id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
            if (error || ![obj isKindOfClass:[NSDictionary class]]) {
                fprintf(stderr,
                        "failed to parse RMSNorm batch server JSON: %s\n",
                        error.localizedDescription.UTF8String);
                free(line);
                return 1;
            }
            NSDictionary *request = (NSDictionary *)obj;
            NSString *command = request[@"command"];
            if ([command isKindOfClass:[NSString class]] &&
                [command isEqualToString:@"quit"]) {
                break;
            }

            NSString *resident_layout =
                moe_plan_string(request,
                                @"resident_layout",
                                @"resident_layout_path",
                                "server resident_layout",
                                1);
            NSString *norm_suffix =
                moe_plan_string(request,
                                @"norm_suffix",
                                @"norm_suffix",
                                "server norm_suffix",
                                1);
            NSString *input_f32 =
                moe_plan_string(request,
                                @"input_f32",
                                @"input_f32_path",
                                "server input_f32",
                                1);
            NSString *output_f32 =
                moe_plan_string(request,
                                @"output_f32",
                                @"output_f32_path",
                                "server output_f32",
                                1);
            if (!resident_layout || !norm_suffix || !input_f32 || !output_f32) {
                free(line);
                return 1;
            }

            uint64_t layer_u64 = 0;
            uint64_t batch_u64 = 0;
            uint64_t max_runner_scratch_mib = 0;
            if (!read_json_u64_number(request[@"layer"],
                                      "server layer",
                                      0,
                                      &layer_u64) ||
                !read_json_u64_number(request[@"batch_tokens"],
                                      "server batch_tokens",
                                      1,
                                      &batch_u64) ||
                !moe_plan_optional_u64(request,
                                       @"max_runner_scratch_mib",
                                       "server max_runner_scratch_mib",
                                       1,
                                       4096,
                                       &max_runner_scratch_mib)) {
                free(line);
                return 1;
            }
            if (layer_u64 == UINT64_MAX || batch_u64 > UINT32_MAX) {
                fprintf(stderr,
                        "server layer and batch_tokens are out of range\n");
                free(line);
                return 1;
            }
            float eps = 1e-5f;
            id eps_value = request[@"rms_norm_eps"];
            if (eps_value && eps_value != [NSNull null] &&
                !read_json_f32_number(eps_value, "server rms_norm_eps", &eps)) {
                free(line);
                return 1;
            }
            if (eps < 0.0f) {
                fprintf(stderr, "server rms_norm_eps must be non-negative\n");
                free(line);
                return 1;
            }
            uint64_t max_runner_scratch_bytes = 0;
            if (!mib_to_bytes_arg(max_runner_scratch_mib,
                                  "server max_runner_scratch_mib",
                                  &max_runner_scratch_bytes)) {
                free(line);
                return 1;
            }

            request_count++;
            printf("LargerLM resident RMSNorm batch server request\n");
            printf("  request:             %llu\n",
                   (unsigned long long)request_count);
            printf("  layer:               %llu\n",
                   (unsigned long long)layer_u64);
            printf("  batch tokens:        %llu\n",
                   (unsigned long long)batch_u64);
            fflush(stdout);
            int status = run_resident_rmsnorm_batch(device,
                                                    resident_layout,
                                                    layer_u64,
                                                    norm_suffix,
                                                    input_f32,
                                                    output_f32,
                                                    (uint32_t)batch_u64,
                                                    eps,
                                                    max_runner_scratch_bytes);
            if (status != 0) {
                printf("  server request:      failed\n");
                fflush(stdout);
                free(line);
                return status;
            }
            printf("  server request:      ok\n");
            fflush(stdout);
        }
    }
    free(line);
    printf("LargerLM resident RMSNorm batch server done\n");
    printf("  requests:            %llu\n", (unsigned long long)request_count);
    printf("  server timing total: %.6f\n",
           CFAbsoluteTimeGetCurrent() - server_started);
    fflush(stdout);
    return 0;
}

static int run_mla_attention_batch_server_jsonl(id<MTLDevice> device) {
    if (!device) {
        fprintf(stderr, "invalid MLA attention batch server arguments\n");
        return 2;
    }
    printf("LargerLM MLA attention batch server\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  protocol:           jsonl\n");
    fflush(stdout);

    char *line = NULL;
    size_t line_cap = 0;
    ssize_t line_len = 0;
    uint64_t request_count = 0;
    CFAbsoluteTime server_started = CFAbsoluteTimeGetCurrent();
    while ((line_len = getline(&line, &line_cap, stdin)) >= 0) {
        @autoreleasepool {
            while (line_len > 0 &&
                   (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
                line[line_len - 1] = '\0';
                line_len--;
            }
            if (line_len == 0) {
                continue;
            }
            NSData *data = [NSData dataWithBytes:line length:(NSUInteger)line_len];
            NSError *error = nil;
            id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
            if (error || ![obj isKindOfClass:[NSDictionary class]]) {
                fprintf(stderr,
                        "failed to parse MLA attention batch server JSON: %s\n",
                        error.localizedDescription.UTF8String);
                free(line);
                return 1;
            }
            NSDictionary *request = (NSDictionary *)obj;
            NSString *command = request[@"command"];
            if ([command isKindOfClass:[NSString class]] &&
                [command isEqualToString:@"quit"]) {
                break;
            }

            NSString *resident_layout =
                moe_plan_string(request,
                                @"resident_layout",
                                @"resident_layout_path",
                                "server resident_layout",
                                1);
            NSString *cache_layout =
                moe_plan_string(request,
                                @"cache_layout",
                                @"cache_layout_path",
                                "server cache_layout",
                                1);
            NSString *cache_file =
                moe_plan_string(request,
                                @"cache_file",
                                @"cache_file_path",
                                "server cache_file",
                                1);
            NSString *q_nope =
                moe_plan_string(request,
                                @"q_nope_f32",
                                @"q_nope_f32_path",
                                "server q_nope_f32",
                                1);
            NSString *q_rope =
                moe_plan_string(request,
                                @"q_rope_f32",
                                @"q_rope_f32_path",
                                "server q_rope_f32",
                                1);
            NSString *output_f32 =
                moe_plan_string(request,
                                @"output_f32",
                                @"output_f32_path",
                                "server output_f32",
                                1);
            NSString *indices_u32 =
                moe_plan_string(request,
                                @"indices_u32",
                                @"indices_u32_path",
                                "server indices_u32",
                                0);
            NSString *mla_kv_b_cache_dir =
                moe_plan_string(request,
                                @"mla_kv_b_cache_dir",
                                nil,
                                "server mla_kv_b_cache_dir",
                                0);
            if (!resident_layout || !cache_layout || !cache_file || !q_nope ||
                !q_rope || !output_f32) {
                free(line);
                return 1;
            }

            id index_topk_value = request[@"index_topk"];
            int has_index_topk = index_topk_value && index_topk_value != [NSNull null];
            int indexed = (indices_u32 != nil || has_index_topk);
            if ((indices_u32 != nil) != has_index_topk) {
                fprintf(stderr,
                        "server indices_u32 and index_topk must be provided together\n");
                free(line);
                return 1;
            }

            uint64_t layer_u64 = 0;
            uint64_t context_u64 = 0;
            uint64_t batch_u64 = 0;
            uint64_t start_u64 = 0;
            uint64_t index_topk_u64 = 0;
            uint64_t num_heads_u64 = 0;
            uint64_t kv_lora_u64 = 0;
            uint64_t qk_nope_u64 = 0;
            uint64_t rope_dim_u64 = 0;
            uint64_t v_head_u64 = 0;
            uint64_t pos_offset_u64 = 0;
            uint64_t max_cache_file_mib = 0;
            uint64_t max_cache_read_mib = 0;
            uint64_t max_matrix_mib = 0;
            uint64_t max_runner_scratch_mib = 0;
            if (!read_json_u64_number(request[@"layer"],
                                      "server layer",
                                      0,
                                      &layer_u64) ||
                !read_json_u64_number(request[@"context_length"],
                                      "server context_length",
                                      1,
                                      &context_u64) ||
                !read_json_u64_number(request[@"batch_tokens"],
                                      "server batch_tokens",
                                      1,
                                      &batch_u64) ||
                !read_json_u64_number(request[@"num_heads"],
                                      "server num_heads",
                                      1,
                                      &num_heads_u64) ||
                !moe_plan_optional_u64(request,
                                       @"kv_lora_dim",
                                       "server kv_lora_dim",
                                       0,
                                       0,
                                       &kv_lora_u64) ||
                !read_json_u64_number(request[@"qk_nope_dim"],
                                      "server qk_nope_dim",
                                      1,
                                      &qk_nope_u64) ||
                !read_json_u64_number(request[@"rope_dim"],
                                      "server rope_dim",
                                      1,
                                      &rope_dim_u64) ||
                !read_json_u64_number(request[@"v_head_dim"],
                                      "server v_head_dim",
                                      1,
                                      &v_head_u64) ||
                !moe_plan_optional_u64(request,
                                       @"cache_position_offset",
                                       "server cache_position_offset",
                                       0,
                                       0,
                                       &pos_offset_u64) ||
                !moe_plan_optional_u64(request,
                                       @"max_cache_file_mib",
                                       "server max_cache_file_mib",
                                       1,
                                       32768,
                                       &max_cache_file_mib) ||
                !moe_plan_optional_u64(request,
                                       @"max_cache_read_mib",
                                       "server max_cache_read_mib",
                                       1,
                                       256,
                                       &max_cache_read_mib) ||
                !moe_plan_optional_u64(request,
                                       @"max_resident_matrix_mib",
                                       "server max_resident_matrix_mib",
                                       1,
                                       512,
                                       &max_matrix_mib) ||
                !moe_plan_optional_u64(request,
                                       @"max_runner_scratch_mib",
                                       "server max_runner_scratch_mib",
                                       1,
                                       4096,
                                       &max_runner_scratch_mib)) {
                free(line);
                return 1;
            }
            if (indexed) {
                if (!read_json_u64_number(index_topk_value,
                                          "server index_topk",
                                          1,
                                          &index_topk_u64)) {
                    free(line);
                    return 1;
                }
            } else if (!read_json_u64_number(request[@"start_position"],
                                             "server start_position",
                                             0,
                                             &start_u64)) {
                free(line);
                return 1;
            }
            if (layer_u64 == UINT64_MAX ||
                context_u64 > UINT32_MAX ||
                batch_u64 > UINT32_MAX ||
                (!indexed && (start_u64 > UINT32_MAX ||
                              start_u64 + batch_u64 > context_u64)) ||
                (indexed && index_topk_u64 > UINT32_MAX) ||
                num_heads_u64 > UINT32_MAX ||
                kv_lora_u64 > UINT32_MAX ||
                qk_nope_u64 > UINT32_MAX ||
                rope_dim_u64 > UINT32_MAX ||
                v_head_u64 > UINT32_MAX ||
                pos_offset_u64 > UINT32_MAX) {
                fprintf(stderr,
                        "server MLA attention numeric arguments are out of range\n");
                free(line);
                return 1;
            }

            float theta = 10000.0f;
            float scale = 0.0f;
            id theta_value = request[@"rope_theta"];
            id scale_value = request[@"attention_scale"];
            if ((theta_value && theta_value != [NSNull null] &&
                 !read_json_f32_number(theta_value, "server rope_theta", &theta)) ||
                (scale_value && scale_value != [NSNull null] &&
                 !read_json_f32_number(scale_value, "server attention_scale", &scale))) {
                free(line);
                return 1;
            }
            int interleave = 0;
            if (!read_optional_json_bool(request,
                                         @"rope_interleave",
                                         "server rope_interleave",
                                         0,
                                         &interleave)) {
                free(line);
                return 1;
            }
            uint64_t max_cache_file_bytes = 0;
            uint64_t max_cache_read_bytes = 0;
            uint64_t max_matrix_bytes = 0;
            uint64_t max_runner_scratch_bytes = 0;
            if (!mib_to_bytes_arg(max_cache_file_mib,
                                  "server max_cache_file_mib",
                                  &max_cache_file_bytes) ||
                !mib_to_bytes_arg(max_cache_read_mib,
                                  "server max_cache_read_mib",
                                  &max_cache_read_bytes) ||
                !mib_to_bytes_arg(max_matrix_mib,
                                  "server max_resident_matrix_mib",
                                  &max_matrix_bytes) ||
                !mib_to_bytes_arg(max_runner_scratch_mib,
                                  "server max_runner_scratch_mib",
                                  &max_runner_scratch_bytes)) {
                free(line);
                return 1;
            }
            if (!validate_decode_cache_backing(cache_layout,
                                               cache_file,
                                               max_cache_file_bytes)) {
                free(line);
                return 1;
            }

            request_count++;
            printf("LargerLM MLA attention batch server request\n");
            printf("  request:             %llu\n",
                   (unsigned long long)request_count);
            printf("  layer:               %llu\n",
                   (unsigned long long)layer_u64);
            printf("  indexed:             %s\n", indexed ? "yes" : "no");
            printf("  batch tokens:        %llu\n",
                   (unsigned long long)batch_u64);
            fflush(stdout);
            int status = 0;
            if (indexed) {
                status = run_mla_attention_indexed_batch(
                    device,
                    resident_layout,
                    cache_layout,
                    cache_file,
                    layer_u64,
                    q_nope,
                    q_rope,
                    indices_u32,
                    output_f32,
                    (uint32_t)context_u64,
                    (uint32_t)batch_u64,
                    (uint32_t)index_topk_u64,
                    (uint32_t)num_heads_u64,
                    (uint32_t)kv_lora_u64,
                    (uint32_t)qk_nope_u64,
                    (uint32_t)rope_dim_u64,
                    (uint32_t)v_head_u64,
                    (uint32_t)pos_offset_u64,
                    scale,
                    theta,
                    interleave,
                    mla_kv_b_cache_dir,
                    max_cache_file_bytes,
                    max_cache_read_bytes,
                    max_matrix_bytes,
                    max_runner_scratch_bytes);
            } else {
                status = run_mla_attention_batch(device,
                                                 resident_layout,
                                                 cache_layout,
                                                 cache_file,
                                                 layer_u64,
                                                 q_nope,
                                                 q_rope,
                                                 output_f32,
                                                 (uint32_t)context_u64,
                                                 (uint32_t)start_u64,
                                                 (uint32_t)batch_u64,
                                                 (uint32_t)num_heads_u64,
                                                 (uint32_t)kv_lora_u64,
                                                 (uint32_t)qk_nope_u64,
                                                 (uint32_t)rope_dim_u64,
                                                 (uint32_t)v_head_u64,
                                                 (uint32_t)pos_offset_u64,
                                                 scale,
                                                 theta,
                                                 interleave,
                                                 mla_kv_b_cache_dir,
                                                 max_cache_file_bytes,
                                                 max_cache_read_bytes,
                                                 max_matrix_bytes,
                                                 max_runner_scratch_bytes,
                                                 NULL);
            }
            if (status != 0) {
                printf("  server request:      failed\n");
                fflush(stdout);
                free(line);
                return status;
            }
            printf("  server request:      ok\n");
            fflush(stdout);
        }
    }
    free(line);
    printf("LargerLM MLA attention batch server done\n");
    printf("  requests:            %llu\n", (unsigned long long)request_count);
    printf("  server timing total: %.6f\n",
           CFAbsoluteTimeGetCurrent() - server_started);
    fflush(stdout);
    return 0;
}

static int compute_router_topk(id<MTLDevice> device,
                               NSString *resident_layout_path,
                               uint64_t layer_id,
                               NSString *input_path,
                               NSData *input_override_data,
                               uint32_t top_k,
                               NSString *score_mode,
                               RouterOptions options,
                               uint64_t max_router_bytes,
                               uint64_t max_runner_scratch_bytes,
                               RouterTopKResult *result) {
    if (!result) return 1;
    memset(result, 0, sizeof(*result));
    if (top_k == 0 || top_k > 64) {
        fprintf(stderr, "top-k %u out of range; maximum supported top-k is 64\n", top_k);
        return 1;
    }
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    apply_router_layout_metadata(resident_layout, &options);
    finalize_router_options(&options);
    RouterTensorInfo router = {0};
    if (!find_router_tensor(resident_layout, layer_id, &router)) return 1;
    ResidentAffineInt4MatrixInfo router_affine = {0};
    ResidentMxfp4MatrixInfo router_mxfp4 = {0};
    int use_affine_int4 = 0;
    int use_mxfp4 = 0;
    ResidentMatrixInfo router_matrix = router_to_resident_matrix(router);
    if (resident_matrix_is_affine_int4_weight(router_matrix)) {
        if (find_resident_mxfp4_matrix(resident_layout,
                                       router_matrix,
                                       &router_mxfp4)) {
            if (router_mxfp4.total_bytes > (uint64_t)SIZE_MAX) {
                fprintf(stderr, "router MXFP4 tensor %s is too large\n",
                        router_mxfp4.name);
                return 1;
            }
            use_mxfp4 = 1;
            router.num_experts = router_mxfp4.out_dim;
            router.hidden_dim = router_mxfp4.in_dim;
            router.size = (NSUInteger)router_mxfp4.total_bytes;
            snprintf(router.dtype, sizeof(router.dtype), "%s", "mlx-mxfp4");
        } else {
            if (!find_resident_affine_int4_matrix(resident_layout,
                                                  router_matrix,
                                                  &router_affine)) {
                return 1;
            }
            if (router_affine.total_bytes > (uint64_t)SIZE_MAX) {
                fprintf(stderr, "router affine-int4 tensor %s is too large\n",
                        router_affine.name);
                return 1;
            }
            use_affine_int4 = 1;
            router.num_experts = router_affine.out_dim;
            router.hidden_dim = router_affine.in_dim;
            router.size = (NSUInteger)router_affine.total_bytes;
            snprintf(router.dtype, sizeof(router.dtype), "%s", "affine-int4");
        }
    }
    if ((uint64_t)router.size > max_router_bytes) {
        fprintf(stderr, "router tensor %llu bytes exceeds configured limit %llu\n",
                (unsigned long long)router.size,
                (unsigned long long)max_router_bytes);
        return 1;
    }
    if (top_k == 0 || top_k > router.num_experts) {
        fprintf(stderr, "top-k %u out of range for %u experts\n",
                top_k, router.num_experts);
        return 1;
    }
    int dtype_f32 = strcmp(router.dtype, "F32") == 0 ||
                    strcmp(router.dtype, "float32") == 0 ||
                    strcmp(router.dtype, "FLOAT32") == 0;
    int dtype_bf16 = strcmp(router.dtype, "BF16") == 0 ||
                     strcmp(router.dtype, "bfloat16") == 0 ||
                     strcmp(router.dtype, "BFLOAT16") == 0;
    if (!use_mxfp4 && !use_affine_int4 && !dtype_f32 && !dtype_bf16) {
        fprintf(stderr, "unsupported router dtype %s; expected F32, BF16, affine-int4, or mlx-mxfp4\n", router.dtype);
        return 1;
    }

    if (!use_mxfp4 && !use_affine_int4) {
        uint64_t expected_bytes = (uint64_t)router.num_experts * router.hidden_dim *
                                  (dtype_f32 ? sizeof(float) : sizeof(uint16_t));
        if (expected_bytes != router.size) {
            fprintf(stderr, "router tensor size mismatch: layout=%llu expected=%llu\n",
                    (unsigned long long)router.size,
                    (unsigned long long)expected_bytes);
            return 1;
        }
    }
    uint64_t router_storage_for_peak = use_mxfp4
        ? align_up_u64(router_mxfp4.total_bytes, 2 * 1024 * 1024)
        : (use_affine_int4
            ? align_up_u64(router_affine.total_bytes, 2 * 1024 * 1024)
            : (uint64_t)router.size);
    uint64_t router_peak = estimate_router_peak(router_storage_for_peak,
                                                router.hidden_dim,
                                                router.num_experts);
    if (!enforce_scratch_limit("router", router_peak, max_runner_scratch_bytes)) {
        return 1;
    }

    NSData *input_data = input_override_data ?: [NSData dataWithContentsOfFile:input_path];
    if (!input_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)router.hidden_dim * sizeof(float);
    if (input_data.length != expected_input_bytes) {
        fprintf(stderr, "input bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)input_data.length,
                (unsigned long long)expected_input_bytes);
        return 1;
    }

    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    float *selection_bias = NULL;
    int used_correction_bias = 0;
    if (options.use_correction_bias) {
        VectorTensorInfo bias = {0};
        if (find_router_bias_tensor(resident_layout, layer_id, &bias)) {
            if (!read_vector_f32(weight_path, bias, router.num_experts, &selection_bias)) {
                return 1;
            }
            used_correction_bias = 1;
        }
    }

    void *router_data = NULL;
    if (!use_mxfp4 && !use_affine_int4) {
        router_data = malloc((size_t)router.size);
        if (!router_data) {
            free(selection_bias);
            return 1;
        }
        if (!read_exact_slot(weight_path.UTF8String, router_data, (size_t)router.size,
                             (off_t)router.offset)) {
            free(router_data);
            free(selection_bias);
            return 1;
        }
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        if (router_data) free(router_data);
        free(selection_bias);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "router");
    if (!library) {
        if (router_data) free(router_data);
        free(selection_bias);
        return 1;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(
        device,
        library,
        use_mxfp4 ? @"mxfp4_matvec" :
        (use_affine_int4 ? @"dequant4" : (dtype_f32 ? @"router_f32" : @"router_bf16")));
    if (!pipe) {
        if (router_data) free(router_data);
        free(selection_bias);
        return 1;
    }

    id<MTLBuffer> bRouter = nil;
    if (use_mxfp4) {
        bRouter = new_resident_mxfp4_buffer(device,
                                            weight_path,
                                            router_mxfp4,
                                            NULL);
    } else if (use_affine_int4) {
        bRouter = new_resident_affine_int4_buffer(device,
                                                  weight_path,
                                                  router_affine,
                                                  NULL);
    } else {
        bRouter = [device newBufferWithBytes:router_data
                                      length:(NSUInteger)router.size
                                     options:MTLResourceStorageModeShared];
        free(router_data);
    }
    id<MTLBuffer> bInput = [device newBufferWithBytes:input_data.bytes
                                               length:input_data.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bLogits = [device newBufferWithLength:router.num_experts * sizeof(float)
                                                options:MTLResourceStorageModeShared];
    if (!bRouter || !bInput || !bLogits) {
        free(selection_bias);
        fprintf(stderr, "failed to allocate router buffers\n");
        return 1;
    }

    id<MTLCommandBuffer> cmd = [queue commandBuffer];
    if (!cmd) {
        free(selection_bias);
        fprintf(stderr, "failed to create router command buffer\n");
        return 1;
    }
    int encoded = 0;
    if (use_mxfp4) {
        encoded = encode_mxfp4_matvec(cmd,
                                      pipe,
                                      bRouter,
                                      0,
                                      router_mxfp4.weight.size,
                                      bInput,
                                      bLogits,
                                      router_mxfp4.out_dim,
                                      router_mxfp4.in_dim,
                                      router_mxfp4.group_size);
    } else if (use_affine_int4) {
        encoded = encode_dequant4(cmd,
                                  pipe,
                                  bRouter,
                                  0,
                                  router_affine.weight.size,
                                  router_affine.weight.size + router_affine.scales.size,
                                  bInput,
                                  bLogits,
                                  router_affine.out_dim,
                                  router_affine.in_dim,
                                  router_affine.group_size,
                                  router_affine.meta_dtype);
    } else {
        encoded = encode_router_matvec(cmd, pipe, bRouter, bInput, bLogits,
                                       router.num_experts, router.hidden_dim);
    }
    if (!encoded) {
        free(selection_bias);
        return 1;
    }
    [cmd commit];
    [cmd waitUntilCompleted];
    if (cmd.status == MTLCommandBufferStatusError) {
        free(selection_bias);
        fprintf(stderr, "router Metal command failed: %s\n",
                cmd.error.localizedDescription.UTF8String);
        return 1;
    }

    size_t logits_bytes = (size_t)router.num_experts * sizeof(float);
    result->logits = malloc(logits_bytes);
    if (!result->logits) {
        free(selection_bias);
        fprintf(stderr, "failed to allocate router logits copy\n");
        return 1;
    }
    memcpy(result->logits, bLogits.contents, logits_bytes);
    if (!topk_scores(result->logits, router.num_experts, top_k, score_mode,
                     selection_bias, options, result->indices, result->weights)) {
        free(selection_bias);
        free_router_topk_result(result);
        fprintf(stderr, "failed to compute router top-k\n");
        return 1;
    }
    free(selection_bias);
    result->router = router;
    result->top_k = top_k;
    result->options = options;
    result->used_correction_bias = used_correction_bias;
    return 0;
}

static int run_router(id<MTLDevice> device,
                      NSString *resident_layout_path,
                      uint64_t layer_id,
                      NSString *input_path,
                      uint32_t top_k,
                      NSString *score_mode,
                      RouterOptions options,
                      NSString *output_json,
                      uint64_t max_router_bytes,
                      uint64_t max_runner_scratch_bytes) {
    RouterTopKResult result = {0};
    int status = compute_router_topk(device,
                                     resident_layout_path,
                                     layer_id,
                                     input_path,
                                     nil,
                                     top_k,
                                     score_mode,
                                     options,
                                     max_router_bytes,
                                     max_runner_scratch_bytes,
                                     &result);
    if (status != 0) return status;

    printf("LargerLM router\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", result.router.name);
    printf("  dtype:              %s\n", result.router.dtype);
    printf("  experts:            %u\n", result.router.num_experts);
    printf("  hidden dim:         %u\n", result.router.hidden_dim);
    printf("  score:              %s\n", score_mode.UTF8String);
    printf("  norm top-k:         %s\n", result.options.norm_topk_prob ? "yes" : "no");
    printf("  routed scale:       %.6f\n", result.options.routed_scaling_factor);
    printf("  groups:             %u/%u\n", result.options.topk_group, result.options.n_group);
    printf("  correction bias:    %s\n", result.used_correction_bias ? "yes" : "no");
    printf("  top-k:              ");
    for (uint32_t i = 0; i < result.top_k; i++) {
        printf("%u%s", result.indices[i], (i + 1 == result.top_k) ? "" : ",");
    }
    printf("\n");
    printf("  weights:            ");
    for (uint32_t i = 0; i < result.top_k; i++) {
        printf("%.6f%s", result.weights[i], (i + 1 == result.top_k) ? "" : ",");
    }
    printf("\n");
    if (output_json) {
        if (!write_router_json(output_json, result.indices, result.weights, result.logits,
                               result.top_k, result.router.num_experts, score_mode,
                               result.options, result.used_correction_bias)) {
            free_router_topk_result(&result);
            fprintf(stderr, "failed to write router JSON: %s\n", output_json.UTF8String);
            return 1;
        }
        printf("  router json:        %s\n", output_json.UTF8String);
    }

    free_router_topk_result(&result);
    return 0;
}

static int run_router_batch(id<MTLDevice> device,
                            NSString *resident_layout_path,
                            uint64_t layer_id,
                            NSString *input_path,
                            uint32_t batch_tokens,
                            uint32_t top_k,
                            NSString *score_mode,
                            RouterOptions options,
                            NSString *output_json_dir,
                            uint64_t max_router_bytes,
                            uint64_t max_runner_scratch_bytes) {
    if (batch_tokens == 0 || !input_path || !output_json_dir) {
        fprintf(stderr, "invalid router batch arguments\n");
        return 1;
    }
    if (top_k == 0 || top_k > 64) {
        fprintf(stderr, "top-k %u out of range; maximum supported top-k is 64\n", top_k);
        return 1;
    }
    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    apply_router_layout_metadata(resident_layout, &options);
    finalize_router_options(&options);
    RouterTensorInfo router = {0};
    if (!find_router_tensor(resident_layout, layer_id, &router)) return 1;
    ResidentAffineInt4MatrixInfo router_affine = {0};
    ResidentMxfp4MatrixInfo router_mxfp4 = {0};
    int use_affine_int4 = 0;
    int use_mxfp4 = 0;
    ResidentMatrixInfo router_matrix = router_to_resident_matrix(router);
    if (resident_matrix_is_affine_int4_weight(router_matrix)) {
        if (find_resident_mxfp4_matrix(resident_layout,
                                       router_matrix,
                                       &router_mxfp4)) {
            if (router_mxfp4.total_bytes > (uint64_t)SIZE_MAX) {
                fprintf(stderr, "router MXFP4 tensor %s is too large\n",
                        router_mxfp4.name);
                return 1;
            }
            use_mxfp4 = 1;
            router.num_experts = router_mxfp4.out_dim;
            router.hidden_dim = router_mxfp4.in_dim;
            router.size = (NSUInteger)router_mxfp4.total_bytes;
            snprintf(router.dtype, sizeof(router.dtype), "%s", "mlx-mxfp4");
        } else {
            if (!find_resident_affine_int4_matrix(resident_layout,
                                                  router_matrix,
                                                  &router_affine)) {
                return 1;
            }
            if (router_affine.total_bytes > (uint64_t)SIZE_MAX) {
                fprintf(stderr, "router affine-int4 tensor %s is too large\n",
                        router_affine.name);
                return 1;
            }
            use_affine_int4 = 1;
            router.num_experts = router_affine.out_dim;
            router.hidden_dim = router_affine.in_dim;
            router.size = (NSUInteger)router_affine.total_bytes;
            snprintf(router.dtype, sizeof(router.dtype), "%s", "affine-int4");
        }
    }
    if ((uint64_t)router.size > max_router_bytes) {
        fprintf(stderr, "router tensor %llu bytes exceeds configured limit %llu\n",
                (unsigned long long)router.size,
                (unsigned long long)max_router_bytes);
        return 1;
    }
    if (top_k > router.num_experts) {
        fprintf(stderr, "top-k %u out of range for %u experts\n",
                top_k, router.num_experts);
        return 1;
    }
    int dtype_f32 = strcmp(router.dtype, "F32") == 0 ||
                    strcmp(router.dtype, "float32") == 0 ||
                    strcmp(router.dtype, "FLOAT32") == 0;
    int dtype_bf16 = strcmp(router.dtype, "BF16") == 0 ||
                     strcmp(router.dtype, "bfloat16") == 0 ||
                     strcmp(router.dtype, "BFLOAT16") == 0;
    if (!use_mxfp4 && !use_affine_int4 && !dtype_f32 && !dtype_bf16) {
        fprintf(stderr, "unsupported router dtype %s; expected F32, BF16, affine-int4, or mlx-mxfp4\n", router.dtype);
        return 1;
    }

    if (!use_mxfp4 && !use_affine_int4) {
        uint64_t expected_router_bytes = (uint64_t)router.num_experts * router.hidden_dim *
                                         (dtype_f32 ? sizeof(float) : sizeof(uint16_t));
        if (expected_router_bytes != router.size) {
            fprintf(stderr, "router tensor size mismatch: layout=%llu expected=%llu\n",
                    (unsigned long long)router.size,
                    (unsigned long long)expected_router_bytes);
            return 1;
        }
    }
    uint64_t router_storage_for_peak = use_mxfp4
        ? align_up_u64(router_mxfp4.total_bytes, 2 * 1024 * 1024)
        : (use_affine_int4
            ? align_up_u64(router_affine.total_bytes, 2 * 1024 * 1024)
            : (uint64_t)router.size);
    uint64_t router_peak = estimate_router_peak(router_storage_for_peak,
                                                router.hidden_dim,
                                                router.num_experts);
    if (!enforce_scratch_limit("router batch", router_peak, max_runner_scratch_bytes)) {
        return 1;
    }

    size_t row_bytes = (size_t)router.hidden_dim * sizeof(float);
    uint64_t expected_input_bytes = (uint64_t)batch_tokens * row_bytes;
    int input_fd = open(input_path.UTF8String, O_RDONLY);
    if (input_fd < 0) {
        fprintf(stderr, "open failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        return 1;
    }
    struct stat input_stat;
    if (fstat(input_fd, &input_stat) != 0) {
        fprintf(stderr, "fstat failed for %s: %s\n", input_path.UTF8String, strerror(errno));
        close(input_fd);
        return 1;
    }
    if ((uint64_t)input_stat.st_size != expected_input_bytes) {
        fprintf(stderr, "router batch input bytes %llu do not match expected %llu\n",
                (unsigned long long)input_stat.st_size,
                (unsigned long long)expected_input_bytes);
        close(input_fd);
        return 1;
    }

    NSError *dir_error = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:output_json_dir
                                   withIntermediateDirectories:YES
                                                    attributes:nil
                                                         error:&dir_error]) {
        fprintf(stderr, "failed to create router JSON dir %s: %s\n",
                output_json_dir.UTF8String,
                dir_error.localizedDescription.UTF8String);
        close(input_fd);
        return 1;
    }

    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) {
        close(input_fd);
        return 1;
    }
    float *selection_bias = NULL;
    int used_correction_bias = 0;
    if (options.use_correction_bias) {
        VectorTensorInfo bias = {0};
        if (find_router_bias_tensor(resident_layout, layer_id, &bias)) {
            if (!read_vector_f32(weight_path, bias, router.num_experts, &selection_bias)) {
                close(input_fd);
                return 1;
            }
            used_correction_bias = 1;
        }
    }

    void *router_data = NULL;
    if (!use_mxfp4 && !use_affine_int4) {
        router_data = malloc((size_t)router.size);
        if (!router_data) {
            free(selection_bias);
            close(input_fd);
            fprintf(stderr, "failed to allocate router tensor copy\n");
            return 1;
        }
        if (!read_exact_slot(weight_path.UTF8String, router_data, (size_t)router.size,
                             (off_t)router.offset)) {
            free(router_data);
            free(selection_bias);
            close(input_fd);
            return 1;
        }
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        if (router_data) free(router_data);
        free(selection_bias);
        close(input_fd);
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "router");
    if (!library) {
        if (router_data) free(router_data);
        free(selection_bias);
        close(input_fd);
        return 1;
    }
    id<MTLComputePipelineState> pipe = make_pipeline(
        device,
        library,
        use_mxfp4 ? @"mxfp4_matvec" :
        (use_affine_int4 ? @"dequant4" : (dtype_f32 ? @"router_f32" : @"router_bf16")));
    if (!pipe) {
        if (router_data) free(router_data);
        free(selection_bias);
        close(input_fd);
        return 1;
    }

    id<MTLBuffer> bRouter = nil;
    if (use_mxfp4) {
        bRouter = new_resident_mxfp4_buffer(device,
                                            weight_path,
                                            router_mxfp4,
                                            NULL);
    } else if (use_affine_int4) {
        bRouter = new_resident_affine_int4_buffer(device,
                                                  weight_path,
                                                  router_affine,
                                                  NULL);
    } else {
        bRouter = [device newBufferWithBytes:router_data
                                      length:(NSUInteger)router.size
                                     options:MTLResourceStorageModeShared];
        free(router_data);
    }
    id<MTLBuffer> bInput = [device newBufferWithLength:row_bytes
                                               options:MTLResourceStorageModeShared];
    id<MTLBuffer> bLogits = [device newBufferWithLength:router.num_experts * sizeof(float)
                                                options:MTLResourceStorageModeShared];
    if (!bRouter || !bInput || !bLogits) {
        free(selection_bias);
        close(input_fd);
        fprintf(stderr, "failed to allocate router batch buffers\n");
        return 1;
    }

    uint32_t indices[64] = {0};
    float weights[64] = {0};
    for (uint32_t token = 0; token < batch_tokens; token++) {
        if (!read_exact_fd(input_fd, input_path.UTF8String, bInput.contents,
                           row_bytes, (off_t)((uint64_t)token * row_bytes))) {
            free(selection_bias);
            close(input_fd);
            return 1;
        }
        id<MTLCommandBuffer> cmd = [queue commandBuffer];
        if (!cmd) {
            free(selection_bias);
            close(input_fd);
            fprintf(stderr, "failed to create router batch token %u command buffer\n",
                    token);
            return 1;
        }
        int encoded = 0;
        if (use_mxfp4) {
            encoded = encode_mxfp4_matvec(cmd,
                                          pipe,
                                          bRouter,
                                          0,
                                          router_mxfp4.weight.size,
                                          bInput,
                                          bLogits,
                                          router_mxfp4.out_dim,
                                          router_mxfp4.in_dim,
                                          router_mxfp4.group_size);
        } else if (use_affine_int4) {
            encoded = encode_dequant4(cmd,
                                      pipe,
                                      bRouter,
                                      0,
                                      router_affine.weight.size,
                                      router_affine.weight.size + router_affine.scales.size,
                                      bInput,
                                      bLogits,
                                      router_affine.out_dim,
                                      router_affine.in_dim,
                                      router_affine.group_size,
                                      router_affine.meta_dtype);
        } else {
            encoded = encode_router_matvec(cmd, pipe, bRouter, bInput, bLogits,
                                           router.num_experts, router.hidden_dim);
        }
        if (!encoded) {
            free(selection_bias);
            close(input_fd);
            return 1;
        }
        [cmd commit];
        [cmd waitUntilCompleted];
        if (cmd.status == MTLCommandBufferStatusError) {
            free(selection_bias);
            close(input_fd);
            fprintf(stderr, "router batch token %u Metal command failed: %s\n",
                    token,
                    cmd.error.localizedDescription.UTF8String);
            return 1;
        }
        if (!topk_scores((float *)bLogits.contents, router.num_experts, top_k,
                         score_mode, selection_bias, options, indices, weights)) {
            free(selection_bias);
            close(input_fd);
            fprintf(stderr, "failed to compute router top-k for token %u\n", token);
            return 1;
        }
        NSString *filename = [NSString stringWithFormat:@"token_%06u.router.json", token];
        NSString *json_path = [output_json_dir stringByAppendingPathComponent:filename];
        if (!write_router_json(json_path, indices, weights, (float *)bLogits.contents,
                               top_k, router.num_experts, score_mode,
                               options, used_correction_bias)) {
            free(selection_bias);
            close(input_fd);
            fprintf(stderr, "failed to write router JSON: %s\n", json_path.UTF8String);
            return 1;
        }
    }
    free(selection_bias);
    close(input_fd);

    printf("LargerLM router batch\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  tensor:             %s\n", router.name);
    printf("  dtype:              %s\n", router.dtype);
    printf("  batch tokens:       %u\n", batch_tokens);
    printf("  experts:            %u\n", router.num_experts);
    printf("  hidden dim:         %u\n", router.hidden_dim);
    printf("  top-k:              %u\n", top_k);
    printf("  score:              %s\n", score_mode.UTF8String);
    printf("  norm top-k:         %s\n", options.norm_topk_prob ? "yes" : "no");
    printf("  routed scale:       %.6f\n", options.routed_scaling_factor);
    printf("  groups:             %u/%u\n", options.topk_group, options.n_group);
    printf("  correction bias:    %s\n", used_correction_bias ? "yes" : "no");
    printf("  router json dir:    %s\n", output_json_dir.UTF8String);
    return 0;
}

static int run_layer_moe(id<MTLDevice> device,
                         NSString *layout_path,
                         NSString *resident_layout_path,
                         uint64_t layer_id,
                         NSString *input_path,
                         NSData *input_override_data,
                         NSData *residual_data,
                         uint32_t top_k,
                         NSString *score_mode,
                         RouterOptions router_options,
                         NSString *output_f32,
                         NSString *output_router_json,
                         NSData *__strong *output_data,
                         uint64_t max_slot_bytes,
                         uint64_t max_router_bytes,
                         uint64_t max_runner_scratch_bytes,
                         uint64_t expert_read_advise_merge_gap_bytes,
                         uint64_t expert_read_advise_align_bytes,
                         int include_shared_expert,
                         MlpBlockTimings *timings) {
    NSDictionary *layout = load_json(layout_path);
    if (!layout) return 1;
    NSArray *layers = layout[@"layers"];
    if (![layers isKindOfClass:[NSArray class]]) {
        fprintf(stderr, "layout missing layers array\n");
        return 1;
    }
    NSDictionary *layer = find_layer(layers, layer_id);
    if (!layer) {
        fprintf(stderr, "layer %llu not found in layout\n",
                (unsigned long long)layer_id);
        return 1;
    }

    NSString *layer_file = nil;
    uint64_t num_experts = 0;
    uint64_t slot_bytes = 0;
    uint64_t layer_file_bytes = 0;
    if (!parse_expert_layer_fields(layer,
                                   max_slot_bytes,
                                   &layer_file,
                                   &num_experts,
                                   &slot_bytes,
                                   &layer_file_bytes)) {
        return 1;
    }
    NSString *layout_dir = [layout_path stringByDeletingLastPathComponent];
    NSString *expert_path = [layout_dir stringByAppendingPathComponent:layer_file];
    if (!validate_expert_layer_file_size(expert_path, layer_file_bytes)) return 1;

    ExpertLayoutInfo expert_info = {0};
    if (!parse_expert_layout(layout, layer, &expert_info)) return 1;

    RouterTopKResult route = {0};
    CFAbsoluteTime router_started = CFAbsoluteTimeGetCurrent();
    int status = compute_router_topk(device,
                                     resident_layout_path,
                                     layer_id,
                                     input_path,
                                     input_override_data,
                                     top_k,
                                     score_mode,
                                     router_options,
                                     max_router_bytes,
                                     max_runner_scratch_bytes,
                                     &route);
    if (timings) {
        timings->router_elapsed_seconds +=
            CFAbsoluteTimeGetCurrent() - router_started;
    }
    if (status != 0) return status;
    if (route.router.num_experts != num_experts) {
        fprintf(stderr, "router has %u experts but expert layout has %llu\n",
                route.router.num_experts,
                (unsigned long long)num_experts);
        free_router_topk_result(&route);
        return 1;
    }
    if (route.router.hidden_dim != expert_info.hidden_dim) {
        fprintf(stderr, "router hidden dim %u does not match expert hidden dim %u\n",
                route.router.hidden_dim, expert_info.hidden_dim);
        free_router_topk_result(&route);
        return 1;
    }

    uint64_t moe_experts[64] = {0};
    for (uint32_t i = 0; i < route.top_k; i++) {
        moe_experts[i] = route.indices[i];
    }
    uint64_t alloc_size = align_up_u64(slot_bytes, 2 * 1024 * 1024);
    SharedExpertInfo shared_info = {0};
    SharedExpertInfo *shared_ptr = NULL;
    NSString *shared_weight_path = nil;
    if (include_shared_expert) {
        NSDictionary *resident_layout = load_json(resident_layout_path);
        if (!resident_layout) {
            free_router_topk_result(&route);
            return 1;
        }
        if (!parse_shared_expert_layout(resident_layout, layer_id, &shared_info)) {
            free_router_topk_result(&route);
            return 1;
        }
        if (shared_info.hidden_dim != expert_info.hidden_dim) {
            fprintf(stderr, "shared expert hidden dim %u does not match layer hidden dim %u\n",
                    shared_info.hidden_dim, expert_info.hidden_dim);
            free_router_topk_result(&route);
            return 1;
        }
        shared_weight_path = validate_resident_weight_path(
            resident_layout_path,
            resident_layout);
        if (!shared_weight_path) {
            free_router_topk_result(&route);
            return 1;
        }
        shared_ptr = &shared_info;
    }

    printf("LargerLM layer MoE\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  router tensor:      %s\n", route.router.name);
    printf("  score:              %s\n", score_mode.UTF8String);
    printf("  norm top-k:         %s\n", route.options.norm_topk_prob ? "yes" : "no");
    printf("  routed scale:       %.6f\n", route.options.routed_scaling_factor);
    printf("  groups:             %u/%u\n", route.options.topk_group, route.options.n_group);
    printf("  correction bias:    %s\n", route.used_correction_bias ? "yes" : "no");
    printf("  top-k:              ");
    for (uint32_t i = 0; i < route.top_k; i++) {
        printf("%u%s", route.indices[i], (i + 1 == route.top_k) ? "" : ",");
    }
    printf("\n");
    printf("  weights:            ");
    for (uint32_t i = 0; i < route.top_k; i++) {
        printf("%.6f%s", route.weights[i], (i + 1 == route.top_k) ? "" : ",");
    }
    printf("\n");
    printf("  slot bytes:         %llu\n", (unsigned long long)slot_bytes);
    printf("  2MB alloc bytes:    %llu\n", (unsigned long long)alloc_size);
    printf("  include shared:     %s\n", include_shared_expert ? "yes" : "no");

    if (output_router_json) {
        if (!write_router_json(output_router_json, route.indices, route.weights,
                               route.logits, route.top_k,
                               route.router.num_experts, score_mode,
                               route.options, route.used_correction_bias)) {
            fprintf(stderr, "failed to write router JSON: %s\n",
                    output_router_json.UTF8String);
            free_router_topk_result(&route);
            return 1;
        }
        printf("  router json:        %s\n", output_router_json.UTF8String);
    }

    status = run_moe_forward(device, expert_path.UTF8String, slot_bytes,
                             num_experts * slot_bytes,
                             moe_experts, route.weights, (int)route.top_k,
                             expert_info, input_path, input_override_data, residual_data,
                             output_f32, output_data, alloc_size,
                             route.router.num_experts * sizeof(float),
                             max_runner_scratch_bytes,
                             expert_read_advise_merge_gap_bytes,
                             expert_read_advise_align_bytes,
                             shared_ptr,
                             shared_weight_path,
                             timings);
    if (status == 0 && timings) {
        printf("  timing router:      %.6f\n", timings->router_elapsed_seconds);
        printf("  timing moe:         %.6f\n", timings->moe_elapsed_seconds);
        printf("  timing moe setup:   %.6f\n", timings->moe_setup_elapsed_seconds);
        printf("  timing moe clear:   %.6f\n", timings->moe_clear_elapsed_seconds);
        printf("  timing expert read: %.6f\n", timings->expert_read_elapsed_seconds);
        printf("  timing expert kernel: %.6f\n",
               timings->expert_kernel_elapsed_seconds);
        printf("  timing shared:      %.6f\n", timings->shared_elapsed_seconds);
        printf("  timing residual:    %.6f\n", timings->residual_elapsed_seconds);
        printf("  timing output:      %.6f\n", timings->output_elapsed_seconds);
    }
    free_router_topk_result(&route);
    return status;
}

static int run_mlp_block(id<MTLDevice> device,
                         NSString *layout_path,
                         NSString *resident_layout_path,
                         uint64_t layer_id,
                         NSString *input_path,
                         NSData *input_data_override,
                         uint32_t top_k,
                         NSString *score_mode,
                         RouterOptions router_options,
                         NSString *output_f32,
                         NSString *output_router_json,
                         NSData *__strong *output_data,
                         uint64_t max_slot_bytes,
                         uint64_t max_router_bytes,
                         uint64_t max_runner_scratch_bytes,
                         uint64_t expert_read_advise_merge_gap_bytes,
                         uint64_t expert_read_advise_align_bytes,
                         int include_shared_expert,
                         float rms_norm_eps,
                         MlpBlockTimings *timings) {
    reset_mlp_block_timings(timings);
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();
    NSData *residual_data = input_data_override ?: [NSData dataWithContentsOfFile:input_path];
    if (!residual_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    CFAbsoluteTime rmsnorm_started = CFAbsoluteTimeGetCurrent();
    NSData *normed = run_resident_rmsnorm(device,
                                          resident_layout_path,
                                          layer_id,
                                          residual_data,
                                          @".post_attention_layernorm.weight",
                                          rms_norm_eps,
                                          max_runner_scratch_bytes);
    if (!normed) return 1;
    if (timings) {
        timings->rmsnorm_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - rmsnorm_started;
    }
    printf("LargerLM MLP block\n");
    printf("  RMSNorm eps:        %.9g\n", rms_norm_eps);
    int status = run_layer_moe(device,
                               layout_path,
                               resident_layout_path,
                               layer_id,
                               input_path,
                               normed,
                               residual_data,
                               top_k,
                               score_mode,
                               router_options,
                               output_f32,
                               output_router_json,
                               output_data,
                               max_slot_bytes,
                               max_router_bytes,
                               max_runner_scratch_bytes,
                               expert_read_advise_merge_gap_bytes,
                               expert_read_advise_align_bytes,
                               include_shared_expert,
                               timings);
    if (timings) {
        timings->total_elapsed_seconds = CFAbsoluteTimeGetCurrent() - total_started;
    }
    return status;
}

static int run_dense_mlp_block(id<MTLDevice> device,
                               NSString *resident_layout_path,
                               uint64_t layer_id,
                               NSString *input_path,
                               NSData *input_data_override,
                               NSString *output_f32,
                               NSData *__strong *output_data,
                               uint64_t max_resident_matrix_bytes,
                               uint64_t max_runner_scratch_bytes,
                               float rms_norm_eps,
                               MlpBlockTimings *timings) {
    reset_mlp_block_timings(timings);
    CFAbsoluteTime total_started = CFAbsoluteTimeGetCurrent();
    NSData *residual_data = input_data_override ?: [NSData dataWithContentsOfFile:input_path];
    if (!residual_data) {
        fprintf(stderr, "failed to read input f32 file: %s\n", input_path.UTF8String);
        return 1;
    }
    CFAbsoluteTime rmsnorm_started = CFAbsoluteTimeGetCurrent();
    NSData *normed = run_resident_rmsnorm(device,
                                          resident_layout_path,
                                          layer_id,
                                          residual_data,
                                          @".post_attention_layernorm.weight",
                                          rms_norm_eps,
                                          max_runner_scratch_bytes);
    if (!normed) return 1;
    if (timings) {
        timings->rmsnorm_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - rmsnorm_started;
    }

    NSDictionary *resident_layout = load_json(resident_layout_path);
    if (!resident_layout) return 1;
    NSString *weight_path = validate_resident_weight_path(
        resident_layout_path,
        resident_layout);
    if (!weight_path) return 1;
    SharedExpertInfo dense = {0};
    if (!parse_dense_mlp_layout(resident_layout, layer_id, &dense)) return 1;
    if (!enforce_shared_component_matrix_limit("dense gate",
                                               dense.gate,
                                               dense.gate_affine,
                                               dense.gate_mxfp4,
                                               dense.gate_is_affine_int4,
                                               dense.gate_is_mxfp4,
                                               max_resident_matrix_bytes) ||
        !enforce_shared_component_matrix_limit("dense up",
                                               dense.up,
                                               dense.up_affine,
                                               dense.up_mxfp4,
                                               dense.up_is_affine_int4,
                                               dense.up_is_mxfp4,
                                               max_resident_matrix_bytes) ||
        !enforce_shared_component_matrix_limit("dense down",
                                               dense.down,
                                               dense.down_affine,
                                               dense.down_mxfp4,
                                               dense.down_is_affine_int4,
                                               dense.down_is_mxfp4,
                                               max_resident_matrix_bytes)) {
        return 1;
    }
    NSUInteger expected_input_bytes = (NSUInteger)dense.hidden_dim * sizeof(float);
    if (residual_data.length != expected_input_bytes || normed.length != expected_input_bytes) {
        fprintf(stderr, "dense MLP input bytes mismatch for layer %llu\n",
                (unsigned long long)layer_id);
        return 1;
    }
    uint64_t peak = estimate_moe_forward_peak_with_shared(0,
                                                          dense.hidden_dim,
                                                          dense.intermediate_dim,
                                                          expected_input_bytes,
                                                          dense.max_matrix_alloc_bytes);
    if (!enforce_scratch_limit("dense MLP block", peak, max_runner_scratch_bytes)) {
        return 1;
    }

    id<MTLCommandQueue> queue = shared_command_queue(device);
    if (!queue) {
        fprintf(stderr, "failed to create Metal command queue\n");
        return 1;
    }
    id<MTLLibrary> library = expert_kernel_library(device, "dense MLP");
    if (!library) return 1;
    id<MTLComputePipelineState> swiglu = make_pipeline(device, library, @"swiglu");
    id<MTLComputePipelineState> add = make_pipeline(device, library, @"weighted_add");
    if (!swiglu || !add) return 1;

    id<MTLBuffer> bInput = [device newBufferWithBytes:normed.bytes
                                               length:normed.length
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bGate = [device newBufferWithLength:dense.intermediate_dim * sizeof(float)
                                              options:MTLResourceStorageModeShared];
    id<MTLBuffer> bUp = [device newBufferWithLength:dense.intermediate_dim * sizeof(float)
                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAct = [device newBufferWithLength:dense.intermediate_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bOut = [device newBufferWithLength:dense.hidden_dim * sizeof(float)
                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> bAccum = [device newBufferWithBytes:residual_data.bytes
                                               length:residual_data.length
                                              options:MTLResourceStorageModeShared];
    if (!bInput || !bGate || !bUp || !bAct || !bOut || !bAccum) {
        fprintf(stderr, "failed to allocate dense MLP buffers\n");
        return 1;
    }
    CFAbsoluteTime dense_started = CFAbsoluteTimeGetCurrent();
    if (!run_shared_expert_to_accum(device, queue, library, swiglu, add,
                                    weight_path, dense,
                                    bInput, bGate, bUp, bAct, bOut, bAccum)) {
        return 1;
    }
    if (timings) {
        timings->shared_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - dense_started;
    }

    CFAbsoluteTime output_started = CFAbsoluteTimeGetCurrent();
    NSUInteger output_bytes = (NSUInteger)dense.hidden_dim * sizeof(float);
    if (output_f32 || output_data) {
        NSData *out_data = [[NSData alloc] initWithBytes:bAccum.contents length:output_bytes];
        if (output_data) {
            *output_data = out_data;
        }
        if (output_f32 && ![out_data writeToFile:output_f32 atomically:YES]) {
            fprintf(stderr, "failed to write dense MLP output f32 file: %s\n",
                    output_f32.UTF8String);
            return 1;
        }
    }
    if (timings) {
        timings->output_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - output_started;
        timings->total_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - total_started;
    }
    float *out = (float *)bAccum.contents;
    printf("LargerLM dense MLP block\n");
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  hidden dim:         %u\n", dense.hidden_dim);
    printf("  intermediate dim:   %u\n", dense.intermediate_dim);
    printf("  matrix peak:        %llu\n",
           (unsigned long long)dense.max_matrix_alloc_bytes);
    printf("  RMSNorm eps:        %.9g\n", rms_norm_eps);
    printf("  output[0]:          %.6f\n", out[0]);
    if (output_f32) printf("  output f32:         %s\n", output_f32.UTF8String);
    printf("  result:             ok\n");
    return 0;
}

static NSString *create_decoder_work_dir(NSString *requested, int *owns_work_dir) {
    *owns_work_dir = 0;
    if (requested) {
        NSError *error = nil;
        if (![[NSFileManager defaultManager] createDirectoryAtPath:requested
                                       withIntermediateDirectories:YES
                                                        attributes:nil
                                                             error:&error]) {
            fprintf(stderr, "failed to create decoder work dir %s: %s\n",
                    requested.UTF8String, error.localizedDescription.UTF8String);
            return nil;
        }
        return requested;
    }

    char template_path[] = "/private/tmp/largerlm-decoder-layer-XXXXXX";
    char *created = mkdtemp(template_path);
    if (!created) {
        fprintf(stderr, "mkdtemp failed for decoder work dir: %s\n", strerror(errno));
        return nil;
    }
    *owns_work_dir = 1;
    return [NSString stringWithUTF8String:created];
}

static void cleanup_decoder_work_dir(NSString *path, int owns_work_dir) {
    if (!owns_work_dir || !path) return;
    NSError *error = nil;
    if (![[NSFileManager defaultManager] removeItemAtPath:path error:&error]) {
        fprintf(stderr, "warning: failed to remove decoder work dir %s: %s\n",
                path.UTF8String, error.localizedDescription.UTF8String);
    }
}

static float apply_rope_f32_cpu(const float *src,
                                uint32_t idx,
                                uint32_t rope_dim,
                                uint32_t position,
                                float theta,
                                int interleave) {
    uint32_t half_dim = rope_dim / 2;
    uint32_t freq_idx = 0;
    float rot = 0.0f;
    if (interleave) {
        uint32_t pair = idx ^ 1u;
        rot = (idx & 1u) ? src[pair] : -src[pair];
        freq_idx = idx / 2u;
    } else if (idx < half_dim) {
        rot = -src[idx + half_dim];
        freq_idx = idx;
    } else {
        rot = src[idx - half_dim];
        freq_idx = idx - half_dim;
    }
    double angle = (double)position /
        pow((double)theta, (2.0 * (double)freq_idx) / (double)rope_dim);
    return src[idx] * (float)cos(angle) + rot * (float)sin(angle);
}

static int split_q_b_file_with_cpu_rope(NSString *q_b_path,
                                        NSData *q_b_data_override,
                                        NSString *q_nope_path,
                                        NSString *q_rope_path,
                                        uint32_t num_heads,
                                        uint32_t qk_nope_dim,
                                        uint32_t rope_dim,
                                        uint32_t position,
                                        float theta,
                                        int interleave,
                                        uint64_t max_runner_scratch_bytes,
                                        NSData *__strong *q_nope_output_data,
                                        NSData *__strong *q_rope_output_data) {
    if (num_heads == 0 || qk_nope_dim == 0 || rope_dim == 0 ||
        (rope_dim % 2) != 0) {
        fprintf(stderr, "invalid q_b RoPE split dimensions\n");
        return 0;
    }
    if (theta <= 0.0f) {
        fprintf(stderr, "--rope-theta must be positive\n");
        return 0;
    }
    uint64_t q_head_dim = (uint64_t)qk_nope_dim + rope_dim;
    uint64_t q_count = (uint64_t)num_heads * q_head_dim;
    uint64_t q_nope_count = (uint64_t)num_heads * qk_nope_dim;
    uint64_t q_rope_count = (uint64_t)num_heads * rope_dim;
    uint64_t q_bytes = q_count * sizeof(float);
    uint64_t q_nope_bytes = q_nope_count * sizeof(float);
    uint64_t q_rope_bytes = q_rope_count * sizeof(float);
    uint64_t peak = q_bytes + q_nope_bytes + q_rope_bytes;
    if (!enforce_scratch_limit("q_b split/RoPE", peak, max_runner_scratch_bytes)) {
        return 0;
    }

    NSData *q_data = q_b_data_override ?: [NSData dataWithContentsOfFile:q_b_path];
    if (!q_data) {
        fprintf(stderr, "failed to read q_b file: %s\n", q_b_path.UTF8String);
        return 0;
    }
    if (q_data.length != q_bytes) {
        fprintf(stderr, "q_b bytes mismatch: got %llu expected %llu\n",
                (unsigned long long)q_data.length,
                (unsigned long long)q_bytes);
        return 0;
    }

    NSMutableData *q_nope = [NSMutableData dataWithLength:(NSUInteger)q_nope_bytes];
    NSMutableData *q_rope = [NSMutableData dataWithLength:(NSUInteger)q_rope_bytes];
    if (!q_nope || !q_rope) {
        fprintf(stderr, "failed to allocate split/RoPE q buffers\n");
        return 0;
    }
    const float *src = (const float *)q_data.bytes;
    float *nope = (float *)q_nope.mutableBytes;
    float *rope = (float *)q_rope.mutableBytes;
    for (uint32_t h = 0; h < num_heads; h++) {
        uint64_t src_base = (uint64_t)h * q_head_dim;
        uint64_t nope_base = (uint64_t)h * qk_nope_dim;
        uint64_t rope_base = (uint64_t)h * rope_dim;
        for (uint32_t d = 0; d < qk_nope_dim; d++) {
            nope[nope_base + d] = src[src_base + d];
        }
        const float *rot_src = src + src_base + qk_nope_dim;
        for (uint32_t d = 0; d < rope_dim; d++) {
            rope[rope_base + d] = apply_rope_f32_cpu(rot_src,
                                                     d,
                                                     rope_dim,
                                                     position,
                                                     theta,
                                                     interleave);
        }
    }
    if (q_nope_output_data) {
        *q_nope_output_data = q_nope;
    }
    if (q_rope_output_data) {
        *q_rope_output_data = q_rope;
    }
    if (q_nope_path || q_rope_path) {
        if (!q_nope_path || !q_rope_path ||
            ![q_nope writeToFile:q_nope_path atomically:YES] ||
            ![q_rope writeToFile:q_rope_path atomically:YES]) {
            fprintf(stderr, "failed to write split/RoPE q files\n");
            return 0;
        }
    }
    return 1;
}

typedef struct {
    double attention_projections_elapsed_seconds;
    double split_q_elapsed_seconds;
    double dummy_k_elapsed_seconds;
    double rope_elapsed_seconds;
    double mla_attention_elapsed_seconds;
    MlaAttentionBatchTimings mla_attention_batch;
    double attention_output_elapsed_seconds;
    double mlp_elapsed_seconds;
    MlpBlockTimings mlp_block;
} DecoderLayerTimings;

static void reset_decoder_layer_timings(DecoderLayerTimings *timings) {
    if (timings) {
        memset(timings, 0, sizeof(*timings));
    }
}

static int run_decoder_layer(id<MTLDevice> device,
                             NSString *layout_path,
                             NSString *resident_layout_path,
                             NSString *cache_layout_path,
                             NSString *cache_file_path,
                             uint64_t layer_id,
                             NSString *input_path,
                             NSData *input_data_override,
                             NSString *output_path,
                             NSString *output_router_json,
                             NSString *work_dir_arg,
                             uint64_t position,
                             uint32_t context_len,
                             uint32_t num_heads,
                             uint32_t kv_lora_dim,
                             uint32_t qk_nope_dim,
                             uint32_t rope_dim,
                             uint32_t v_head_dim,
                             uint32_t cache_position_offset,
                             float attention_scale,
                             float rope_theta,
                             int rope_interleave,
                             NSString *mla_kv_b_cache_dir,
                             uint32_t top_k,
                             NSString *score_mode,
                             RouterOptions router_options,
                             uint64_t max_slot_bytes,
                             uint64_t max_router_bytes,
                             uint64_t max_matrix_bytes,
                             uint64_t max_cache_file_bytes,
                             uint64_t max_cache_read_bytes,
                             uint64_t max_runner_scratch_bytes,
                             uint64_t expert_read_advise_merge_gap_bytes,
                             uint64_t expert_read_advise_align_bytes,
                             int include_shared_expert,
                             float rms_norm_eps,
                             DecoderLayerTimings *timings,
                             NSData *__strong *output_data) {
    reset_decoder_layer_timings(timings);
    if (position > UINT32_MAX) {
        fprintf(stderr, "--position is out of range for RoPE\n");
        return 1;
    }
    int owns_work_dir = 0;
    NSString *work_dir = create_decoder_work_dir(work_dir_arg, &owns_work_dir);
    if (!work_dir) return 1;
    NSString *q_nope_path = [work_dir stringByAppendingPathComponent:@"q_nope.f32"];
    NSString *q_rope_path = [work_dir stringByAppendingPathComponent:@"q_rope.f32"];
    NSString *attn_value_path = [work_dir stringByAppendingPathComponent:@"attn_value.f32"];
    NSString *attn_out_path = [work_dir stringByAppendingPathComponent:@"attn_out.f32"];
    NSData *q_b_data = nil;
    NSData *attn_value_data = nil;
    NSData *attn_out_data = nil;

    int status = 0;
    CFAbsoluteTime stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_attention_projections(device,
                                           resident_layout_path,
                                           layer_id,
                                           input_path,
                                           input_data_override,
                                           nil,
                                           1,
                                           cache_layout_path,
                                           cache_file_path,
                                           position,
                                           1,
                                           rms_norm_eps,
                                           max_matrix_bytes,
                                           max_cache_file_bytes,
                                           max_runner_scratch_bytes,
                                           &q_b_data);
    }
    if (timings) {
        timings->attention_projections_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;

    stage_started = CFAbsoluteTimeGetCurrent();
    if (!split_q_b_file_with_cpu_rope(nil,
                                      q_b_data,
                                      q_nope_path,
                                      q_rope_path,
                                      num_heads,
                                      qk_nope_dim,
                                      rope_dim,
                                      (uint32_t)position,
                                      rope_theta,
                                      rope_interleave,
                                      max_runner_scratch_bytes,
                                      NULL,
                                      NULL)) {
        status = 1;
        goto done;
    }
    q_b_data = nil;
    if (timings) {
        timings->split_q_elapsed_seconds = CFAbsoluteTimeGetCurrent() - stage_started;
    }

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_mla_attention_batch(device,
                                         resident_layout_path,
                                         cache_layout_path,
                                         cache_file_path,
                                         layer_id,
                                         q_nope_path,
                                         q_rope_path,
                                         attn_value_path,
                                         context_len,
                                         context_len - 1u,
                                         1u,
                                         num_heads,
                                         kv_lora_dim,
                                         qk_nope_dim,
                                         rope_dim,
                                         v_head_dim,
                                         cache_position_offset,
                                         attention_scale,
                                         rope_theta,
                                         rope_interleave,
                                         mla_kv_b_cache_dir,
                                         max_cache_file_bytes,
                                         max_cache_read_bytes,
                                         max_matrix_bytes,
                                         max_runner_scratch_bytes,
                                         timings ? &timings->mla_attention_batch : NULL);
    }
    if (timings) {
        timings->mla_attention_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;
    attn_value_data = [NSData dataWithContentsOfFile:attn_value_path];
    if (!attn_value_data) {
        fprintf(stderr, "failed to read decoder MLA attention value output\n");
        status = 1;
        goto done;
    }

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_attention_output(device,
                                      resident_layout_path,
                                      layer_id,
                                      nil,
                                      input_path,
                                      input_data_override,
                                      nil,
                                      nil,
                                      max_matrix_bytes,
                                      max_runner_scratch_bytes,
                                      attn_value_data,
                                      &attn_out_data);
    }
    attn_value_data = nil;
    if (timings) {
        timings->attention_output_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_mlp_block(device,
                               layout_path,
                               resident_layout_path,
                               layer_id,
                               attn_out_path,
                               attn_out_data,
                               top_k,
                               score_mode,
                               router_options,
                               output_path,
                               output_router_json,
                               output_data,
                               max_slot_bytes,
                               max_router_bytes,
                               max_runner_scratch_bytes,
                               expert_read_advise_merge_gap_bytes,
                               expert_read_advise_align_bytes,
                               include_shared_expert,
                               rms_norm_eps,
                               timings ? &timings->mlp_block : NULL);
    }
    if (timings) {
        timings->mlp_elapsed_seconds = CFAbsoluteTimeGetCurrent() - stage_started;
    }

done:
    printf("LargerLM decoder layer\n");
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  position:           %llu\n", (unsigned long long)position);
    printf("  context length:     %u\n", context_len);
    printf("  work dir:           %s\n", work_dir.UTF8String);
    printf("  result:             %s\n", status == 0 ? "ok" : "failed");
    if (status == 0) {
        cleanup_decoder_work_dir(work_dir, owns_work_dir);
    }
    return status;
}

static int run_dense_decoder_layer(id<MTLDevice> device,
                                   NSString *resident_layout_path,
                                   NSString *cache_layout_path,
                                   NSString *cache_file_path,
                                   uint64_t layer_id,
                                   NSString *input_path,
                                   NSData *input_data_override,
                                   NSString *output_path,
                                   NSString *work_dir_arg,
                                   uint64_t position,
                                   uint32_t context_len,
                                   uint32_t num_heads,
                                   uint32_t kv_lora_dim,
                                   uint32_t qk_nope_dim,
                                   uint32_t rope_dim,
                                   uint32_t v_head_dim,
                                   uint32_t cache_position_offset,
                                   float attention_scale,
                                   float rope_theta,
                                   int rope_interleave,
                                   NSString *mla_kv_b_cache_dir,
                                   uint64_t max_matrix_bytes,
                                   uint64_t max_cache_file_bytes,
                                   uint64_t max_cache_read_bytes,
                                   uint64_t max_runner_scratch_bytes,
                                   float rms_norm_eps,
                                   DecoderLayerTimings *timings,
                                   NSData *__strong *output_data) {
    reset_decoder_layer_timings(timings);
    if (position > UINT32_MAX) {
        fprintf(stderr, "--position is out of range for RoPE\n");
        return 1;
    }
    int owns_work_dir = 0;
    NSString *work_dir = create_decoder_work_dir(work_dir_arg, &owns_work_dir);
    if (!work_dir) return 1;
    NSString *q_nope_path = [work_dir stringByAppendingPathComponent:@"q_nope.f32"];
    NSString *q_rope_path = [work_dir stringByAppendingPathComponent:@"q_rope.f32"];
    NSString *attn_value_path = [work_dir stringByAppendingPathComponent:@"attn_value.f32"];
    NSString *attn_out_path = [work_dir stringByAppendingPathComponent:@"attn_out.f32"];
    NSData *q_b_data = nil;
    NSData *attn_value_data = nil;
    NSData *attn_out_data = nil;

    int status = 0;
    CFAbsoluteTime stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_attention_projections(device,
                                           resident_layout_path,
                                           layer_id,
                                           input_path,
                                           input_data_override,
                                           nil,
                                           1,
                                           cache_layout_path,
                                           cache_file_path,
                                           position,
                                           1,
                                           rms_norm_eps,
                                           max_matrix_bytes,
                                           max_cache_file_bytes,
                                           max_runner_scratch_bytes,
                                           &q_b_data);
    }
    if (timings) {
        timings->attention_projections_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;

    stage_started = CFAbsoluteTimeGetCurrent();
    if (!split_q_b_file_with_cpu_rope(nil,
                                      q_b_data,
                                      q_nope_path,
                                      q_rope_path,
                                      num_heads,
                                      qk_nope_dim,
                                      rope_dim,
                                      (uint32_t)position,
                                      rope_theta,
                                      rope_interleave,
                                      max_runner_scratch_bytes,
                                      NULL,
                                      NULL)) {
        status = 1;
        goto done;
    }
    q_b_data = nil;
    if (timings) {
        timings->split_q_elapsed_seconds = CFAbsoluteTimeGetCurrent() - stage_started;
    }

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_mla_attention_batch(device,
                                         resident_layout_path,
                                         cache_layout_path,
                                         cache_file_path,
                                         layer_id,
                                         q_nope_path,
                                         q_rope_path,
                                         attn_value_path,
                                         context_len,
                                         context_len - 1u,
                                         1u,
                                         num_heads,
                                         kv_lora_dim,
                                         qk_nope_dim,
                                         rope_dim,
                                         v_head_dim,
                                         cache_position_offset,
                                         attention_scale,
                                         rope_theta,
                                         rope_interleave,
                                         mla_kv_b_cache_dir,
                                         max_cache_file_bytes,
                                         max_cache_read_bytes,
                                         max_matrix_bytes,
                                         max_runner_scratch_bytes,
                                         timings ? &timings->mla_attention_batch : NULL);
    }
    if (timings) {
        timings->mla_attention_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;
    attn_value_data = [NSData dataWithContentsOfFile:attn_value_path];
    if (!attn_value_data) {
        fprintf(stderr, "failed to read dense decoder MLA attention value output\n");
        status = 1;
        goto done;
    }

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_attention_output(device,
                                      resident_layout_path,
                                      layer_id,
                                      nil,
                                      input_path,
                                      input_data_override,
                                      nil,
                                      nil,
                                      max_matrix_bytes,
                                      max_runner_scratch_bytes,
                                      attn_value_data,
                                      &attn_out_data);
    }
    attn_value_data = nil;
    if (timings) {
        timings->attention_output_elapsed_seconds =
            CFAbsoluteTimeGetCurrent() - stage_started;
    }
    if (status != 0) goto done;

    stage_started = CFAbsoluteTimeGetCurrent();
    @autoreleasepool {
        status = run_dense_mlp_block(device,
                                     resident_layout_path,
                                     layer_id,
                                     attn_out_path,
                                     attn_out_data,
                                     output_path,
                                     output_data,
                                     max_matrix_bytes,
                                     max_runner_scratch_bytes,
                                     rms_norm_eps,
                                     timings ? &timings->mlp_block : NULL);
    }
    if (timings) {
        timings->mlp_elapsed_seconds = CFAbsoluteTimeGetCurrent() - stage_started;
    }

done:
    printf("LargerLM dense decoder layer\n");
    printf("  layer:              %llu\n", (unsigned long long)layer_id);
    printf("  position:           %llu\n", (unsigned long long)position);
    printf("  context length:     %u\n", context_len);
    printf("  work dir:           %s\n", work_dir.UTF8String);
    printf("  result:             %s\n", status == 0 ? "ok" : "failed");
    if (status == 0) {
        cleanup_decoder_work_dir(work_dir, owns_work_dir);
    }
    return status;
}

static int u64_list_contains(const uint64_t *values, int count, uint64_t needle) {
    for (int i = 0; i < count; i++) {
        if (values[i] == needle) return 1;
    }
    return 0;
}

static int write_decoder_layers_report(NSString *path,
                                       NSArray *records,
                                       double elapsed_seconds) {
    if (!path) return 1;
    NSDictionary *payload = @{
        @"elapsed_seconds": @(elapsed_seconds),
        @"records": records ?: @[],
    };
    NSError *error = nil;
    NSData *json = [NSJSONSerialization dataWithJSONObject:payload
                                                   options:NSJSONWritingPrettyPrinted
                                                     error:&error];
    if (!json) {
        fprintf(stderr, "failed to serialize decoder layers report: %s\n",
                error.localizedDescription.UTF8String);
        return 0;
    }
    if (![json writeToFile:path atomically:YES]) {
        fprintf(stderr, "failed to write decoder layers report: %s\n",
                path.UTF8String);
        return 0;
    }
    return 1;
}

static int run_decoder_layers(id<MTLDevice> device,
                              NSString *layout_path,
                              NSString *resident_layout_path,
                              NSString *cache_layout_path,
                              NSString *cache_file_path,
                              const uint64_t *layers,
                              int layer_count,
                              const uint64_t *dense_layers,
                              int dense_count,
                              NSString *input_path,
                              NSString *output_path,
                              NSString *report_path,
                              NSString *work_dir_arg,
                              uint64_t position,
                              uint32_t context_len,
                              uint32_t num_heads,
                              uint32_t kv_lora_dim,
                              uint32_t qk_nope_dim,
                              uint32_t rope_dim,
                              uint32_t v_head_dim,
                              uint32_t cache_position_offset,
                              float attention_scale,
                              float rope_theta,
                              int rope_interleave,
                              NSString *mla_kv_b_cache_dir,
                              uint32_t top_k,
                              NSString *score_mode,
                              RouterOptions router_options,
                              uint64_t max_slot_bytes,
                              uint64_t max_router_bytes,
                              uint64_t max_matrix_bytes,
                              uint64_t max_cache_file_bytes,
                              uint64_t max_cache_read_bytes,
                              uint64_t max_runner_scratch_bytes,
                              uint64_t expert_read_advise_merge_gap_bytes,
                              uint64_t expert_read_advise_align_bytes,
                              int include_shared_expert,
                              float rms_norm_eps,
                              int quiet_inner_layers,
                              NSData *__strong *final_output_data) {
    if (layer_count <= 0) {
        fprintf(stderr, "--layers must contain at least one layer\n");
        return 2;
    }
    int owns_work_dir = 0;
    NSString *work_dir = create_decoder_work_dir(work_dir_arg, &owns_work_dir);
    if (!work_dir) return 1;

    NSMutableArray *records = [NSMutableArray arrayWithCapacity:(NSUInteger)layer_count];
    NSString *current_input = input_path;
    NSData *current_input_data = nil;
    int status = 0;
    int saved_stdout = -1;
    if (quiet_inner_layers) {
        fflush(stdout);
        saved_stdout = dup(STDOUT_FILENO);
        int null_fd = open("/dev/null", O_WRONLY);
        if (saved_stdout < 0 || null_fd < 0 || dup2(null_fd, STDOUT_FILENO) < 0) {
            fprintf(stderr, "failed to silence decoder layer stdout: %s\n", strerror(errno));
            if (null_fd >= 0) close(null_fd);
            if (saved_stdout >= 0) close(saved_stdout);
            cleanup_decoder_work_dir(work_dir, owns_work_dir);
            return 1;
        }
        close(null_fd);
    }
    CFAbsoluteTime started = CFAbsoluteTimeGetCurrent();
    for (int i = 0; i < layer_count; i++) {
        uint64_t layer_id = layers[i];
        int is_last = (i + 1 == layer_count);
        int is_dense = u64_list_contains(dense_layers, dense_count, layer_id);
        int capture_final_output = (is_last && final_output_data != NULL);
        NSString *layer_output = is_last
            ? output_path
            : [work_dir stringByAppendingPathComponent:
               [NSString stringWithFormat:@"layer_%04llu.f32",
                (unsigned long long)layer_id]];
        NSString *actual_layer_output = (is_last && !capture_final_output) ? output_path : nil;
        NSString *layer_work = [work_dir stringByAppendingPathComponent:
                                [NSString stringWithFormat:@"layer_%04llu_work",
                                 (unsigned long long)layer_id]];
        DecoderLayerTimings timings;
        reset_decoder_layer_timings(&timings);
        NSData *layer_output_data = nil;
        CFAbsoluteTime layer_started = CFAbsoluteTimeGetCurrent();
        @autoreleasepool {
            if (is_dense) {
                status = run_dense_decoder_layer(device,
                                                 resident_layout_path,
                                                 cache_layout_path,
                                                 cache_file_path,
                                                 layer_id,
                                                 current_input,
                                                 current_input_data,
                                                 actual_layer_output,
                                                 layer_work,
                                                 position,
                                                 context_len,
                                                 num_heads,
                                                 kv_lora_dim,
                                                 qk_nope_dim,
                                                 rope_dim,
                                                 v_head_dim,
                                                 cache_position_offset,
                                                 attention_scale,
                                                 rope_theta,
                                                 rope_interleave,
                                                 mla_kv_b_cache_dir,
                                                 max_matrix_bytes,
                                                 max_cache_file_bytes,
                                                 max_cache_read_bytes,
                                                 max_runner_scratch_bytes,
                                                 rms_norm_eps,
                                                 &timings,
                                                 &layer_output_data);
            } else {
                status = run_decoder_layer(device,
                                           layout_path,
                                           resident_layout_path,
                                           cache_layout_path,
                                           cache_file_path,
                                           layer_id,
                                           current_input,
                                           current_input_data,
                                           actual_layer_output,
                                           nil,
                                           layer_work,
                                           position,
                                           context_len,
                                           num_heads,
                                           kv_lora_dim,
                                           qk_nope_dim,
                                           rope_dim,
                                           v_head_dim,
                                           cache_position_offset,
                                           attention_scale,
                                           rope_theta,
                                           rope_interleave,
                                           mla_kv_b_cache_dir,
                                           top_k,
                                           score_mode,
                                           router_options,
                                           max_slot_bytes,
                                           max_router_bytes,
                                           max_matrix_bytes,
                                           max_cache_file_bytes,
                                           max_cache_read_bytes,
                                           max_runner_scratch_bytes,
                                           expert_read_advise_merge_gap_bytes,
                                           expert_read_advise_align_bytes,
                                           include_shared_expert,
                                           rms_norm_eps,
                                           &timings,
                                           &layer_output_data);
            }
        }
        double layer_elapsed = CFAbsoluteTimeGetCurrent() - layer_started;
        [records addObject:@{
            @"layer": @(layer_id),
            @"kind": is_dense ? @"dense" : @"moe",
            @"input_path": current_input,
            @"output_path": layer_output,
            @"input_in_memory": [NSNumber numberWithBool:(current_input_data != nil)],
            @"output_in_memory": [NSNumber numberWithBool:(!is_last || capture_final_output)],
            @"elapsed_seconds": @(layer_elapsed),
            @"attention_projections_elapsed_seconds": @(timings.attention_projections_elapsed_seconds),
            @"split_q_elapsed_seconds": @(timings.split_q_elapsed_seconds),
            @"dummy_k_elapsed_seconds": @(timings.dummy_k_elapsed_seconds),
            @"rope_elapsed_seconds": @(timings.rope_elapsed_seconds),
            @"mla_attention_elapsed_seconds": @(timings.mla_attention_elapsed_seconds),
            @"mla_timing_input_elapsed_seconds": @(timings.mla_attention_batch.input_elapsed_seconds),
            @"mla_timing_cache_read_elapsed_seconds": @(timings.mla_attention_batch.cache_read_elapsed_seconds),
            @"mla_timing_value_read_elapsed_seconds": @(timings.mla_attention_batch.value_read_elapsed_seconds),
            @"mla_timing_metal_setup_elapsed_seconds": @(timings.mla_attention_batch.metal_setup_elapsed_seconds),
            @"mla_timing_kernel_elapsed_seconds": @(timings.mla_attention_batch.kernel_elapsed_seconds),
            @"mla_timing_kernel_weights_elapsed_seconds": @(timings.mla_attention_batch.kernel_weights_elapsed_seconds),
            @"mla_timing_kernel_values_elapsed_seconds": @(timings.mla_attention_batch.kernel_values_elapsed_seconds),
            @"mla_timing_write_elapsed_seconds": @(timings.mla_attention_batch.write_elapsed_seconds),
            @"mla_timing_total_elapsed_seconds": @(timings.mla_attention_batch.total_elapsed_seconds),
            @"mla_weights_bytes": @(timings.mla_attention_batch.weights_bytes),
            @"mla_key_cache_bytes": @(timings.mla_attention_batch.key_cache_bytes),
            @"mla_rope_cache_bytes": @(timings.mla_attention_batch.rope_cache_bytes),
            @"mla_value_cache_bytes": @(timings.mla_attention_batch.value_cache_bytes),
            @"mla_estimated_peak_bytes": @(timings.mla_attention_batch.estimated_peak_bytes),
            @"mla_singleton_kernel": [NSNumber numberWithBool:timings.mla_attention_batch.singleton_kernel],
            @"mla_split_kernel_timing_enabled": [NSNumber numberWithBool:timings.mla_attention_batch.split_kernel_timing_enabled],
            @"mla_key_cache_enabled": [NSNumber numberWithBool:timings.mla_attention_batch.key_cache_enabled],
            @"mla_rope_cache_enabled": [NSNumber numberWithBool:timings.mla_attention_batch.rope_cache_enabled],
            @"mla_value_cache_enabled": [NSNumber numberWithBool:timings.mla_attention_batch.value_cache_enabled],
            @"attention_output_elapsed_seconds": @(timings.attention_output_elapsed_seconds),
            @"mlp_elapsed_seconds": @(timings.mlp_elapsed_seconds),
            @"mlp_timing_rmsnorm_elapsed_seconds": @(timings.mlp_block.rmsnorm_elapsed_seconds),
            @"mlp_timing_router_elapsed_seconds": @(timings.mlp_block.router_elapsed_seconds),
            @"mlp_timing_moe_elapsed_seconds": @(timings.mlp_block.moe_elapsed_seconds),
            @"mlp_timing_moe_setup_elapsed_seconds": @(timings.mlp_block.moe_setup_elapsed_seconds),
            @"mlp_timing_moe_clear_elapsed_seconds": @(timings.mlp_block.moe_clear_elapsed_seconds),
            @"mlp_timing_expert_read_elapsed_seconds": @(timings.mlp_block.expert_read_elapsed_seconds),
            @"mlp_timing_expert_kernel_elapsed_seconds": @(timings.mlp_block.expert_kernel_elapsed_seconds),
            @"mlp_timing_shared_elapsed_seconds": @(timings.mlp_block.shared_elapsed_seconds),
            @"mlp_timing_residual_elapsed_seconds": @(timings.mlp_block.residual_elapsed_seconds),
            @"mlp_timing_output_elapsed_seconds": @(timings.mlp_block.output_elapsed_seconds),
            @"mlp_timing_total_elapsed_seconds": @(timings.mlp_block.total_elapsed_seconds),
            @"mlp_preload_selected_enabled": [NSNumber numberWithBool:timings.mlp_block.preload_selected_enabled],
            @"mlp_preload_selected_bytes": @(timings.mlp_block.preload_selected_bytes),
            @"mlp_mxfp4_fused_decode_enabled": [NSNumber numberWithBool:timings.mlp_block.mxfp4_fused_decode_enabled],
        }];
        if (status != 0) break;
        if ((!is_last || capture_final_output) && !layer_output_data) {
            fprintf(stderr, "decoder layer %llu did not produce in-memory output\n",
                    (unsigned long long)layer_id);
            status = 1;
            break;
        }
        if (capture_final_output) {
            *final_output_data = layer_output_data;
        }
        current_input = layer_output;
        current_input_data = is_last ? nil : layer_output_data;
    }
    if (saved_stdout >= 0) {
        fflush(stdout);
        if (dup2(saved_stdout, STDOUT_FILENO) < 0) {
            fprintf(stderr, "warning: failed to restore stdout: %s\n", strerror(errno));
        }
        close(saved_stdout);
    }

    double elapsed = CFAbsoluteTimeGetCurrent() - started;
    if (status == 0 && !write_decoder_layers_report(report_path, records, elapsed)) {
        status = 1;
    }

    printf("LargerLM decoder layers\n");
    printf("  Metal device:       %s\n", device.name.UTF8String);
    printf("  layers:             %d\n", layer_count);
    printf("  position:           %llu\n", (unsigned long long)position);
    printf("  context length:     %u\n", context_len);
    printf("  work dir:           %s\n", work_dir.UTF8String);
    printf("  elapsed seconds:    %.6f\n", elapsed);
    printf("  result:             %s\n", status == 0 ? "ok" : "failed");
    if (status == 0) {
        cleanup_decoder_work_dir(work_dir, owns_work_dir);
    }
    return status;
}

static int validate_baseline(NSString *root_path) {
    NSString *manifest_path = [root_path stringByAppendingPathComponent:@"manifest.json"];
    NSData *data = [NSData dataWithContentsOfFile:manifest_path];
    if (!data) {
        fprintf(stderr, "failed to read baseline manifest: %s\n",
                manifest_path.UTF8String);
        return 1;
    }

    NSError *error = nil;
    id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
    if (error || ![obj isKindOfClass:[NSDictionary class]]) {
        fprintf(stderr, "failed to parse baseline manifest: %s\n",
                error.localizedDescription.UTF8String);
        return 1;
    }
    NSDictionary *manifest = (NSDictionary *)obj;
    NSNumber *version = manifest[@"version"];
    if (!version || version.integerValue != 1) {
        fprintf(stderr, "unsupported baseline version\n");
        return 1;
    }
    NSArray *records = manifest[@"records"];
    if (![records isKindOfClass:[NSArray class]]) {
        fprintf(stderr, "baseline manifest missing records array\n");
        return 1;
    }

    uint64_t tensor_count = 0;
    uint64_t total_bytes = 0;
    for (id record_obj in records) {
        if (![record_obj isKindOfClass:[NSDictionary class]]) continue;
        NSArray *tensors = ((NSDictionary *)record_obj)[@"tensors"];
        if (![tensors isKindOfClass:[NSArray class]]) continue;
        for (id tensor_obj in tensors) {
            if (![tensor_obj isKindOfClass:[NSDictionary class]]) continue;
            NSDictionary *tensor = (NSDictionary *)tensor_obj;
            NSString *rel = tensor[@"path"];
            NSNumber *expected = tensor[@"bytes"];
            if (![rel isKindOfClass:[NSString class]] || !expected) {
                fprintf(stderr, "invalid tensor entry in baseline manifest\n");
                return 1;
            }
            if ([rel hasPrefix:@"/"]) {
                fprintf(stderr, "absolute tensor paths are not allowed: %s\n",
                        rel.UTF8String);
                return 1;
            }
            NSString *tensor_path = [root_path stringByAppendingPathComponent:rel];
            NSData *tensor_data = [NSData dataWithContentsOfFile:tensor_path];
            if (!tensor_data) {
                fprintf(stderr, "missing baseline tensor: %s\n", tensor_path.UTF8String);
                return 1;
            }
            if (tensor_data.length != expected.unsignedLongLongValue) {
                fprintf(stderr, "baseline tensor size mismatch: %s\n",
                        tensor_path.UTF8String);
                return 1;
            }
            tensor_count++;
            total_bytes += tensor_data.length;
        }
    }

    printf("LargerLM baseline validation\n");
    printf("  root:               %s\n", root_path.UTF8String);
    printf("  tensors:            %llu\n", (unsigned long long)tensor_count);
    printf("  total bytes:        %llu\n", (unsigned long long)total_bytes);
    printf("  result:             ok\n");
    return 0;
}

int main(int argc, const char **argv) {
    @autoreleasepool {
        if (has_flag(argc, argv, "--self-test-dequant")) {
            return run_dequant_self_test();
        }
        if (has_flag(argc, argv, "--self-test-expert")) {
            return run_expert_self_test();
