                return 2;
            }
            uint64_t max_router_bytes = 0;
            uint64_t max_runner_scratch_bytes = 0;
            if (!parse_optional_mib_bytes_arg(argc,
                                              argv,
                                              "--max-router-mib",
                                              64.0,
                                              &max_router_bytes) ||
                !parse_optional_mib_bytes_arg(argc,
                                              argv,
                                              "--max-runner-scratch-mib",
                                              4096.0,
                                              &max_runner_scratch_bytes)) {
                return 2;
            }
            if (!validate_resident_layout_backing(resident_layout_path)) {
                return 1;
            }
            RouterOptions router_options = {0};
            if (!router_options_from_args(argc, argv, &router_options)) {
                return 2;
            }
            id<MTLDevice> device = MTLCreateSystemDefaultDevice();
            if (!device) {
                fprintf(stderr, "Metal device unavailable\n");
                return 1;
            }
            return run_router_batch(device,
                                    resident_layout_path,
                                    layer_id,
                                    input_f32,
                                    (uint32_t)batch_tokens_u64,
                                    (uint32_t)top_k_u64,
                                    score_mode,
                                    router_options,
                                    output_dir,
                                    max_router_bytes,
                                    max_runner_scratch_bytes);
        }

        if (has_flag(argc, argv, "--run-router")) {
            NSString *resident_layout_path = arg_value(argc, argv, "--resident-layout");
            NSString *layer_s = arg_value(argc, argv, "--layer");
            NSString *input_f32 = arg_value(argc, argv, "--input-f32");
            if (!resident_layout_path || !layer_s || !input_f32) {
                usage(argv[0]);
                return 2;
            }
            NSString *score_mode = arg_value(argc, argv, "--router-score");
            if (!score_mode) score_mode = @"sigmoid";
            if (!([score_mode isEqualToString:@"sigmoid"] ||
                  [score_mode isEqualToString:@"softmax"] ||
                  [score_mode isEqualToString:@"raw"])) {
                fprintf(stderr, "--router-score must be sigmoid, softmax, or raw\n");
                return 2;
            }
            uint64_t layer_id = 0;
            uint64_t top_k_u64 = 0;
            if (!parse_u64_strict_value(layer_s, "--layer", &layer_id) ||
                !parse_optional_u64_arg(argc, argv, "--top-k", 8, &top_k_u64) ||
                layer_id == UINT64_MAX) {
                fprintf(stderr, "--layer must be a non-negative integer\n");
                return 2;
            }
            if (top_k_u64 == 0 || top_k_u64 > 64) {
                fprintf(stderr, "--top-k must be in 1..64\n");
                return 2;
            }
            uint32_t top_k = (uint32_t)top_k_u64;
            uint64_t max_router_bytes = 0;
            uint64_t max_runner_scratch_bytes = 0;
            if (!parse_optional_mib_bytes_arg(argc,
                                              argv,
                                              "--max-router-mib",
                                              64.0,
                                              &max_router_bytes) ||
                !parse_optional_mib_bytes_arg(argc,
                                              argv,
                                              "--max-runner-scratch-mib",
                                              4096.0,
                                              &max_runner_scratch_bytes)) {
                return 2;
            }
            if (!validate_resident_layout_backing(resident_layout_path)) {
                return 1;
            }
            RouterOptions router_options = {0};
            if (!router_options_from_args(argc, argv, &router_options)) {
                return 2;
            }
            id<MTLDevice> device = MTLCreateSystemDefaultDevice();
            if (!device) {
                fprintf(stderr, "Metal device unavailable\n");
                return 1;
            }
            return run_router(device,
                              resident_layout_path,
                              layer_id,
                              input_f32,
                              top_k,
                              score_mode,
                              router_options,
                              arg_value(argc, argv, "--output-router-json"),
                              max_router_bytes,
                              max_runner_scratch_bytes);
        }

        NSString *layout_path = arg_value(argc, argv, "--layout");
        NSString *layer_s = arg_value(argc, argv, "--layer");
        NSString *expert_s = arg_value(argc, argv, "--expert");
        int run_expert = has_flag(argc, argv, "--run-expert");
        int run_moe = has_flag(argc, argv, "--run-moe");
        int run_moe_batch = has_flag(argc, argv, "--run-moe-batch");
        if (!layout_path || !layer_s || (!expert_s && !run_moe && !run_moe_batch)) {
            usage(argv[0]);
            return 2;
        }
        if ((run_expert ? 1 : 0) + (run_moe ? 1 : 0) + (run_moe_batch ? 1 : 0) > 1) {
            fprintf(stderr, "--run-expert, --run-moe, and --run-moe-batch are mutually exclusive\n");
            return 2;
        }

        uint64_t layer_id = 0;
        if (!parse_u64_strict_value(layer_s, "--layer", &layer_id)) {
            return 2;
        }
        uint64_t expert_id = UINT64_MAX;
        if (expert_s && !parse_u64_strict_value(expert_s, "--expert", &expert_id)) {
            return 2;
        }
        uint64_t max_slot_mib = 0;
        uint64_t max_runner_scratch_mib = 0;
        uint64_t expert_read_advise_merge_gap_bytes = 0;
        uint64_t expert_read_advise_align_bytes = 0;
        if (!parse_optional_u64_arg(argc, argv, "--max-slot-mib", 256, &max_slot_mib) ||
            !parse_optional_u64_arg(argc,
                                    argv,
                                    "--max-runner-scratch-mib",
                                    4096,
                                    &max_runner_scratch_mib) ||
            !parse_optional_kib_bytes_arg_checked(argc,
                                                  argv,
                                                  "--expert-read-advise-merge-gap-kib",
                                                  0,
                                                  &expert_read_advise_merge_gap_bytes) ||
            !parse_optional_kib_bytes_arg_checked(argc,
                                                  argv,
                                                  "--expert-read-advise-align-kib",
                                                  0,
                                                  &expert_read_advise_align_bytes)) {
            return 2;
        }
        uint64_t max_slot_bytes = 0;
        uint64_t max_runner_scratch_bytes = 0;
        if (!mib_to_bytes_arg(max_slot_mib, "--max-slot-mib", &max_slot_bytes) ||
            !mib_to_bytes_arg(max_runner_scratch_mib,
                              "--max-runner-scratch-mib",
                              &max_runner_scratch_bytes)) {
            return 2;
        }
        int do_read = has_flag(argc, argv, "--read") || run_expert;
        NSString *input_f32 = arg_value(argc, argv, "--input-f32");
        NSString *output_f32 = arg_value(argc, argv, "--output-f32");
        if (run_expert && !input_f32) {
            fprintf(stderr, "--run-expert requires --input-f32 PATH\n");
            return 2;
        }
        if (run_moe && !input_f32) {
            fprintf(stderr, "--run-moe requires --input-f32 PATH\n");
            return 2;
        }
        NSString *routes_json = arg_value(argc, argv, "--routes-json");
        NSString *routes_bin = arg_value(argc, argv, "--routes-bin");
        uint64_t batch_tokens_u64 = 0;
        if (run_moe_batch &&
            !parse_u64_strict_value(arg_value(argc, argv, "--batch-tokens"),
                                    "--batch-tokens",
                                    &batch_tokens_u64)) {
            return 2;
        }
        if (run_moe_batch && (!input_f32 || !output_f32 ||
                              ((routes_json ? 1 : 0) + (routes_bin ? 1 : 0) != 1) ||
                              batch_tokens_u64 == 0 || batch_tokens_u64 > UINT32_MAX)) {
            fprintf(stderr,
                    "--run-moe-batch requires --input-f32, --output-f32, "
                    "exactly one of --routes-json/--routes-bin, and positive --batch-tokens\n");
            return 2;
        }

        uint64_t max_k_u64 = 0;
        if (!parse_optional_u64_arg(argc, argv, "--max-k", 8, &max_k_u64)) {
            return 2;
        }
        NSString *moe_token_block_arg = arg_value(argc, argv, "--moe-token-block");
        uint64_t moe_token_block_u64 = 0;
        int moe_token_block_auto =
            (!moe_token_block_arg || [moe_token_block_arg isEqualToString:@"auto"]);
        if (!moe_token_block_auto) {
            if (!parse_u64_strict_value(moe_token_block_arg,
                                        "--moe-token-block",
                                        &moe_token_block_u64)) {
                return 2;
            }
        }
        uint64_t moe_experts[64] = {0};
        float moe_weights[64] = {0};
        int moe_count = 0;
        if (max_k_u64 == 0 || max_k_u64 > 64) {
            fprintf(stderr, "--max-k must be in 1..64\n");
            return 2;
        }
        const int max_k = (int)max_k_u64;
        if (!moe_token_block_auto &&
            (moe_token_block_u64 == 0 || moe_token_block_u64 > UINT32_MAX)) {
            fprintf(stderr, "--moe-token-block must be auto or in 1..%u\n", UINT32_MAX);
            return 2;
        }
        uint32_t moe_token_block = moe_token_block_auto ? 0 : (uint32_t)moe_token_block_u64;
        if (run_moe) {
            moe_count = parse_u64_list(arg_value(argc, argv, "--experts"), moe_experts, max_k);
            int weight_count = parse_float_list(arg_value(argc, argv, "--weights"), moe_weights, max_k);
            if (moe_count <= 0 || weight_count != moe_count) {
                fprintf(stderr, "--run-moe requires matching --experts and --weights lists\n");
                return 2;
            }
        }

        NSDictionary *layout = load_json(layout_path);
        if (!layout) return 1;
        NSArray *layers = layout[@"layers"];
        if (![layers isKindOfClass:[NSArray class]]) {
            fprintf(stderr, "layout missing layers array\n");
            return 1;
        }
        NSDictionary *layer = find_layer(layers, layer_id);
        if (!layer) {
            fprintf(stderr, "layer %llu not found in layout\n",
                    (unsigned long long)layer_id);
            return 1;
        }

        NSString *layer_file = nil;
        uint64_t num_experts = 0;
        uint64_t slot_bytes = 0;
        uint64_t layer_file_bytes = 0;
        if (!parse_expert_layer_fields(layer,
                                       max_slot_bytes,
                                       &layer_file,
                                       &num_experts,
                                       &slot_bytes,
                                       &layer_file_bytes)) {
            return 1;
        }
        NSString *layout_dir = [layout_path stringByDeletingLastPathComponent];
        NSString *expert_path = [layout_dir stringByAppendingPathComponent:layer_file];
        if (!validate_expert_layer_file_size(expert_path, layer_file_bytes)) return 1;

        ExpertLayoutInfo expert_info = {0};
        if ((run_expert || run_moe || run_moe_batch) &&
            !parse_expert_layout(layout, layer, &expert_info)) {
            return 1;
        }

        if (!run_moe && !run_moe_batch && expert_id >= num_experts) {
            fprintf(stderr, "expert %llu out of range; layer has %llu experts\n",
                    (unsigned long long)expert_id,
                    (unsigned long long)num_experts);
            return 1;
        }
        if (run_moe) {
            for (int i = 0; i < moe_count; i++) {
                if (moe_experts[i] >= num_experts) {
                    fprintf(stderr, "expert %llu out of range; layer has %llu experts\n",
                            (unsigned long long)moe_experts[i],
                            (unsigned long long)num_experts);
                    return 1;
                }
            }
        }

        MoEBatchRoute *preloaded_routes = NULL;
        MoEBatchAssignment *preloaded_assignments = NULL;
        uint64_t preloaded_assignment_count = 0;
        int preloaded_assignments_sorted = 0;
        if (run_moe_batch) {
            if (routes_json) {
                if (!load_moe_batch_routes(routes_json,
                                           (uint32_t)batch_tokens_u64,
                                           max_k,
                                           num_experts,
                                           &preloaded_routes)) {
                    return 1;
                }
            } else {
                if (!load_moe_batch_assignments_bin(routes_bin,
                                                    (uint32_t)batch_tokens_u64,
                                                    max_k,
                                                    num_experts,
                                                    max_runner_scratch_bytes,
                                                    &preloaded_assignments,
                                                    &preloaded_assignment_count,
                                                    &preloaded_assignments_sorted)) {
                    return 1;
                }
            }
        }

        id<MTLDevice> device = MTLCreateSystemDefaultDevice();
        if (!device) {
            fprintf(stderr, "Metal device unavailable\n");
            free(preloaded_routes);
            free(preloaded_assignments);
            return 1;
        }

        uint64_t offset = expert_id * slot_bytes;
        uint64_t alloc_size = align_up_u64(slot_bytes, 2 * 1024 * 1024);

        if (run_moe_batch) {
            if (routes_json) {
                int status = run_moe_forward_batch(device,
                                                   expert_path.UTF8String,
                                                   slot_bytes,
                                                   num_experts * slot_bytes,
                                                   preloaded_routes,
                                                   (uint32_t)batch_tokens_u64,
                                                   moe_token_block,
                                                   expert_info,
                                                   input_f32,
                                                   output_f32,
                                                   alloc_size,
                                                   max_runner_scratch_bytes,
                                                   expert_read_advise_merge_gap_bytes,
                                                   expert_read_advise_align_bytes);
                free(preloaded_routes);
                return status;
            }

            return run_moe_forward_batch_assignments(device,
                                                     expert_path.UTF8String,
                                                     slot_bytes,
                                                     num_experts * slot_bytes,
                                                     preloaded_assignments,
                                                     preloaded_assignment_count,
                                                     preloaded_assignments_sorted,
                                                     (uint32_t)batch_tokens_u64,
                                                     moe_token_block,
                                                     expert_info,
                                                     input_f32,
                                                     output_f32,
                                                     alloc_size,
                                                     max_runner_scratch_bytes,
                                                     expert_read_advise_merge_gap_bytes,
                                                     expert_read_advise_align_bytes);
        }

        if (run_moe) {
            printf("LargerLM runner\n");
            printf("  Metal device:       %s\n", device.name.UTF8String);
            printf("  layer:              %llu\n", (unsigned long long)layer_id);
            printf("  slot bytes:         %llu\n", (unsigned long long)slot_bytes);
            printf("  2MB alloc bytes:    %llu\n", (unsigned long long)alloc_size);
            return run_moe_forward(device, expert_path.UTF8String, slot_bytes,
                                   num_experts * slot_bytes,
                                   moe_experts, moe_weights, moe_count,
                                   expert_info, input_f32, nil, nil, output_f32, nil, alloc_size,
                                   0,
                                   max_runner_scratch_bytes,
                                   expert_read_advise_merge_gap_bytes,
                                   expert_read_advise_align_bytes,
                                   NULL,
                                   nil,
                                   NULL);
        }

        printf("LargerLM runner\n");
        printf("  Metal device:       %s\n", device.name.UTF8String);
        printf("  layer:              %llu\n", (unsigned long long)layer_id);
        printf("  expert:             %llu / %llu\n",
               (unsigned long long)expert_id, (unsigned long long)num_experts);
        printf("  slot bytes:         %llu\n", (unsigned long long)slot_bytes);
        printf("  2MB alloc bytes:    %llu\n", (unsigned long long)alloc_size);
        printf("  file offset:        %llu\n", (unsigned long long)offset);

        void *aligned = NULL;
        if (posix_memalign(&aligned, 2 * 1024 * 1024, (size_t)alloc_size) != 0) {
            fprintf(stderr, "posix_memalign failed for %llu bytes\n",
                    (unsigned long long)alloc_size);
            return 1;
        }
        memset(aligned, 0, (size_t)alloc_size);

        if (do_read) {
            if (!read_exact_slot(expert_path.UTF8String, aligned, (size_t)slot_bytes,
                                 (off_t)offset)) {
                free(aligned);
                return 1;
            }
            printf("  read:               ok\n");
        } else {
            printf("  read:               skipped (pass --read to pread slot)\n");
        }

        id<MTLBuffer> buffer =
            [device newBufferWithBytesNoCopy:aligned
                                       length:(NSUInteger)alloc_size
                                      options:MTLResourceStorageModeShared
                                  deallocator:^(void *pointer, NSUInteger length) {
                                      (void)length;
                                      free(pointer);
                                  }];
        if (!buffer) {
            fprintf(stderr, "failed to wrap aligned memory as Metal buffer\n");
            free(aligned);
            return 1;
        }

        printf("  Metal buffer:       ok\n");
        if (run_expert) {
            return run_expert_forward(device, buffer, expert_info, input_f32, output_f32,
                                      alloc_size,
                                      max_runner_scratch_bytes);
        }
        return 0;
    }
}
